import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IGuestAuthGuestSignOutResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignOutResponse";

/**
 * Test error handling for guest logout attempt without a valid JWT token.
 *
 * This test verifies that the API enforces guest session protection rules when a logout attempt is made without providing a valid guest JWT, such as when the Authorization header is missing or contains an expired/invalid token.
 * The logout endpoint (POST /auth/guest/logout) should respond with an authentication error and audit the failed attempt, without allowing a successful logout.
 *
 * Steps:
 * 1. Attempt to call POST /auth/guest/logout using a connection with no Authorization header (no JWT token).
 *    - Validate that the API returns an authentication error.
 * 2. Optionally, if possible, attempt with an explicitly invalid or expired JWT token and validate error response (cannot be implemented if no token issuance/expiry logic is available in scope).
 * 3. Confirm that a valid logout attempt with a proper token would succeed (outside the scope for this negative test).
 *
 * The main goal is to ensure unauthenticated guest logout attempts are properly rejected.
 */
export async function test_api_guest_logout_without_token_error(connection: api.IConnection) {
  // 1. Attempt logout with no Authorization header (simulate an unauthenticated guest)
  await TestValidator.error("logout without authentication should fail")(async () => {
    // Construct a connection with empty or no Authorization header
    const unauthenticatedConnection = { ...connection, headers: { ...connection.headers } };
    delete unauthenticatedConnection.headers?.Authorization;

    await api.functional.auth.guest.logout.signOut(unauthenticatedConnection);
  });
}

