import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validate input validation and error reporting for guest login.
 *
 * This test ensures the /auth/guest/login endpoint properly enforces required guest device/auth info (user agent and ip address) during login. It attempts to log in as a guest with incomplete or malformed data in the request body, expecting the API to reject invalid input with appropriate errors.
 *
 * Steps:
 * 1. Attempt login omitting the required user_agent property. Expect validation error.
 * 2. Attempt login omitting the required ip_address property. Expect validation error.
 * 3. Attempt login with both user_agent and ip_address present, but provide a clearly invalid (non-string) value for user_agent. Expect validation error.
 * 4. Attempt login with both user_agent and ip_address present, but provide a clearly invalid (non-string) value for ip_address. Expect validation error.
 * 5. Confirm that successful login is not possible with incomplete or malformed inputs.
 */
export async function test_api_guest_login_invalid_payload_error(connection: api.IConnection) {
  // 1. Omitting user_agent
  await TestValidator.error("missing user_agent triggers validation error")(() =>
    api.functional.auth.guest.login.signIn(connection, {
      body: {
        // user_agent: omitted
        ip_address: "123.123.123.123",
      } as any // as any required for omission in test only
    })
  );

  // 2. Omitting ip_address
  await TestValidator.error("missing ip_address triggers validation error")(() =>
    api.functional.auth.guest.login.signIn(connection, {
      body: {
        user_agent: "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
        // ip_address: omitted
      } as any // as any required for omission in test only
    })
  );

  // 3. Invalid user_agent type
  await TestValidator.error("non-string user_agent fails validation")(() =>
    api.functional.auth.guest.login.signIn(connection, {
      body: {
        user_agent: 12345 as any, // invalid type
        ip_address: "123.123.123.123",
      }
    })
  );

  // 4. Invalid ip_address type
  await TestValidator.error("non-string ip_address fails validation")(() =>
    api.functional.auth.guest.login.signIn(connection, {
      body: {
        user_agent: "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
        ip_address: 12345 as any, // invalid type
      }
    })
  );
}

