import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test member login with incorrect password (negative authentication test)
 *
 * This test verifies that the authentication system rejects login attempts when given the correct member email but an invalid (incorrect) password. It ensures that password verification logic is enforced and that error handling works as expected.
 *
 * Test workflow:
 * 1. Register a member with known credentials (random email, password, nickname)
 * 2. Attempt to login using the correct email but an incorrect password
 * 3. Confirm that an error is thrown, indicating failed authentication due to password mismatch
 */
export async function test_api_member_login_incorrect_password(connection: api.IConnection) {
  // 1. Register a new member so we have known credentials
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberNickname = RandomGenerator.name();
  const correctPassword = "TestPassw0rd!";
  const signUpSession: IDiscussionBoardMember.ISession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: correctPassword,
      nickname: memberNickname,
      avatar_uri: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(signUpSession);
  TestValidator.equals("signup member email")(signUpSession.member.email)(memberEmail);
  TestValidator.equals("signup member nickname")(signUpSession.member.nickname)(memberNickname);

  // 2. Try to login with correct email but invalid password
  const WRONG_PASSWORD = "Wrong_Pass1234!";
  TestValidator.error("login should fail with wrong password")(async () => {
    await api.functional.auth.member.login.signIn(connection, {
      body: {
        email: memberEmail,
        password: WRONG_PASSWORD,
      } satisfies IDiscussionBoardMember.ILogin,
    });
  });
}

