 * Validate that the system detects a tampered guest JWT and correctly rejects it.
 *
 * Businesses often must defend against token forgery or manipulation by validating JWT signatures. This test ensures that after a guest session successfully retrieves a token, if the token is modified even slightly (thus invalidating the cryptographic signature), the /auth/guest/validate endpoint returns a validation failure, not a false positive.
 *
 * Step-by-step process:
 * 1. Perform guest login to obtain a valid JWT token (via /auth/guest/login).
 * 2. Modify the acquired JWT by changing a single character in its signature part.
 * 3. Submit the tampered JWT to /auth/guest/validate along with user agent and IP used in step 1.
 * 4. Check the response: 'valid' must be false, and 'reason' should indicate invalidity (e.g., 'invalid', 'tampered', or similar).
 */
export async function test_api_guest_jwt_validation_invalid_signature(connection: api.IConnection) {
  // 1. Guest login: request a valid guest JWT
  const request: IGuestAuthGuestSignInRequest = {
    user_agent: RandomGenerator.alphabets(10),
    ip_address: [
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<1> & tags.Maximum<255>>(),
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<0> & tags.Maximum<255>>(),
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<0> & tags.Maximum<255>>(),
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<1> & tags.Maximum<254>>()
    ].join("."),
  };
  const loginOutput: IGuestAuthGuestSignInResponse = await api.functional.auth.guest.login.signIn(connection, {
    body: request,
  });
  typia.assert(loginOutput);

  // 2. Tamper the JWT string: change a character (in payload or signature)
  let tamperedToken = loginOutput.token;
  // Find a position in the signature part and flip a char
  const parts = tamperedToken.split('.');
  if (parts.length !== 3) throw new Error("JWT does not have 3 parts");
  let sig = parts[2];
  // Mutate a character: flip the first char (simple and safe)
  const origChar = sig[0];
  let mutatedChar;
  // Swap to a different valid JWT charset character
  if (origChar === 'A') mutatedChar = 'B';
  else if (origChar === 'B') mutatedChar = 'A';
  else mutatedChar = 'A';
  sig = mutatedChar + sig.slice(1);
  parts[2] = sig;
  tamperedToken = parts.join('.');

  // 3. Call /auth/guest/validate with tampered (invalid) JWT
  const validationOutput: IGuestAuthGuestValidateResponse =
    await api.functional.auth.guest.validate.validateToken(connection, {
      body: {
        token: tamperedToken,
        user_agent: request.user_agent,
        ip_address: request.ip_address,
      },
    });
  typia.assert(validationOutput);

  // 4. Assert invalid token is detected
  TestValidator.equals("token should be invalid")(validationOutput.valid)(false);
  TestValidator.predicate("reason is present")(typeof validationOutput.reason === 'string' && validationOutput.reason.length > 0);
