import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test updating a discussion board notification's mutable fields as an admin.
 *
 * This test ensures that an admin can successfully update the modifiable fields of a notification, such as the title, body, or unread status, while immutable fields (ID, recipient) remain unchanged. It also checks that audit fields such as updated_at reflect the update.
 *
 * Steps:
 * 1. Register a new admin account.
 * 2. As this admin, create a notification (using admin_id as recipient for role-clarity).
 * 3. Call the update API to modify at least two mutable fields (e.g., title and unread; optionally body).
 * 4. Assert the returned notification reflects the updates: the new value(s) for modifiable fields, but unchanged values for immutable recipient, id, and created_at.
 * 5. Confirm updated_at is newer/later than created_at.
 */
export async function test_api_notification_update_success(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPass123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // 2. Create a notification as this admin (send to self for clarity)
  const createInput: IDiscussionBoardNotification.ICreate = {
    admin_id: adminAuth.admin_id,
    title: "Original Title",
    body: "Original body of the notification.",
    event_type: "system_announcement",
    related_entity_id: null,
    related_entity_type: null,
    member_id: null,
    moderator_id: null,
    guest_id: null,
  };
  const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: createInput,
  });
  typia.assert(notification);

  // 3. Update some mutable fields (title, body, mark as read)
  const updateInput: IDiscussionBoardNotification.IUpdate = {
    title: "Updated Title",
    body: "This body has been updated.",
    unread: false,
  };
  const updated = await api.functional.discussionBoard.admin.notifications.update(connection, {
    notificationId: notification.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. Assert updated fields and audit trail
  TestValidator.equals("notification id should not change")(updated.id)(notification.id);
  TestValidator.equals("admin_id must remain the same")(updated.admin_id)(notification.admin_id);
  TestValidator.equals("title updated")(updated.title)(updateInput.title);
  TestValidator.equals("body updated")(updated.body)(updateInput.body);
  TestValidator.equals("unread flag updated")(updated.unread)(updateInput.unread);

  // 5. Fields that must NOT change
  TestValidator.equals("created_at unchanged")(updated.created_at)(notification.created_at);

  // 6. updated_at should be later than created_at
  TestValidator.predicate("updated_at advances")(new Date(updated.updated_at).getTime() > new Date(notification.created_at).getTime());
}

