default const adminEmail = typia.random<string & tags.Format<'email'>>();
  const oldPassword = RandomGenerator.alphaNumeric(10);
  const registerResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: oldPassword,
    },
  });
  typia.assert(registerResponse);

  // 2. Login to get JWT (also establishes session)
  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: oldPassword,
    },
  });
  typia.assert(loginResponse);

