  await TestValidator.error("invalid new password policy rejected")(() =>
    api.functional.auth.admin.password.changePassword(connection, {
      body: {
        oldPassword: oldPassword,
        newPassword: invalidPassword,
      },
    })
  );

  // 4. Attempt login with new (invalid) password – should fail
  await TestValidator.error("login with invalid new password fails")(() =>
    api.functional.auth.admin.login.signIn(connection, {
      body: {
        email: adminEmail,
        password: invalidPassword,
      },
    })
  );

  // 5. Login with original password – should still succeed
  const relogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: oldPassword,
    },
  });
  typia.assert(relogin);
  TestValidator.equals("account unchanged")(relogin.email)(adminEmail);
}

