import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IStd } from "@ORGANIZATION/PROJECT-api/lib/structures/IStd";

/**
 * Validates that the system properly detects and rejects a JWT with an invalid signature.
 *
 * This test simulates the scenario where an attacker or malfunctioning client submits a JWT token whose signature has been tampered with. The intent is to confirm that the backend strictly validates JWT signatures and does not accept a token whose integrity is compromised.
 *
 * Business context: JWT signature validation is critical to prevent impersonation, session hijacking, or privilege escalation by forged tokens.
 *
 * Test procedure:
 * 1. Register a new member with random credentials.
 * 2. Log in as the member to retrieve a valid JWT access token.
 * 3. Tamper with the JWT signature by flipping or replacing characters in the signature part (the third JWT section after the second period).
 * 4. Submit the tampered token to the /auth/member/validate endpoint.
 * 5. Confirm that the response indicates rejected authentication (authenticated=false, and an appropriate reason).
 * 6. Optionally confirm that the original, untampered JWT remains valid when sent.
 */
export async function test_api_member_jwt_validation_invalid_signature(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const nickname = RandomGenerator.name();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(session);
  TestValidator.predicate("token issued")(typeof session.token === "string");

  // 2. Log in to get a fresh valid token (ensure login flow works)
  const login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardMember.ILogin,
  });
  typia.assert(login);
  const validToken = login.token;

  // 3. Tamper with the JWT signature section
  // (JWT format: header.payload.signature)
  const jwtParts = validToken.split(".");
  if (jwtParts.length !== 3) throw new Error("JWT format invalid");
  // Flip one character in signature, or replace all
  const originalSignature = jwtParts[2];
  let tamperedSignature =
    originalSignature.length > 4
      ? originalSignature.substring(0, originalSignature.length - 2) +
        (originalSignature[originalSignature.length - 1] === "A" ? "B" : "A") +
        (originalSignature[originalSignature.length - 2] === "B" ? "X" : "B")
      : originalSignature
          .split("")
          .map((ch) => (ch === "A" ? "B" : "A"))
          .join("");
  const tamperedToken = `${jwtParts[0]}.${jwtParts[1]}.${tamperedSignature}`;

  // 4. Submit tampered token - expect rejection
  const tampered = await api.functional.auth.member.validate.validateToken(connection, {
    body: {
      token: tamperedToken,
    } satisfies IStd.ITokenCheck,
  });
  typia.assert(tampered);
  TestValidator.equals("authenticated false for tampered token")(tampered.authenticated)(false);
  TestValidator.predicate("reason must be present")(typeof tampered.reason === "string");

  // 5. Submit the original token - expect acceptance
  const original = await api.functional.auth.member.validate.validateToken(connection, {
    body: {
      token: validToken,
    } satisfies IStd.ITokenCheck,
  });
  typia.assert(original);
  TestValidator.equals("authenticated true for valid token")(original.authenticated)(true);
}

