 * 3. Confirms a positive response is returned, indicating session invalidation.
 * 4. Attempts to use the (now invalid) guest JWT token for another guest API, and expects failure (error thrown).
 *
 * This ensures guests cannot access resources after logout and verifies compliance with session invalidation policy.
 */
export async function test_api_guest_logout_success_session_end(connection: api.IConnection) {
