 * 3. Assert that the pagination structure is present and correctly reflects zero total records/pages, with current and limit fields according to the request or default values.
 * 4. Ensure the API does not throw errors and the response structure matches the expected type.
 */
export async function test_api_user_sanctions_moderator_search_no_results(connection: api.IConnection) {
  // 1. Prepare a filter object that certainly won't match any sanctions
  const filters: IDiscussionBoardUserSanction.IRequest = {
    sanctioned_member_id: typia.random<string & tags.Format<"uuid">>(), // random UUID
    sanction_type: "nonexistent_type", // value that can't match actual data
    active: false,
    timeline_start_from: "2100-01-01T00:00:00.000Z", // date far in the future
    timeline_start_to: "2100-12-31T23:59:59.999Z",
