  TestValidator.equals("Total pages")(output.pagination.pages)(0);
  TestValidator.equals("Current page")(output.pagination.current)(filters.page ?? 1);
  TestValidator.equals("Limit")(output.pagination.limit)(filters.limit ?? 10);
}

