  TestValidator.error("login fails with non-existent email")(
    async () => {
      await api.functional.auth.moderator.login.signIn(connection, {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          password: "RandomPwd!"
        } satisfies IModerator.SignIn
      });
    }
  );
  // 5. (Edge status transitions: not tested - no status change API available.)
