import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that deleting a sub-category which is still in use (because another sub-category is defined under it) fails.
 *
 * This test covers restriction enforcement: A sub-category cannot be deleted if it has child sub-categories (usage dependency).
 *
 * Steps:
 * 1. Create a parent category (root level)
 * 2. Create a sub-category under the parent
 * 3. Create a child sub-category under the sub-category (i.e., child of the sub-category)
 * 4. Attempt to delete the sub-category (which is now in-use)
 * 5. Confirm the API rejects the deletion, indicating usage dependency
 */
export async function test_api_subcategory_soft_delete_in_use_restricted(connection: api.IConnection) {
  // 1. Create parent category (root)
  const parent: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      display_order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
      version: 1,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(parent);

  // 2. Create sub-category under parent
  const subCategory: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
    categoryId: parent.id,
    body: {
      name: RandomGenerator.alphaNumeric(8),
      display_order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
      version: 1,
      parent_id: parent.id,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(subCategory);

  // 3. Create child sub-category under subCategory
  const childSub: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
    categoryId: subCategory.id,
    body: {
      name: RandomGenerator.alphaNumeric(8),
      display_order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
      version: 1,
      parent_id: subCategory.id,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(childSub);

  // 4. Attempt to delete sub-category (should fail)
  await TestValidator.error("Cannot delete sub-category in use")(() =>
    api.functional.discussionBoard.admin.categories.subs.eraseSubCategory(connection, {
      categoryId: parent.id,
      subCategoryId: subCategory.id,
    })
  );
}

