 * 2. Create the first sub-category under this parent with a distinct name.
 * 3. Attempt to create a second sub-category under the same parent using the same name.
 * 4. API call should result in a uniqueness/conflict error per business rules (NOT a successful creation, not a type error).
 * 5. Validate that the error semantics align with conflict response expectations (HTTP status and error type) – only presence of error is checked.
 */
export async function test_api_subcategory_creation_duplicate_name(connection: api.IConnection) {
  // 1. Create a parent category (top-level, no parent_id)
  const parentName: string = RandomGenerator.alphabets(8);
  const parentOrder: number = typia.random<number & tags.Type<"int32">>();
  const parent: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: parentName,
      display_order: parentOrder,
      enabled: true,
      version: 1
    } satisfies IDiscussionBoardCategory.ICreate
  });
  typia.assert(parent);

