 * Validate the system's response to invalid or malformed filter criteria in post metrics search as a moderator.
 *
 * Business context:
 * Moderators need to be able to search and filter post metrics using a rich set of analytic filters (counts, ranges, date windows, ordering, pagination). However, the backend must enforce strong validation rules—rejecting malformed, nonsensical, or type-violating filter values with clear, actionable error feedback. This ensures dashboard stability, prevents data leaks, and helps moderators correct input errors quickly.
 *
 * Step-by-step process:
 * 1. Submit malformed requests using invalid data types or illogical filter value combinations over the patch endpoint `/discussionBoard/moderator/postMetrics`
 *     a) Non-numeric strings instead of integers in count range fields
 *     b) Provide a min value greater than the corresponding max (e.g., `comments_count_min = 10, comments_count_max = 5`)
 *     c) Provide invalid date string (malformed ISO-8601) in a date field
 *     d) last_activity_from after last_activity_to (reversed logic)
 * 2. For each malformed or logically invalid request, verify that the API responds with an error and does not return a valid result or silent success.
 * 3. Only basic runtime error occurrence is checked; the specific content of error messages is not validated.
 */
export async function test_api_post_metrics_search_invalid_filters(
  connection: api.IConnection,
) {
  // a) Non-numeric string in numeric fields
  await TestValidator.error("non-numeric view count fails")(async () => {
    await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
      body: {
        views_count_min: "not-a-number" as any,
      },
    });
  });

  // b) Min greater than max (illogical range)
  await TestValidator.error("min > max for comments_count fails")(async () => {
    await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
      body: {
        comments_count_min: 10,
        comments_count_max: 5,
      },
    });
  });

  // c) Malformed date string in datetime field
  await TestValidator.error("malformed last_activity_from date fails")(async () => {
    await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
      body: {
        last_activity_from: "not-a-date",
      },
    });
  });

  // d) last_activity_from later than last_activity_to (reversed logic)
  await TestValidator.error("from after to for last_activity_dates fails")(async () => {
    await api.functional.discussionBoard.moderator.postMetrics.search(connection, {
      body: {
        last_activity_from: "2025-12-31T23:59:59.000Z",
        last_activity_to: "2025-01-01T00:00:00.000Z",
      },
    });
  });
}

