import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate unauthorized profile access prevention.
 *
 * This test verifies that when an authenticated member attempts to fetch another member's profile via the /discussionBoard/member/members/{memberId} endpoint, access is denied and no profile data is leaked. The intention is to test endpoint-level access control enforcement.
 *
 * Steps:
 * 1. Register the first member (target, should remain protected).
 * 2. Register the second member (attacker).
 * 3. Authenticate session as the second member (attacker account's token is set on the connection).
 * 4. Attempt to retrieve the first member's detailed profile by UUID as the second member using api.functional.discussionBoard.member.members.at().
 * 5. Confirm that an error is thrown (access is denied; forbidden or unauthorized error occurs).
 * 6. Verify that no member profile data is accidentally exposed to the requester.
 *
 * This test ensures policy compliance and helps prevent information disclosure vulnerabilities in user profile endpoints.
 */
export async function test_api_member_profile_self_view_forbidden_other_member(connection: api.IConnection) {
  // 1. Register the first member.
  const member1Email = typia.random<string & tags.Format<"email">>();
  const member1Password = "TestPassword123!";
  const member1Nickname = RandomGenerator.name();
  const member1 = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member1Email,
      password: member1Password,
      nickname: member1Nickname,
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(member1);
  const member1Id = member1.member.id;

  // 2. Register the second member.
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2Password = "TestPassword456!";
  const member2Nickname = RandomGenerator.name();
  const member2 = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member2Email,
      password: member2Password,
      nickname: member2Nickname,
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(member2);
  // After sign-up, connection now uses member2's session token.

  // 3. Attempt to fetch member1's profile as member2 (should be forbidden)
  await TestValidator.error("Access to another member's profile is forbidden")(
    async () => {
      await api.functional.discussionBoard.member.members.at(connection, {
        memberId: member1Id,
      });
    },
  );
}

