import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate successful retrieval of a discussion board category's detailed information by an admin user.
 *
 * This test ensures the following workflow:
 * 1. A new category is created via the admin API (setup step).
 * 2. As an authenticated admin, retrieve the full details of the category using its unique ID.
 * 3. Validate that all returned fields (including hierarchy, ordering, enabled status, description, version, and auditing fields such as created/updated timestamps) match and are correctly populated.
 * 4. Assert that the response structure matches the schema, and all relevant admin/audit fields are present and correct.
 * 5. Validate that only admins can access this detail endpoint and that the returned information satisfies admin UI and compliance needs.
 */
export async function test_api_category_detail_view_success_admin(connection: api.IConnection) {
  // 1. Create a new discussion board category as setup
  const createInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphaNumeric(12),
    display_order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
    version: 1,
    description: RandomGenerator.paragraph()(),
    parent_id: null,
    icon_uri: null,
  };

  const createdCategory: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: createInput,
  });
  typia.assert(createdCategory);

  // 2. Retrieve the category detail using the admin endpoint
  const categoryDetail: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.at(connection, {
    categoryId: createdCategory.id,
  });
  typia.assert(categoryDetail);

  // 3. Validate that the important fields are present and accurate
  TestValidator.equals("id matches")(categoryDetail.id)(createdCategory.id);
  TestValidator.equals("name matches")(categoryDetail.name)(createInput.name);
  TestValidator.equals("display_order matches")(categoryDetail.display_order)(createInput.display_order);
  TestValidator.equals("enabled matches")(categoryDetail.enabled)(createInput.enabled);
  TestValidator.equals("version matches")(categoryDetail.version)(createInput.version);
  TestValidator.equals("parent_id root null")(categoryDetail.parent_id)(null);
  TestValidator.equals("description matches")(categoryDetail.description)(createInput.description);
  TestValidator.equals("icon_uri matches")(categoryDetail.icon_uri)(null);

  // 4. Validate the presence and format of audit fields
  TestValidator.predicate("created_at is RFC3339 string")(
    typeof categoryDetail.created_at === "string" && !!Date.parse(categoryDetail.created_at),
  );
  TestValidator.predicate("updated_at is RFC3339 string")(
    typeof categoryDetail.updated_at === "string" && !!Date.parse(categoryDetail.updated_at),
  );
  // deleted_at should be null on creation
  TestValidator.equals("deleted_at is null")(categoryDetail.deleted_at ?? null)(null);
}

