 *
 * This test ensures that admin can soft-delete an external authentication log, which marks the entry as deleted via the `deleted_at` timestamp rather than physically removing it. After deletion, the log should no longer be accessible via standard queries, and any attempt to access, update, or delete the log by ID should result in a not found or forbidden error. Access control is rigorously checked by confirming that only admins can perform the soft-delete. Audit logic is implied, but only what can be validated via the API is tested here.
 *
 * Test Steps:
 * 1. Create a new external authentication log entry as admin (since only admin can create via this endpoint).
 * 2. Soft-delete the log as admin (by calling DELETE on the ID).
 * 3. (If listing/search existed: ensure the deleted entry is not returned in list, but this step can't be implemented without such endpoint.)
 * 4. Attempt to DELETE the same log entry again; expect not found/forbidden error.
 * 5. (If update or detail endpoints existed: try accessing/updating after deletion and expect errors. Omitted as not implementable with provided APIs.)
 * 6. (If non-admin user logic existed: attempt soft-delete as non-admin and expect forbidden, but authentication APIs are not provided, so cannot test this.)
 *
 * Only implementable points are covered below.
 */
export async function test_api_external_auth_log_soft_delete_and_access_control(
  connection: api.IConnection,
) {
  // 1. Create a new external authentication log entry (as admin)
  const log: IDiscussionBoardExternalAuthLog = await api.functional.discussionBoard.admin.externalAuthLogs.create(connection, {
    body: {
      discussion_board_member_id: null,
      auth_channel: "kakao",
      external_user_id: null,
      subject_email: RandomGenerator.alphaNumeric(8) + "@example.com",
      issued_at: new Date().toISOString(),
      completed_at: new Date().toISOString(),
      success: true,
      error_code: null,
      error_message: null,
    } satisfies IDiscussionBoardExternalAuthLog.ICreate,
  });
  typia.assert(log);
  TestValidator.equals("not deleted before")(log.deleted_at)(null);

  // 2. Soft-delete the log as admin
  await api.functional.discussionBoard.admin.externalAuthLogs.erase(connection, {
    externalAuthLogId: log.id
  });

  // 3. (Not implementable: list/search endpoint not available)

  // 4. Attempt to delete again should produce an error (already deleted: forbidden or not found)
  await TestValidator.error("cannot delete already soft-deleted log")(
    async () => {
      await api.functional.discussionBoard.admin.externalAuthLogs.erase(connection, {
        externalAuthLogId: log.id
      });
    }
  );

  // 5. (No update/detail endpoints, so can't check access/update after deletion)
  // 6. (No non-admin auth flows provided, so cannot attempt as non-admin)
}

