  const input: IDiscussionBoardExternalAuthLog.ICreate = {
    auth_channel: "google",
    subject_email: typia.random<string & tags.Format<"email">>(),
    issued_at: new Date().toISOString(),
    success: true,
    discussion_board_member_id: null,
    external_user_id: null,
    completed_at: new Date().toISOString(),
    error_code: null,
    error_message: null,
  };
  const created: IDiscussionBoardExternalAuthLog = await api.functional.discussionBoard.admin.externalAuthLogs.create(connection, {
    body: input,
