import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Verify that a member can successfully retrieve their own detailed profile.
 *
 * This test covers the basic scenario where a user registers as a new discussion board member, authenticates to obtain a session, and then retrieves their profile details using the self-view API endpoint. It ensures that all profile fields are returned excluding any sensitive/hash data. This helps verify secure separation of credentials and public-facing account info.
 *
 * Steps:
 * 1. Register a new member using valid credentials (email, password, nickname, optionally avatar_uri).
 * 2. Ensure registration is successful and a valid JWT/access token is issued.
 * 3. Call the get-profile endpoint with the registered member's ID while authenticated as that member.
 * 4. Validate that the response includes all documented profile fields.
 * 5. Confirm that no secret fields (e.g., password_hash or credential secrets) are ever leaked.
 * 6. Check business constraints: Status must be as-expected (probably 'pending_verification'), timestamps valid, and fields match registration input.
 */
export async function test_api_member_profile_self_view_success(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const newMemberInput: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword123!",
    nickname: RandomGenerator.name(),
    avatar_uri: RandomGenerator.pick([
      undefined,
      null,
      `https://picsum.photos/seed/${Math.random().toString(36).slice(2)}/200/200`,
    ]),
  };
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: newMemberInput,
  });
  typia.assert(session);

  // 2. Use member ID from session
  const memberId = session.member.id;

  // 3. Retrieve own profile using unique memberId (must be authenticated)
  const profile = await api.functional.discussionBoard.member.members.at(connection, {
    memberId,
  });
  typia.assert(profile);

  // 4. Validate profile data matches registration (except server-managed fields)
  TestValidator.equals("member id matches")(profile.id)(memberId);
  TestValidator.equals("email matches")(profile.email)(newMemberInput.email);
  TestValidator.equals("nickname matches")(profile.nickname)(newMemberInput.nickname);
  TestValidator.equals("avatar uri matches")(
    (profile.avatar_uri ?? undefined)
  )(newMemberInput.avatar_uri ?? undefined);
  TestValidator.predicate("status is 'pending_verification' or 'active'")(
    profile.status === "pending_verification" || profile.status === "active"
  );
  TestValidator.equals("email_verified false (on registration)")(profile.email_verified)(false);

  // 5. Check that timestamps are ISO date-strings and last_login_at is set
  TestValidator.predicate("joined_at valid ISO")(
    !!Date.parse(profile.joined_at)
  );
  TestValidator.predicate("last_login_at valid ISO")(
    !!Date.parse(profile.last_login_at)
  );
  TestValidator.predicate("created_at valid ISO")(
    !!Date.parse(profile.created_at)
  );
  TestValidator.predicate("updated_at valid ISO")(
    !!Date.parse(profile.updated_at)
  );

  // 6. Confirm no sensitive fields are present (compile-time enforced by type)
  // 7. deleted_at is null or undefined for non-withdrawn user
  TestValidator.equals("not deleted")(profile.deleted_at ?? null)(null);
}

