import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that attempting to retrieve a subcategory by non-existent or deleted category/subcategory IDs returns not found.
 * 
 * Business context:
 * Admins or moderators may attempt to fetch details of a subcategory under a given parent category. If either the parent category (categoryId) or the subcategory (subCategoryId) does not exist or has been deleted (soft-delete), the API should return a not found error and must not expose partial or orphaned category data. This is important for taxonomy integrity and to prevent UI or backend confusion about invalid nodes.
 * 
 * Steps:
 * 1. Attempt to fetch a subcategory with random UUIDs for both parent and subcategory (ensuring the combination does not exist).
 *    - Expect a not found error.
 * 2. (Edge) Attempt with obviously invalid (but properly formatted) UUIDs for both parent and child.
 *    - Expect a not found error.
 * 3. (Edge) Optionally, if category creation/deletion endpoints existed: create parent and child, delete one, then try to fetch again to ensure soft-deleted categories behave as not found. (But such setup is not possible in this context, so only not found by random ids is tested.)
 */
export async function test_api_admin_subcategory_detail_not_found(
  connection: api.IConnection,
) {
  // 1. Attempt with random UUIDs, expect not found error
  await TestValidator.error("should return not found for nonexistent ids")(
    async () => {
      await api.functional.discussionBoard.admin.categories.subs.atSub(connection, {
        categoryId: typia.random<string & tags.Format<"uuid">>(),
        subCategoryId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 2. Attempt with obviously invalid but properly formatted UUIDs, expect not found error
  await TestValidator.error("should return not found for fake but valid UUIDs")(
    async () => {
      await api.functional.discussionBoard.admin.categories.subs.atSub(connection, {
        categoryId: "11111111-1111-1111-1111-111111111111",
        subCategoryId: "22222222-2222-2222-2222-222222222222",
      });
    },
  );

  // No ability to test actual deletion without create/delete endpoints in this context
}

