/**
 * Validates that a non-privileged user is forbidden from accessing a user sanction record.
 *
 * This test ensures strict RBAC enforcement by verifying that only admin or moderator roles can fetch sanction details;
 * regular users (members) or guests must be rejected with access denied. This protects sensitive disciplinary and compliance info from exposure.
 *
 * Steps:
 * 1. As an admin, create a user sanction record needed for test.
 * 2. Simulate a member or guest attempting to fetch that sanction record via the 'at' API endpoint.
 * 3. Assert that the request fails with access denied (typically HTTP 403/401), and no details are returned.
 * 4. Confirm no sensitive sanction data is leaked.
 */
export async function test_api_user_sanction_admin_at_forbidden(connection: api.IConnection) {
  // 1. Create a user sanction record as admin (to get a real userSanctionId for test)
  const created: IDiscussionBoardUserSanction = await api.functional.discussionBoard.admin.userSanctions.create(connection, {
    body: {
      sanctioned_member_id: typia.random<string & tags.Format<"uuid">>(),
      sanctioning_admin_id: typia.random<string & tags.Format<"uuid">>(),
      sanction_type: "warning",
      sanction_level: "minor",
      reason_type: "spam",
      reason_text: "Spamming links in posts",
      timeline_start: new Date().toISOString(),
      timeline_end: null
    } satisfies IDiscussionBoardUserSanction.ICreate
  });
  typia.assert(created);

  // 2. Simulate user switching: remove admin/mod authorization (simulate as member or guest)
  // (Assumption: test infra provides mechanism to clear/replace connection headers for RBAC role)
  // For this test, we clear auth headers to simulate guest access.
  const connectionAsGuest: api.IConnection = {
    ...connection,
    headers: { }
  };

  // 3. Attempt to retrieve the sanction record as a forbidden user (member/guest)
  await TestValidator.error("access denied for non-admin")(
    async () => {
      await api.functional.discussionBoard.admin.userSanctions.at(connectionAsGuest, {
        userSanctionId: created.id
      });
    }
  );
}

