/**
 * Validate error handling when deleting a non-existent or already deleted post report as a moderator.
 *
 * This test ensures that the system returns a proper 'not found' error when a moderator attempts to delete a post report with a non-existent or already deleted postReportId. It also checks that no side-effects occur, confirming the idempotency and safety of the DELETE operation for missing resources.
 *
 * Steps:
 * 1. Generate a random UUID that does not correspond to any existing post report (simulate a missing or already deleted resource).
 * 2. Attempt to perform the erase operation with moderator permissions on this non-existent postReportId.
 * 3. Confirm that the operation fails and triggers a clear runtime error (e.g., a 404 Not Found error).
 * 4. Optionally, ensure repeated deletion yields the same error, verifying idempotency.
 *
 * No prior setup or dependencies are required for this test case.
 */
export async function test_api_post_report_moderator_erase_not_found(connection: api.IConnection) {
  // 1. Generate a random, very likely non-existent post report ID
  const missingPostReportId = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt to delete the non-existent post report as moderator and expect error
  await TestValidator.error("should throw not found error when deleting non-existent report")(async () => {
    await api.functional.discussionBoard.moderator.postReports.erase(connection, {
      postReportId: missingPostReportId,
    });
  });

  // 3. Retry deletion for the same ID to check idempotency (should also error)
  await TestValidator.error("should consistently throw not found error on repeated delete")(async () => {
    await api.functional.discussionBoard.moderator.postReports.erase(connection, {
      postReportId: missingPostReportId,
    });
  });
}

