    body: payload,
  });
  typia.assert(firstLog);
  TestValidator.equals("recipient_email matches")(firstLog.recipient_email)(payload.recipient_email);
  TestValidator.equals("email_type matches")(firstLog.email_type)(payload.email_type);

  // 3. Attempt to create a duplicate email log with the same payload
  await TestValidator.error("duplicate creation should fail")(
