import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostVote";

/**
 * Validate forbidden access to moderator post vote detail endpoint.
 *
 * Business context:
 * - The moderator detail endpoint for post votes must not be accessible by ordinary members or guests.
 * - Attempting to access as a non-moderator must result in a 403 Forbidden error, with no sensitive data exposure.
 *
 * Test Workflow:
 * 1. Create a post vote as a (non-moderator) member.
 * 2. Attempt to retrieve the vote detail from the moderator endpoint as a member; expect 403 Forbidden.
 * 3. Attempt to retrieve the same vote detail from the moderator endpoint as a guest (unauthenticated); expect 403 Forbidden.
 */
export async function test_api_post_vote_detail_moderator_forbidden(connection: api.IConnection) {
  // 1. Create a post vote as an ordinary member
  const postVoteInput: IDiscussionBoardPostVote.ICreate = {
    discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
    is_upvote: true,
  };
  const vote: IDiscussionBoardPostVote = await api.functional.discussionBoard.member.postVotes.create(connection, { body: postVoteInput });
  typia.assert(vote);

  // 2. Attempt to fetch moderator vote detail as member (should be forbidden)
  await TestValidator.error("Member forbidden from moderator endpoint")(async () => {
    await api.functional.discussionBoard.moderator.postVotes.at(connection, { postVoteId: vote.id });
  });

  // 3. Simulate logout by removing auth header to act as guest
  const guestConnection = { ...connection, headers: { ...connection.headers } };
  delete guestConnection.headers["Authorization"];
  await TestValidator.error("Guest forbidden from moderator endpoint")(async () => {
    await api.functional.discussionBoard.moderator.postVotes.at(guestConnection, { postVoteId: vote.id });
  });
}

