/**
 * Test that a moderator can search and paginate user sanction records.
 *
 * This test creates a new user sanction record (as dependency), then performs a search using moderator privileges:
 * - Confirms the sanction entry appears in search results when filtered by sanctioned member.
 * - Verifies paging (page/limit) and basic filter controls (by sanctioned_member_id, sanction_type, active).
 * - Asserts result list returns expected summary fields, no sensitive fields leaked.
 * - Checks basic pagination metadata is consistent.
 *
 * Steps:
 * 1. Create a sanction record against a test member/admin pair (dependency call).
 * 2. Search with filter by sanctioned_member_id and confirm the new record is returned in paged data (page=1, limit=10).
 * 3. Search with irrelevant filters and confirm the record does not appear.
 * 4. Inspect page pagination metadata for correctness.
 * 5. Validate that summary entries do not expose sensitive fields (e.g., admin id, notes).
 */
export async function test_api_user_sanctions_moderator_search_success(connection: api.IConnection) {
  // 1. Create a sanction record for a specific member (using dependency)
  const sanctionCreateInput: IDiscussionBoardUserSanction.ICreate = {
    sanctioned_member_id: typia.random<string & tags.Format<"uuid">>(),
    sanctioning_admin_id: typia.random<string & tags.Format<"uuid">>(),
    sanction_type: "temporary_ban",
    sanction_level: "moderate",
    reason_type: "spam",
    reason_text: "Test moderation",
    timeline_start: new Date().toISOString(),
    timeline_end: null
  };
  const created = await api.functional.discussionBoard.moderator.userSanctions.create(connection, { body: sanctionCreateInput });
  typia.assert(created);

  // 2. Search filtered by sanctioned_member_id (expect record returned)
  const pageLimit = 10;
  const searchResult = await api.functional.discussionBoard.moderator.userSanctions.search(connection, {
    body: {
      sanctioned_member_id: created.sanctioned_member_id,
      page: 1,
      limit: pageLimit
    }
  });
  typia.assert(searchResult);

  // The created sanction must be present in results
  const found = searchResult.data.some(r => r.id === created.id);
  TestValidator.predicate("sanction should be found in search result")(found);

  // Validate summary fields (no admin id, reason text)
  const retrieved = searchResult.data.find(r => r.id === created.id);
  if (retrieved) {
    TestValidator.equals("sanctioned_member_id matches")(retrieved.sanctioned_member_id)(created.sanctioned_member_id);
    TestValidator.equals("sanction_type matches")(retrieved.sanction_type)(created.sanction_type);
    // summary must not expose sanctioning_admin_id or reason_text
    TestValidator.predicate("summary should not have sanctioning_admin_id")(!("sanctioning_admin_id" in retrieved));
    TestValidator.predicate("summary should not have reason_text")(!("reason_text" in retrieved));
  }

  // 3. Search with filter that excludes this entry (wrong member id and type)
  const irrelevantResult = await api.functional.discussionBoard.moderator.userSanctions.search(connection, {
    body: {
      sanctioned_member_id: typia.random<string & tags.Format<"uuid">>(),
      sanction_type: "warning",
      page: 1,
      limit: pageLimit
    }
  });
  typia.assert(irrelevantResult);
  const notFound = irrelevantResult.data.every(r => r.id !== created.id);
  TestValidator.predicate("created sanction not returned when filter is irrelevant")(notFound);

  // 4. Paging checks (pagination fields present and match expectations)
  TestValidator.equals("pagination.limit matches")(searchResult.pagination.limit)(pageLimit);
  TestValidator.equals("pagination.current page is 1")(searchResult.pagination.current)(1);
  TestValidator.predicate("pagination.records should be >= 1")(searchResult.pagination.records >= 1);
  TestValidator.predicate("pagination.pages should be >= 1")(searchResult.pagination.pages >= 1);
}

