/**
 * Validates that only admin or moderator roles may access the advanced search endpoint for comment report moderation; access must be denied for normal members and guests (unauthenticated users).
 *
 * - Registers a normal discussion board member, then attempts to use the admin search for comment reports as that member (should be forbidden).
 * - Attempts to use the admin search endpoint as a guest (unauthenticated, no token), also expected to be forbidden.
 * - Asserts that both attempts fail with forbidden error (do not return valid data), and that there is no data leakage (response must not leak collection or entity data for unauthorized calls).
 *
 * Steps:
 * 1. Register a discussion board member
 * 2. Attempt admin comment report search as this normal member - expect error
 * 3. Attempt admin comment report search as a guest (no user) - expect error
 * 4. (Edge case) Confirm that if any forbidden response returns data, it is never any report entity
 */
export async function test_api_comment_report_admin_search_no_permission(connection: api.IConnection) {
  // 1. Register a normal member (forbidden user)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "!Test1234";
  const nickname = RandomGenerator.name();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname,
    }
  });
  typia.assert(session);

  // 2. Attempt admin comment report search as the registered member (should be forbidden)
  let memberError: unknown = null;
  try {
    await api.functional.discussionBoard.admin.commentReports.search(connection, {
      body: {
        page: 1,
        limit: 10
      }
    });
  } catch (err) {
    memberError = err;
  }
  TestValidator.predicate("member forbidden error thrown")(!!memberError);

