import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardEmailLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardEmailLog";

/**
 * Validate updating an existing outgoing email log as an admin, including audit/version changes.
 *
 * This test ensures:
 * - The ability to update information such as the recipient_email, delivery_status, and provider responses
 * - Correct schema and business validation of inputs
 * - All changes are reflected, and audit/versioned fields (like updated_at) are modified
 *
 * Test workflow:
 * 1. Create a new email log via POST as admin with full required metadata
 * 2. Perform a PUT update by id, updating: recipient_email, delivery_status, and response_message
 * 3. Assert: changed fields have new values, others are unchanged, and updated_at differs
 * 4. Type assertion and field-level business rule validation
 */
export async function test_api_email_log_update_success(connection: api.IConnection) {
  // 1. Create initial email log
  const initialInput: IDiscussionBoardEmailLog.ICreate = {
    recipient_email: typia.random<string & tags.Format<"email">>(),
    email_type: "verification",
    subject: "Welcome to the Board!",
    sent_at: new Date().toISOString(),
    delivery_status: "SENT",
    response_code: null,
    response_message: null,
    external_message_id: null
  };
  const created = await api.functional.discussionBoard.admin.emailLogs.create(connection, { body: initialInput });
  typia.assert(created);

  // 2. Prepare update
  const updateInput: IDiscussionBoardEmailLog.IUpdate = {
    recipient_email: typia.random<string & tags.Format<"email">>(),
    delivery_status: "DELIVERED",
    response_message: "Accepted and delivered by provider."
  };
  const updated = await api.functional.discussionBoard.admin.emailLogs.update(connection, {
    emailLogId: created.id,
    body: updateInput
  });
  typia.assert(updated);

  // 3. Assert only the updated fields changed; updated_at has changed
  TestValidator.notEquals("updated_at should change on update")(updated.updated_at)(created.updated_at);
  TestValidator.equals("recipient_email updated")(updated.recipient_email)(updateInput.recipient_email);
  TestValidator.equals("delivery_status updated")(updated.delivery_status)(updateInput.delivery_status);
  TestValidator.equals("response_message updated")(updated.response_message)(updateInput.response_message);
  // All other fields should match the original (where unchanged)
  TestValidator.equals("id remains")(updated.id)(created.id);
  TestValidator.equals("email_type remains")(updated.email_type)(created.email_type);
  TestValidator.equals("subject remains")(updated.subject)(created.subject);
  TestValidator.equals("sent_at remains")(updated.sent_at)(created.sent_at);
  TestValidator.equals("response_code remains")(updated.response_code)(created.response_code);
  TestValidator.equals("external_message_id remains")(updated.external_message_id)(created.external_message_id);
}

