 *
 * This test covers the full business rule cycle:
 * 1. Register a new moderator (requires unique moderator email and assigned admin email).
 * 2. Create a platform config as an admin (using the admin context that can assign moderators).
 * 3. As the moderator (using JWT/session from sign-up), retrieve the config by ID.
 * 4. Validate the returned object contains required fields (ID, config fields, enabled, version, description, all audit/meta fields).
 * 5. Ensure the moderator's permissions suffice for reading (but not modifying) the config.
 * 6. Cleanly assert type, field presence, and business rule invariants.
 */
export async function test_api_platform_config_detail_moderator_success(connection: api.IConnection) {
  // 1. Register a new moderator (simulate admin acting as assigner)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const signUpResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: "testPassword123!",
    } satisfies IModerator.SignUp,
  });
  typia.assert(signUpResponse);

  // The response provides a session token and setHeaders.Autorization (SDK stores for us, so next call is authenticated)

  // 2. Create a new platform configuration as an admin
  // (Assume the initial connection context is admin-authenticated)
  const configCreate = {
    config_name: `feature_flag_${Date.now()}`,
    config_value: JSON.stringify({ enabled: true, x: typia.random<number>() }),
    enabled: true,
    version: 1,
    description: "Test feature flag from E2E test.",
  } satisfies IDiscussionBoardPlatformConfig.ICreate;
  const createdConfig = await api.functional.discussionBoard.admin.platformConfigs.create(connection, { body: configCreate });
  typia.assert(createdConfig);

