  // SDK's auto header management means the token from moderator registration is already in connection
  const result = await api.functional.discussionBoard.moderator.platformConfigs.at(connection, {
    platformConfigId: createdConfig.id,
  });
  typia.assert(result);
  // 4. Validate required fields and audit trail present
  TestValidator.equals("id matches")(result.id)(createdConfig.id);
  TestValidator.equals("config_name matches")(result.config_name)(configCreate.config_name);
