 * 2. Create sub-category A under the parent, with a unique name.
 * 3. Create sub-category B under the same parent, with a different unique name.
 * 4. Attempt to update sub-category B's name to the same as sub-category A's name (should now violate uniqueness).
 * 5. Validate that the update API call fails with an error (conflict/validation).
 * 6. Check that sub-category B's data (name) has not changed.
 */
export async function test_api_subcategory_update_to_duplicate_name(connection: api.IConnection) {
  // 1. Create parent category
  const parentCategoryName = RandomGenerator.alphabets(10);
  const parentCategory: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: parentCategoryName,
      display_order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
      version: 1,
      description: null,
      icon_uri: null,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(parentCategory);

  // 2. Create sub-category A
  const subAName = RandomGenerator.alphabets(10);
  const subA: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
    categoryId: parentCategory.id,
    body: {
      name: subAName,
      display_order: 1,
      enabled: true,
      version: 1,
      parent_id: parentCategory.id,
      description: null,
      icon_uri: null,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(subA);

  // 3. Create sub-category B
  const subBName = RandomGenerator.alphabets(10);
  const subB: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
    categoryId: parentCategory.id,
    body: {
      name: subBName,
      display_order: 2,
      enabled: true,
      version: 1,
      parent_id: parentCategory.id,
      description: null,
      icon_uri: null,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(subB);

  // 4. Attempt to update sub-category B's name to sub-category A's name
  await TestValidator.error("sub-category name duplication should fail")(async () => {
    await api.functional.discussionBoard.admin.categories.subs.updateSubCategory(connection, {
      categoryId: parentCategory.id,
      subCategoryId: subB.id,
      body: {
        name: subAName,
      } satisfies IDiscussionBoardCategory.IUpdate,
    });
  });

  // 5. Confirm sub-category B remains unchanged
  // Since there is no reload API for sub-category, assert using last known value
  TestValidator.equals("sub-category B name remains unchanged")(subB.name)(subBName);
}

