  connection: api.IConnection,
) {
  // 1. Create a policy document for database seed
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const createdDoc = await api.functional.discussionBoard.admin.policyDocuments.create(connection, {
    body: {
      title: "Terms of Service",
      body: "Example body content.",
