 * 4. Call moderator "get by categoryId" endpoint with the created category's ID
 * 5. Check that all properties (id, parent_id, name, description, display_order, icon_uri, enabled, version, created_at, updated_at, deleted_at) exist and match what was created, including audit fields
 * 6. Confirm proper retrieval and visibility per role policy
 */
export async function test_api_category_detail_view_success_moderator(connection: api.IConnection) {
