  const categoryCreate: IDiscussionBoardCategory.ICreate = {
    name: `TestCategory_${Date.now()}`,
    display_order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
    version: 1,
    parent_id: null,
    description: "E2E test category for moderator detail access.",
