  TestValidator.equals("id")(detail.id)(category.id);
  TestValidator.equals("parent_id")(detail.parent_id)(category.parent_id ?? null);
  TestValidator.equals("name")(detail.name)(category.name);
  TestValidator.equals("description")(detail.description)(category.description);
  TestValidator.equals("display_order")(detail.display_order)(category.display_order);
