 * 2. As admin, create a new post (capture postId).
 * 3. Soft-delete the post with the admin's authorization.
 * 4. Fetch post detail (if possible) and validate 'deleted_at' and 'status'; if not possible, verify directly after creation and deletion steps.
 */
export async function test_api_post_soft_delete_by_admin_success(connection: api.IConnection) {
