  const sanctioningAdmin = memberRes.data.find(m => m.status === "admin") || memberRes.data[0];

  // 2. Prepare unique combination for the sanction record
  const now = new Date();
  const timeline_start = now.toISOString();
  const timeline_end = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(); // +1 day for a temporary ban

