 *
 * Test Workflow:
 * 1. Register a new admin via /auth/admin/register, confirming JWT and headers are returned.
 * 2. As the new admin, create a new post metrics entry via /discussionBoard/admin/postMetrics with valid counts and a valid (assumed pre-existing) post UUID.
 * 3. Validate response: all fields are populated with correct types/values, e.g. all initialized counts are reflected, timestamps are in valid format, and the returned discussion_board_post_id matches input.
 * 4. Error validation: attempt duplicate metric creation for the same post id and assert that an error is thrown (uniqueness constraint).
 */
export async function test_api_post_metrics_creation_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPassw0rd!";
  const adminResp: IDiscussionBoardAdminAuthResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminResp);
  // Use returned access_token for further requests
  connection.headers = {
    ...connection.headers,
    Authorization: adminResp.setHeaders.Authorization,
  };

  // 2. Create a post metric as admin (using valid/unique post UUID)
  const postId = typia.random<string & tags.Format<"uuid">>();
  const metricsInput: IDiscussionBoardPostMetric.ICreate = {
    discussion_board_post_id: postId,
    views_count: 0,
    comments_count: 0,
    votes_up_count: 0,
    votes_down_count: 0,
    reports_count: 0,
    last_activity_at: null,
  };
  const createdMetric: IDiscussionBoardPostMetric = await api.functional.discussionBoard.admin.postMetrics.create(connection, {
    body: metricsInput,
  });
  typia.assert(createdMetric);
  TestValidator.equals("post id matches")(createdMetric.discussion_board_post_id)(postId);
  TestValidator.equals("views initialized")(createdMetric.views_count)(0);
  TestValidator.equals("comments initialized")(createdMetric.comments_count)(0);
  TestValidator.equals("votes up initialized")(createdMetric.votes_up_count)(0);
  TestValidator.equals("votes down initialized")(createdMetric.votes_down_count)(0);
  TestValidator.equals("reports initialized")(createdMetric.reports_count)(0);
  TestValidator.equals("last activity null")(createdMetric.last_activity_at)(null);

