  if (!/^[0-9a-fA-F-]{36}$/.test(createdMetric.id)) throw new Error("Invalid metric UUID");
  if (isNaN(Date.parse(createdMetric.created_at))) throw new Error("Invalid created_at");
  if (isNaN(Date.parse(createdMetric.updated_at))) throw new Error("Invalid updated_at");

  // 3. Attempt duplicate metric creation for the same post (should fail integrity constraint)
  TestValidator.error("duplicate post metric creation should fail")(async () => {
    await api.functional.discussionBoard.admin.postMetrics.create(connection, {
      body: metricsInput,
    });
  });
}

