/**
 * Test successful update of an admin's profile, status, or assignment.
 *
 * This scenario validates the ability of the system to update only the allowed fields on an admin's record—specifically status and revoked_at—while ensuring that immutable fields (such as created_at and assigned_at) remain unchanged. It covers the business workflow from admin registration to profile/status update and includes comprehensive validation of audit and immutable fields.
 *
 * Steps:
 * 1. Register a new admin using the dedicated admin registration endpoint.
 * 2. Capture relevant information for the created admin (such as id, email, status, assigned_at, etc).
 * 3. Use the admin's id to update profile fields allowed by schema: status and revoked_at.
 * 4. Retrieve the resulting admin record and assert:
 *    - status and revoked_at reflect the updates
 *    - immutable fields (created_at, assigned_at, email, id) are unchanged
 *    - updated_at is changed to reflect the update operation
 *    - deleted_at remains null
 * 5. Test a negative update (attempting to supply an immutable field) is omitted because only updatable fields are accepted by the API.
 */
export async function test_api_admin_update_profile_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPass123!";

  const registerResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(registerResponse);

  // 2. Capture created admin's data
  const adminId = registerResponse.admin_id;
  const originalEmail = registerResponse.email;

  // 3. Prepare a permitted update: change status and supply revoked_at field
  const newStatus = "suspended";
  const newRevokedAt = new Date().toISOString();
  const updateBody = {
    status: newStatus,
    revoked_at: newRevokedAt,
  } satisfies IDiscussionBoardAdmin.IUpdate;

  const updatedAdmin = await api.functional.discussionBoard.admin.admins.update(connection, {
    adminId: adminId,
    body: updateBody,
  });
  typia.assert(updatedAdmin);

  // 4. Assert fields
  // Updatable fields changed
  TestValidator.equals("status updated")(updatedAdmin.status)(newStatus);
  TestValidator.equals("revoked_at updated")(updatedAdmin.revoked_at)(newRevokedAt);
  // Immutable fields unchanged
  TestValidator.equals("ID unchanged")(updatedAdmin.id)(adminId);
  TestValidator.equals("email unchanged")(updatedAdmin.email)(originalEmail);
  // Immutable assigned_at and created_at exist and are not empty (format validation handled by typia.assert)
  TestValidator.predicate("assigned_at remains set")(
    typeof updatedAdmin.assigned_at === "string" && updatedAdmin.assigned_at.length > 0
  );
  TestValidator.predicate("created_at remains set")(
    typeof updatedAdmin.created_at === "string" && updatedAdmin.created_at.length > 0
  );
  // Audit field updated_at updated to (roughly) now
  TestValidator.predicate("updated_at reflects update")(
    new Date(updatedAdmin.updated_at).getTime() >= new Date(newRevokedAt).getTime()
  );
  // deleted_at remains null or undefined
  TestValidator.equals("deleted_at unchanged or null")(updatedAdmin.deleted_at ?? null)(null);
}

