  // 1. Create a new policy change log entry (as admin)
  const newPolicyChangeLogBody: IDiscussionBoardPolicyChangeLog.ICreate = {
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
    policy_namespace: "moderation",
    target_table: "discussion_board_settings",
    target_field: "max_report_count",
    previous_value: "5",
    new_value: "10",
    change_reason: "Policy update as per compliance review."
  };
