/**
 * Validate that the admin search endpoint returns an empty paginated result when searched with filters that match no admin records.
 *
 * This test verifies the robustness of search filters and pagination logic by using filters that are guaranteed not to match any admins (such as a nonexistent status and a future-only assignment window). The function ensures that when such filters are applied, the endpoint returns an empty `data` array along with correct pagination metadata, instead of throwing errors or returning invalid responses.
 *
 * Business rationale: Even if no admins match provided filters, the admin management interface must respond predictably and safely. Admin-facing tools often support advanced search, and admins will commonly input invalid, edge, or extreme filters either on purpose or by mistake. A correct implementation must not produce errors or misleading data but should return the proper empty search result format.
 *
 * Process steps:
 * 1. Register at least one admin so the environment is not empty and base behavior can be validated.
 * 2. Call the admin search endpoint with filter parameters that can never match any record (impossible status, assignment date range in the far future).
 * 3. Confirm that the response is an empty page with `data: []` and valid pagination structure, not an error or undefined result.
 */
export async function test_api_admin_search_invalid_filters_returns_empty_page(connection: api.IConnection) {
  // 1. Register at least one admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminRegisterResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "StrongPassword123!",
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRegisterResponse);

  // 2. Search admins with impossible filters: status that doesn't exist and a far future assign range
  const impossibleStatus = "impossible_status";
  const farFutureFrom = "2100-01-01T00:00:00.000Z";
  const farFutureTo = "2100-12-31T23:59:59.999Z";
  const searchResult = await api.functional.discussionBoard.admin.admins.search(connection, {
    body: {
      status: impossibleStatus,
      assigned_at_from: farFutureFrom,
      assigned_at_to: farFutureTo,
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardAdmin.IRequest,
  });
  typia.assert(searchResult);

  // 3. Confirm the response is empty (no data) and pagination is valid
  TestValidator.equals("no results with impossible filter")(searchResult.data.length)(0);
  TestValidator.equals("pagination meta: current page is 1")(searchResult.pagination.current)(1);
  TestValidator.equals("pagination meta: limit matches filter")(searchResult.pagination.limit)(10);
  TestValidator.equals("pagination meta: records is 0")(searchResult.pagination.records)(0);
  TestValidator.equals("pagination meta: pages is 0")(searchResult.pagination.pages)(0);
}

