 * 3. Use the admin-authenticated session (with Authorization header) to create the policy document.
 * 4. Validate the response: correct title, body, version, is_active status, created_by_admin_id, created_at, updated_at fields are returned with correct formats/values; deleted_at is null or omitted.
 * 5. Optionally, attempt to create another document with the same (title, version) pair to confirm duplication is disallowed (should fail, but this is outside of "success" scope).
 */
export async function test_api_policy_document_creation_success(
  connection: api.IConnection,
) {
