    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminRegisterResponse);
  const adminId = adminRegisterResponse.admin_id;

  // Set Authorization header from registration (JWT issued on signUp)
  connection.headers = {
    ...connection.headers,
    Authorization: adminRegisterResponse.setHeaders.Authorization
  };

  // 2. Prepare unique policy document creation data
  const policyTitle = `Policy - ${RandomGenerator.alphabets(12)}`;
  const policyBody = "# Terms of Service\n\nWelcome to our community. Please read carefully.";
  const policyVersion = typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<10000>>();
  const isActive = true;
  const policyCreateBody = {
    title: policyTitle,
    body: policyBody,
    version: policyVersion,
    is_active: isActive,
    created_by_admin_id: adminId
  } satisfies IDiscussionBoardPolicyDocument.ICreate;

  // 3. Create the policy document as admin
  const createdPolicy = await api.functional.discussionBoard.admin.policyDocuments.create(connection, {
    body: policyCreateBody
  });
  typia.assert(createdPolicy);

  // 4. Validate the response (all business & audit fields)
  TestValidator.equals("title matches")(createdPolicy.title)(policyCreateBody.title);
  TestValidator.equals("body matches")(createdPolicy.body)(policyCreateBody.body);
  TestValidator.equals("version matches")(createdPolicy.version)(policyCreateBody.version);
  TestValidator.equals("is_active is correct")(createdPolicy.is_active)(policyCreateBody.is_active);
  TestValidator.equals("created_by_admin_id matches")(createdPolicy.created_by_admin_id)(policyCreateBody.created_by_admin_id);
  TestValidator.predicate("created_at must be valid ISO-8601 date")(
    !isNaN(Date.parse(createdPolicy.created_at))
  );
  TestValidator.predicate("updated_at must be valid ISO-8601 date")(
    !isNaN(Date.parse(createdPolicy.updated_at))
  );
  TestValidator.equals("deleted_at must be null or omitted")(
    createdPolicy.deleted_at === undefined || createdPolicy.deleted_at === null
  )(true);
};

