import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that a discussion board member can search and filter their own notifications.
 *
 * Business context: Members use the notification center UI to view, filter, and paginate notifications such as post comments, sanctions, or site messages. Notifications must only show those for the currently authenticated member, without leaking moderator/admin/guest data. Admin creates notification(s) for this member, and member must be able to search them with appropriate filters (including read/unread, pagination, and event type).
 *
 * Workflow steps:
 * 1. Register a new member (POST /auth/member/register)
 * 2. Admin generates several notifications for this member (POST /discussionBoard/admin/notifications)
 * 3. Search for notifications as the member (PATCH /discussionBoard/member/notifications) and verify:
 *    - Only notifications for this member are returned
 *    - Can filter by unread status (true/false)
 *    - Pagination results are correct
 *    - All fields for the notification row are present and populated as per ISummary
 *    - Edge: Confirm no notifications received by creating for another recipient (admin/mod/guest)
 */
export async function test_api_notification_member_search_success(connection: api.IConnection) {
  // 1. Register new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: "VerySecurePw123!",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);
  const memberId = memberSession.member.id;

  // 2. Admin creates notifications
  // Switch to admin context assumed (system test runner/admin privilege)
  const notification1 = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      member_id: memberId,
      title: "Test Notification 1",
      body: "Body A",
      event_type: "post_comment",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notification1);
  const notification2 = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      member_id: memberId,
      title: "Test Notification 2",
      body: "Body B",
      event_type: "sanction",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notification2);
  // Create extra notification for different user to prove not leaked
  const notificationOther = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      admin_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Other Admin Notification",
      body: "Admin only",
      event_type: "post_comment",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notificationOther);

  // 3. Search: member notification search for all notifications
  const searchAll = await api.functional.discussionBoard.member.notifications.search(connection, {
    body: {
      recipient_role: "member",
      recipient_id: memberId,
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardNotification.IRequest,
  });
  typia.assert(searchAll);
  // Confirm only our notifications are returned
  for (const row of searchAll.data) {
    TestValidator.equals("notification for member only")(row.id)(notification1.id === row.id || notification2.id === row.id ? row.id : undefined);
    TestValidator.predicate("required fields in summary")(
      !!row.title && typeof row.body === "string" && typeof row.event_type === "string" && typeof row.unread === "boolean" && typeof row.created_at === "string"
    );
  }

  // 4. Filter unread (should all be unread initially)
  const searchUnread = await api.functional.discussionBoard.member.notifications.search(connection, {
    body: {
      recipient_role: "member",
      recipient_id: memberId,
      unread: true,
      limit: 10,
      page: 1,
    } satisfies IDiscussionBoardNotification.IRequest,
  });
  typia.assert(searchUnread);
  TestValidator.predicate("all unread in filter")(searchUnread.data.every(row => row.unread === true));

  // 5. Filter by event_type
  const searchType = await api.functional.discussionBoard.member.notifications.search(connection, {
    body: {
      recipient_role: "member",
      recipient_id: memberId,
      event_type: "sanction",
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardNotification.IRequest,
  });
  typia.assert(searchType);
  TestValidator.equals("returns only 'sanction' type")(
    searchType.data.length === 1 && searchType.data[0].event_type === "sanction"
  )(true);
}

