import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that a published discussion post can be accessed publicly (as a guest user).
 *
 * Business context:
 * - Posts with status 'active' (not soft-deleted) are meant to be visible to all users, including unauthenticated guests.
 * - This test ensures that an anonymous (guest) user can retrieve details of an active, published post by its postId, and verifies all key fields are returned.
 *
 * Steps:
 * 1. Register a new member for the discussion board using /auth/member/register (required to be able to create a post).
 * 2. As this authenticated member, create a discussion post via /discussionBoard/member/posts using valid data.
 * 3. Capture the postId, and confirm the returned post has status 'active' and is not soft-deleted.
 * 4. Simulate a guest/anonymous session by stripping (or not sending) authentication information from the connection object.
 * 5. As a guest, retrieve the post details using /discussionBoard/posts/{postId}.
 * 6. Verify all visible/public fields are present (title, body, category context, author linkage, attachments, created/updated, etc.).
 * 7. Ensure the returned post is the one expected, is not soft-deleted, and status is 'active'.
 * 8. Ensure there is no not found (404) or forbidden error for this active post.
 */
export async function test_api_post_detail_public_access(
  connection: api.IConnection,
) {
  // 1. Register discussion board member
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const memberNickname = RandomGenerator.name();
  const registerRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: 'pw' + RandomGenerator.alphaNumeric(8),
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(registerRes);
  const memberId = registerRes.member.id;

  // 2. Create post as member
  const postTitle = RandomGenerator.paragraph()().substring(0, 80);
  const postBody = RandomGenerator.content()()().substring(0, 2000);
  const createRes = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: postTitle,
      body: postBody,
