import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Validate that an admin can retrieve all detailed information for a specific subcategory within the discussion board taxonomy.
 *
 * This test ensures the API correctly returns all business-related and audit fields for a subcategory, guaranteeing data integrity between create and read workflows, as well as correct handling of parent-child relationships in the category hierarchy.
 *
 * Step-by-step process:
 * 1. Create a root (parent) category with random data.
 * 2. Under that parent category, create a subcategory with distinct random values.
 * 3. Fetch (read) the subcategory details using its ID and the parent category ID as admin.
 * 4. Assert that all returned values (name, description, status, parent_id, display_order, icon_uri, enabled, version, audit fields) match what was provided at creation and as returned in creation response.
 * 5. Confirm parent linkage (parent_id) points to the correct parent category.
 * 6. Assert audit fields (created_at, updated_at, version) are properly populated, consistent, and reasonable.
 */
export async function test_api_admin_subcategory_detail_success(
  connection: api.IConnection,
) {
  // 1. Create the parent category
  const parentInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphaNumeric(12),
    display_order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
    version: 1,
    description: RandomGenerator.paragraph()(),
    icon_uri: null,
  };
  const parentCategory: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: parentInput,
  });
  typia.assert(parentCategory);

  // 2. Create the subcategory under parent
  const subInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphaNumeric(12),
    display_order: typia.random<number & tags.Type<"int32">>(),
    enabled: false,
    version: 1,
    parent_id: parentCategory.id,
    description: RandomGenerator.paragraph()(),
    icon_uri: null,
  };
  const subCategory: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
    categoryId: parentCategory.id,
    body: subInput,
  });
  typia.assert(subCategory);

  // 3. Fetch the subcategory details as admin
  const obtained: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.subs.atSub(connection, {
    categoryId: parentCategory.id,
    subCategoryId: subCategory.id,
  });
  typia.assert(obtained);

  // 4. Assert all relevant metadata fields - business + audit
  TestValidator.equals("subcategory id matches")(obtained.id)(subCategory.id);
  TestValidator.equals("subcategory name")(obtained.name)(subInput.name);
  TestValidator.equals("subcategory display_order")(obtained.display_order)(subInput.display_order);
  TestValidator.equals("subcategory enabled")(obtained.enabled)(subInput.enabled);
  TestValidator.equals("subcategory version")(obtained.version)(subInput.version);
  TestValidator.equals("subcategory description")(obtained.description)(subInput.description);
  TestValidator.equals("subcategory icon_uri")(obtained.icon_uri)(subInput.icon_uri);
  TestValidator.equals("subcategory parent linkage")(obtained.parent_id)(parentCategory.id);
  // Audit fields - existence and reasonable timestamp logic
  TestValidator.predicate("created_at present")(typeof obtained.created_at === "string" && obtained.created_at.length > 0);
  TestValidator.predicate("updated_at present")(typeof obtained.updated_at === "string" && obtained.updated_at.length > 0);
  // created_at and updated_at should be equal right after creation
  TestValidator.equals("audit timestamps match")(obtained.created_at)(obtained.updated_at);
  // The returned subcategory should not be deleted
  TestValidator.equals("not soft-deleted")(obtained.deleted_at)(null);
}

