 *
 * This test ensures that a moderator account can update any comment on any discussion post, at any time regardless of original authorship or edit time window. It validates privilege override and proper audit trail update.
 *
 * The business workflow covered:
 * 1. Register a moderator (via /auth/moderator/register)
 * 2. Create a new post as moderator (via /discussionBoard/moderator/posts)
 * 3. Add a comment to the post (as the same moderator)
 * 4. Update the comment as moderator using the update endpoint (privileged scenario)
 * 5. Validate updated fields including audit/updated_at, new body text, and unchanged post/comment id/author.
 *
 * Steps:
 *  - Create a unique admin email so that moderator registration (assigned_by_admin_email) is accepted
 *  - Register and authenticate moderator account
 *  - Create a post as moderator
 *  - Add a comment to the post as moderator
 *  - Update the comment body field as the moderator
 *  - Assert that the comment's id, post_id, and author_moderator_id fields are unchanged, status is still 'active', updated_at is updated, and new body is exactly as sent
 */
export async function test_api_comment_update_by_moderator_success(connection: api.IConnection) {
  // 1. Simulate admin assigning a moderator account.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "modpass1234";
  const signup = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp
  });
  typia.assert(signup);

  // 2. Moderator creates a post
  const post = await api.functional.discussionBoard.moderator.posts.create(connection, {
    body: {
      title: "Sample Post by Moderator",
      body: "Initial post content.",
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 3. Moderator adds a comment
  const comment = await api.functional.discussionBoard.moderator.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: "Original comment content by moderator."
    } satisfies IDiscussionBoardComment.ICreate
  });
  typia.assert(comment);

  // 4. Moderator updates the comment body
  const updatedBody = "Edited by moderator (privileged update).";
  const updated = await api.functional.discussionBoard.moderator.posts.comments.update(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      body: updatedBody
    } satisfies IDiscussionBoardComment.IUpdate
  });
  typia.assert(updated);
  // 5. Validate post/comment integrity & audit fields
  TestValidator.equals("comment id unchanged")(updated.id)(comment.id);
  TestValidator.equals("post_id unchanged")(updated.post_id)(comment.post_id);
  TestValidator.equals("author moderator unchanged")(updated.author_moderator_id)(comment.author_moderator_id);
  TestValidator.equals("status remains active")(updated.status)(comment.status);
  TestValidator.equals("body updated")(updated.body)(updatedBody);
  TestValidator.predicate("updated_at is later")(Date.parse(updated.updated_at) >= Date.parse(comment.updated_at));
}

