import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate that duplicate admin comment submissions on a post are blocked (no duplicate record, no side effect).
 *
 * This test checks that, if the same payload for a comment is submitted twice in rapid succession (e.g., accidental double-submit), the system does NOT create duplicate comments or have unintended effects. Instead, it should only create one comment, or throw a duplicate error on the second try.
 *
 * Test process:
 * 1. Register a new admin account (for clean auth context).
 * 2. Create a post as admin (to ensure post exists).
 * 3. Submit a comment on that post as admin (capture the body/payload, so we can resend it).
 * 4. Quickly submit exactly the same comment payload a second time for that post as admin.
 *    - Acceptable outcomes: (a) duplicate error on 2nd attempt; (b) idempotency policy: only one comment is created for same payload repeated very closely in time.
 * 5. Validate result: only one comment should exist for that admin/post/payload combination; no duplicate records, no extra side effects.
 */
export async function test_api_post_comment_creation_duplicate_submission_blocked(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "p@ssw0rd!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminAuth);
  TestValidator.equals("admin email matches")(adminAuth.email)(adminEmail);
  // Auth token set on connection automatically after signUp.

  // 2. Create a target post as the authenticated admin
  const postBody: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()().substring(0, 100),
    body: RandomGenerator.content()()().substring(0, 4000),
    // category_id, platform_config_id, attachments: all optional
  };
  const post = await api.functional.discussionBoard.admin.posts.create(connection, {
    body: postBody,
  });
  typia.assert(post);
  TestValidator.equals("post title matches")(post.title)(postBody.title);

  // 3. Submit a comment (capture payload)
  const commentPayload: IDiscussionBoardComment.ICreate = {
    body: RandomGenerator.paragraph()().substring(0, 1000),
  };
  const comment1 = await api.functional.discussionBoard.admin.posts.comments.create(connection, {
    postId: post.id,
    body: commentPayload,
  });
  typia.assert(comment1);
  TestValidator.equals("comment post_id matches")(comment1.post_id)(post.id);
  TestValidator.equals("comment body matches")(comment1.body)(commentPayload.body);

  // 4. Submit the very same comment again (simulate accidental double-submit)
  let duplicateCaught = false;
  let comment2: typeof comment1 | undefined = undefined;
  try {
    comment2 = await api.functional.discussionBoard.admin.posts.comments.create(connection, {
      postId: post.id,
      body: commentPayload,
    });
    typia.assert(comment2);
  } catch (_err) {
    duplicateCaught = true;
  }
  // Acceptable outcomes: Either duplicate error is thrown, or second submission returns the same comment (idempotency). If no error, only one's allowed.
  if (!duplicateCaught && comment2) {
    TestValidator.equals("idempotent duplicate submission gives same comment id")(comment2.id)(comment1.id);
  }
  TestValidator.predicate("duplicate comment submission handled correctly")(duplicateCaught || (comment2 !== undefined && comment2.id === comment1.id));
}

