 * 1. Create at least two user sanction records via admin create endpoint (different types, users, and reasons).
 * 2. Search for sanctions without filters and validate both appear in search result (pagination metadata and summary structure).
 * 3. Filter by sanction_type for the first sanction and verify only the matching record is returned.
 * 4. Filter by sanctioned_member_id for the second sanction and verify only the matching record is returned.
 * 5. Filter by active=true and deleted_at=nil to confirm only active, non-deleted records are returned.
 * 6. Confirm pagination metadata (current page, limit, record count) is accurate for 1-page scenario.
 * 7. Use limit=1 to confirm pagination splits results and both records appear across pages as expected.
 * 8. Verify summary fields (id, sanctioned_member_id, sanction_type, level, reason_type, active, timeline_start, etc.) are present and accurate.
 */
export async function test_api_user_sanctions_admin_search_basic_pagination(connection: api.IConnection) {
  // 1. Create two user sanction records as admin
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const user1: string = typia.random<string & tags.Format<"uuid">>();
  const user2: string = typia.random<string & tags.Format<"uuid">>();
  const type1 = "warning";
  const type2 = "temporary_ban";
  const level1 = "minor";
  const level2 = "severe";
  const reason1 = "spam";
  const reason2 = "hate";
  const now = new Date();
  const start1 = now.toISOString();
  const start2 = new Date(now.getTime() + 10000).toISOString();

  const sanctionA = await api.functional.discussionBoard.admin.userSanctions.create(connection, {
    body: {
      sanctioned_member_id: user1,
      sanctioning_admin_id: adminId,
      sanction_type: type1,
      sanction_level: level1,
      reason_type: reason1,
      reason_text: "Unsolicited spam messages",
      timeline_start: start1,
      timeline_end: null,
    },
