  const sanctionB = await api.functional.discussionBoard.admin.userSanctions.create(connection, {
    body: {
      sanctioned_member_id: user2,
      sanctioning_admin_id: adminId,
      sanction_type: type2,
      sanction_level: level2,
      reason_type: reason2,
      reason_text: "Hate speech content",
      timeline_start: start2,
      timeline_end: null,
    },
