import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPermissionMatrix } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPermissionMatrix";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test successful creation of a new permission matrix entry in the discussion board system.
 *
 * Business context:
 * Role-based access control (RBAC) is foundational to secure discussion board management. Only authenticated admin users should be able to create permission matrix entries that define access rules for roles, resources, and actions the admin interface allows. This test ensures that a newly registered admin can create a permission matrix entry, that the returned entry is auditable, and that all defined fields are returned and properly set.
 *
 * Steps:
 * 1. Register a new admin user via the dedicated registration endpoint.
 * 2. Authenticate as that admin to obtain JWT credentials (the API SDK manages connection headers automatically).
 * 3. Create a new permission matrix policy using allowed RBAC fields (role, resource, action, etc).
 * 4. Validate that the response contains the full matrix fields as specified (role_name, resource, action, allowed, effective_from, effective_to, audit fields, etc).
 * 5. Optional: Confirm the returned data contains correct audit information (created_at, updated_at, etc) and is suitable for logging/compliance.
 */
export async function test_api_permission_matrix_creation_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestAdmin123!";
  const registration = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(registration);
  TestValidator.equals("admin email matches")(registration.email)(adminEmail);

  // 2. Log in as the newly created admin
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ILogin,
  });
  typia.assert(login);
  TestValidator.equals("admin_id matches registration")(login.admin_id)(registration.admin_id);

  // 3. Create a new permission matrix entry
  const now = new Date();
  const effectiveFrom = now.toISOString();
  // use no expiration for a perpetual rule
  const matrixInput = {
    role_name: "moderator",
    resource: "post",
    action: "delete",
    allowed: true,
    effective_from: effectiveFrom,
    effective_to: null,
  } satisfies IDiscussionBoardPermissionMatrix.ICreate;
  const matrix = await api.functional.discussionBoard.admin.permissionMatrices.create(connection, {
    body: matrixInput,
  });
  typia.assert(matrix);

  // 4. Validate returned fields and audit information
  TestValidator.equals("role_name matches")(matrix.role_name)(matrixInput.role_name);
  TestValidator.equals("resource matches")(matrix.resource)(matrixInput.resource);
  TestValidator.equals("action matches")(matrix.action)(matrixInput.action);
  TestValidator.equals("allowed matches")(matrix.allowed)(matrixInput.allowed);
  TestValidator.equals("effective_from matches")(matrix.effective_from)(matrixInput.effective_from);
  TestValidator.equals("effective_to matches")(matrix.effective_to)(matrixInput.effective_to);

  // Validate all required audit fields
  TestValidator.predicate("id is a UUID")(typeof matrix.id === "string" && /[0-9a-fA-F\-]{36}/.test(matrix.id));
  TestValidator.predicate("created_at valid date")(typeof matrix.created_at === "string" && !Number.isNaN(Date.parse(matrix.created_at)));
  TestValidator.predicate("updated_at valid date")(typeof matrix.updated_at === "string" && !Number.isNaN(Date.parse(matrix.updated_at)));
  // deleted_at can be null or string
  TestValidator.predicate("deleted_at is null or valid date")(matrix.deleted_at == null || (typeof matrix.deleted_at === "string" && !Number.isNaN(Date.parse(matrix.deleted_at))));
}

