import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate that attempting to soft-delete (withdraw) a member who is already deleted results in a not found or already-deleted error response.
 *
 * This test covers an error edge case to ensure business policy and database state are enforced:
 * If an admin tries to erase a member using the admin endpoint, and that member has already been deleted (soft-deleted or otherwise not found), the system must return a clear error—whether this is 'not found' or 'already deleted' depending on backend logic.
 *
 * Steps:
 * 1. Register a discussion board member (as a regular user)
 * 2. Register an admin user and obtain credentials
 * 3. As the admin, erase (soft-delete) the created member by memberId
 * 4. Attempt to erase the same member again — should result in a not found or already deleted error
 */
export async function test_api_member_admin_erase_already_deleted(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = "Member123!";
  const memberNickname: string = RandomGenerator.name();
  const memberSession: IDiscussionBoardMember.ISession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberSession);
  const memberId = memberSession.member.id;

  // 2. Register an admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "AdminTest1!";
  const adminAuth: IDiscussionBoardAdminAuthResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(adminAuth);
  // The admin token is set in connection.headers by SDK, so subsequent requests are as admin

  // 3. Erase (soft-delete) the member as admin
  await api.functional.discussionBoard.admin.members.erase(connection, {
    memberId
  });
  // No output/return (void)

  // 4. Attempt to erase the same member again
  await TestValidator.error("Cannot erase already deleted or non-existent member")(
    async () => {
      await api.functional.discussionBoard.admin.members.erase(connection, {
        memberId
      });
    }
  );
}

