/**
 * Validate that non-moderators cannot search moderator comment reports.
 *
 * This test ensures the PATCH /discussionBoard/moderator/commentReports endpoint is protected:
 * - An authenticated regular member attempts to search for comment reports via this endpoint and must receive a forbidden error.
 * - An unauthenticated (guest) user attempts the same and must also receive a forbidden error.
 * - The endpoint must not return any data or partial responses for these unauthorized users.
 *
 * Steps:
 * 1. Register a regular member (not a moderator/admin).
 * 2. As this member, attempt to search comment reports (expect forbidden - access denied).
 * 3. Logout the user (remove credentials from connection), attempt the same request as guest (expect forbidden).
 */
export async function test_api_comment_report_moderator_search_unauthorized(connection: api.IConnection) {
  // 1. Register a discussion board member (regular user, not moderator)
  const memberEmail = typia.random<string & tags.Format<"email">>();
