    await api.functional.discussionBoard.moderator.commentReports.search(connection, {
      body: {
        page: 1,
        limit: 10,
      } satisfies IDiscussionBoardCommentReport.IRequest,
    });
  });

  // 3. Remove Authorization header from connection to simulate guest (unauthenticated)
  const guestConnection = {
    ...connection,
    headers: {
      ...connection.headers,
    },
  };
  delete guestConnection.headers.Authorization;

  await TestValidator.error("guest should not access moderator search endpoint")(async () => {
    await api.functional.discussionBoard.moderator.commentReports.search(guestConnection, {
      body: {
        page: 1,
        limit: 10,
      } satisfies IDiscussionBoardCommentReport.IRequest,
    });
  });
