import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReport";

/**
 * Validate that only users with admin or moderator role can erase (soft-delete) a comment report.
 *
 * Ensures the system forbids members or guests from deleting reports via the admin endpoint, and such attempts are properly rejected with a forbidden error (HTTP 403) and potentially logged for audit purposes.
 *
 * Steps:
 * 1. As a normal member, create a new comment report to obtain a valid commentReportId.
 * 2. As the member (i.e., without admin/mod rights), attempt to call the admin-only erase API using this commentReportId.
 *    - Expect the call to fail with a forbidden error (HTTP 403), verifying no privilege escalation is possible.
 * 3. (Optionally) Attempt the same call as a guest (unauthenticated connection) to confirm guests are also rejected.
 */
export async function test_api_comment_report_admin_erase_permission(connection: api.IConnection) {
  // Step 1: As a normal member, create a comment report.
  const report: IDiscussionBoardCommentReport = await api.functional.discussionBoard.member.commentReports.create(connection, {
    body: {
      discussion_board_comment_id: typia.random<string & tags.Format<"uuid">>(),
      reason_type: "spam",
      reason_text: "Obvious spam in comment."
    },
  });
  typia.assert(report);

  // Step 2: As the member (NOT an admin/mod), attempt to delete via admin endpoint.
  // Expect a forbidden (403) error.
  await TestValidator.error("forbidden: member cannot erase via admin endpoint")(
    async () =>
      api.functional.discussionBoard.admin.commentReports.erase(connection, {
        commentReportId: report.id,
      }),
  );

  // Step 3: As a guest (no authentication), attempt the same forbidden action
  // Prepare a guest (unauthenticated) connection by removing auth headers.
  const guestConnection: api.IConnection = {
    ...connection,
    headers: Object.fromEntries(Object.entries(connection.headers || {}).filter(([k]) => k.toLowerCase() !== "authorization")),
  };
  await TestValidator.error("forbidden: guest cannot erase via admin endpoint")(
    async () =>
      api.functional.discussionBoard.admin.commentReports.erase(guestConnection, {
        commentReportId: report.id,
      }),
  );
}

