import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate retrieval of member profile detail as admin.
 *
 * 1. Register a new admin to obtain authorization and session token.
 * 2. Register a new member and collect their memberId.
 * 3. Use admin privileges to retrieve profile detail for the registered member using GET /discussionBoard/admin/members/{memberId}.
 * 4. Confirm that all profile fields are present except sensitive hashes (like password).
 * 5. Validate lifecycle and audit fields: registration (joined_at), account status (status), and timestamps (created_at, updated_at, possibly deleted_at), and that no password-related hashes are present.
 * 6. Confirm status reflects the member's current lifecycle (e.g., active).
 */
export async function test_api_member_retrieve_detail_success(connection: api.IConnection) {
  // 1. Register and login as admin to obtain access token
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "A_strong_password!123";
  const adminRegResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRegResponse);

  // 2. Register a new member to retrieve
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberNickname: string = RandomGenerator.name();
  const memberPassword: string = "Valid_member_pass_!1";

  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
      avatar_uri: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);
  const memberId = memberSession.member.id;

  // 3. Switch to admin by restoring Authorization header from admin registration response
  connection.headers = {
    ...connection.headers,
    Authorization: adminRegResponse.setHeaders.Authorization,
  };

  // 4. Retrieve member detail as admin
  const profile = await api.functional.discussionBoard.admin.members.at(connection, {
    memberId,
  });
  typia.assert(profile);

  // 5. Validate returned fields: confirm presence of expected, absence of sensitive, and correct status/timestamp fields
  TestValidator.equals("member id")(profile.id)(memberSession.member.id);
  TestValidator.equals("email")(profile.email)(memberEmail);
  TestValidator.equals("nickname")(profile.nickname)(memberNickname);
