import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validate role-based notification filtering for guest users in the discussion board.
 *
 * This test ensures:
 *  1. After authenticating as a guest, only notifications specifically addressed to THIS guest are visible to the session.
 *  2. Notifications for other guests, members, moderators, and admins are NOT accessible via the guest's session.
 *
 * Steps:
 * 1. Authenticate as guest and extract guest_id for the session (simulate by creating/administering notifications addressed to it).
 * 2. As admin, create notifications for:
 *    - this guest (via guest_id)
 *    - another guest (random/other guest_id)
 *    - member (random member_id)
 *    - moderator (random moderator_id)
 *    - admin (random admin_id)
 * 3. As guest, search for notifications using PATCH endpoint.
 * 4. Assert only the notification addressed to this guest is present (by notification id and guest_id), and other notifications are excluded.
 */
export async function test_api_guest_notification_access_success_and_role_filtering(connection: api.IConnection) {
  // --- Step 1: Authenticate as guest and obtain guest_id ---
  const guestAuth = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: RandomGenerator.alphaNumeric(12),
      ip_address: `192.0.2.${typia.random<number & tags.Type<"int32"> & tags.Minimum<2> & tags.Maximum<254>>()}`,
    },
  });
  typia.assert(guestAuth);

  // The guest_id is not returned in auth, but we can use the issued JWT session as the recipient for notification creation.
  // For clarity, create a unique guest notification and separately for other roles; use randomized UUIDs for isolation.
  const thisGuestId = typia.random<string & tags.Format<"uuid">>(); // simulate this guest's uuid for notification
  const otherGuestId = typia.random<string & tags.Format<"uuid">>();
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();

  // --- Step 2: As admin, issue notifications for various recipient types ---
  // a. Notification for this guest
  const guestNotification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      guest_id: thisGuestId,
      title: "For this guest only",
      body: "A notification only the current guest should see.",
      event_type: "test_guest",
    },
  });
  typia.assert(guestNotification);

  // b. Notification for another guest
  const otherGuestNotification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      guest_id: otherGuestId,
      title: "Other guest's notification",
      body: "Should not be shown to current guest.",
      event_type: "test_guest",
    },
  });
  typia.assert(otherGuestNotification);

  // c. Notification for member
  const memberNotification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      member_id: memberId,
      title: "Member notification",
      body: "Should not be shown to guest.",
      event_type: "test_member",
    },
  });
  typia.assert(memberNotification);

  // d. Notification for moderator
  const moderatorNotification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      moderator_id: moderatorId,
      title: "Moderator notification",
      body: "Should not be shown to guest.",
      event_type: "test_mod",
    },
  });
  typia.assert(moderatorNotification);

  // e. Notification for admin
  const adminNotification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      admin_id: adminId,
      title: "Admin notification",
      body: "Should not be shown to guest.",
      event_type: "test_admin",
    },
  });
  typia.assert(adminNotification);

  // --- Step 3: As guest, search for notifications via PATCH endpoint ---
  // Simulate guest context by searching with recipient_role 'guest' and recipient_id set to 'thisGuestId'
  // (In real system, it should be scoped to session, but this ensures correct output filtering here)
  const searchOutput = await api.functional.discussionBoard.guest.notifications.search(connection, {
    body: {
      recipient_role: "guest",
      recipient_id: thisGuestId,
      limit: 20,
    },
  });
  typia.assert(searchOutput);

  // --- Step 4: Assert only the notification addressed to THIS guest is present ---
  const found = searchOutput.data.find((n) => n.id === guestNotification.id);
  TestValidator.predicate("Should return notification for current guest only")(!!found);
  // Ensure all returned notifications, if any, are for THIS guest and NOT for other roles/guests
  for (const n of searchOutput.data) {
    TestValidator.equals("only this guest notification present")(n.id)(guestNotification.id);
    // Optionally, further check by recipient_id if available/returned
  }
  // Additionally assert that notifications for other roles/guests were not returned
  TestValidator.predicate("No foreign notifications present")(
    !searchOutput.data.find((n) => n.id === otherGuestNotification.id
      || n.id === memberNotification.id
      || n.id === moderatorNotification.id
      || n.id === adminNotification.id
    )
  );
}

