      body: {
        title: RandomGenerator.paragraph()(1).substring(0, 100),
        body: RandomGenerator.content()()(1).substring(0, 4000),
        attachments: null,
        // For system fields, nothing set here since author/status assigned by backend; we'll update status later.
      } satisfies IDiscussionBoardPost.ICreate,
    });
    typia.assert(post);
    // Immediately update to force desired status (simulate real moderation process)
