import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin category search with multiple filters, pagination, and data integrity.
 *
 * This test ensures that an admin can retrieve categories based on various filters and that pagination, data integrity, and filter accuracy are robust. It verifies not just the list contents, but also pagination metadata and the presence/accuracy of audit fields as required by the business.
 *
 * Steps:
 * 1. Create several categories with varying names, parent-child relationships, enabled/disabled flags, and display orders. Ensure some are roots, and some are children.
 * 2. Search categories by name substring and verify only matching categories are returned.
 * 3. Search categories by parent_id to check proper nesting/hierarchy filtering.
 * 4. Search categories by enabled/disabled flag.
 * 5. Search (and sort) by display order using sorting options.
 * 6. Confirm that pagination works: default pagination, explicit limit/page, record count, and pages.
 * 7. On each result: assert presence and type of ID, parent_id, name, display_order, enabled, version, audit fields (created_at, updated_at, deleted_at), and optional fields.
 */
export async function test_api_category_search_admin_success(connection: api.IConnection) {
  // 1. Create root categories
  const rootA = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "RootAlpha",
      display_order: 10,
      enabled: true,
      version: 1
    }
  });
  typia.assert(rootA);

  const rootB = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "RootBeta",
      display_order: 20,
      enabled: false,
      version: 1
    }
  });
  typia.assert(rootB);

  // 2. Create children for rootA
  const childA1 = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "AlphaChildA",
      display_order: 31,
      enabled: true,
      version: 1,
      parent_id: rootA.id
    }
  });
  typia.assert(childA1);

  const childA2 = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "AlphaChildB",
      display_order: 32,
      enabled: false,
      version: 1,
      parent_id: rootA.id
    }
  });
  typia.assert(childA2);

  // 3. Create child for rootB
  const childB1 = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "BetaChildSingle",
      display_order: 40,
      enabled: true,
      version: 1,
      parent_id: rootB.id
    }
  });
  typia.assert(childB1);

  // --- Filter: by name substring (case and partial)
  let result = await api.functional.discussionBoard.admin.categories.search(connection, {
    body: { name: "Alpha" }
  });
  typia.assert(result);
  TestValidator.predicate("Should match only names containing Alpha")(
    result.data.every(x => x.name.includes("Alpha")) && result.data.length >= 2
  );

  // --- Filter: by parent_id (children of rootA)
  result = await api.functional.discussionBoard.admin.categories.search(connection, {
    body: { parent_id: rootA.id }
  });
  typia.assert(result);
  const childNames = [childA1.name, childA2.name];
  TestValidator.equals("Parent filter matches only children of rootA")(
    result.data.map(x => x.name).sort()
  )(childNames.sort());

  // --- Filter: by enabled (just enabled)
  result = await api.functional.discussionBoard.admin.categories.search(connection, {
    body: { enabled: true }
  });
  typia.assert(result);
  TestValidator.predicate("All are enabled")(
    result.data.every(x => x.enabled === true)
  );

  // --- Filter: by disabled (enabled: false)
  result = await api.functional.discussionBoard.admin.categories.search(connection, {
    body: { enabled: false }
  });
  typia.assert(result);
  TestValidator.predicate("All are disabled")(
    result.data.every(x => x.enabled === false)
  );

  // --- Sort by display_order desc
  result = await api.functional.discussionBoard.admin.categories.search(connection, {
    body: { orderBy: "display_order", order: "desc" }
  });
  typia.assert(result);
  TestValidator.predicate("Sorted by display_order desc")(
    result.data.every((c, i, arr) => i === 0 || c.display_order <= arr[i-1].display_order)
  );

  // --- Pagination: default (should return at least 5 records since 5 created above)
  result = await api.functional.discussionBoard.admin.categories.search(connection, {
    body: {} // defaults
  });
  typia.assert(result);
  TestValidator.predicate("Has all expected records >= 5")(
    result.data.length >= 5 && result.pagination.records >= 5
  );

  // --- Pagination: page and limit
  result = await api.functional.discussionBoard.admin.categories.search(connection, {
    body: { page: 1, limit: 2 }
  });
  typia.assert(result);
  TestValidator.equals("Limit respected")(result.data.length)(2);
  TestValidator.equals("Current page should be 1")(result.pagination.current)(1);
  TestValidator.equals("Pagination limit matches")(result.pagination.limit)(2);

  // --- Audit & summary fields check (all results in a paged response)
  for (const cat of result.data) {
    TestValidator.predicate("ID present")(
      typeof cat.id === "string" && cat.id.length > 0
    );
    TestValidator.predicate("name present")(
      typeof cat.name === "string" && cat.name.length > 0
    );
    TestValidator.predicate("enabled is boolean")(
      typeof cat.enabled === "boolean"
    );
    TestValidator.predicate("display_order is int")(
      typeof cat.display_order === "number"
    );
    TestValidator.predicate("version is number")(
      typeof cat.version === "number"
    );
    TestValidator.predicate("created_at valid")(
      typeof cat.created_at === "string" && cat.created_at.length > 0
    );
    TestValidator.predicate("updated_at valid")(
      typeof cat.updated_at === "string" && cat.updated_at.length > 0
    );
    TestValidator.predicate("parent_id: string|null|undefined")(
      cat.parent_id === null || cat.parent_id === undefined || typeof cat.parent_id === "string"
    );
    TestValidator.predicate("description: string|null|undefined")(
      cat.description === null || cat.description === undefined || typeof cat.description === "string"
    );
    TestValidator.predicate("icon_uri: string|null|undefined")(
      cat.icon_uri === null || cat.icon_uri === undefined || typeof cat.icon_uri === "string"
    );
    TestValidator.predicate("deleted_at: string|null|undefined")(
      cat.deleted_at === null || cat.deleted_at === undefined || typeof cat.deleted_at === "string"
    );
  }
}

