import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate moderator notification search, filtering, and access behavior.
 *
 * This test verifies that moderator users can successfully search, filter, and paginate their notifications using the PATCH /discussionBoard/moderator/notifications endpoint. It ensures that only notifications addressed to the moderator are returned, other users’ notifications are excluded, and pagination/filtering logic functions as expected.
 *
 * Steps:
 * 1. Set up: Register a moderator (capture id/email/token for targeting and authentication).
 * 2. Generate notifications:
 *    - Some addressed to this moderator.
 *    - Some addressed to other user types (e.g., member, admin, guest) or different moderator.
 * 3. As moderator, search for notifications with no filters (should receive only those addressed to them).
 * 4. Test additional search filters (e.g., event_type, unread, recipient_role) to narrow results.
 * 5. Test pagination (limit/page params) to ensure correct subsetting/ordering.
 * 6. Validate:
 *    - Only notifications the moderator is allowed to see are returned.
 *    - Non-moderator-targeted notifications are not returned.
 *    - Pagination/filters work as intended.
 */
export async function test_api_notification_moderator_search_access(connection: api.IConnection) {
  // 1. Register a new moderator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "StrongP@ssw0rd";
  const signUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(signUp);
  const moderatorId = signUp.moderator_id;

  // 2. Create notifications: some to this moderator, some to others
  const notificationToModerator = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      moderator_id: moderatorId,
      title: "Post flagged for review",
      body: "A post requires your moderation.",
      event_type: "post_flag",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notificationToModerator);

  const notificationToOtherModerator = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      title: "For another mod",
      body: "Another mod event.",
      event_type: "system_alert",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notificationToOtherModerator);

  const notificationToMember = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Welcome Member",
      body: "Welcome to our board!",
      event_type: "welcome",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notificationToMember);

  const notificationToAdmin = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      admin_id: typia.random<string & tags.Format<"uuid">>(),
      title: "System upgrade",
      body: "Admin only news.",
      event_type: "sys_upgrade",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notificationToAdmin);

  // 3. As moderator (Authorization token is set in connection by signUp), search notifications - no filter
  const allResults = await api.functional.discussionBoard.moderator.notifications.search(connection, {
    body: {} satisfies IDiscussionBoardNotification.IRequest,
  });
  typia.assert(allResults);
  // Ensure only notifications addressed to this moderator are present
  TestValidator.predicate("only moderator-notifications for self")(allResults.data.every(n => n.title === notificationToModerator.title));

  // 4. Search with filter (event_type: "post_flag")
  const filteredResults = await api.functional.discussionBoard.moderator.notifications.search(connection, {
    body: {
      event_type: "post_flag"
    } satisfies IDiscussionBoardNotification.IRequest,
  });
  typia.assert(filteredResults);
  TestValidator.equals("only 'post_flag' notification")(filteredResults.data.length)(1);
  TestValidator.equals("event_type matches")(filteredResults.data[0].event_type)("post_flag");

  // 5. Pagination test: page 1, limit 1 (there is only one notification for this mod, but test structure)
  const pagedResults = await api.functional.discussionBoard.moderator.notifications.search(connection, {
    body: {
      page: 1,
      limit: 1,
    } satisfies IDiscussionBoardNotification.IRequest,
  });
  typia.assert(pagedResults);
  TestValidator.equals("pagination matches")(pagedResults.pagination.limit)(1);
  TestValidator.predicate("data length matches limit")(pagedResults.data.length <= 1);

  // 6. Unread notifications only
  const unreadResults = await api.functional.discussionBoard.moderator.notifications.search(connection, {
    body: {
      unread: true
    } satisfies IDiscussionBoardNotification.IRequest,
  });
  typia.assert(unreadResults);
  TestValidator.predicate("all unread")(unreadResults.data.every(n => n.unread));
}

