 */
export async function test_api_notification_moderator_search_access(connection: api.IConnection) {
  // 1. Register a new moderator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "StrongP@ssw0rd";
  const signUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(signUp);
  const moderatorId = signUp.moderator_id;

  // 2. Create notifications: two for this moderator, others for others
  const notif1 = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      moderator_id: moderatorId,
      title: RandomGenerator.paragraph()(4),
      body: RandomGenerator.content()(2)(2),
      event_type: "post_flag",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notif1);

  const notif2 = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      moderator_id: moderatorId,
      title: RandomGenerator.paragraph()(3),
      body: RandomGenerator.content()(1)(2),
      event_type: "system_update",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notif2);

  const otherModId = typia.random<string & tags.Format<"uuid">>();
  const notifOtherMod = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      moderator_id: otherModId,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()(2)(1),
      event_type: "admin_alert",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notifOtherMod);

  const notifMember = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()(1)(1),
      event_type: "welcome",
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(notifMember);

  const notifAdmin = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      admin_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()(1)(2),
      event_type: "sys_upgrade",
