  );
  // Make sure other moderator's and member/admin notifications are NOT visible
  TestValidator.predicate("no non-moderator or other moderator notifications")(
    !allResults.data.some(n => n.title === notifOtherMod.title || n.title === notifMember.title || n.title === notifAdmin.title)
