  const page1 = await api.functional.discussionBoard.moderator.notifications.search(connection, {
    body: { page: 1, limit: 1 } satisfies IDiscussionBoardNotification.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("pagination returns 1 item")(page1.data.length)(1);
  TestValidator.equals("pagination limit set")(page1.pagination.limit)(1);

  // 7. All notifications should be unread
