 * 3. Using the same authentication, create a new comment (with a valid body length, not a reply).
 * 4. Assert that the returned comment matches the sent content, has status = 'active', correct relationships (post_id, author_member_id), and timestamps/defaults are present.
 * 5. (Optional) Fetch or list comments for the post and validate that the new comment appears and the relationship is consistent.
 */
export async function test_api_comment_creation_success_by_member(
  connection: api.IConnection,
) {
