    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(session);
  // (Connection headers updated with token automatically)

  // 2. Create a post as this member
  const post: IDiscussionBoardPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(5).slice(0, 100),
