  TestValidator.predicate("timestamps present")(typeof comment.created_at === "string" && typeof comment.updated_at === "string");
  TestValidator.equals("top-level comment")(comment.thread_parent_comment_id)(null);

  // 5. (Could fetch comment list for the post and check inclusion if such API existed)
}

