import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardRuleLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRuleLog";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Test that non-admin users are forbidden from updating rule log records (RBAC enforcement).
 *
 * This test validates that only users with admin privileges can update rule logs via the PUT /discussionBoard/admin/ruleLogs/{ruleLogId} endpoint. Specifically:
 * - Register a member account, and verify that a member user receives a 403 Forbidden error when attempting to update a rule log.
 * - Register a moderator account, and verify that a moderator user receives a 403 Forbidden error on the same endpoint.
 * - A guest (no authentication) also receives a 403 Forbidden error.
 * - Confirm that an unauthorized access attempt is properly denied by the API (error is thrown), 
 * - (If audit log verification was possible, confirm an audit log entry is made—but code for this step is omitted due to lack of provided audit API/read function.)
 *
 * Steps:
 * 1. Register a new member with unique credentials, which provides a member-level session
 * 2. Attempt to update a rule log record as member (random ruleLogId, random payload)
 *    - Expect a permission error (403 Forbidden)
 * 3. Register a new moderator with unique credentials and admin assignment (use fake admin email)
 * 4. Attempt to update a rule log as moderator (random ruleLogId, random payload)
 *    - Expect a permission error (403 Forbidden)
 * 5. Attempt to update a rule log as a guest (no token in connection)
 *    - Expect a permission error (403 Forbidden)
 */
export async function test_api_rule_log_update_permission_denied_forbidden(connection: api.IConnection) {
  // 1. Register a member user
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Password123!";
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberSession);

  // Use the session returned to set member Authorization token
  const memberConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: memberSession.setHeaders.Authorization
    }
  };

  // Prepare fake data for update
  const ruleLogId = typia.random<string & tags.Format<"uuid">>();
  const updateBody = typia.random<IDiscussionBoardRuleLog.IUpdate>();

  // 2. Attempt rule log update as member—must fail with 403 Forbidden
  await TestValidator.error("member forbidden to update rule log")(async () => {
    await api.functional.discussionBoard.admin.ruleLogs.update(memberConnection, {
      ruleLogId,
      body: updateBody
    });
  });

  // 3. Register a moderator; this requires a fake admin assignment email
  const modEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = "Password123!";

  const modSession = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      assigned_by_admin_email: adminEmail,
      password: modPassword
    } satisfies IModerator.SignUp
  });
  typia.assert(modSession);

  // Use the JWT token returned to set moderator Authorization
  const modConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: modSession.setHeaders.Authorization
    }
  };

  // 4. Attempt rule log update as moderator—must fail with 403 Forbidden
  await TestValidator.error("moderator forbidden to update rule log")(async () => {
    await api.functional.discussionBoard.admin.ruleLogs.update(modConnection, {
      ruleLogId,
      body: updateBody
    });
  });

  // 5. Attempt rule log update as guest (no token or Authorization header)
  const guestConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers
    }
  };
  await TestValidator.error("guest forbidden to update rule log")(async () => {
    await api.functional.discussionBoard.admin.ruleLogs.update(guestConnection, {
      ruleLogId,
      body: updateBody
    });
  });

  // Note: Auditing the API logs for entry of unauthorized access would require additional audit log read APIs, which are not provided here.
}

