import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validate forbidden/not found access control for guest notifications.
 *
 * This test ensures that a guest user cannot read notification details for:
 * 1. Notifications addressed to a different guest session.
 * 2. Non-existent (random UUID) notifications.
 *
 * The test steps:
 * 1. Sign in as a guest user, capturing the Authorization token (simulate user agent + IP).
 * 2. As an admin, create a notification for another (random) guest session.
 * 3. As the guest user, attempt to GET the notification created for another guest.
 *    - Assert a 403 or 404 error is returned (forbidden/not found).
 *    - Ensure no notification data is leaked.
 * 4. As the guest user, attempt to GET a notification using a random (non-existent) UUID.
 *    - Assert a 404 error is returned (not found).
 *
 * This validates that notifications cannot be read by unintended guest sessions and that error handling does not leak sensitive notification data across sessions or on deleted/missing records.
 */
export async function test_api_guest_notification_detail_access_forbidden_or_not_found(connection: api.IConnection) {
  // 1. Sign in as a guest user
  const guestSignIn = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: RandomGenerator.alphabets(10),
      ip_address: "192.168.1.100",
    },
  });
  typia.assert(guestSignIn);
  // Store the token on connection.headers (simulated by E2E infra)

  // 2. Create a notification for ANOTHER guest session (not for our guest user)
  const otherGuestId = typia.random<string & tags.Format<"uuid">>();
  const foreignNotification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      guest_id: otherGuestId,
      title: "Notification for another guest",
      body: "Not for current guest.",
      event_type: "event_x",
    },
  });
  typia.assert(foreignNotification);

  // 3. Attempt to get notification for another guest (should be forbidden or not found)
  await TestValidator.error("guest forbidden/not found accessing another guest's notification")(
    async () => {
      await api.functional.discussionBoard.guest.notifications.at(connection, {
        notificationId: foreignNotification.id,
      });
    }
  );

  // 4. Attempt to get notification with a random non-existent UUID (should be not found)
  await TestValidator.error("guest accessing non-existent notification returns not found")(
    async () => {
      await api.functional.discussionBoard.guest.notifications.at(connection, {
        notificationId: typia.random<string & tags.Format<"uuid">>(),
      });
    }
  );
}

