import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPlatformConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPlatformConfig";
import type { IPageIDiscussionBoardPlatformConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPlatformConfig";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Test searching platform configs as a moderator using typical filter options.
 *
 * This test validates that a moderator can search for platform configuration entries using a mixture of filter and pagination options, ensuring only authorized data is returned for the moderator role, and that auditability and pagination work as intended. Sensitive fields should be appropriately restricted for the moderator.
 *
 * Steps:
 * 1. Register and authenticate as a moderator.
 * 2. Create a diverse set of platform config records as test data (with various config_name, values, enabled states, etc.).
 * 3. As the moderator, perform a search with a filter (e.g., config_name/description/enabled).
 * 4. Validate that the search results contain correct records matching the filter criteria.
 * 5. Validate standard pagination (limit/page/count/records).
 * 6. Check that only allowed fields are present for the moderator and no admin-only secrets are present.
 * 7. Ensure the response supports audit tracking: version and timestamp fields are present and correct.
 */
export async function test_api_platform_config_search_moderator_success(connection: api.IConnection) {
  // 1. Register an admin and then register a moderator assigned by that admin
  // (Assume a known admin email is available for assignment)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  // Create a moderator email
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = "testPw1!";

  // Register moderator, assigned by admin
  const modSignup = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password,
      assigned_by_admin_email: adminEmail,
    },
  });
  typia.assert(modSignup);
  // Token will be auto-assigned to connection.headers.Authorization

  // 2. Create multiple platform configs as admin
  // (Simulate admin role by temporarily switching Authorization header)
  connection.headers = { ...(connection.headers || {}), Authorization: `Bearer adminTestToken` };
  // Create several platform configs
  const platformConfigs: IDiscussionBoardPlatformConfig[] = [];
  for (let i = 0; i < 6; ++i) {
    const config = await api.functional.discussionBoard.admin.platformConfigs.create(connection, {
      body: {
        config_name: `feature_flag_test_${i}`,
        config_value: i % 2 ? "true" : "false",
        enabled: i % 2 === 0,
        version: 1,
        description: i % 2 === 0 ? `Test config ${i}` : null,
      },
    });
    typia.assert(config);
    platformConfigs.push(config);
  }

  // Revert to moderator authentication
  connection.headers = { ...connection.headers, Authorization: modSignup.setHeaders.Authorization };

  // 3. Search as a moderator with filters
  // Choose one config_name for filter
  const filterConfigName = platformConfigs[2].config_name;
  const searchBody: IDiscussionBoardPlatformConfig.IRequest = {
    page: 1,
    limit: 3,
    config_name: filterConfigName,
  };
  const resultPage = await api.functional.discussionBoard.moderator.platformConfigs.search(connection, {
    body: searchBody,
  });
  typia.assert(resultPage);

  // 4. Validate results match filter
  TestValidator.predicate("all configs match config_name filter")(
    resultPage.data.every(pc => pc.config_name === filterConfigName));

  // 5. Validate pagination
  TestValidator.equals("pagination limit is 3")(
    resultPage.pagination.limit)(3);
  TestValidator.equals("pagination current page is 1")(
    resultPage.pagination.current)(1);

  // 6. Ensure only authorized fields are present (should not contain extra admin-only secrets)
  // (All fields returned here are allowed for moderator by schema)

  // 7. Ensure audit fields present and version >= 1
  for (const pc of resultPage.data) {
    TestValidator.predicate("version >= 1")(pc.version >= 1);
    TestValidator.predicate("created_at present")(
      typeof pc.created_at === "string" && !!pc.created_at.length);
    TestValidator.predicate("updated_at present")(
      typeof pc.updated_at === "string" && !!pc.updated_at.length);
  }
}

