  for (const log of filterByChannel.data) {
    TestValidator.equals("filtered by channel")(log.auth_channel)("kakao");
  }

  // 4. Test search with filter: by success status (e.g., only failures)
  const filterByFailure = await api.functional.discussionBoard.admin.externalAuthLogs.search(connection, {
    body: {
      success: false,
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardExternalAuthLog.IRequest,
  });
  typia.assert(filterByFailure);
  for (const log of filterByFailure.data) {
    TestValidator.equals("filtered by failed status")(log.success)(false);
  }

  // 5. Test search with filter: issued_at range covering only subset
  const fromDate = new Date(baseIssuedAt.getTime() - 24 * 60 * 60 * 1000).toISOString();
  const toDate = baseIssuedAt.toISOString();
  const filterByDate = await api.functional.discussionBoard.admin.externalAuthLogs.search(connection, {
    body: {
      issued_at_gte: fromDate,
      issued_at_lte: toDate,
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardExternalAuthLog.IRequest,
  });
  typia.assert(filterByDate);
  for (const log of filterByDate.data) {
    TestValidator.predicate("issued_at within range")(
      log.issued_at >= fromDate && log.issued_at <= toDate,
    );
  }

  // 6. Test pagination - using a page size of 2
  const paginationTest = await api.functional.discussionBoard.admin.externalAuthLogs.search(connection, {
    body: {
      page: 1,
      limit: 2,
    } satisfies IDiscussionBoardExternalAuthLog.IRequest,
  });
  typia.assert(paginationTest);
  TestValidator.equals("pagination.limit")(paginationTest.pagination.limit)(2);
  TestValidator.predicate("pagination size <= limit")(paginationTest.data.length <= 2);

  // 7. Ensure sensitive data is present for admin in search results
  for (const log of paginationTest.data) {
    TestValidator.predicate("admin can see subject_email")(typeof log.subject_email === "string" && log.subject_email.length > 0);
  }
}

