import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate enforcement of admin-only permission on category deletion (soft-delete) endpoint.
 *
 * This test ensures that non-admin users (registered members and moderators) cannot delete categories using the admin privilege endpoint. It covers scenarios for both standard members and users holding the moderator role, neither of whom should have authority to erase categories via the protected endpoint.
 *
 * 1. Register a standard platform member and obtain a JWT session.
 * 2. Attempt to delete a (random) category as the member. Confirm that access is denied.
 * 3. Register a moderator, assigned by a random admin email, and receive moderator JWT.
 * 4. Attempt category deletion as moderator. Confirm that access is denied.
 * 5. Confirm both denials result in errors/auditable events (e.g., forbidden error is thrown, error is not due to missing/invalid parameters but permission).
 *
 * This protects taxonomy integrity and verifies Role-Based Access Control (RBAC) for compliance and audit description.
 */
export async function test_api_admin_category_erase_unauthorized_access(connection: api.IConnection) {
  // 1. Register a standard member
  const memberInput: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "MemberPassw0rd$",
    nickname: RandomGenerator.name(),
  };
  const memberSession = await api.functional.auth.member.register.signUp(connection, { body: memberInput });
  typia.assert(memberSession);

  // Use member's JWT session
  connection.headers = { ...connection.headers, ...memberSession.setHeaders };

  // 2. Attempt to delete a category as member (should fail with permission/forbidden error)
  const randomCategoryId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("member forbidden to delete category")(async () => {
    await api.functional.discussionBoard.admin.categories.erase(connection, { categoryId: randomCategoryId });
  });

  // 3. Register a moderator
  const adminEmailForModerAssign: string = typia.random<string & tags.Format<"email">>();
  const moderatorInput = {
    email: typia.random<string & tags.Format<"email">>(),
    assigned_by_admin_email: adminEmailForModerAssign,
    password: "ModeratorStr0ng!Pass",
  } satisfies IModerator.SignUp;
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: moderatorInput,
  });
  typia.assert(moderatorSignUp);
  // Switch to moderator's JWT
  connection.headers = { ...connection.headers, ...moderatorSignUp.setHeaders };
  // 4. Attempt to delete a category as moderator (should fail with permission/forbidden error)
  await TestValidator.error("moderator forbidden to delete category")(async () => {
    await api.functional.discussionBoard.admin.categories.erase(connection, { categoryId: randomCategoryId });
  });
}

