import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test successful update of an existing discussion board category by an admin user.
 *
 * This test covers the workflow where an admin creates a category and then performs an update on editable fields including name, enabled status, display order, description, and icon URI.
 *
 * Validation steps:
 * 1. Create a category using the admin "create" API (used as the update target).
 * 2. Update one or more editable fields using the update API (e.g., change name, display_order, enabled, description, icon_uri).
 * 3. Assert the response has all updated fields, version increment/update, and appropriate updated_at timestamp.
 * 4. Confirm all non-updated fields remain unchanged.
 *
 * This verifies proper admin update rights, accurate update field handling, and audit/version field updates.
 */
export async function test_api_category_update_success_admin(connection: api.IConnection) {
  // 1. Create a new category as admin
  const initialCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(12),
      display_order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
      version: 1,
      description: RandomGenerator.paragraph()(),
      icon_uri: null,
      parent_id: null,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(initialCategory);

  // 2. Update editable fields of this category
  const newName = RandomGenerator.alphabets(10);
  const newDescription = RandomGenerator.paragraph()();
  const newDisplayOrder = initialCategory.display_order + 1;
  const newEnabled = !initialCategory.enabled;
  const newIconUri = "https://example.com/icon.png";

  const updatedCategory = await api.functional.discussionBoard.admin.categories.update(connection, {
    categoryId: initialCategory.id,
    body: {
      name: newName,
      display_order: newDisplayOrder,
      enabled: newEnabled,
      description: newDescription,
      icon_uri: newIconUri,
      // version omitted to check if system auto-increments or preserves
    } satisfies IDiscussionBoardCategory.IUpdate,
  });
  typia.assert(updatedCategory);

  // 3. Validate that the update is reflected
  TestValidator.equals("category id")(updatedCategory.id)(initialCategory.id);
  TestValidator.equals("name updated")(updatedCategory.name)(newName);
  TestValidator.equals("description updated")(updatedCategory.description)(newDescription);
  TestValidator.equals("display order updated")(updatedCategory.display_order)(newDisplayOrder);
  TestValidator.equals("enabled updated")(updatedCategory.enabled)(newEnabled);
  TestValidator.equals("icon_uri updated")(updatedCategory.icon_uri)(newIconUri);

  // 4. Validate unchanged and version/audit fields
  TestValidator.equals("parent id unchanged")(updatedCategory.parent_id)(initialCategory.parent_id);
  TestValidator.predicate("updated_at changed")(updatedCategory.updated_at !== initialCategory.updated_at);
  TestValidator.equals("created_at unchanged")(updatedCategory.created_at)(initialCategory.created_at);
  TestValidator.equals("not deleted")(updatedCategory.deleted_at)(null);
}

