import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test access control for admin detail retrieval to ensure security boundaries are enforced for non-admin roles (moderator/member/guest).
 *
 * This test verifies that only users with admin privileges can view admin details via GET /discussionBoard/admin/admins/:adminId, and that moderator, member, and unauthenticated (guest) users are explicitly forbidden from this operation. Audit logging of forbidden attempts is required by policy, but only error outcome is validated here.
 *
 * Steps:
 * 1. Register a valid admin user (to create target adminId and for assignment flows).
 * 2. Register a valid member and moderator user (for privilege escalation attempt checks).
 * 3. As member, attempt to fetch admin details and expect error (forbidden).
 * 4. As moderator, attempt same and expect error (forbidden).
 * 5. As guest (without authentication), attempt and expect error (forbidden).
 */
export async function test_api_admin_detail_unauthorized_access_for_other_roles(connection: api.IConnection) {
  // 1. Register a new admin - will be the target of detail retrieval attempts
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin123!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // 2. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Member123!";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 3. Register a new moderator (assigned by admin)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Moderator123!";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorSignUp);

  // 4. As member, attempt to retrieve admin details (should fail)
  connection.headers = {
    ...connection.headers,
    Authorization: memberSession.setHeaders.Authorization,
  };
  await TestValidator.error("member forbidden from admin detail")(() =>
    api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: adminAuth.admin_id,
    })
  );

  // 5. As moderator, attempt to retrieve admin details (should fail)
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorSignUp.setHeaders.Authorization,
  };
  await TestValidator.error("moderator forbidden from admin detail")(() =>
    api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: adminAuth.admin_id,
    })
  );

  // 6. As guest (no Authorization header), attempt to retrieve admin details (should fail)
  if (connection.headers) {
    delete connection.headers.Authorization;
  }
  await TestValidator.error("guest forbidden from admin detail")(() =>
    api.functional.discussionBoard.admin.admins.at(connection, {
      adminId: adminAuth.admin_id,
    })
  );
}

