 * 1. Register a new discussion board admin using unique credentials.
 * 2. Perform a soft-delete operation against the registered admin (simulate account deactivation).
 * 3. Attempt a second soft-delete operation on the same admin ID.
 * 4. Confirm that the second delete throws an error (admin not found or already deleted), validating error handling and audit compliance.
 */
export async function test_api_admin_soft_delete_already_deleted_returns_error(connection: api.IConnection) {
  // 1. Register a new admin (to get a valid admin_id)
  const email = typia.random<string & tags.Format<"email">>();
  const password = "AutoBE-Test-1234!";
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(registerResp);
  const adminId = registerResp.admin_id;

  // 2. Soft-delete the admin
  await api.functional.discussionBoard.admin.admins.erase(connection, { adminId });

  // 3. Attempt to soft-delete again: must throw error (already deleted or not found)
  await TestValidator.error("already deleted admin should cause error")(
    () => api.functional.discussionBoard.admin.admins.erase(connection, { adminId })
  );
}

