 * 1. Register member A (owner of vote).
 * 2. Register member B (non-owner who will attempt deletion).
 * 3. As member A, create a new discussion board post.
 * 4. As member A, submit a vote (upvote/downvote) on the post.
 * 5. As member B, attempt to delete the vote created by member A (should receive 403 Forbidden / error).
 * 6. After the forbidden attempt, re-check that the vote still exists (was NOT deleted/affected).
 */
export async function test_api_post_vote_member_delete_forbidden_other_member(connection: api.IConnection) {
  // 1. Register member A
  const memberA_email = typia.random<string & tags.Format<"email">>();
  const memberA_password = "testpassA123!";
  const memberA_nickname = RandomGenerator.name();
  const memberASession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
      nickname: memberA_nickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberASession);
  const memberAId = memberASession.member.id;

  // 2. Register member B
  const memberB_email = typia.random<string & tags.Format<"email">>();
  const memberB_password = "testpassB321!";
  const memberB_nickname = RandomGenerator.name();
  const memberBSession = await api.functional.auth.member.register.signUp(connection, {
