  typia.assert(memberBSession);

  // 3. As member A: create a post
  connection.headers = { Authorization: memberASession.setHeaders.Authorization };
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: "Permission Test Post",
      body: "Checking forbidden deletion of another's vote.",
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. As member A: submit a vote on the post
  const vote = await api.functional.discussionBoard.member.postVotes.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      is_upvote: true,
    } satisfies IDiscussionBoardPostVote.ICreate,
  });
