  connection.headers = { Authorization: memberBSession.setHeaders.Authorization };
  await TestValidator.error("delete non-owned vote is forbidden")(async () => {
    await api.functional.discussionBoard.member.postVotes.erase(connection, {
      postVoteId: vote.id,
