  const memberAId = memberA.member.id;

  // 2. Register Member B
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = randomStrongPassword();
  const memberB: IDiscussionBoardMember.ISession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberB);

  // 3. Member A is authenticated (connection token remains unchanged after registration)

  // 4. Member A creates a post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1, 3),
      body: RandomGenerator.paragraph()(1, 6),
    } satisfies IDiscussionBoardPost.ICreate,
  });
