  // 7. Switch authentication context to Member B by updating only Authorization header
  connection.headers = {
    ...connection.headers,
    Authorization: memberB.setHeaders.Authorization,
  };

  // 8. Member B (non-owner) attempts to delete Member A's comment vote
  await TestValidator.error("forbidden: only the vote owner can delete it")(() =>
    api.functional.discussionBoard.member.commentVotes.erase(connection, {
      commentVoteId: commentVote.id,
    })
  );
}

