 *
 * 1. Register a new member (who will serve as the voter).
 * 2. Sign in as this member (session established and stored in connection).
 * 3. Create a discussion board post as the member.
 * 4. Cast a vote (upvote or downvote) as that member on the created post.
 * 5. As admin (connection with admin privileges), retrieve the vote by its postVoteId using the admin endpoint.
 * 6. Assert that the returned vote details match exactly what was submitted: voter, post reference, is_upvote flag, and timestamps are all correct and consistent with the original input/generated vote.
 * 7. Confirm type validation on all output fields and ensure the record is returned without error.
 */
export async function test_api_post_vote_detail_admin_success(connection: api.IConnection) {
  // 1. Register a new member (voter) and retrieve session.
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);
  const memberId = memberSession.member.id;

  // Connection auto-stores the member's token in headers for subsequent auth.

  // 2. Create a discussion board post as this member.
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()().slice(0, 100),
      body: RandomGenerator.content()()().slice(0, 4000),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Cast a vote (random upvote/downvote) as the member on the post.
  const isUpvote = Math.random() < 0.5;
  const vote = await api.functional.discussionBoard.member.postVotes.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      is_upvote: isUpvote,
    } satisfies IDiscussionBoardPostVote.ICreate,
  });
  typia.assert(vote);

  // 4. As admin, retrieve the vote by its postVoteId via admin endpoint.
  //    (Assume test-env connection can be switched or is elevated for admin calls.)

  // Simulate admin privileges by removing auth token if required or use same connection for this test.
  const adminVote = await api.functional.discussionBoard.admin.postVotes.at(connection, {
    postVoteId: vote.id,
  });
  typia.assert(adminVote);

  // 5. Assert that detailed fields match expectations.
  TestValidator.equals("vote id")(adminVote.id)(vote.id);
  TestValidator.equals("post id")(adminVote.discussion_board_post_id)(post.id);
  TestValidator.equals("voter id")(adminVote.discussion_board_member_id)(memberId);
  TestValidator.equals("is_upvote flag")(adminVote.is_upvote)(isUpvote);
  // timestamps must exist and be string-formatted; further checks could be added if needed
  TestValidator.predicate("created_at format")(typeof adminVote.created_at === "string" && adminVote.created_at.length > 0);
  TestValidator.predicate("updated_at format")(typeof adminVote.updated_at === "string" && adminVote.updated_at.length > 0);
}

