import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate the system prevents a member from filing multiple reports for the same comment (duplicate reports not allowed).
 *
 * Context: Only one comment report should be allowed per member per comment according to business rules. This test ensures the server enforces the duplication constraint and returns an error on the second attempt.
 *
 * Steps:
 * 1. Register a new discussion board member with randomized but valid credentials.
 * 2. Log in with the registered member to obtain a session and authenticated connection context.
 * 3. Post a new discussion post as the member, providing a title and body.
 * 4. Post a comment to the discussion post as the same member.
 * 5. Report the newly created comment as the same member (first report should succeed).
 * 6. Attempt to report the same comment again with the same member (should fail with error).
 * 7. Verify the system rejects the duplicate report with an error, confirming the one-report-per-member-per-comment rule.
 *
 * Throughout, all API responses are asserted for correctness and type safety. The error response on the second report attempt is validated using TestValidator.error().
 */
export async function test_api_member_comment_report_duplicate_report(
  connection: api.IConnection,
) {
  // 1. Register member
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword123$";
  const nickname = RandomGenerator.name();

  const signUpRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(signUpRes);
  const memberId = signUpRes.member.id;

  // 2. Login as member
  const signInRes = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardMember.ILogin,
  });
  typia.assert(signInRes);

  // 3. Create discussion post
  const postRes = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(100),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(postRes);
  const postId = postRes.id;

  // 4. Comment as member
  const commentRes = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId,
    body: {
      body: RandomGenerator.paragraph()(6),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(commentRes);
  const commentId = commentRes.id;

  // 5. Submit initial report (should succeed)
  const reportReq = {
    discussion_board_comment_id: commentId,
    reason_type: "spam",
    reason_text: RandomGenerator.content()()(30),
  } satisfies IDiscussionBoardCommentReport.ICreate;
  const reportRes = await api.functional.discussionBoard.member.commentReports.create(connection, {
    body: reportReq,
  });
  typia.assert(reportRes);
  TestValidator.equals("reported comment ID matches")(reportRes.discussion_board_comment_id)(commentId);
  TestValidator.equals("reporter member matches")(reportRes.discussion_board_member_id)(memberId);
  TestValidator.equals("reason type matches")(reportRes.reason_type)("spam");

  // 6. Try to report again with same member and comment (should fail)
  TestValidator.error("duplicate comment report must be rejected")(async () => {
    await api.functional.discussionBoard.member.commentReports.create(connection, {
      body: reportReq,
    });
  });
}

