/**
 * Test that a moderator can successfully retrieve subcategory details via /discussionBoard/moderator/categories/{categoryId}/subs/{subCategoryId}.
 *
 * Scenario:
 * - Use the admin token to create a parent category.
 * - Use the admin token to create a subcategory under it (and obtain both IDs).
 * - Register a moderator using /auth/moderator/register (moderator must be assigned by admin's email).
 * - Switch to the moderator token (simulate login via SignUpResponse.setHeaders.Authorization).
 * - As moderator, fetch details of the subcategory via GET /discussionBoard/moderator/categories/{categoryId}/subs/{subCategoryId}.
 *
 * Validate:
 * - Response includes mandatory category fields (id, name, parent_id, enabled, version, display_order, created_at, updated_at, etc.).
 * - Response does NOT contain admin-only audit fields not permitted for moderator view (if any).
 * - parent_id field should equal the created parent category's id, and id should match the subcategory id created.
 * - (No soft-delete: deleted_at should be null.)
 * - All string fields are populated, and version/display_order are numbers.
 * * Edge: Handling of missing/forbidden fields is not tested, just successful access.
 */
export async function test_api_moderator_subcategory_detail_success(connection: api.IConnection) {
  // 1. Admin creates the parent category
  const categoryName = RandomGenerator.alphabets(12);
  const adminCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      enabled: true,
      display_order: 1,
      version: 1,
    } satisfies IDiscussionBoardCategory.ICreate
  });
  typia.assert(adminCategory);

  // 2. Admin creates a sub-category under the parent
  const subCategoryName = RandomGenerator.alphabets(8);
  const adminSubCategory = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
    categoryId: adminCategory.id,
    body: {
      name: subCategoryName,
      enabled: true,
      display_order: 2,
      version: 1
    } satisfies IDiscussionBoardCategory.ICreate
  });
  typia.assert(adminSubCategory);

  // 3. Register a moderator account (assigned_by_admin_email must be an admin email address)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  // For the test, assume adminEmail is the active admin (simulate as system permits).
  const modSignUpResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: RandomGenerator.alphaNumeric(10),
    }
  });
  typia.assert(modSignUpResp);

  // 4. Simulate login as moderator (set Authorization header if needed)
  connection.headers = connection.headers || {};
  connection.headers["Authorization"] = modSignUpResp.setHeaders.Authorization;

  // 5. Moderator fetches the subcategory details
  const result = await api.functional.discussionBoard.moderator.categories.subs.atSub(connection, {
    categoryId: adminCategory.id,
    subCategoryId: adminSubCategory.id,
  });
