  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  // For the purpose of test, treat adminCategory and admin as belonging to the same admin email account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const modSignUpResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
