import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate successful update of a comment vote by its owner (member).
 *
 * This test sequence confirms that a member can change their own vote on a comment (for example, from upvote to downvote), and that the change is accurately persisted and reflected by the API.
 *
 * Business context: Comment votes are an important mechanism for discussion engagement and sentiment analytics. To prevent vote fraud or abuse, only the owner of a comment vote should be able to update their own vote. This test checks for correct ownership permissions and verifies that the update propagates as expected in the returned data.
 *
 * Test Steps:
 * 1. Register a new member account and obtain authenticated session (register + token acquisition)
 * 2. Create a discussion post as the member
 * 3. Add a comment to the created post (member as the author)
 * 4. Member casts an upvote on their own comment
 * 5. Member updates their comment vote to a downvote via the update endpoint
 * 6. Assert that the vote's new value is reflected in the response and ownership constraints are preserved
 */
export async function test_api_comment_vote_update_by_owner_success(connection: api.IConnection) {
  // 1. Member registration
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Passw0rd!";
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberSession);

  // Inject JWT for subsequent requests (simulated: real system sets Authorization automatically)
  connection.headers = {
    ...(connection.headers ?? {}),
    ...(memberSession.setHeaders ?? {})
  };

  // 2. Member creates a post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.paragraph()(25)
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 3. Add comment to the post
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(3)
    } satisfies IDiscussionBoardComment.ICreate
  });
  typia.assert(comment);

  // 4. Member creates an upvote on the comment
  const vote = await api.functional.discussionBoard.member.commentVotes.create(connection, {
    body: {
      discussion_board_comment_id: comment.id,
      is_upvote: true
    } satisfies IDiscussionBoardCommentVote.ICreate
  });
  typia.assert(vote);
  TestValidator.equals("upvote registered")(vote.is_upvote)(true);
  TestValidator.equals("ownership")(vote.discussion_board_member_id)(memberSession.member.id);

  // 5. Member updates their vote to a downvote
  const updatedVote = await api.functional.discussionBoard.member.commentVotes.update(connection, {
    commentVoteId: vote.id,
    body: {
      is_upvote: false
    } satisfies IDiscussionBoardCommentVote.IUpdate
  });
  typia.assert(updatedVote);

  // 6. Validate successful update: should now be a downvote
  TestValidator.equals("vote is now downvote")(updatedVote.is_upvote)(false);
  TestValidator.equals("vote id remains")(updatedVote.id)(vote.id);
  TestValidator.equals("ownership remains the same")(updatedVote.discussion_board_member_id)(vote.discussion_board_member_id);
}

