    report.status
  )("pending");
  TestValidator.predicate("has id")(typeof report.id === "string" && report.id.length > 0);
  TestValidator.predicate("has created_at")(typeof report.created_at === "string");
  TestValidator.predicate("has updated_at")(typeof report.updated_at === "string");
