import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostMetric";
import type { IPageIDiscussionBoardPostMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate successful search, advanced filtering, and pagination of discussion board post metrics as an admin.
 *
 * Business context: Admin dashboards and analytics tools need to filter and page through diverse post engagement metrics (views, comments, votes, reports, recency), often with advanced filtering and specific orderings. The test ensures search behaves correctly as real admins would use for monitoring and triage.
 *
 * Steps:
 * 1. Register a new admin, simulating a privileged dashboard user.
 * 2. Seed the system with multiple post metric records (at least 4), each tied to a unique post id and with deliberately varied counts for views, comments, votes, downvotes, reports, last activity, and creation times. This allows for meaningful filter exercises.
 * 3. Query post metrics (PATCH /discussionBoard/admin/postMetrics) with various advanced filters:
 *    - Filter by minimum and maximum view counts (views_count_min/max) to select a subset.
 *    - Filter by a specific post id to verify targeted search.
 *    - Filter by recency (last_activity_from/to) to select most/least recently active metrics.
 *    - Apply combinations of multiple filters (e.g., votes & recency & views) to confirm AND logic.
 *    - Order results by different keys (e.g., votes_up_count desc/asc), confirm result order matches params.
 *    - Test pagination: request a subset per page (limit, page), verify pagination info and non-overlapping pages.
 * 4. For each query, check:
 *    - Only metrics matching filters are returned (numeric and id constraints).
 *    - Sorting direction and field is respected.
 *    - Pagination info (current page, limit, records, pages) reflects expected state.
 *    - When using post_id or fully exclusive filters, empty result is possible and correctly paginated.
 * 5. Test several filter/sort/pagination combinations for breadth.
 *
 * Data cleanup is not required as test dataset is isolated by randomization. No emails or personal info are part of metric data.
 */
export async function test_api_post_metrics_search_success_advanced_filter_pagination(
  connection: api.IConnection,
) {
  // 1. Register admin and capture token
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: "1234-Abcd"
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(adminRes);
  // Assign JWT - in most E2E infra, connection.headers.Authorization is set automatically
  connection.headers = { ...(connection.headers ?? {}), ...adminRes.setHeaders };

  // 2. Create several post metrics records with varied stats
  const generatedMetrics: IDiscussionBoardPostMetric[] = [];
  const now = new Date();
  for (let i = 0; i < 4; ++i) {
    // Offset time and vary stats for diversity
    const base = i * 100;
    const metric = await api.functional.discussionBoard.admin.postMetrics.create(connection, {
      body: {
        discussion_board_post_id: typia.random<string & tags.Format<'uuid'>>(),
        views_count: base + 120,
        comments_count: base + 10,
        votes_up_count: base + 7,
        votes_down_count: base + 2,
        reports_count: i,
        last_activity_at: new Date(now.getTime() - i * 24 * 60 * 60 * 1000).toISOString(),
      } satisfies IDiscussionBoardPostMetric.ICreate
    });
    typia.assert(metric);
    generatedMetrics.push(metric);
  }

  // 3. Advanced filter: min/max views
  {
    const minViews = 150;
    const maxViews = 320;
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        views_count_min: minViews,
        views_count_max: maxViews,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (const row of filterRes.data) {
      TestValidator.predicate("views_count filter matches")(row.views_count >= minViews && row.views_count <= maxViews);
    }
    // Coverage: All rows within this range
    TestValidator.equals("non-empty if matches exist")(filterRes.data.length > 0)(true);
  }

  // 4. Filter by specific post id
  {
    const targetMetric = generatedMetrics[0];
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        discussion_board_post_id: targetMetric.discussion_board_post_id
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (const row of filterRes.data) {
      TestValidator.equals("exact post id match")(row.discussion_board_post_id)(targetMetric.discussion_board_post_id);
    }
    // Should find exactly 1 metric for this post
    TestValidator.equals("single match")(filterRes.data.length)(1);
  }

  // 5. Recency filter: last_activity_from
  {
    // Only pick most recent metric (i=0)
    const recentTS = generatedMetrics[0].last_activity_at!;
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        last_activity_from: recentTS,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (const row of filterRes.data) {
      TestValidator.predicate("recency filter")(row.last_activity_at! >= recentTS);
    }
  }

  // 6. Multi-filter (votes up + comments)
  {
    const mu = generatedMetrics[1].votes_up_count;
    const cm = generatedMetrics[1].comments_count;
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        votes_up_count_min: mu,
        comments_count_min: cm,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (const row of filterRes.data) {
      TestValidator.predicate("multi-filter and logic")(row.votes_up_count >= mu && row.comments_count >= cm);
    }
  }

  // 7. Order by votes_up_count asc
  {
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        order_by: "votes_up_count",
        order_dir: "asc",
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    for (let i = 1; i < filterRes.data.length; ++i) {
      TestValidator.predicate("ascending order")(filterRes.data[i-1].votes_up_count <= filterRes.data[i].votes_up_count);
    }
  }

  // 8. Pagination: 2 per page, page 1 then 2
  {
    const limit = 2;
    // Page 1
    const page1 = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        limit,
        page: 1,
        order_by: "views_count",
        order_dir: "desc",
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(page1);
    TestValidator.equals("page1.current")(page1.pagination.current)(1);
    TestValidator.equals("page1.limit")(page1.pagination.limit)(limit);
    TestValidator.predicate("page1 count <= limit")(page1.data.length <= limit);
    // Page 2
    const page2 = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        limit,
        page: 2,
        order_by: "views_count",
        order_dir: "desc",
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(page2);
    TestValidator.equals("page2.current")(page2.pagination.current)(2);
    TestValidator.equals("page2.limit")(page2.pagination.limit)(limit);
    // Pages do not overlap
    const ids1 = page1.data.map(x => x.id);
    const ids2 = page2.data.map(x => x.id);
    for (const id of ids1) {
      TestValidator.predicate("pagination does not overlap")(ids2.indexOf(id) === -1);
    }
  }

  // 9. Exclusive filter - no match
  {
    const filterRes = await api.functional.discussionBoard.admin.postMetrics.search(connection, {
      body: {
        views_count_min: 99999,
      } satisfies IDiscussionBoardPostMetric.IRequest,
    });
    typia.assert(filterRes);
    TestValidator.equals("no matching rows")(filterRes.data.length)(0);
    TestValidator.equals("pagination for empty")(filterRes.pagination.records)(0);
  }
}

