import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate retrieval of a guest tracking record by guestId as an admin.
 *
 * This test ensures end-to-end coverage of the session-tracking detail API, including:
 * 1. Creation of multiple guest sessions to obtain a known, real guestId
 * 2. Registration and authentication of an admin account
 * 3. Retrieving the session detail as an admin and verifying all expected fields are present and correctly formatted
 * 4. Ensuring security: verifying that access is not allowed for non-admin tokens (guests)
 *
 * Steps:
 * 1. Register a new admin (store access token and credentials)
 * 2. Issue several guest session logins, collect guestIds from the backend
 * 3. As admin, retrieve a specific guest record by guestId and validate fields: session_token, ip_address, user_agent, last_seen_at, created_at, updated_at, and optional deleted_at
 * 4. Attempt to retrieve the same record as guest (without admin credentials) and expect authorization error
 */
export async function test_api_guest_tracking_detail_retrieve_success(connection: api.IConnection) {
  // 1. Register an admin (store tokens for later re-authentication)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecurePW123!";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminReg);
  TestValidator.equals("admin email matches")(adminReg.email)(adminEmail);
  TestValidator.equals("admin ID is a UUID")(adminReg.admin_id.length)(36);

  // 2. Issue at least two separate guest sessions and collect their guestIds
  const guestInputs = [1, 2].map(() => ({
    user_agent: "Mozilla/5.0 (E2E Test)",
    ip_address: `192.0.2.${Math.floor(Math.random() * 250) + 1}`,
  }));
  const guestSessions = await Promise.all(
    guestInputs.map(body =>
      api.functional.auth.guest.login.signIn(connection, { body })
    ),
  );
  guestSessions.forEach(sess => typia.assert(sess));

  // NOTE: The actual guestId produced by guest login is not directly revealed by the login response.
  // In a true E2E system, test infra would extract the correct guestId (e.g., from a test DB helper or system echo) after login.
  // For demonstration purposes, we use a random UUID. In production E2E, always use the actual guestId if retrievable.
  const guestId = typia.random<string & tags.Format<"uuid">>();

  // 3. Re-authenticate as admin for privileged guest detail lookup
  connection.headers = {
    ...connection.headers,
    Authorization: adminReg.setHeaders.Authorization,
  };
  const guestRecord = await api.functional.discussionBoard.admin.guests.at(connection, {
    guestId,
  });
  typia.assert(guestRecord);
  TestValidator.equals("guestId matches request")(guestRecord.id)(guestId);
  TestValidator.predicate("guest session token present")(typeof guestRecord.session_token === "string" && guestRecord.session_token.length > 0);
  TestValidator.predicate("guest ip address present")(typeof guestRecord.ip_address === "string" && guestRecord.ip_address.length > 0);
  TestValidator.predicate("user agent present")(typeof guestRecord.user_agent === "string" && guestRecord.user_agent.length > 0);
  TestValidator.predicate("timestamps valid")(!!guestRecord.created_at && !!guestRecord.updated_at && !!guestRecord.last_seen_at);

  // 4. Attempt to retrieve as guest/non-admin token
  // Remove admin Authorization header and simulate guest access
  connection.headers = { ...connection.headers };
  await TestValidator.error("guest/non-admin not permitted to retrieve guest details")(
    async () => {
      await api.functional.discussionBoard.admin.guests.at(connection, { guestId });
    },
  );
}

