/**
 * Validates that a moderator can successfully search and list discussion board categories with filters.
 *
 * This test simulates a real-world scenario where an admin creates multiple categories (including nested/parent-child and enabled/disabled variations), and then a moderator retrieves those categories using search filters.
 *
 * Steps:
 * 1. Generate a fake admin email to act as the assigning admin for moderator signup.
 * 2. Admin creates several categories:
 *    - At least one root category (no parent)
 *    - At least one subcategory (with parent_id of the root)
 *    - Include both enabled:true and enabled:false variations in categories
 *    - Vary names and descriptions for filter testing
 * 3. Register a moderator account, using the above admin email as the assigner (to ensure fully valid RBAC).
 * 4. As the moderator (connection uses returned Authorization), perform paginated category searches:
 *    a. By parent_id (should return just appropriate child categories)
 *    b. By enabled flag (both true and false)
 *    c. By partial name match (should be case-sensitive substring search)
 *    d. By page/limit (test pagination correctness)
 * 5. Assert that results match filtered expectations:
 *    - All fields correspond to accessible data for moderators
 *    - No extra or missing categories in each filtered case
 *    - Pagination metadata matches total items
 */
export async function test_api_category_search_moderator_success(connection: api.IConnection) {
  // 1. Generate admin email for assigning moderator
  const adminEmail = typia.random<string & tags.Format<"email">>();

  // 2. Admin creates categories
  // 2a. Root category (enabled)
  const rootCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: "RootCategory_ENABLED",
        display_order: 1,
        enabled: true,
        version: 1
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(rootCategory);
  // 2b. Subcategory (enabled)
  const subCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: "SubCategory_ENABLED",
        display_order: 2,
        enabled: true,
        version: 1,
        parent_id: rootCategory.id
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(subCategory);
  // 2c. Disabled root category
  const disabledRoot = await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: "RootCategory_DISABLED",
        display_order: 3,
        enabled: false,
        version: 1
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(disabledRoot);
  // 2d. Disabled subcategory under disabled root
  const disabledSub = await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: "SubCategory_DISABLED",
        display_order: 4,
        enabled: false,
        version: 1,
        parent_id: disabledRoot.id
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(disabledSub);
  // 2e. Unique name category for searching
  const specialName = `SpecialSearch_${RandomGenerator.alphabets(8)}`;
  const specialCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
      body: {
        name: specialName,
        display_order: 5,
        enabled: true,
        version: 1,
        description: "Used for partial name filter"
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(specialCategory);

  // 3. Register moderator (with auto-token injection into connection)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "testP@ssw0rd";
  const moderator = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword
    } satisfies IModerator.SignUp
  });
  typia.assert(moderator);
  // Apply token for future moderator calls
  connection.headers = {
    ...connection.headers,
    ...moderator.setHeaders
  };

  // 4a. Filter by parent_id (should return only subCategory)
  const byParent = await api.functional.discussionBoard.moderator.categories.search(connection, {
      body: {
        parent_id: rootCategory.id,
      } satisfies IDiscussionBoardCategory.IRequest
    });
  typia.assert(byParent);
  TestValidator.predicate("returns only subCategory with parent_id = rootCategory.id")(byParent.data.length === 1 
 byParent.data[0].id === subCategory.id);

