 * 5. Switch context to a moderator (simulate with connection context; assumes system-level authorization or manually reset connection headers if required by business logic).
 * 6. Retrieve the post vote using the moderator GET endpoint by the returned postVoteId.
 * 7. Assert that the output contains all expected fields and matches the actual vote previously created by the member (including field-by-field validation).
 */
export async function test_api_post_vote_detail_moderator_success(connection: api.IConnection) {
