  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword = "test-Password123!";
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // Set connection authorization header for the member
  connection.headers = { ...connection.headers, ...memberSession.setHeaders };

  // 2. Create a new post as this member
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()().slice(0, 100),
      body: RandomGenerator.content()()().slice(0, 4000),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Vote on the post as the member
  const isUpvote = true;
  const vote = await api.functional.discussionBoard.member.postVotes.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      is_upvote: isUpvote,
    } satisfies IDiscussionBoardPostVote.ICreate,
  });
  typia.assert(vote);

  // 4. Switch context to moderator (simulate: use a new connection with moderator credentials or clear headers for unrestricted mod endpoint)
  // For most OpenAPI e2e systems, this step assumes default connection after clearing member auth.
  connection.headers = {};

  // 5. Retrieve the vote as moderator
  const modVote = await api.functional.discussionBoard.moderator.postVotes.at(connection, {
    postVoteId: vote.id,
  });
  typia.assert(modVote);

  // 6. Assert all fields on the retrieved vote match expectation
  TestValidator.equals("Vote ID matches")(modVote.id)(vote.id);
  TestValidator.equals("Post ID matches")(modVote.discussion_board_post_id)(post.id);
  TestValidator.equals("Member ID matches")(modVote.discussion_board_member_id)(vote.discussion_board_member_id);
  TestValidator.equals("Upvote flag matches")(modVote.is_upvote)(isUpvote);
  // Fields like created_at, updated_at should exist as valid date strings
  TestValidator.predicate("created_at is ISO8601 date")(!!modVote.created_at && !isNaN(Date.parse(modVote.created_at)));
  TestValidator.predicate("updated_at is ISO8601 date")(!!modVote.updated_at && !isNaN(Date.parse(modVote.updated_at)));
}

