import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test that an admin can soft delete any comment on any post (discussion board).
 *
 * Business context:
 * - Admins should be able to logically (soft) delete any comment on any post for moderation or policy reasons.
 * - A soft-deleted comment should be appropriately flagged in the backend, not physically removed, and should not appear in standard member queries.
 *
 * Test Workflow:
 * 1. Register a discussion/member account.
 * 2. Register a discussion board admin account.
 * 3. Log in as the member (token is in connection.headers)
 * 4. Create a post as that member.
 * 5. Create a comment for the post as that member.
 * 6. Switch to admin (token is in connection.headers).
 * 7. Soft delete the comment (admin endpoint).
 * 8. (Optional) Query backend directly for comment (if query function were available) to check deleted_at is set and status is updated. (NOTE: No public API to re-fetch by commentId exists, so step will be omitted as cannot be implemented.)
 * 9. (Optional) Ensure the deleted comment would not appear in normal comment queries (no query function for comments available, so step will be omitted as well.)
 *
 * Thus, this test will focus on proper completion of the delete operation (logical deletion by admin), and will at least assert all available outputs and pre/post state that the SDK structure allows.
 */
export async function test_api_admin_comment_soft_delete_valid(connection: api.IConnection) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const memberNickname = RandomGenerator.name();
  const memberPassword = 'Test1234!';
  const memberRegRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberRegRes);
  const memberId = memberRegRes.member.id;

  // 2. Register an admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'Admin1234!';
  const adminRegRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(adminRegRes);

  // 3. Create a post as member
  // (connection is already member session because just registered member)
  const postTitle = RandomGenerator.paragraph()(1).slice(0, 100);
  const postBody = RandomGenerator.content()()().slice(0, 4000);
  const postRes = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: postTitle,
      body: postBody
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(postRes);
  const postId = postRes.id;

  // 4. Create a comment as member
  const commentBody = RandomGenerator.paragraph()(1).slice(0, 1000);
  const commentRes = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId,
    body: {
      body: commentBody
    } satisfies IDiscussionBoardComment.ICreate
  });
  typia.assert(commentRes);
  const commentId = commentRes.id;

  // 5. Switch to admin (simulate admin login by using admin session's token)
  connection.headers = {
    ...connection.headers,
    Authorization: adminRegRes.setHeaders.Authorization
  };

  // 6. Soft delete the comment using the admin endpoint
  await api.functional.discussionBoard.admin.posts.comments.erase(connection, {
    postId,
    commentId
  });

  // 7. (No SDK to fetch the deleted comment to double-check deleted_at)

  // 8. (No API to list comments, so cannot check comment absence in queries)
}

