import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Verify that updating a deleted comment is strictly forbidden in the discussion board member context.
 *
 * This test ensures that after a comment is created and then soft-deleted, any further update attempts are not allowed. The API must enforce logical deletion correctly, preventing modification of a comment that has already been deleted, and it must return an appropriate error (typically not found or forbidden).
 *
 * Steps:
 * 1. Register a new member for comment ownership and authentication context.
 * 2. Create a new post under the registered member account.
 * 3. Add a new top-level comment to the created post using the member session.
 * 4. Soft-delete (logically remove) the comment just created, simulating a deleted state.
 * 5. Attempt to update the soft-deleted comment (change body field) using the same author session.
 * 6. Assert that the update attempt throws an error—API should prevent update and respond with a not found or forbidden error, confirming business rules.
 */
export async function test_api_comment_update_forbidden_on_deleted_comment(
  connection: api.IConnection,
) {
  // 1. Register a new member to act as the comment author
  const memberInput: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Secur3P@ss#" + typia.random<number & tags.Type<"uint32">>(),
    nickname: RandomGenerator.name(),
    avatar_uri: null,
  };
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: memberInput,
  });
  typia.assert(session);

  // The token is set in connection.headers. Proceed as the registered member.

  // 2. Create a new post as this member
  const postInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph(1)().slice(0, 100), // Max 100 chars
    body: RandomGenerator.content(1)().slice(0, 1000),   // Max 4000 chars (limit further for safety)
    attachments: null,
    category_id: null,
    platform_config_id: null,
  };
  const post = await api.functional.discussionBoard.member.posts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // 3. Add a new comment under the created post
  const commentInput: IDiscussionBoardComment.ICreate = {
    body: RandomGenerator.paragraph(1)().slice(0, 1000), // Max 1000 chars
    thread_parent_comment_id: null,
  };
  const comment = await api.functional.discussionBoard.member.posts.comments.create(
    connection,
    { postId: post.id, body: commentInput },
  );
  typia.assert(comment);

  // 4. Soft-delete (logically remove) the comment
  await api.functional.discussionBoard.member.posts.comments.erase(
    connection,
    { postId: post.id, commentId: comment.id },
  );

  // 5. Attempt to update the deleted comment
  const updateInput: IDiscussionBoardComment.IUpdate = {
    body: "This edit should be rejected", // Try to update body
    status: null,                         // No status update
  };
  await TestValidator.error("update forbidden on deleted comment")(
    async () => {
      await api.functional.discussionBoard.member.posts.comments.update(
        connection,
        {
          postId: post.id,
          commentId: comment.id,
          body: updateInput,
        },
      );
    },
  );
}

