import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostReport";
import type { IPageIDiscussionBoardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test moderator post report search for empty result and restricted access
 *
 * This test verifies two scenarios:
 * 1. A moderator attempts to search for post abuse reports using filters that ensure no reports are found, and verifies that the paginated result contains an empty data array.
 * 2. An unauthorized user (a regular member) attempts to call the moderator postReports search endpoint and receives an error (access denied/unauthorized).
 *  
 * Business context:
 * - Moderator endpoints should only be accessible to privileged users (moderator/admin roles). Regular members should receive errors on any attempt to use moderator-specific endpoints.
 * - Moderators may search for post reports using various filters and should receive empty results when no matching data exists.
 *
 * Step-by-step process:
 * 1. Register a test member (used as a regular member for negative authorization check)
 * 2. Register another test member (simulating a moderator, but with only member rights, since there is no explicit moderator registration API available)
 * 3. As a regular member, create a post to establish minimal context
 * 4. As a (simulated) moderator, attempt to search for post reports with filters guaranteed to yield no results (e.g., filter by a random UUID as discussion_board_post_id)
 * 5. Verify that the paginated result data array is empty
 * 6. As a regular member, attempt to use the moderator post report search endpoint
 * 7. Verify that the regular member receives a permission error (TestValidator.error)
 *
 * Note: As there is no public API to elevate a member to moderator/admin, only business logic is validated. True role-based enforcement can only be fully exercised with real moderator credentials.
 */
export async function test_api_post_report_search_moderator_no_results_and_restricted_access(connection: api.IConnection) {
  // 1. Register member1 (regular user)
  const member1Email = typia.random<string & tags.Format<'email'>>();
  const member1Session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member1Email,
      password: "Test123!",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1Session);

  // 2. Register member2 (simulated moderator, not a real moderator)
  const member2Email = typia.random<string & tags.Format<'email'>>();
  const member2Session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member2Email,
      password: "Test234!",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member2Session);

  // 3. As member1, create a post
  connection.headers = { Authorization: member1Session.setHeaders.Authorization };
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: "Moderator ghost search test",
      body: "This post exists for E2E edge search test.",
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. As member2 (simulated moderator), search with guaranteed-no-match filter
  connection.headers = { Authorization: member2Session.setHeaders.Authorization };
  const noMatchFilter = {
    discussion_board_post_id: typia.random<string & tags.Format<'uuid'>>(), // random UUID, no report will match
    page: 1,
    limit: 10,
  } satisfies IDiscussionBoardPostReport.IRequest;
  const searchResult = await api.functional.discussionBoard.moderator.postReports.search(connection, { body: noMatchFilter });
  typia.assert(searchResult);
  TestValidator.equals("empty result data")(searchResult.data)([]);

  // 5. As regular member, attempt to call moderator endpoint and expect error
  connection.headers = { Authorization: member1Session.setHeaders.Authorization };
  const memberSearchFilter = {
    page: 1,
    limit: 5,
  } satisfies IDiscussionBoardPostReport.IRequest;
  await TestValidator.error("regular member cannot access moderator endpoint")(async () => {
    await api.functional.discussionBoard.moderator.postReports.search(connection, { body: memberSearchFilter });
  });
}

