import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Test retrieving analytics (user metrics) detail as a moderator for a specific userMetricsId.
 *
 * This test ensures complete coverage of analytics detail retrieval, requiring realistic scenario setup:
 * 1. Register a moderator (for authenticated access to protected analytics endpoint)
 * 2. Register a new member account (the subject of the analytics)
 * 3. As admin, create a user metrics record for the new member (initialize with known values)
 * 4. As moderator, fetch and validate all relevant analytics fields for the created metricsId
 * 5. Validate that all engagement and reputation fields are correct, audit fields are present, and record is active (not soft-deleted)
 *
 * Steps:
 * 1. Register and authenticate a moderator (acquire auth for endpoint)
 * 2. Register a new discussion board member (collect memberId)
 * 3. As admin, create a userMetrics analytic record for the new member (use known counters)
 * 4. As moderator, invoke GET /discussionBoard/moderator/userMetrics/{userMetricsId} for the created userMetricsId
 * 5. Assert all fields: participation (posts/comments), votes, reports, reputation, and audit fields, confirming entity is active (no deletion/withdrawal status)
 */
export async function test_api_user_metrics_detail_by_moderator_success(connection: api.IConnection) {
  // 1. Register and authenticate moderator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Password1!";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorSignUp);

  // 2. Register a discussion board member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "testpass1234!";
  const memberNickname = RandomGenerator.name();
  const memberResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberResult);
  const memberId = memberResult.member.id;

  // 3. As admin, create the user metric analytics record
  const analyticInitVals = {
    discussion_board_member_id: memberId,
    posts_count: 2,
    comments_count: 4,
    votes_up_given_count: 7,
    votes_down_given_count: 1,
    reports_made_count: 0,
    reputation_score: 15,
    last_activity_at: new Date().toISOString(),
  } satisfies IDiscussionBoardUserMetric.ICreate;
  const userMetrics = await api.functional.discussionBoard.admin.userMetrics.create(connection, { body: analyticInitVals });
  typia.assert(userMetrics);

  // 4. As moderator, retrieve detailed user metrics
  const analyticDetail = await api.functional.discussionBoard.moderator.userMetrics.at(connection, { userMetricsId: userMetrics.id });
  typia.assert(analyticDetail);

  // 5. Validate returned fields match what was initialized (ignoring auto audit fields)
  TestValidator.equals("member id matches")(analyticDetail.discussion_board_member_id)(memberId);
  TestValidator.equals("posts count matches")(analyticDetail.posts_count)(analyticInitVals.posts_count);
  TestValidator.equals("comments count matches")(analyticDetail.comments_count)(analyticInitVals.comments_count);
  TestValidator.equals("upvotes given count matches")(analyticDetail.votes_up_given_count)(analyticInitVals.votes_up_given_count);
  TestValidator.equals("downvotes given count matches")(analyticDetail.votes_down_given_count)(analyticInitVals.votes_down_given_count);
  TestValidator.equals("reports made count matches")(analyticDetail.reports_made_count)(analyticInitVals.reports_made_count);
  TestValidator.equals("reputation score matches")(analyticDetail.reputation_score)(analyticInitVals.reputation_score);
  if (analyticInitVals.last_activity_at)
    TestValidator.equals("last activity at matches")(analyticDetail.last_activity_at)(analyticInitVals.last_activity_at);

  // Validate audit fields (created_at/updated_at are ISO datetime strings)
  TestValidator.predicate("created_at is a valid ISO datetime")(!!analyticDetail.created_at && !isNaN(Date.parse(analyticDetail.created_at)));
  TestValidator.predicate("updated_at is a valid ISO datetime")(!!analyticDetail.updated_at && !isNaN(Date.parse(analyticDetail.updated_at)));
}

