import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Verify that a moderator can update a post written by a member, confirming audit trail and status transitions.
 *
 * Business context:
 * Moderators should be able to alter any editable field of a member's post (e.g., content, status, category, attachments) for purposes such as policy enforcement, correction, or hiding. Authorship should be preserved, and audit fields (updated_at) should reflect the update. Enforcement of moderator privileges and auditability is crucial.
 *
 * Test workflow:
 * 1. Register a random member (obtain access token)
 * 2. That member creates a post with required fields (title, body)
 * 3. Register a moderator (obtain access token by registration)
 * 4. As moderator, update the member's post changing title, body, attachments, category_id, and set status to 'hidden'.
 * 5. Verify the returned post has the expected updates, updated_at has changed, and authorship (author_member_id) remains unchanged.
 */
export async function test_api_moderator_update_another_users_post(connection: api.IConnection) {
  // 1. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "1234Strong!";
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 2. Member creates a post
  connection.headers = { ...connection.headers, ...memberSession.setHeaders };
  const postTitle = RandomGenerator.paragraph()(1, 4).slice(0, 100);
  const postBody = RandomGenerator.content()()().slice(0, 4000);
  const createInput: IDiscussionBoardPost.ICreate = {
    title: postTitle,
    body: postBody,
    attachments: JSON.stringify(["https://example.com/attachment1.png"]),
  };
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: createInput,
  });
  typia.assert(post);
  const preUpdateTimestamp = post.updated_at;

  // 3. Register moderator
  const adminEmail = typia.random<string & tags.Format<"email">>(); // Simulate assigning admin
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorSession = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: "secureModeratorPwd#1",
    },
  });
  typia.assert(moderatorSession);

  // 4. Switch to moderator context, update the member's post
  connection.headers = { ...connection.headers, ...moderatorSession.setHeaders };
  const updateInput: IDiscussionBoardPost.IUpdate = {
    title: postTitle + " [Edited by Moderator]",
    body: postBody + "\n[Policy correction]",
    attachments: JSON.stringify(["https://example.com/attachment2.pdf"]),
    status: "hidden",
  };
  const updated = await api.functional.discussionBoard.moderator.posts.update(connection, {
    postId: post.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 5. Assertions: verify updates
  TestValidator.equals("title updated")(updated.title)(updateInput.title);
  TestValidator.equals("body updated")(updated.body)(updateInput.body);
  TestValidator.equals("attachments changed")(updated.attachments)(updateInput.attachments);
  TestValidator.equals("status set to hidden")(updated.status)("hidden");
  TestValidator.equals("author is unchanged")(updated.author_member_id)(post.author_member_id);
  TestValidator.notEquals("updated_at changed")(updated.updated_at)(preUpdateTimestamp);
}

