  const memberNickname = RandomGenerator.name();
  const memberPassword = "pw1234!";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    },
  });
  typia.assert(memberSession);
  const memberId = memberSession.member.id;

  // 3. Create a sanction record for the member
  // Use admin's auth/session
  const sanctionType = "temporary_ban";
  const sanctionLevel = "moderate";
  const reasonType = "spam";
  const now = new Date();
  const sanctionStart = now.toISOString();
  const sanctionEnd = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
  const sanction = await api.functional.discussionBoard.admin.userSanctions.create(connection, {
    body: {
      sanctioned_member_id: memberId,
      sanctioning_admin_id: adminRes.admin_id,
      sanction_type: sanctionType,
      sanction_level: sanctionLevel,
      reason_type: reasonType,
      reason_text: "Spam activity detected.",
      timeline_start: sanctionStart,
      timeline_end: sanctionEnd,
    },
  });
  typia.assert(sanction);
  const userSanctionId = sanction.id;

  // 4. Register a moderator and obtain a JWT
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "modpw1234";
  const moderatorRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorRes);

  // 5. Moderator deletes the user sanction using DELETE
  connection.headers = { ...(connection.headers ?? {}), Authorization: moderatorRes.setHeaders.Authorization };
  await api.functional.discussionBoard.moderator.userSanctions.erase(connection, { userSanctionId });

  // 6. (Optional) Try to retrieve or search for the sanction; expect not found (if such GET exists). Otherwise, pass test if no error so far.
}

