import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validate guest access to their own notification detail by ID in discussion board system.
 *
 * This test checks that a guest user, after obtaining a session and token, can only retrieve notifications that were explicitly created for their own session (by guest_id), and that the notification returned matches schema and linkage rules. It also ensures that this notification is not accessible by others and must return full content accurately.
 *
 * Test steps:
 * 1. Authenticate as a guest user: obtain a valid session/JWT token. This establishes the guest session/identity and gives us a guest_id (typically encoded in the JWT or mapped server-side).
 * 2. Simulate the admin creating a notification for this guest (using guest_id in the notification recipient field). Capture newly created notification's ID for lookup and ensure that the notification's guest_id matches that of the logged-in guest.
 * 3. As the same guest session, call GET /discussionBoard/guest/notifications/:notificationId using the notificationId. Validate that the returned entity is of type IDiscussionBoardNotification, that its guest_id matches, and that all core fields (title, body, event_type, unread, timestamps etc.) match what was set by the admin.
 * 4. Optionally: Attempt access with a different session (e.g., a new guest token or without authentication) to ensure 403/404 error. (This negative test is described in scenario, but skipped if cannot simulate alternate sessions in current harness.)
 */
export async function test_api_guest_notification_detail_access_success(connection: api.IConnection) {
  // 1. Authenticate guest session
  const guestSignInReq: IGuestAuthGuestSignInRequest = {
    user_agent: RandomGenerator.alphaNumeric(16),
    ip_address: `192.168.${typia.random<number & tags.Type<"uint32"> & tags.Maximum<255>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Maximum<255>>()}`,
  };
  const guestAuthResp: IGuestAuthGuestSignInResponse = await api.functional.auth.guest.login.signIn(connection, { body: guestSignInReq });
  typia.assert(guestAuthResp);

  // Update connection with guest token for authenticated actions
  connection.headers = {
    ...(connection.headers ?? {}),
    ...(guestAuthResp.setHeaders ?? {}),
  };

  // 2. Admin creates notification for this guest_id
  // Extract guest_id from JWT to set for notification recipient
  const guestId = extractGuestIdFromToken(guestAuthResp.setHeaders.Authorization);
  if (!guestId)
    throw new Error("Could not extract guest_id from guest JWT token.");

  const notificationBody: IDiscussionBoardNotification.ICreate = {
    guest_id: guestId,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.paragraph()(),
    event_type: "system.alert"
  };
  const notifResp: IDiscussionBoardNotification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: notificationBody,
  });
  typia.assert(notifResp);

  // 3. Guest calls GET notification detail endpoint
  const notifDetail = await api.functional.discussionBoard.guest.notifications.at(connection, {
    notificationId: notifResp.id
  });
  typia.assert(notifDetail);

  // 4. Validate that the returned entity matches schema and linkage logic
  TestValidator.equals("returned notification id matches")(notifDetail.id)(notifResp.id);
  TestValidator.equals("notification guest_id matches")(notifDetail.guest_id)(notifResp.guest_id);
  TestValidator.equals("title matches")(notifDetail.title)(notificationBody.title);
  TestValidator.equals("body matches")(notifDetail.body)(notificationBody.body);
  TestValidator.equals("event_type matches")(notifDetail.event_type)(notificationBody.event_type);
  TestValidator.predicate("must be unread")(notifDetail.unread === true);
  TestValidator.predicate("created_at exists")(!!notifDetail.created_at);
  TestValidator.predicate("updated_at exists")(!!notifDetail.updated_at);
  // 5. Optional: Verify forbidden access with wrong guest or unauthenticated (not implemented here)
}

// Helper: decode guest_id from JWT token (simplified placeholder, not for prod use)
function extractGuestIdFromToken(token: string): string | undefined {
  // JWT: header.payload.signature base64
  const payload = token.split(".")[1];
  if (!payload) return undefined;
  try {
    const json = JSON.parse(Buffer.from(payload, "base64").toString("utf8"));
    return json.guest_id || json.sub || undefined;
  } catch {
    return undefined;
  }
}

