import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validate guest notification pagination and filtering.
 *
 * This test ensures that a guest user can retrieve a paginated and filtered list of notifications relevant to their session, including filtering by unread status and event type. The business logic requires the following workflow:
 *
 * 1. Authenticate as a guest to obtain a JWT and identify the guest session for notification targeting.
 * 2. As an admin, create multiple notifications targeted to the guest (with variation in event_type, unread flag, etc).
 * 3. As the guest, request notifications with various pagination and filter parameters—such as unread only, or specific event types.
 * 4. Verify the response includes only notifications targeted to this guest, with correct filtering and pagination meta info.
 * 5. Validate that unread filtering works and that only matching event_types appear when filtered.
 */
export async function test_api_guest_notification_pagination_and_filtering_success(connection: api.IConnection) {
  // 1. Authenticate as guest and obtain the guest JWT session
  const guestSignInRes = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: RandomGenerator.alphaNumeric(12),
      ip_address: "127.0.0.1",
    },
  });
  typia.assert(guestSignInRes);
  const guestToken = guestSignInRes.token;
  const guestId = guestSignInRes.setHeaders.Authorization.split(" ")[1] || guestToken;

  // 2. As admin, create notifications targeted to this guest
  //   - Create multiple with various event_types, unread status, etc.
  //   - All must include the guest_id from step 1
  const eventTypes = ["post_comment", "sanction", "announcement"];
  const notifications = await Promise.all(eventTypes.map(async (eventType) => {
    const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
      body: {
        guest_id: guestId,
        title: `Notification for event: ${eventType}`,
        body: `Body for ${eventType} event`,
        event_type: eventType,
        related_entity_id: null,
        related_entity_type: null,
      },
    });
    typia.assert(notification);
    return notification;
  }));

  // 3. Use the guest JWT for subsequent requests (simulate user with Authorization header)
  connection.headers = { ...(connection.headers || {}), Authorization: `Bearer ${guestToken}` };

