  const guestToken = guestAuth.token;
  const guestAuthorization = guestAuth.setHeaders.Authorization;

  // Extract a synthetic guest identifier for targeting: typically the guest JWT, but strictly guest_id for notification
  // For this test, we'll use the JWT token (issued identity), as guest_id must match for notification delivery
  const guestId = guestToken;

