  TestValidator.predicate("Should include at least one rule log of type permission_matrix")(
    resByType.data.some(x => x.rule_type === "permission_matrix")
  );

  // 4c. Filter by effective_from (gte/lte)
  const resByTime = await api.functional.discussionBoard.admin.ruleLogs.search(connection, {
    body: {
      effective_from_gte: now,
      effective_from_lte: now
    }
  });
  typia.assert(resByTime);
  TestValidator.predicate("Should find rule log with expected effective_from")(
    resByTime.data.some(x => x.effective_from === now)
  );

  // 4d. Pagination: limit 1, page 1
  const paged = await api.functional.discussionBoard.admin.ruleLogs.search(connection, {
    body: {
      limit: 1,
      page: 1
    }
  });
  typia.assert(paged);
  TestValidator.equals("pagination limit")(paged.pagination.limit)(1);
  TestValidator.equals("pagination current page")(paged.pagination.current)(1);

  // 5. Validate log fields mapping with known values
  const matchingLog = resByAdmin.data.find(x => x.rule_type === "permission_matrix" && x.operator_admin_id === adminId);
  if (!matchingLog) throw new Error("Expected rule log not found");
  TestValidator.equals("rule log action matches")(matchingLog.change_type)("created");
  TestValidator.equals("rule type matches")(matchingLog.rule_type)("permission_matrix");
}

