import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import type { IPageIDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuest";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate the admin guest session search and pagination API.
 *
 * This test ensures that an administrator can search and paginate non-member (guest) session tracking records from the discussion board using a combination of available filters:
 *  - session_token
 *  - ip_address
 *  - user_agent
 *  - last_seen_at date range
 *  - pagination (limit, page)
 *  - ordering (order_by, order)
 *
 * Steps:
 * 1. Register a new admin and ensure the returned account and JWTs are valid, capturing the Authorization token for later admin searches.
 * 2. Create several unique guest session records via guest login API, using a variety of user agent/IP/date values for thorough filter testing.
 * 3. As admin, search for guest sessions by:
 *    a) session_token
 *    b) ip_address
 *    c) user_agent
 *    d) date range (last_seen_at_from/to)
 *    e) pagination (setting limit and page)
 *    f) ordering (created_at, updated_at, last_seen_at; asc & desc)
 *
 * Validate:
 *  - Only non-deleted sessions are returned (no logical deletes shown)
 *  - Summary audit fields (id, session_token, ip_address, user_agent, last_seen_at) are present and correct for results
 *  - Pagination metadata is correct (limit, current, records, pages)
 *  - Records are correctly ordered by requested field and direction
 *  - Admin authorization is enforced (e.g., if not logged in as admin, operation errors)
 *
 * 4. Test invalid authorization: call the API with a guest token and verify access is denied.
 */
export async function test_api_guest_tracking_search_success(connection: api.IConnection) {
  // 1. Register and authenticate a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPass = RandomGenerator.alphaNumeric(12);
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPass,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // Update connection headers to use admin Authorization for future requests
  connection.headers = { ...connection.headers, Authorization: adminAuth.setHeaders.Authorization };

  // 2. Simulate guest logins to create sessions for search coverage
  const guestSessions = await ArrayUtil.asyncRepeat(5)(async () => {
    const ip = RandomGenerator.ipv4();
    const userAgent = RandomGenerator.alphabets(8) + RandomGenerator.alphaNumeric(4);
    const guestLogin = await api.functional.auth.guest.login.signIn(connection, {
      body: {
        ip_address: ip,
        user_agent: userAgent,
      } satisfies IGuestAuthGuestSignInRequest,
    });
    typia.assert(guestLogin);
    return { ...guestLogin, ip_address: ip, user_agent: userAgent };
  });

  // Ensure enough distinct data to test search
  const [targetGuest] = guestSessions;

  // 3a. Search by session_token
  const byToken = await api.functional.discussionBoard.admin.guests.search(connection, {
    body: { session_token: targetGuest.token } satisfies IDiscussionBoardGuest.IRequest,
  });
  typia.assert(byToken);
  TestValidator.predicate("filter by session_token")(byToken.data.length > 0 && byToken.data.some(g => g.session_token === targetGuest.token));

  // 3b. Search by ip_address
  const byIp = await api.functional.discussionBoard.admin.guests.search(connection, {
    body: { ip_address: targetGuest.ip_address } satisfies IDiscussionBoardGuest.IRequest,
  });
  typia.assert(byIp);
  TestValidator.predicate("filter by ip_address")(byIp.data.length > 0 && byIp.data.every(g => g.ip_address === targetGuest.ip_address));

  // 3c. Search by user_agent
  const byAgent = await api.functional.discussionBoard.admin.guests.search(connection, {
    body: { user_agent: targetGuest.user_agent } satisfies IDiscussionBoardGuest.IRequest,
  });
  typia.assert(byAgent);
  TestValidator.predicate("filter by user_agent")(byAgent.data.length > 0 && byAgent.data.every(g => g.user_agent === targetGuest.user_agent));

  // 3d. Search by last_seen_at_from/to (narrow window so must match specific guest)
  const now = new Date();
  const windowBefore = new Date(now.getTime() - 5 * 60000).toISOString();
  const windowAfter = new Date(now.getTime() + 5 * 60000).toISOString();
  const byDate = await api.functional.discussionBoard.admin.guests.search(connection, {
    body: {
      last_seen_at_from: windowBefore,
      last_seen_at_to: windowAfter,
    } satisfies IDiscussionBoardGuest.IRequest,
  });
  typia.assert(byDate);
  TestValidator.predicate("filter by last_seen_at window")(byDate.data.length > 0);

  // 3e. Pagination: set limit=2 & page=1, check pagination metadata
  const paged = await api.functional.discussionBoard.admin.guests.search(connection, {
    body: { limit: 2, page: 1 } satisfies IDiscussionBoardGuest.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("pagination.limit")(paged.pagination.limit)(2);
  TestValidator.equals("pagination.current")(paged.pagination.current)(1);

  // 3f. Ordering: order_by="created_at" desc
  const orderedDesc = await api.functional.discussionBoard.admin.guests.search(connection, {
    body: { order_by: "created_at", order: "desc" } satisfies IDiscussionBoardGuest.IRequest,
  });
  typia.assert(orderedDesc);
  TestValidator.predicate("ordered created_at desc")(
    orderedDesc.data.length < 2 ||
    orderedDesc.data.every((item, i, arr) => i === 0 || !arr[i-1].id || !item.id || item.id <= arr[i-1].id)
  );

  // Validate summary audit fields presence for each record in one result
  for (const g of paged.data) {
    TestValidator.predicate("summary.id exists")(typeof g.id === "string" && !!g.id);
    TestValidator.predicate("summary.session_token exists")(typeof g.session_token === "string" && !!g.session_token);
    TestValidator.predicate("summary.ip_address exists")(typeof g.ip_address === "string" && !!g.ip_address);
    TestValidator.predicate("summary.user_agent exists")(typeof g.user_agent === "string" && !!g.user_agent);
    TestValidator.predicate("summary.last_seen_at exists")(typeof g.last_seen_at === "string" && !!g.last_seen_at);
  }

  // 4. Attempt search as guest: should be unauthorized
  const guestConn = { ...connection, headers: { ...connection.headers } };
  // Use one of the guest session tokens
  guestConn.headers.Authorization = guestSessions[0].setHeaders.Authorization;
  await TestValidator.error("guest token forbidden access to admin API")(async () => {
    await api.functional.discussionBoard.admin.guests.search(guestConn, {
      body: {} as IDiscussionBoardGuest.IRequest,
    });
  });
}

