import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test RBAC (Role-Based Access Control) for updating an admin profile on the discussion board.
 * 
 * This test validates that only users with "admin" privileges can update another admin profile. It does so by:
 *
 * 1. Creating an admin account to be updated (the test target admin).
 * 2. Registering a member (regular user) and a moderator (staff) with unique emails.
 * 3. Attempting to update the admin (created in step 1) while authenticated as the member. Expects forbidden error.
 * 4. Attempting the same update while authenticated as the moderator. Expects forbidden error.
 * 5. (Optional) Verifies that these failed attempts are correctly audited/logged according to business policy.
 *
 * This ensures that admin update endpoints are protected, and only admins can perform such modifications, thereby maintaining system security and governance integrity. The test checks RBAC correctness and the immutability of admin data against privilege escalation attempts from weaker roles.
 *
 * Steps:
 * 1. Register admin-A (target) via api.functional.auth.admin.register.signUp.
 * 2. Register member-B via api.functional.auth.member.register.signUp.
 * 3. Register moderator-C via api.functional.auth.moderator.register.signUp, assigning by admin-A.
 * 4. Try api.functional.discussionBoard.admin.admins.update as the member JWT; expect forbidden error.
 * 5. Try api.functional.discussionBoard.admin.admins.update as the moderator JWT; expect forbidden error.
 * 6. If possible, re-register/login as admin-A, and perform api.functional.discussionBoard.admin.admins.update successfully to show that admins can update (optional for further validation).
 */
export async function test_api_admin_update_unauthorized_by_other_roles(connection: api.IConnection) {
  // 1. Register admin-A (the target)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test123!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminSignUp);
  const adminId = adminSignUp.admin_id;

  // 2. Register member-B
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberNickname = RandomGenerator.name();
  const memberPassword = "Test123!";
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSignUp);

  // 3. Register moderator-C (requires admin assignment)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Test123!";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      assigned_by_admin_email: adminEmail,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorSignUp);

  // 4. Attempt update as member-B
  // Use member JWT session
  connection.headers = { Authorization: memberSignUp.setHeaders.Authorization };
  await TestValidator.error("member cannot update admin profile")(() =>
    api.functional.discussionBoard.admin.admins.update(connection, {
      adminId: adminId,
      body: {
        status: "suspended",
        revoked_at: new Date().toISOString(),
      } satisfies IDiscussionBoardAdmin.IUpdate,
    })
  );

  // 5. Attempt update as moderator-C
  connection.headers = { Authorization: moderatorSignUp.setHeaders.Authorization };
  await TestValidator.error("moderator cannot update admin profile")(() =>
    api.functional.discussionBoard.admin.admins.update(connection, {
      adminId: adminId,
      body: {
        status: "revoked",
        revoked_at: new Date().toISOString(),
      } satisfies IDiscussionBoardAdmin.IUpdate,
    })
  );

  // 6. (Optional) Try as admin - should succeed
  connection.headers = { Authorization: adminSignUp.setHeaders.Authorization };
  const updated = await api.functional.discussionBoard.admin.admins.update(connection, {
    adminId: adminId,
    body: {
      status: "active",
      revoked_at: null,
    } satisfies IDiscussionBoardAdmin.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("adminId updated")(updated.id)(adminId);
}

