 *
 * Step-by-step process:
 * 1. Register a new admin account. This provides admin privileges and sets the connection to be authenticated as admin.
 * 2. Register a new discussion board member. Capture the member's UUID, which is needed to relate the user metrics record.
 * 3. Using the admin session, create a user metrics analytic profile for the member, initializing all participation/reputation fields with test values. Record the returned userMetricsId.
 * 4. As admin, call the detail GET API for that userMetricsId. Confirm:
 *   - All relevant analytic counters (posts_count, comments_count, votes given, reports, reputation)
 *   - Foreign key matches member
 *   - All audit fields (created_at, updated_at, last_activity_at if present) are returned and valid
 * 5. Use assertions to validate:
 *   - Participation and reputation fields are present and correct
 *   - Foreign key linkage to member's ID
 *   - All audit/timestamp fields are populated
 */
export async function test_api_user_metrics_detail_by_admin_success(
  connection: api.IConnection,
) {
  // 1. Register admin for privileges
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "A1b!" + typia.random<string & tags.Format<"uuid">>().slice(0,8);
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminSignUp);
  // SDK stores admin's token for subsequent privileged requests

  // 2. Register member whose analytics will be created
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Pwd-" + typia.random<string & tags.Format<"uuid">>().slice(0,8);
  const memberNickname = RandomGenerator.name();
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
      avatar_uri: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSignUp);
  const member = memberSignUp.member;

  // 3. As admin, create analytics (user metrics) record for this member
  const metricInit: IDiscussionBoardUserMetric.ICreate = {
    discussion_board_member_id: member.id,
    posts_count: typia.random<number & tags.Type<"int32">>(),
    comments_count: typia.random<number & tags.Type<"int32">>(),
    votes_up_given_count: typia.random<number & tags.Type<"int32">>(),
    votes_down_given_count: typia.random<number & tags.Type<"int32">>(),
    reports_made_count: typia.random<number & tags.Type<"int32">>(),
    reputation_score: typia.random<number & tags.Type<"int32">>(),
    last_activity_at: new Date().toISOString(),
  };
  const metrics = await api.functional.discussionBoard.admin.userMetrics.create(connection, {
    body: metricInit,
  });
  typia.assert(metrics);

  // 4. As admin, retrieve the analytics detail for the created userMetricsId
  const fetched = await api.functional.discussionBoard.admin.userMetrics.at(connection, {
    userMetricsId: metrics.id,
  });
  typia.assert(fetched);

  // 5. Validate result fields
  // a) All analytic counters present and matching
  TestValidator.equals("posts_count")(fetched.posts_count)(metricInit.posts_count);
  TestValidator.equals("comments_count")(fetched.comments_count)(metricInit.comments_count);
  TestValidator.equals("votes_up_given_count")(fetched.votes_up_given_count)(metricInit.votes_up_given_count);
  TestValidator.equals("votes_down_given_count")(fetched.votes_down_given_count)(metricInit.votes_down_given_count);
  TestValidator.equals("reports_made_count")(fetched.reports_made_count)(metricInit.reports_made_count);
  TestValidator.equals("reputation_score")(fetched.reputation_score)(metricInit.reputation_score);

  // b) Foreign key relationship present
  TestValidator.equals("discussion_board_member_id")(fetched.discussion_board_member_id)(member.id);

  // c) Audit fields populated
  TestValidator.predicate("created_at present")(!!fetched.created_at && typeof fetched.created_at === "string");
  TestValidator.predicate("updated_at present")(!!fetched.updated_at && typeof fetched.updated_at === "string");
  // d) last_activity_at: may be null or string, check that it matches (string or null) as set
  TestValidator.equals("last_activity_at")(fetched.last_activity_at)(metricInit.last_activity_at);
}

