 * 3. Member creates a new forum post
 * 4. Member adds a comment to the post
 * 5. Member submits an abuse/violation report on the comment
 * 6. Admin logs in, updates the report: changes its status to 'action_taken', supplies a resolution message, and sets themselves as handler
 * 7. Validate that all modifications (status, resolution message, handler assignment, timestamps) are correctly reflected in the comment report entity and compliant with audit requirements
 * 8. Optionally, perform a second update to test 'rejected' status and null handler
 */
export async function test_api_admin_comment_report_update_status_and_resolution(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassw0rd!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(adminSignUp);

  // 2. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Member1234!";
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name()
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberSignUp);
  const memberId = memberSignUp.member.id;

  // 3. Login as member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IDiscussionBoardMember.ILogin
  });

  // 4. Member creates a discussion post
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: "E2E Test Post",
      body: "Test body content for comment reporting.",
      attachments: null
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);
  const postId = post.id;

  // 5. Member adds a comment to the post
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId,
    body: {
      body: "Abusive or questionable comment for report test."
    } satisfies IDiscussionBoardComment.ICreate
  });
  typia.assert(comment);
  const commentId = comment.id;

  // 6. Member reports the comment
  const report = await api.functional.discussionBoard.member.commentReports.create(connection, {
    body: {
      discussion_board_comment_id: commentId,
      reason_type: "spam"
    } satisfies IDiscussionBoardCommentReport.ICreate
  });
  typia.assert(report);
  const reportId = report.id;

  // 7. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IDiscussionBoardAdmin.ILogin
  });

  // 8. Admin updates the report status, resolution, handler
  const updateBody: IDiscussionBoardCommentReport.IUpdate = {
    status: "action_taken",
    resolution_message: "Confirmed, comment violates guidelines",
    handler_admin_id: adminSignUp.admin_id
  };
  const updatedReport = await api.functional.discussionBoard.admin.commentReports.update(connection, {
    commentReportId: reportId,
    body: updateBody
  });
  typia.assert(updatedReport);
  TestValidator.equals("status updated")(updatedReport.status)("action_taken");
  TestValidator.equals("resolution message")(updatedReport.resolution_message)("Confirmed, comment violates guidelines");
  TestValidator.equals("handler assignment")(updatedReport.handler_admin_id)(adminSignUp.admin_id);
  TestValidator.predicate("audit updated_at change")(updatedReport.updated_at !== report.updated_at);

  // 9. Optionally, reject the report and remove handler
  const updateReject: IDiscussionBoardCommentReport.IUpdate = {
    status: "rejected",
    resolution_message: "Report was unfounded.",
    handler_admin_id: null
  };
  const rejectedReport = await api.functional.discussionBoard.admin.commentReports.update(connection, {
    commentReportId: reportId,
    body: updateReject
  });
  typia.assert(rejectedReport);
  TestValidator.equals("status rejected")(rejectedReport.status)("rejected");
  TestValidator.equals("resolution rejection")(rejectedReport.resolution_message)("Report was unfounded.");
  TestValidator.equals("handler removed")(rejectedReport.handler_admin_id)(null);
}

