/**
 * E2E test: Moderator paginated analytics search for user metrics with filters and data setup.
 *
 * This test covers the following steps:
 * 1. Register a moderator with a random email (provide random admin-assigned email for assignment).
 * 2. Register several (e.g., 3-5) members.
 * 3. For each member, initialize a user metrics analytic record (with random but realistic reputation, participation counts, date window).
 * 4. As the moderator, perform a PATCH search for user metrics using:
 *   - basic pagination (page 1, limit 3)
 *   - at least one filter (e.g., minimal reputation_score_min)
 *   - date window (e.g., last_activity_after/before windows around a metric's value)
 * 5. Assert that the returned data is an array with correct length (<= limit),
 *    and page metadata matches expectations (total records, total pages >=1, current page).
 * 6. Validate all user metrics entities returned contain the correct details (id, member id, counters, reputation, timestamps).
 * 7. Ensure that the moderator is able to read all entries (no admin-only restriction errors on results).
 */
export async function test_api_user_metrics_search_by_moderator_success(connection: api.IConnection) {
  // 1. Register a moderator (need fake admin email for assignment)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const modSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: "TestModPass!234",
    } satisfies IModerator.SignUp,
  });
  typia.assert(modSignUp);
  // Moderator token is now in connection.headers (setHeaders.Authorization).

  // 2. Register several members
  const memberSessions: IDiscussionBoardMember.ISession[] = await ArrayUtil.asyncRepeat(5)(async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const session = await api.functional.auth.member.register.signUp(connection, {
      body: {
        email,
        password: "UserPass#1234",
        nickname: RandomGenerator.alphaNumeric(8),
        avatar_uri: null,
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(session);
    return session;
  });

  // 3. Initialize user metric analytics for those members (as admin)
  for (const session of memberSessions) {
    await api.functional.discussionBoard.admin.userMetrics.create(connection, {
      body: {
        discussion_board_member_id: session.member.id,
        posts_count: typia.random<number & tags.Type<"int32">>(),
        comments_count: typia.random<number & tags.Type<"int32">>(),
        votes_up_given_count: typia.random<number & tags.Type<"int32">>(),
        votes_down_given_count: typia.random<number & tags.Type<"int32">>(),
        reports_made_count: typia.random<number & tags.Type<"int32">>(),
        reputation_score: typia.random<number & tags.Type<"int32">>(),
        last_activity_at: new Date(Date.now() - 3600*1000*Math.floor(Math.random()*100)).toISOString(),
      } satisfies IDiscussionBoardUserMetric.ICreate,
    });
