import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate advanced comment list filtering, sorting, and pagination for a forum post.
 *
 * Business context: Listing comments under a given post is used for threaded discussion UX. Forums must support large volumes of comments with rich UI search and paging, including filtering by status/author/thread, ordering, and controlling page size for performance.
 *
 * This test covers UI/UX and backend business rules for comment list API including:
 *   - Setup: Register a member, create a post, add sufficient comments (and some replies) for paging (20+)
 *   - Filtering: by author; by parent (show only top/comments/replies)
 *   - Sorting: by creation date ascending and descending
 *   - Pagination: check page 1, next/last page, enforced min=1 and max=100 page sizes, empty result handling
 *   - Edge Cases: Exactly one page, request beyond last page, invalid limits, filtering w/ no matches
 *   - Security: Ensure deleted/hidden comments status are only visible to creator (via status filter), not by unrelated members
 *
 * Test Flow:
 * 1. Register and authenticate a new member.
 * 2. Create a new post as this member.
 * 3. Add top-level and threaded comments (e.g., 15 top-level, 5 replies).
 * 4. List comments with default params: verify correct data, proper page size, ordering by created_at (default sort).
 * 5. Fetch with explicit sort descending and page 1, confirm ordering is reversed.
 * 6. Fetch replies-only (filter by parent_comment_id).
 * 7. Filter by author_member_id: expect only their comments.
 * 8. Try limit=150 (over max): should clamp/fail to 100 per policy.
 * 9. Page beyond last page: expect empty results with accurate pagination meta.
 * 10. Filter by status='deleted'/'hidden': should not see unless creator; verify as other member (register), no results on those statuses.
 * 11. Attempt invalid (zero/negative/too high) page/limit values, expect validation error or fallback to policy.
 */
export async function test_api_comment_search_pagination_and_filtering(
  connection: api.IConnection,
) {
  // Step 1: Register primary member
  const email = typia.random<string & tags.Format<"email">>();
  const nickname = RandomGenerator.name();
  const password = RandomGenerator.alphaNumeric(10);
  const { member } = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname,
      avatar_uri: null,
    },
  });

  // Step 2: Create a new post as this member
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(10).slice(0, 100),
      body: RandomGenerator.content()(3)(3).slice(0, 4000),
      category_id: null,
      platform_config_id: null,
      attachments: null,
    },
  });
  typia.assert(post);

  // Step 3: Add top-level and threaded comments
  const topComments = await ArrayUtil.asyncRepeat(15)(async () => {
    return await api.functional.discussionBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body: RandomGenerator.paragraph()(5).slice(0, 1000),
      },
    });
  });
  typia.assert(topComments);
  // Add replies to some of the top-level comments
  const replies = await ArrayUtil.asyncRepeat(5)(async () => {
    const parent = RandomGenerator.pick(topComments);
    return await api.functional.discussionBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body: RandomGenerator.paragraph()(3).slice(0, 1000),
        thread_parent_comment_id: parent.id,
      },
    });
  });
  typia.assert(replies);
  const allComments = [...topComments, ...replies];

  // Step 4: List comments (default - page 1)
  const page1 = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
    },
  });
  typia.assert(page1);
  TestValidator.predicate("page1 has comments")(page1.data.length > 0);

  // Step 5: Fetch with explicit sort descending and page 1, check reverse order
  const desc = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      sort_by: "created_at",
      sort_direction: "desc",
    },
  });
  typia.assert(desc);
  if (desc.data.length > 1) {
    // Descending sort: first should be latest
    TestValidator.predicate("descending order")(desc.data[0].created_at >= desc.data[1].created_at);
  }

  // Step 6: Fetch replies-only
  if (replies.length > 0) {
    const p = replies[0].thread_parent_comment_id!;
    const childList = await api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        post_id: post.id,
        parent_comment_id: p,
      },
    });
    typia.assert(childList);
    TestValidator.predicate("replies are correct parent")(childList.data.every(d => d.thread_parent_comment_id === p));
  }

  // Step 7: Filter by author_member_id
  const byAuthor = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      author_member_id: member.id,
    },
  });
  typia.assert(byAuthor);
  TestValidator.predicate("only own comments")(byAuthor.data.every(d => d.author_role === "member" && d.author_display_name === nickname));

  // Step 8: Try limit>100, expect max capped at 100
  const bigLimit = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      limit: 150,
    },
  });
  typia.assert(bigLimit);
  TestValidator.predicate("limit clamp to 100")(bigLimit.pagination.limit === 100);

  // Step 9: Page beyond last page
  const beyond = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      page: 9999,
    },
  });
  typia.assert(beyond);
  TestValidator.equals("no results")(beyond.data.length)(0);

  // Step 10: Filter by status=deleted (should only see own deleted if any)
  // (No deletions simulated here, but can check empty result)
  const deleted = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      status: "deleted",
    },
  });
  typia.assert(deleted);
  TestValidator.equals("deleted empty")(deleted.data.length)(0);

  // Step 11: Invalid limit (zero/negative)
  await TestValidator.error("limit=0 fails")(
    () => api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        post_id: post.id,
        limit: 0,
      },
    }),
  );
  await TestValidator.error("limit=-3 fails")(
    () => api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        post_id: post.id,
        limit: -3,
      },
    }),
  );
  await TestValidator.error("invalid page fails")(
    () => api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        post_id: post.id,
        page: 0,
      },
    }),
  );
}

