  TestValidator.predicate("all comments belong to member")(
    byAuthor.data.every(d => d.author_role === "member" && d.author_display_name === nickname),
  );

  // Step 8: limit>100 (should clamp/cap to 100)
  const bigLimit = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
