  TestValidator.predicate("Updated time present")(!!report.updated_at);
  TestValidator.predicate("No resolution message (new)")(report.resolution_message === null || report.resolution_message === undefined);
  TestValidator.predicate("No handler assigned yet")(report.handler_admin_id === null || report.handler_admin_id === undefined);
