/**
 * Validates member comment voting on the discussion board, covering upvote/downvote creation and duplicate prevention.
 *
 * This test covers the end-to-end flow required to create legitimate upvote and downvote actions from a registered member on distinct comments and ensures that duplicate votes on the same comment are properly blocked, as well as verifying audit trail and business logic enforcement.
 *
 * Step-by-step process:
 * 1. Register a new member to serve as the voter and obtain a session for authentication context.
 * 2. Create two distinct posts as the context for comments (could be simple placeholder titles/bodies).
 * 3. For each post, author a comment (so each has a separate comment ID for independent voting).
 * 4. Member creates an upvote for the first comment and a downvote for the second comment using POST /discussionBoard/member/commentVotes (unique comment+member per vote).
 * 5. Assert the returns have correct types, and each vote reflects the intended upvote/downvote, comment association, and audit fields present (created_at, updated_at, etc.).
 * 6. Attempt to create a duplicate upvote for the first comment with the same member: expect an error thrown/returned due to unique constraint (single vote per user per comment). Repeat for downvote on second comment.
 * 7. Use TestValidator.error() to catch and assert error throwing for duplicates (but do not inspect error message string per instruction).
 * 8. Ensure no type safety or business logic violations (e.g., member identity only from session, not request body).
 */
export async function test_api_comment_vote_creation_success_and_duplicate_prevention(connection: api.IConnection) {
  // 1. Register a new member to act as the voter
  const email = typia.random<string & tags.Format<"email">>();
  const password = "password1234";
  const nickname = RandomGenerator.name();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(session);
  const memberId = session.member.id;

  // 2. Create two posts (one for each comment)
  const post1 = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.paragraph()(80)
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post1);
  const post2 = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(16),
      body: RandomGenerator.paragraph()(45)
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post2);

  // 3. Author a comment on each post
  const comment1 = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post1.id,
    body: {
      body: RandomGenerator.paragraph()(10)
    } satisfies IDiscussionBoardComment.ICreate
  });
  typia.assert(comment1);
  const comment2 = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post2.id,
    body: {
      body: RandomGenerator.paragraph()(20)
    } satisfies IDiscussionBoardComment.ICreate
  });
  typia.assert(comment2);

  // 4. Create an upvote for the first comment
  const upvote = await api.functional.discussionBoard.member.commentVotes.create(connection, {
    body: {
      discussion_board_comment_id: comment1.id,
      is_upvote: true
    } satisfies IDiscussionBoardCommentVote.ICreate
  });
  typia.assert(upvote);
  TestValidator.equals("Upvote member context")(upvote.discussion_board_member_id)(memberId);
  TestValidator.equals("Upvote context")(upvote.discussion_board_comment_id)(comment1.id);
  TestValidator.equals("Upvote type")(upvote.is_upvote)(true);

  // 5. Create a downvote for the second comment
  const downvote = await api.functional.discussionBoard.member.commentVotes.create(connection, {
    body: {
      discussion_board_comment_id: comment2.id,
      is_upvote: false
    } satisfies IDiscussionBoardCommentVote.ICreate
  });
  typia.assert(downvote);
  TestValidator.equals("Downvote member context")(downvote.discussion_board_member_id)(memberId);
  TestValidator.equals("Downvote context")(downvote.discussion_board_comment_id)(comment2.id);
  TestValidator.equals("Downvote type")(downvote.is_upvote)(false);

  // 6. Attempt to create a duplicate upvote (should be blocked)
  await TestValidator.error("Duplicate upvote should fail")(() =>
    api.functional.discussionBoard.member.commentVotes.create(connection, {
      body: {
        discussion_board_comment_id: comment1.id,
        is_upvote: true
      } satisfies IDiscussionBoardCommentVote.ICreate
    })
  );

  // 7. Attempt to create a duplicate downvote (should be blocked)
  await TestValidator.error("Duplicate downvote should fail")(() =>
    api.functional.discussionBoard.member.commentVotes.create(connection, {
      body: {
        discussion_board_comment_id: comment2.id,
        is_upvote: false
      } satisfies IDiscussionBoardCommentVote.ICreate
    })
  );
}

