/**
 * Validate moderator search and pagination over comment abuse reports.
 *
 * This test verifies that moderators can effectively retrieve, filter, and paginate comment abuse reports. The flow simulates multiple members posting comments, generating reports with different statuses, reasons, and reporters. The test checks that the moderator's search endpoint returns accurate, filtered, and paginated results matching expectations for various query conditions.
 *
 * Steps:
 * 1. Create three new posts as a member.
 * 2. On each post, create two comments (total: 6 comments).
 * 3. Generate four different members. Each member submits an abuse report for a unique combination: some report the same comment with different reasons/statuses.
 * 4. Some reports are given unique status values (e.g., 'pending', 'resolved', 'rejected'), and have different reason_type values.
 * 5. As a moderator, search for reports with default filter (should receive all),
 * 6. Search for reports filtered by specific status, e.g., only 'pending', only 'resolved'.
 * 7. Filter by reporter's member ID and by reason_type.
 * 8. Apply time filters (created_from/created_to) to check correct inclusion/exclusion.
 * 9. Use pagination (page, limit) and verify pagination meta and data chunking.
 * 10. For high-restrictive filter, verify empty result is returned.
 */
export async function test_api_comment_report_moderator_search_basic_pagination(connection: api.IConnection) {
  // Step 1: Create 3 posts as a member
  const posts = await ArrayUtil.asyncRepeat(3)(async () => {
    const post = await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(8),
        body: RandomGenerator.content()()(16),
      } satisfies IDiscussionBoardPost.ICreate,
    });
    typia.assert(post);
    return post;
  });

  // Step 2: Create 2 comments per post
  const comments = [] as IDiscussionBoardComment[];
  for (const post of posts) {
    for (let i = 0; i < 2; ++i) {
      const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
        postId: post.id,
        body: {
          body: RandomGenerator.content()()(6),
        } satisfies IDiscussionBoardComment.ICreate,
      });
