      comments.push(comment);
    }
  }

  // Step 3: Generate 4 member 'reporters' (simulate by changing connection if needed)
  // Here we assume current test context allows submission by different context, so we simply create different reports (cannot assign different member IDs explicitly)

  // Step 4: Create diverse reports for the comments
  const statuses = ["pending", "resolved", "rejected", "in_review"];
  const reasonTypes = ["spam", "hate", "off-topic", "advertising"];
  const now = new Date();
  const dayAgo = new Date(now.getTime() - 24*60*60*1000);
  // Use 6 reports, with different status/reason_type
  const reports: IDiscussionBoardCommentReport[] = [];
  for (let i = 0; i < 6; ++i) {
    const report = await api.functional.discussionBoard.member.commentReports.create(connection, {
      body: {
