    body: {
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardCommentReport.IRequest,
  });
  typia.assert(searchAll);
  TestValidator.predicate("should retrieve at least 6 reports")(searchAll.data.length >= 6);

  // Step 6: Filter by status
  const statusFilter = await api.functional.discussionBoard.moderator.commentReports.search(connection, {
    body: {
      status: statuses[0],
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardCommentReport.IRequest,
  });
