 * 5. As the member, submit a comment report against their own comment.
 * 6. Switch to moderator account, and update the status of the report to 'in_review', add resolution notes, and set handler.
 * 7. Update again to 'action_taken' with updated notes, confirming workflow status transitions and audit fields are correct.
 * 8. Attempt to update an already "finalized" (action_taken or rejected) comment report to verify modifications are rejected.
 * 9. (Edge) Attempt to update a non-existent or deleted report and confirm error response.
 * 10. At each update, verify status, resolution, handler, and audit fields are changed as expected, and only allowed transitions proceed.
 */
export async function test_api_moderator_comment_report_update_resolution_by_moderator(connection: api.IConnection) {
  // --- 1. Register moderator and login (moderator workflow) ---
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestPassword!1";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
