  // Out-of-range timestamp
  const outNegRange = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_from: "2099-01-01T00:00:00Z" } });
  typia.assert(outNegRange);
  TestValidator.equals("empty future filter")(outNegRange.data.length)(0);

  // Garbage date format (expect error thrown!)
  await TestValidator.error("garbage date throws")(() =>
    api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_from: "NOTADATE" } })
  );

  // 12. Permission: as moderator with mod JWT (should error/forbid)
  connection.headers = { ...connection.headers, Authorization: moderators[0].setHeaders.Authorization };
