import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostReport";
import type { IPageIDiscussionBoardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate searching and filtering of post reports as an admin with varied filters and pagination.
 *
 * Business context:
 * Ensures the admin post report searching endpoint supports all filter and pagination criteria described in API documentation. Guarantees reliability of moderation dashboard and compliance workflows, and validates correctness of returned data for each search option.
 *
 * Step-by-step process:
 * 1. Register multiple members (at least 2).
 * 2. Each member creates different posts (at least 2 per member).
 * 3. Members file abuse reports against posts (multiple combinations, some cross-reporting, and various reason types like 'spam', 'hate', etc).
 * 4. As admin, search post reports with each documented filter field:
 *    - filter by reason_type
 *    - filter by status
 *    - filter by reporting member
 *    - filter by post ID
 *    - test pagination (page/limit)
 *    - combine filters (e.g., status+reason_type)
 * 5. For each search, assert that the returned list contains only correct, matching reports (exact filter match), that pagination metadata is correct, and no extraneous entries appear.
 */
export async function test_api_post_report_search_admin_with_varied_filters(connection: api.IConnection) {
  // 1. Register members A and B
  const memberA_email = typia.random<string & tags.Format<"email">>();
  const memberA_nickname = RandomGenerator.name();
  const memberB_email = typia.random<string & tags.Format<"email">>();
  const memberB_nickname = RandomGenerator.name();

  const sessionA = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberA_email,
      password: "TestPass1!",
      nickname: memberA_nickname
    }
  });
  typia.assert(sessionA);
  const memberA_id = sessionA.member.id;

  const sessionB = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberB_email,
      password: "TestPass2!",
      nickname: memberB_nickname
    }
  });
  typia.assert(sessionB);
  const memberB_id = sessionB.member.id;

  // 2. Each member creates two posts
  connection.headers = { ...connection.headers, Authorization: sessionA.setHeaders.Authorization };
  const postA1 = await api.functional.discussionBoard.member.posts.create(connection, { body: { title: "PostA1", body: "Content A1" } });
  typia.assert(postA1);
  const postA2 = await api.functional.discussionBoard.member.posts.create(connection, { body: { title: "PostA2", body: "Content A2" } });
  typia.assert(postA2);

  connection.headers = { ...connection.headers, Authorization: sessionB.setHeaders.Authorization };
  const postB1 = await api.functional.discussionBoard.member.posts.create(connection, { body: { title: "PostB1", body: "Content B1" } });
  typia.assert(postB1);
  const postB2 = await api.functional.discussionBoard.member.posts.create(connection, { body: { title: "PostB2", body: "Content B2" } });
  typia.assert(postB2);

  // 3. Members file abuse reports (mix up targets and reporters, with different types/statuses)
  // - Member A reports B1 as spam
  connection.headers = { ...connection.headers, Authorization: sessionA.setHeaders.Authorization };
  const report1 = await api.functional.discussionBoard.member.postReports.create(connection, {
    body: { discussion_board_post_id: postB1.id, reason_type: "spam", reason_text: "Spam report by A on B1" }
  });
  typia.assert(report1);
  // - Member A reports A2 as hate
  const report2 = await api.functional.discussionBoard.member.postReports.create(connection, {
    body: { discussion_board_post_id: postA2.id, reason_type: "hate", reason_text: "Hate report by A on A2" }
  });
  typia.assert(report2);

  // - Member B reports A1 as hate
  connection.headers = { ...connection.headers, Authorization: sessionB.setHeaders.Authorization };
  const report3 = await api.functional.discussionBoard.member.postReports.create(connection, {
    body: { discussion_board_post_id: postA1.id, reason_type: "hate", reason_text: "Hate report by B on A1" }
  });
  typia.assert(report3);
  // - Member B reports B2 as spam
  const report4 = await api.functional.discussionBoard.member.postReports.create(connection, {
    body: { discussion_board_post_id: postB2.id, reason_type: "spam", reason_text: "Spam report by B on B2" }
  });
  typia.assert(report4);

  // Switch to admin user by removing Authorization header (simulate admin context for test environment)
  delete connection.headers.Authorization;

  // 4. As admin, search by reason_type="spam"
  let out = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: { reason_type: "spam", page: 1, limit: 10 }
  });
  typia.assert(out);
  TestValidator.predicate("all are spam")(
    out.data.every(r => r.reason_type === "spam")
  );

  // 5. Search by reason_type="hate"
  out = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: { reason_type: "hate", page: 1, limit: 10 }
  });
  typia.assert(out);
  TestValidator.predicate("all are hate")(
    out.data.every(r => r.reason_type === "hate")
  );

  // 6. Filter by status (all will initially be 'pending')
  out = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: { status: "pending", page: 1, limit: 10 }
  });
  typia.assert(out);
  TestValidator.predicate("all pending")(
    out.data.every(r => r.status === "pending")
  );

  // 7. Filter by reporting member (memberA_id)
  out = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: { discussion_board_member_id: memberA_id, page: 1, limit: 10 }
  });
  typia.assert(out);
  TestValidator.predicate("all reports by memberA")(
    out.data.every(r => r.discussion_board_member_id === memberA_id)
  );

  // 8. Filter by post id (postB1.id)
  out = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: { discussion_board_post_id: postB1.id, page: 1, limit: 10 }
  });
  typia.assert(out);
  TestValidator.predicate("all reports on postB1")(
    out.data.every(r => r.discussion_board_post_id === postB1.id)
  );

  // 9. Combination filter (reason_type + member)
  out = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: { reason_type: "spam", discussion_board_member_id: memberA_id, page: 1, limit: 10 }
  });
  typia.assert(out);
  TestValidator.predicate("all spam by memberA")(
    out.data.every(r => r.reason_type === "spam" && r.discussion_board_member_id === memberA_id)
  );

  // 10. Pagination test: limit=2
  out = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: { page: 1, limit: 2 }
  });
  typia.assert(out);
  TestValidator.equals("page is 1")(out.pagination.current)(1);
  TestValidator.equals("limit is 2")(out.pagination.limit)(2);
  TestValidator.predicate("max two results only")(out.data.length <= 2);
  // Next page: page=2
  const out2 = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: { page: 2, limit: 2 }
  });
  TestValidator.equals("page is 2")(out2.pagination.current)(2);
  TestValidator.equals("limit is 2")(out2.pagination.limit)(2);
  TestValidator.predicate("no overlap")(out2.data.every(r2 => !out.data.find(r1 => r1.id === r2.id)));
}

