import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * E2E test for admin search, filter, and pagination on moderator accounts in discussion board.
 *
 * 1. Register an admin user (for privileged access).
 * 2. Register multiple moderator accounts with different statuses and assigned_at timestamps. Assign by at least 2 different admins for filtering logic.
 * 3. Test search as ADMIN:
 *   - By email (full/partial match)
 *   - By status ('active', 'revoked', 'suspended')
 *   - By assigned_by_admin_email
 *   - By assigned_at_from / assigned_at_to range
 *   - Pagination (limit/page), sorting (order_by/order_dir)
 *   - Combined filters (cross field)
 *   - Check that sorting, pagination, and filter rules are respected in results
 * 4. Test negative/edge cases:
 *   - Non-existent email/status/assigned_by_admin_email/timestamps
 *   - Invalid filter values (e.g. garbage date format, unknown status)
 *   - Permission (MODERATOR with valid JWT attempts to search—should be forbidden)
 *
 * For each test, check that returned data matches search filters and that pagination and sort metadata reflect expectations. Use TestValidator for assertions.
 */
export async function test_api_moderator_search_filter_pagination(connection: api.IConnection) {
  // 1. Register Admin 1
  const adminEmail1 = typia.random<string & tags.Format<"email">>();
  const adminPW = "AdminPW1234!";
  const admin1 = await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail1, password: adminPW } });
  typia.assert(admin1);

  // 2. Register Admin 2
  const adminEmail2 = typia.random<string & tags.Format<"email">>();
  const admin2 = await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail2, password: adminPW } });
  typia.assert(admin2);

  // 3. Register Moderators with varying assignments
  const now = new Date();
  const moderators = await ArrayUtil.asyncRepeat(6)(async (_, i) => {
    // Assign status: 0:active, 1:revoked, 2:suspended, 3+:active
    const email = typia.random<string & tags.Format<"email">>();
    const assigned_by = i % 2 === 0 ? adminEmail1 : adminEmail2;
    const password = "ModPW1234!";
    const signUpResp = await api.functional.auth.moderator.register.signUp(connection, {
      body: { email, assigned_by_admin_email: assigned_by, password },
    });
    typia.assert(signUpResp);
    // Simulate manually status/revoked so we can test filter logic.
    return {
      ...signUpResp,
      // Only status returned by API is "active" at sign-up. For search test, make up revoked/suspended for client-side test assertions (API only supports 'active' at register)
      status: i === 1 ? "revoked" : i === 2 ? "suspended" : "active",
      assigned_by_admin_email: assigned_by,
      assigned_at: new Date(Date.now() - i * 24 * 60 * 60 * 1000).toISOString(),
      revoked_at: i === 1 ? new Date(now.getTime() - 12 * 60 * 60 * 1000).toISOString() : null,
    };
  });

  // Switch to Admin 1's context for privilege tests (simulate by Authorization header)
  connection.headers = { ...connection.headers, Authorization: admin1.setHeaders.Authorization };

  // 4. Search by email (full & partial)
  const searchEmail = moderators[0].email;
  const output1 = await api.functional.discussionBoard.admin.moderators.search(connection, {
    body: { email: searchEmail } satisfies IDiscussionBoardModerator.IRequest,
  });
  typia.assert(output1);
  TestValidator.predicate("search by email is correct")(
    output1.data.every(m => m.email === searchEmail));

  // Partial match (simulate substring)
  const partial = searchEmail.slice(0, searchEmail.indexOf("@"));
  const output1b = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { email: partial } });
  typia.assert(output1b);
  TestValidator.predicate("partial email match")(
    output1b.data.some(m => m.email === searchEmail));

  // 5. Search by status
  const statuses = ["active", "revoked", "suspended"];
  for (const s of statuses) {
    const out = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { status: s } });
    typia.assert(out);
    TestValidator.predicate(`search by status ${s}`)(out.data.every(m => m.status === s));
  }

  // 6. Search by assigned_by_admin_email
  const outByAdmin1 = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_by_admin_email: adminEmail1 } });
  typia.assert(outByAdmin1);
  TestValidator.predicate("search by assigned_by_admin_email admin1")(outByAdmin1.data.every(m => m.assigned_by_admin_email === adminEmail1));

  // 7. Assigned_at time window (from)
  const minAssignedAt = moderators[3].assigned_at;
  const outAssignedFrom = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_from: minAssignedAt } });
  typia.assert(outAssignedFrom);
  TestValidator.predicate("assigned_at_from")(outAssignedFrom.data.every(m => m.assigned_at >= minAssignedAt));

  // To
  const maxAssignedAt = moderators[1].assigned_at;
  const outAssignedTo = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_to: maxAssignedAt } });
  typia.assert(outAssignedTo);
  TestValidator.predicate("assigned_at_to")(outAssignedTo.data.every(m => m.assigned_at <= maxAssignedAt));

  // 8. Pagination (limit, page)
  const outPaginated = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { limit: 2, page: 2 } });
  typia.assert(outPaginated);
  TestValidator.equals("limit")(outPaginated.pagination.limit)(2);
  TestValidator.equals("page")(outPaginated.pagination.current)(2);
  TestValidator.equals("records")(outPaginated.pagination.records)(outPaginated.pagination.pages * outPaginated.pagination.limit >= moderators.length ? moderators.length : outPaginated.pagination.records);

  // 9. Order_by/order_dir
  const outOrdered = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { order_by: "assigned_at", order_dir: "desc" } });
  typia.assert(outOrdered);
  TestValidator.predicate("sorted desc")(
    outOrdered.data.every((val, idx, arr) => idx === 0 || arr[idx - 1].assigned_at >= val.assigned_at));

  // 10. Combined filters
  const combo = await api.functional.discussionBoard.admin.moderators.search(connection, {
    body: {
      status: "active",
      assigned_by_admin_email: adminEmail1,
      assigned_at_from: moderators[4].assigned_at,
      assigned_at_to: moderators[0].assigned_at,
      limit: 5,
    }
  });
  typia.assert(combo);
  TestValidator.predicate("combined filters")(combo.data.every(m => m.status === "active" && m.assigned_by_admin_email === adminEmail1 && m.assigned_at >= moderators[4].assigned_at && m.assigned_at <= moderators[0].assigned_at));

  // 11. Negative: non-existent email
  const outNegEmail = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { email: "no-such-user@domain.com" } });
  typia.assert(outNegEmail);
  TestValidator.equals("empty result for unknown email")(outNegEmail.data.length)(0);

  // Invalid status (should not throw, just empty)
  const outNegStatus = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { status: "doesnotexist" } });
  typia.assert(outNegStatus);
  TestValidator.equals("empty result for bad status")(outNegStatus.data.length)(0);

  // Out-of-range timestamp
  const outNegRange = await api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_from: "2099-01-01T00:00:00Z" } });
  typia.assert(outNegRange);
  TestValidator.equals("empty future filter")(outNegRange.data.length)(0);

  // Garbage date format (expect error thrown!)
  await TestValidator.error("garbage date throws")(() =>
    api.functional.discussionBoard.admin.moderators.search(connection, { body: { assigned_at_from: "NOTADATE" } })
  );

  // 12. Permission: as moderator with mod JWT (should error/forbid)
  connection.headers = { ...connection.headers, Authorization: moderators[0].setHeaders.Authorization };
  await TestValidator.error("moderator forbidden to search")(() =>
    api.functional.discussionBoard.admin.moderators.search(connection, { body: {} })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";
import type { IVoidSuccess } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidSuccess";

/**
 * Validate that administrator password change is not allowed without authentication.
 *
 * This test checks that the admin password update endpoint enforces authentication—preventing unauthenticated calls regardless of request body validity. It ensures that a missing, expired, or invalid JWT prevents password change for discussion board administrators. This is important to confirm security and access controls are correctly applied.
 *
 * 1. Register a new admin account to define valid credentials (no token will be used during password change).
 * 2. Attempt to call the password change API WITHOUT any Authorization header (simulating a missing/unauthenticated context).
 * 3. Verify that the system rejects the request with an unauthorized error and does not process the change.
 */
export async function test_api_admin_password_change_unauthenticated_access(
  connection: api.IConnection,
) {
  // 1. Register a new admin account to have a valid admin in the system (do not use result for authentication)
  const adminInfo = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestAuth123!"
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(adminInfo);

  // 2. Clear any Authorization from headers to simulate unauthenticated state
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
    },
  };

  // 3. Attempt to change password WITHOUT authentication, expect an error
  await TestValidator.error("Password change without authentication should fail")(
    async () => {
      await api.functional.auth.admin.password.changePassword(unauthConnection, {
        body: {
          oldPassword: "TestAuth123!",
          newPassword: "NewUnAuthPass12$"
        } satisfies IDiscussionBoardAdmin.IChangePassword
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardExternalAuthLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardExternalAuthLog";

/**
 * Validate creation and error handling for external authentication log entries as admin.
 *
 * This test covers the creation of an external authentication log for the discussion board platform through the admin endpoint. The workflow includes:
 *
 * 1. Successful creation: Submits all required and optional fields to create a new authentication event log. Checks event completeness, mapping to a user, referential integrity, presence/absence of audit and error fields, and expected audit output.
 * 2. Field coverage: Ensures all core, optional, nullable fields are exercised with valid data.
 * 3. Missing fields error: Attempts creation with mandatory fields omitted, checks API returns error.
 * 4. Invalid format error: Attempts creation with invalid-formatted values (e.g., malformed email or date-time).
 * 5. Permission error: Attempts creation from a (simulated) non-admin context, expects rejection.
 */
export async function test_api_external_auth_log_creation_unique_and_validation(
  connection: api.IConnection,
) {
  // 1. Successful creation with all fields set
  const inputComplete: IDiscussionBoardExternalAuthLog.ICreate = {
    discussion_board_member_id: typia.random<string & tags.Format<"uuid">>(),
    auth_channel: "google",
    external_user_id: typia.random<string & tags.Format<"uuid">>(),
    subject_email: typia.random<string & tags.Format<"email">>(),
    issued_at: new Date().toISOString(),
    completed_at: new Date(Date.now() + 10_000).toISOString(),
    success: true,
    error_code: null,
    error_message: null,
  };
  const created = await api.functional.discussionBoard.admin.externalAuthLogs.create(connection, { body: inputComplete });
  typia.assert(created);
  // Check result structure
  TestValidator.equals("subject_email matches")(created.subject_email)(inputComplete.subject_email);
  TestValidator.equals("success flag matches")(created.success)(inputComplete.success);
  TestValidator.equals("channel matches")(created.auth_channel)(inputComplete.auth_channel);

  // 2. Creation with minimal required fields only (omit optionals/nullables)
  const inputMinimal: IDiscussionBoardExternalAuthLog.ICreate = {
    auth_channel: "kakao",
    subject_email: typia.random<string & tags.Format<"email">>(),
    issued_at: new Date().toISOString(),
    success: false,
  };
  const createdMinimal = await api.functional.discussionBoard.admin.externalAuthLogs.create(connection, { body: inputMinimal });
  typia.assert(createdMinimal);
  TestValidator.equals("required email")(createdMinimal.subject_email)(inputMinimal.subject_email);
  TestValidator.equals("required channel")(createdMinimal.auth_channel)(inputMinimal.auth_channel);
  TestValidator.equals("success flag minimal")(createdMinimal.success)(inputMinimal.success);

  // 3. Error: Missing required field (e.g. omit subject_email)
  const missingField = {
    auth_channel: "naver",
    issued_at: new Date().toISOString(),
    success: true,
  } as any; // purposely broken type (TypeScript will error but runtime test is business logic)
  await TestValidator.error("should fail missing subject_email")(() =>
    api.functional.discussionBoard.admin.externalAuthLogs.create(connection, { body: missingField })
  );

  // 4. Error: Invalid format (malformed email)
  const invalidFormat: IDiscussionBoardExternalAuthLog.ICreate = {
    auth_channel: "email",
    subject_email: "not-an-email-format",
    issued_at: new Date().toISOString(),
    success: true,
  };
  await TestValidator.error("should fail invalid email format")(() =>
    api.functional.discussionBoard.admin.externalAuthLogs.create(connection, { body: invalidFormat })
  );

  // 5. Error: Non-admin context simulation (simulate context removal if possible)
  const noAdminConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("should reject non-admin access")(() =>
    api.functional.discussionBoard.admin.externalAuthLogs.create(noAdminConnection, { body: inputMinimal })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardEmailLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardEmailLog";
import type { IPageIDiscussionBoardEmailLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardEmailLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching and paginating outgoing email logs as an admin.
 *
 * This test confirms that an admin can use multiple filters (recipient, type, status, date range) to query outgoing email logs, with correct pagination, and verifies that soft-deleted records are excluded. It also covers handling of malformed input producing errors. Only actual API/DtOs/fields are used, following type safety and E2E conventions.
 *
 * Steps:
 * 1. Setup test data: Use dependency endpoint to create several email logs with varied recipient, type, status, and send time values.
 * 2. Perform search queries:
 *    - Filter by recipient_email (expect only that recipient)
 *    - Filter by email_type and delivery_status (expect logs matching both)
 *    - Filter by sent_at date range (expect logs in range)
 *    - Paginate results (validate limit/page and correct entries returned)
 * 3. Confirm soft-deleted records are never included
 * 4. Test error case: malformed filter input (invalid page number)
 */
export async function test_api_email_logs_search_pagination_and_filtering(connection: api.IConnection) {
  // 1. Setup test data: create sample email logs
  const recipientEmails = [
    typia.random<string & tags.Format<"email">>(),
    typia.random<string & tags.Format<"email">>()
  ];
  const types = ["verification", "notification", "password_reset"];
  const statuses = ["SENT", "DELIVERED", "FAILED"];
  const now = new Date();

  // Create several diverse logs
  const createdLogs = await Promise.all(
    ArrayUtil.repeat(10)(async (_, i) => {
      const email_type = RandomGenerator.pick(types);
      const delivery_status = RandomGenerator.pick(statuses);
      const sent_at = new Date(now.getTime() - i * 3600 * 1000).toISOString();
      const recipient_email = RandomGenerator.pick(recipientEmails);
      const subject = RandomGenerator.alphaNumeric(12);
      const log = await api.functional.discussionBoard.admin.emailLogs.create(connection, {
        body: {
          recipient_email,
          email_type,
          subject,
          sent_at,
          delivery_status,
        } satisfies IDiscussionBoardEmailLog.ICreate,
      });
      typia.assert(log);
      return log;
    })
  );

  // 2a. Search by recipient_email
  const testRecipient = recipientEmails[0];
  const resultByRecipient = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      recipient_email: testRecipient,
      page: 1,
      limit: 5,
    },
  });
  typia.assert(resultByRecipient);
  TestValidator.predicate("results match recipient")(
    resultByRecipient.data.every((item) => item.recipient_email === testRecipient)
  );

  // 2b. Search by both email_type and delivery_status
  const testType = types[0];
  const testStatus = statuses[0];
  const typeStatusResult = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      email_type: testType,
      delivery_status: testStatus,
    },
  });
  typia.assert(typeStatusResult);
  TestValidator.predicate("results match type and status")(
    typeStatusResult.data.every((item) => item.email_type === testType && item.delivery_status === testStatus)
  );

  // 2c. Search by sent_at date range (last 6 hours)
  const fromDate = new Date(now.getTime() - 6 * 3600 * 1000).toISOString();
  const toDate = now.toISOString();
  const dateRangeResult = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      from_date: fromDate,
      to_date: toDate,
    },
  });
  typia.assert(dateRangeResult);
  TestValidator.predicate("results within date range")(
    dateRangeResult.data.every((item) => item.sent_at >= fromDate && item.sent_at <= toDate)
  );

  // 2d. Pagination: page=1, limit=2, should return 0, 1, or 2 entries
  const paged = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(paged);
  TestValidator.predicate("pagination respected")(paged.data.length <= 2);

  // 3. Confirm soft-deleted records excluded (deleted_at must be null/absent)
  TestValidator.predicate("no soft-deleted logs")(
    paged.data.every((item) => !('deleted_at' in item) || item.deleted_at === null)
  );

  // 4. Error case: malformed filter input (e.g. negative page)
  await TestValidator.error("invalid page rejects")(
    async () => {
      await api.functional.discussionBoard.admin.emailLogs.search(connection, {
        body: {
          page: -1,
        },
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validate successful anonymous guest login and token issuance.
 *
 * This test covers the API for issuing a guest JWT token to an anonymous visitor. It simulates an unknown guest (no prior session or registration) providing basic device and network fingerprinting (user agent, IP address).
 *
 * **Steps:**
 * 1. Construct a plausible browser user agent and IPv4 network address for an anonymous guest.
 * 2. Call the guest login API to request a guest session token, supplying user agent and IP address.
 * 3. Assert that the response matches the required structure, contains a non-empty JWT token, and supplies the correct Bearer token in setHeaders.Authorization.
 *
 * **Business rationale:**
 * - Verifies that an anonymous (unregistered) visitor can receive a guest JWT for session tracking and legal audit, without providing any PII.
 * - Ensures that backend establishes guest sessions, issues tokens only when proper device/network metadata is supplied, and that setHeaders is properly formed for SDK/client workflows.
 */
export async function test_api_guest_login_new_session_token_issued(
  connection: api.IConnection,
) {
  // 1. Construct realistic anonymous device/browser and network metadata.
  const userAgent = `Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/${typia.random<number & tags.Type<"uint32"> & tags.Minimum<80> & tags.Maximum<120>>>()}.0.0.0 Safari/537.36`;
  const ipAddress = `${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<255>>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<255>>>()}`;

  // 2. Make the guest login API call
  const output = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: userAgent,
      ip_address: ipAddress,
    } satisfies IGuestAuthGuestSignInRequest,
  });

  // 3. Assert the result matches output DTO and business constraints
  typia.assert(output);
  TestValidator.predicate("token should be a non-empty JWT string")(
    typeof output.token === "string" && /^\S+\.\S+\.\S+$/.test(output.token),
  );
  TestValidator.predicate("setHeaders.Authorization matches Bearer token")(
    typeof output.setHeaders?.Authorization === "string" &&
      output.setHeaders.Authorization === `Bearer ${output.token}`,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";
import type { IGuestAuthGuestSignOutResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignOutResponse";

/**
 * Validates successful logout of a guest session, ensuring JWT session termination and subsequent token invalidation.
 *
 * This test covers the full logout lifecycle for a guest:
 * 1. Issue a guest JWT token by authenticating as a guest using device metadata (user agent, IP).
 * 2. Perform logout for the guest using the active session token.
 * 3. Confirm a positive response is returned, indicating session invalidation.
 * 4. Attempt to use the (now invalid) guest JWT token for another guest API, and expect failure (error thrown).
 *
 * This ensures guests cannot access resources after logout and verifies compliance with session invalidation policy.
 */
export async function test_api_guest_logout_success_session_end(connection: api.IConnection) {
  // 1. Issue a guest JWT token by logging in as a guest (with metadata).
  const signInBody: IGuestAuthGuestSignInRequest = {
    user_agent: RandomGenerator.alphabets(12),
    ip_address: `192.168.${typia.random<number & tags.Type<"uint8">>()}.${typia.random<number & tags.Type<"uint8">>()}`,
  };
  const loginResponse = await api.functional.auth.guest.login.signIn(connection, { body: signInBody });
  typia.assert(loginResponse);
  TestValidator.predicate("JWT token issued and present")(typeof loginResponse.token === "string" && loginResponse.token.length > 0);
  TestValidator.equals("Authorization header matches JWT token")(
    loginResponse.setHeaders.Authorization.replace(/^Bearer\s+/i, "")
  )(loginResponse.token);

  // 2. Set the guest JWT Token in connection header for logout and subsequent access
  connection.headers = { ...connection.headers, Authorization: `Bearer ${loginResponse.token}` };

  // 3. Perform logout (signOut) – this should invalidate session
  const logoutResponse = await api.functional.auth.guest.logout.signOut(connection);
  typia.assert(logoutResponse);

  // 4. Attempt to use the logged-out token for another guest API, expecting failure (401/invalid token)
  await TestValidator.error("Using guest API after logout should fail")(
    async () => {
      // Attempt to call signOut *again* using the logged-out JWT
      await api.functional.auth.guest.logout.signOut(connection);
    },
  );
}

