/**
 * Validate admin search and pagination of ad integration logs.
 *
 * This test ensures that the admin search endpoint for ad integration logs returns correct, filtered, and paginated results. It first creates several ad integration log entries with various event_types, ad_channels, success flags, and date ranges. It then performs search queries using different filters, including event type, success status, and date ranges. Results are validated so that each entry matches the filter criteria, and pagination is checked for correct number of results per page and correct page navigation.
 *
 * Steps:
 * 1. Create multiple ad integration log entries covering various permutations of ad_channel, event_type, and success.
 * 2. Search with a specific filter (e.g., event_type="click" and success=true).
 * 3. Assert that all results match the filter criteria.
 * 4. Run a search with date range and validate only appropriate items are returned.
 * 5. Create enough entries to require multiple pages, and verify pagination: correct page, limit, and total counts.
 */
export async function test_api_ad_integration_log_search_success(
  connection: api.IConnection,
) {
  // 1. Create test logs with diverse data
  const logs = await Promise.all([
    api.functional.discussionBoard.admin.adIntegrationLogs.create(connection, {
      body: {
        ad_channel: "google_adsense",
        event_type: "impression",
        event_at: new Date().toISOString(),
        success: true,
      } satisfies IDiscussionBoardAdIntegrationLog.ICreate,
    }),
    api.functional.discussionBoard.admin.adIntegrationLogs.create(connection, {
      body: {
        ad_channel: "facebook",
        event_type: "click",
        event_at: new Date(Date.now() - 86400000).toISOString(),
        success: false,
        error_code: "ERR01",
        error_message: "Simulated failure",
      } satisfies IDiscussionBoardAdIntegrationLog.ICreate,
    }),
    api.functional.discussionBoard.admin.adIntegrationLogs.create(connection, {
      body: {
        ad_channel: "google_adsense",
        event_type: "click",
        event_at: new Date().toISOString(),
        success: true,
      } satisfies IDiscussionBoardAdIntegrationLog.ICreate,
    }),
    api.functional.discussionBoard.admin.adIntegrationLogs.create(connection, {
      body: {
        ad_channel: "google_adsense",
        event_type: "conversion",
        event_at: new Date(Date.now() - 2 * 86400000).toISOString(),
        success: true,
      } satisfies IDiscussionBoardAdIntegrationLog.ICreate,
    }),
  ]);
  logs.forEach(typia.assert);

  // 2. Filter: event_type = "click", success = true
  const filterResult = await api.functional.discussionBoard.admin.adIntegrationLogs.search(connection, {
    body: {
      event_type: "click",
      success: true,
      limit: 10,
      page: 1,
    } satisfies IDiscussionBoardAdIntegrationLog.IRequest,
  });
  typia.assert(filterResult);
  filterResult.data.forEach(entry => {
    TestValidator.equals("event_type should be 'click'")(entry.event_type)("click");
    TestValidator.equals("success should be true")(entry.success)(true);
  });

  // 3. Filter: ad_channel = "google_adsense", date range limited to last 2 days
  const fromDate = new Date(Date.now() - 2 * 86400000).toISOString();
  const toDate = new Date().toISOString();
  const dateRangeResult = await api.functional.discussionBoard.admin.adIntegrationLogs.search(connection, {
    body: {
      ad_channel: "google_adsense",
      from_date: fromDate,
      to_date: toDate,
    } satisfies IDiscussionBoardAdIntegrationLog.IRequest,
  });
  typia.assert(dateRangeResult);
  dateRangeResult.data.forEach(entry => {
    TestValidator.equals("ad_channel is google_adsense")(entry.ad_channel)("google_adsense");
    TestValidator.predicate("event_at in range")(entry.event_at >= fromDate && entry.event_at <= toDate);
  });

  // 4. Pagination: create additional logs to require multiple pages
  const additionalLogs = await Promise.all(ArrayUtil.repeat(12)(() =>
    api.functional.discussionBoard.admin.adIntegrationLogs.create(connection, {
      body: {
        ad_channel: "google_adsense",
        event_type: "impression",
        event_at: new Date().toISOString(),
        success: true,
      } satisfies IDiscussionBoardAdIntegrationLog.ICreate,
    })
  ));
  additionalLogs.forEach(typia.assert);

  // Search with pagination (limit = 5, page = 2)
  const paginatedResult = await api.functional.discussionBoard.admin.adIntegrationLogs.search(connection, {
    body: {
      ad_channel: "google_adsense",
      limit: 5,
      page: 2,
    } satisfies IDiscussionBoardAdIntegrationLog.IRequest,
  });
  typia.assert(paginatedResult);
  TestValidator.equals("pagination.limit")(paginatedResult.pagination.limit)(5);
  TestValidator.equals("pagination.current")(paginatedResult.pagination.current)(2);
  TestValidator.predicate("data length <= limit")(paginatedResult.data.length <= 5);
}

