import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";
import type { IValidateToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IValidateToken";

/**
 * Comprehensive validation of admin JWT token lifecycle and privilege handling via /auth/admin/validate.
 *
 * Business Purpose: To verify that the authentication system securely recognizes valid admin sessions, rejects tampered, expired, malformed, or revoked tokens, and enforces privilege checks based on admin status.
 *
 * Test Steps:
 * 1. Register a new admin account (required to ensure a unique valid subject).
 * 2. Log in with that account to obtain a fresh (valid/current) JWT token via access_token.
 * 3. Validate the fresh token using /auth/admin/validate; assert that it is valid and session data is correct.
 * 4. Attempt to validate various invalid token types:
 *    - Malformed: Broken structure (e.g., just a random string or incomplete JWT format)
 *    - Tampered: Corrupted signature (take valid token and flip a character in signature part)
 *    - Expired: (Cannot simulate expiry via API directly—describe this branch and skip code.)
 *    - Wrong claims: Valid JWT shape but e.g. different 'role' or altered subject (explain limitations if not possible)
 * 5. Simulate privilege enforcement: (Business rules call for checking suspended/revoked user status, but without an API to change admin status, skip this or describe what code would look like.)
 * 6. For each failed validation, ensure status field is not 'valid' and isValid is false; for real tokens assert isValid and status is 'valid' or equivalent.
 *
 * Outline edge-cases covered:
 * - Only implement what can be triggered via current API. If status manipulation or token expiry cannot be simulated, explain as comments.
 */
export async function test_api_admin_jwt_validation_active_and_inactive(
  connection: api.IConnection,
) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecureP@ss123";
  const registerResp = await api.functional.auth.admin.register.post.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(registerResp);

  // 2. Admin login to issue a valid access token
  const loginResp = await api.functional.auth.admin.login.post.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IDiscussionBoardAdmin.ILogin
  });
  typia.assert(loginResp);
  const validToken = loginResp.access_token;

  // 3. Validate a valid token
  const validValidation = await api.functional.auth.admin.validate.post.validateToken(connection, {
    body: { token: validToken } satisfies IValidateToken.Request
  });
  typia.assert(validValidation);
  TestValidator.predicate("valid token should be valid")(validValidation.isValid === true);
  TestValidator.equals("valid status")(validValidation.status)("valid");

  // 4a. Validate a malformed token (not even JWT structure)
  const malformedToken = "not.a.jwt";
  const malformedValidation = await api.functional.auth.admin.validate.post.validateToken(connection, {
    body: { token: malformedToken } satisfies IValidateToken.Request
  });
  typia.assert(malformedValidation);
  TestValidator.predicate("malformed token should be invalid")(malformedValidation.isValid === false);
  TestValidator.predicate("malformed non-valid status")(malformedValidation.status !== "valid");

  // 4b. Validate a tampered token (alter signature)
  // Take the JWT, split and mutate a char in signature
  const split = validToken.split(".");
  let tamperedToken = validToken;
  if (split.length === 3) {
    // Flip a character in the signature
    const sig = split[2];
    const mutatedSig = (sig.length > 0)
      ? sig.substring(0, sig.length - 1) + (sig[sig.length - 1] === "A" ? "B" : "A")
      : sig;
    tamperedToken = split[0] + "." + split[1] + "." + mutatedSig;
  }
  const tamperedValidation = await api.functional.auth.admin.validate.post.validateToken(connection, {
    body: { token: tamperedToken } satisfies IValidateToken.Request
  });
  typia.assert(tamperedValidation);
  TestValidator.predicate("tampered token invalid")(tamperedValidation.isValid === false);
  TestValidator.predicate("tampered non-valid status")(tamperedValidation.status !== "valid");

  // 4c. Expired token test cannot be performed because we cannot mint an expired JWT via API; skip.

  // 4d. Wrong claims test - if we could, e.g., mint a token with different role/subject. Not feasible with API, so skip but describe.

  // 5. Admin status suspended/revoked: No API for status change, so this cannot be simulated.

  // 6. All failed cases: status field should not be 'valid' and isValid===false (already checked above)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
