/**
 * Validates searching and filtering of permission matrix entries via admin.
 *
 * This test ensures that only authorized administrators can retrieve permission matrix records, with correct application of filter and pagination logic. The result should reflect only non-deleted entries and conform to the expected paginated schema.
 *
 * Steps:
 * 1. Register a new admin user (using a unique email/password)
 * 2. Perform a search as this admin using various filters (role, resource, action, allowed, effective_from_after, effective_to_before, etc.) and paginated parameters (page, limit)
 * 3. Validate the response: only non-deleted records are returned, filter constraints are respected, data matches requested schema
 * 4. Confirm that if an unauthenticated (or unauthorized) attempt is made, the operation is forbidden
 */
export async function test_api_permission_matrix_search_success(connection: api.IConnection) {
  // 1. Register a new admin user
  const email = typia.random<string & tags.Format<"email">>();
  const res = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password: "TestPassword123!"
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(res);

  // At this point the Authorization header is set on connection for admin session

  // 2. Perform a search with representative filters as an authenticated admin
  const filter: IDiscussionBoardPermissionMatrix.IRequest = {
    role_name: "admin",
    resource: "post",
    action: "read",
    allowed: true,
    effective_from_after: null,
    effective_to_before: null,
    page: 1,
    limit: 10,
  };
  const output = await api.functional.discussionBoard.admin.permissionMatrices.search(connection, {
    body: filter,
  });
  typia.assert(output);

  // 3. Validate pagination and filter logic
  TestValidator.predicate("pagination parameters respected")(
    output.pagination.limit === filter.limit && output.pagination.current === filter.page
  );
  output.data.forEach((item) => {
    TestValidator.equals("role_name matches filter")(item.role_name)(filter.role_name);
    TestValidator.equals("resource matches filter")(item.resource)(filter.resource);
    TestValidator.equals("action matches filter")(item.action)(filter.action);
    TestValidator.equals("allowed matches filter")(item.allowed)(filter.allowed);
    TestValidator.equals("deleted_at is null")(item.deleted_at)(null);
  });

  // 4. Simulate unauthorized search: blank auth header
  const tempConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("forbidden to unauthenticated user")(async () => {
    await api.functional.discussionBoard.admin.permissionMatrices.search(tempConnection, {
      body: filter,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that normal members and guests are forbidden from accessing admin-only category detail endpoint.
 *
 * This test ensures the API enforces proper access restrictions by denying detail access requests to /discussionBoard/admin/categories/{categoryId}
 * for both ordinary members (non-admin/moderator) and unauthenticated guests. Proper forbidden errors should be returned, and no sensitive data exposed.
 *
 * Steps:
 * 1. As an admin (by default, assumed API connection is privileged), create a category to have a testable categoryId.
 * 2. Register and authenticate as a normal member (non-admin), and switch the connection context accordingly.
 * 3. Attempt to access the category detail endpoint as this normal member. Expect a forbidden error.
 * 4. Logout or remove member authentication from connection to simulate guest access.
 * 5. Attempt again to access category detail endpoint as guest (unauthenticated). Expect a forbidden error.
 *
 * Validation:
 * - API should reject access for non-admin/non-moderator users
 * - API should reject access for guests (no authentication)
 * - Forbidden error (HTTP 403) should be thrown for both cases
 */
export async function test_api_category_detail_view_permission_denied_member_or_guest(
  connection: api.IConnection,
) {
  // 1. Create a category as admin
  const createdCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      display_order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
      version: 1,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(createdCategory);

  // 2. Register (and login as) a normal member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: "Test1234!",
      nickname: RandomGenerator.alphabets(8),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);
  // Set Authorization token for connection
  connection.headers.Authorization = memberSession.setHeaders.Authorization;

  // 3. Attempt unauthorized access to category detail as non-admin member
  await TestValidator.error("non-admin member forbidden to access category detail")(async () => {
    await api.functional.discussionBoard.admin.categories.at(connection, {
      categoryId: createdCategory.id,
    });
  });

  // 4. Remove token to simulate guest
  delete connection.headers.Authorization;

  // 5. Attempt unauthorized access to category detail as guest
  await TestValidator.error("guest forbidden to access category detail")(async () => {
    await api.functional.discussionBoard.admin.categories.at(connection, {
      categoryId: createdCategory.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Test that a moderator user can successfully update a category's editable fields.
 *
 * Business context: Moderators have permission to update certain fields of discussion board categories. This test verifies that those permissions are respected, the edit is recorded correctly, and audit/version fields are updated appropriately.
 *
 * Test steps:
 * 1. Register a moderator to obtain a JWT and moderator privileges.
 * 2. As an admin, create a new category that will later be updated by the moderator.
 * 3. Switch connection context/authentication to the moderator (set Authorization header).
 * 4. Update the category using the moderator endpoint; change editable fields such as name, display_order, description, icon_uri, enabled, and version.
 * 5. Verify the returned category has the desired changes, and that audit fields (updated_at, version override, etc.) have been appropriately set/updated.
 * 6. (Edge case) Ensure that only permitted fields are modified, and moderator role is required for the operation.
 */
export async function test_api_category_update_success_moderator(
  connection: api.IConnection,
) {
  // 1. Register moderator and obtain JWT
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const signUpRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: "Test1234$",
      assigned_by_admin_email: adminEmail,
    } satisfies IModerator.SignUp,
  });
  typia.assert(signUpRes);
  TestValidator.equals("moderator email matches")(signUpRes.email)(moderatorEmail);
  // Set Authorization header on connection so API calls use moderator identity
  connection.headers = connection.headers || {};
  connection.headers["Authorization"] = signUpRes.setHeaders.Authorization;

  // 2. Create a category as admin (simulate by switching context or before setting moderator header)
  // Temporarily remove Authorization header to act as admin
  const prevHeaders = { ...connection.headers };
  connection.headers["Authorization"] = undefined;
  const initialCategoryInput: IDiscussionBoardCategory.ICreate = {
    name: "Initial Category",
    display_order: 100,
    enabled: true,
    version: 1,
    description: "Initial category for moderator update test",
    icon_uri: "https://example.com/icon.png",
  };
  const createdCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: initialCategoryInput,
  });
  typia.assert(createdCategory);
  // Restore moderator authentication on connection
  connection.headers["Authorization"] = signUpRes.setHeaders.Authorization;

  // 3. Prepare a set of updates for the category as moderator
  const updateInput: IDiscussionBoardCategory.IUpdate = {
    name: "Updated Category",
    display_order: 200,
    description: "Category updated by moderator.",
    icon_uri: "https://example.com/updated-icon.png",
    enabled: false,
    version: 2,
    // parent_id omitted (would require an existing different category for re-parenting)
  };

  // 4. Call the moderator update endpoint
  const updatedCategory = await api.functional.discussionBoard.moderator.categories.update(connection, {
    categoryId: createdCategory.id,
    body: updateInput,
  });
  typia.assert(updatedCategory);

  // 5. Verify that the changes have taken effect and audit fields have been updated.
  TestValidator.equals("category id matches")(updatedCategory.id)(createdCategory.id);
  TestValidator.equals("name updated")(updatedCategory.name)(updateInput.name!);
  TestValidator.equals("display_order updated")(updatedCategory.display_order)(updateInput.display_order!);
  TestValidator.equals("icon_uri updated")(updatedCategory.icon_uri)(updateInput.icon_uri!);
  TestValidator.equals("description updated")(updatedCategory.description)(updateInput.description!);
  TestValidator.equals("enabled updated")(updatedCategory.enabled)(updateInput.enabled!);
  TestValidator.equals("version updated")(updatedCategory.version)(updateInput.version!);
  TestValidator.predicate("updated_at is after created_at")(
    new Date(updatedCategory.updated_at).getTime() > new Date(updatedCategory.created_at).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
