import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * E2E test verifying admin search/filter/post visibility, audit fields, and pagination robustness.
 *
 * 1. Register an admin account and login, saving the credential token into the connection object for further privileged calls.
 * 2. Create several posts as admin, using a range of statuses ('active', 'hidden', 'flagged', 'deleted'), with diverse title/body/category fields.
 *    - Use at least 2 distinct category_id values.
 *    - Use both short and long title/body text.
 *    - Some posts should be directly "deleted" (by setting status and ensuring deleted_at exists).
 *    - Ensure at least 1 post for each status type.
 * 3. For each of the following, issue a search (PATCH /discussionBoard/admin/posts) with admin credentials, verify the result type, content, and audit visibility:
 *    a. No filter (all posts, all statuses) – verify all created posts (including "deleted"/hidden/flagged) appear and audit info is present
 *    b. By status (one search per: 'active', 'hidden', 'flagged', 'deleted') – verify search only returns posts for that status
 *    c. By author_admin_id (filter by current admin user, verify only self-authored posts returned)
 *    d. By category_id (search by each used category_id, check only posts from that category returned)
 *    e. Text search (partial title/body keywords, verify matches are as expected)
 * 4. Check pagination: use limit smaller than total (limit = 2), verify returned data and pagination meta, iterate over multiple pages if possible.
 * 5. Complex filter: status + category + text combined (ensure only posts matching all constraints are returned)
 * 6. Edge cases: 
 *    - Empty result (search with impossible filters)
 *    - Invalid category_id (well-formed but unused UUID)
 *    - Negative page index (expect graceful error handling, not internal crash)
 * 7. Check that result objects include extra admin-visible audit info where specification expects it (where verifiable by shape or with type assertion only).
 */
export async function test_api_admin_post_search_with_audit_scope_and_metadata(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "P@ssw0rd!";
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(registerResp);

  // 2. Admin login
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(loginResp);

  // At this point, connection.headers.Authorization is set for admin auth.

  // 3. Use two categories (minimal summaries)
  const categoryA = {
    id: typia.random<string & tags.Format<"uuid">>(),
    name: "Category A",
  } satisfies IDiscussionBoardCategory.ISummary;
  const categoryB = {
    id: typia.random<string & tags.Format<"uuid">>(),
    name: "Category B",
  } satisfies IDiscussionBoardCategory.ISummary;

  // 4. Create posts in various statuses/categories (simulate by local mutation since status can only be set by workflow/policy, not at create)
  const postSpecs = [
    { status: "active", category: categoryA, title: "Active Post" },
    { status: "hidden", category: categoryA, title: "Hidden Post" },
    { status: "flagged", category: categoryB, title: "Flagged Post" },
    { status: "deleted", category: categoryB, title: "Deleted Post" },
  ];
  const createdPosts: IDiscussionBoardPost[] = [];
  for (const spec of postSpecs) {
    const post = await api.functional.discussionBoard.admin.posts.create(connection, {
      body: {
        title: spec.title,
        body: `Body for ${spec.title}`,
        category_id: spec.category.id,
        attachments: null,
      },
    });
    typia.assert(post);
    // Simulate status and deleted_at as local mock, since API does not provide direct status mutation
    if (spec.status !== "active") {
      post.status = spec.status;
      if (spec.status === "deleted") post.deleted_at = new Date().toISOString() as string & tags.Format<"date-time">;
    }
    createdPosts.push(post);
  }

  // 5. Search - no filter (admin gets all statuses)
  let result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: {},
  });
  typia.assert(result);
  TestValidator.predicate("all statuses returned as admin")(
    result.data.find((x) => x.status === "deleted" && x.title === "Deleted Post") !== undefined,
  );

  // 6. Search by status
  for (const status of ["active", "hidden", "flagged", "deleted"]) {
    result = await api.functional.discussionBoard.admin.posts.search(connection, {
      body: { status },
    });
    typia.assert(result);
    TestValidator.predicate(`only ${status} posts returned`)(
      result.data.every((x) => x.status === status),
    );
  }

  // 7. Search by author_admin_id (should get only posts authored by this admin)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { author_admin_id: registerResp.admin_id },
  });
  typia.assert(result);
  TestValidator.predicate("posts for this admin only")(
    result.data.every((x) => x.author_admin_id === registerResp.admin_id),
  );

  // 8. Search by category_id
  for (const cat of [categoryA, categoryB]) {
    result = await api.functional.discussionBoard.admin.posts.search(connection, {
      body: { category_id: cat.id },
    });
    typia.assert(result);
    TestValidator.predicate(`category filter: ${cat.name}`)(
      result.data.every((x) => x.category.id === cat.id),
    );
  }

  // 9. Text search (partial title, partial body)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { title: "Active" },
  });
  typia.assert(result);
  TestValidator.predicate("title search finds correct post")(
    result.data.some((x) => x.title.includes("Active")),
  );

  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { body: "Body for Hidden" },
  });
  typia.assert(result);
  TestValidator.predicate("body search finds hidden post")(
    result.data.some((x) => x.title === "Hidden Post"),
  );

  // 10. Pagination test (limit < total)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
