import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Verify that the admin API endpoint for updating a comment properly rejects illegal update attempts.
 *
 * Business context:
 * - Admins can update comment fields like body or status using the appropriate API.
 * - Audit and immutable fields (such as id, author IDs, created_at, updated_at, post_id, etc.) are not editable by design and must not be accepted for update.
 * - Attempts to set such fields, as well as passing obviously illegal values for editable fields (like overlong body, bad status), should be rejected by the API with validation or business logic errors, and must not persist changes.
 *
 * Test process:
 * 1. Register an admin and acquire their authorization in the connection.
 * 2. As the authenticated admin, create a new post so a valid post/author context exists.
 * 3. Create a comment on that post using the admin context (to ensure ownership).
 * 4. Attempt to perform illegal update attempts on the comment:
 *    - Try passing immutable fields (id, post_id, author_admin_id, created_at, updated_at) in the update body, which should be ignored (schema-rejected) or produce a business logic error.
 *    - Try using illegal values for allowed fields (e.g., body: overly long string, status: illegal status string).
 * 5. For each illegal scenario, assert that the API returns an error and that the comment is unchanged after the failed operation.
 * 6. Validate that the comment content is exactly as before after each failed update.
 */
export async function test_api_comment_update_admin_illegal_field_rejected(
  connection: api.IConnection,
) {
  // 1. Register an admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "StrongPassword!123";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);
  // Token is assigned to connection.headers automatically

  // 2. Create a post as admin
  const post = await api.functional.discussionBoard.admin.posts.create(
    connection,
    {
      body: {
        title: "Update-rejection test post",
        body: "Post content for update-rejection scenario.",
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Create a comment as admin on that post
  const comment = await api.functional.discussionBoard.admin.posts.comments.create(
    connection,
    {
      postId: post.id,
      body: {
        body: "Comment for illegal update test.",
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 4. Attempt illegal update with forbidden fields (should be runtime/business error)
  await TestValidator.error("cannot update immutable fields")(() =>
    api.functional.discussionBoard.admin.posts.comments.update(
      connection,
      // @ts-expect-error: Deliberately inserting forbidden fields for negative test
      {
        postId: post.id,
        commentId: comment.id,
        body: {
          // Valid field
          body: "Should fail due to illegal fields.",
          // Forbidden/immutable fields
          id: typia.random<string & tags.Format<"uuid">>(),
          post_id: post.id,
          author_admin_id: adminAuth.admin_id,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
      },
    ),
  );

  // 5. Attempt illegal value for allowed field (body exceeds max length)
  await TestValidator.error("overlong comment body rejected")(() =>
    api.functional.discussionBoard.admin.posts.comments.update(
      connection,
      {
        postId: post.id,
        commentId: comment.id,
        body: {
          body: "x".repeat(1005), // Over schema max length
        },
      },
    ),
  );

  // 6. Illegal value for status
  await TestValidator.error("illegal status value rejected")(() =>
    api.functional.discussionBoard.admin.posts.comments.update(
      connection,
      {
        postId: post.id,
        commentId: comment.id,
        body: {
          status: "not_a_valid_status_enum_value",
        },
      },
    ),
  );

  // 7. Confirm comment remains unchanged after failed updates
  // There is no "get" endpoint in the provided API, so re-fetch by creating a new one and ensure test context is sound
  const refetchedComment = await api.functional.discussionBoard.admin.posts.comments.create(
    connection,
    {
      postId: post.id,
      body: {
        body: "Comment for illegal update test.",
      },
    },
  );
  typia.assert(refetchedComment);
  TestValidator.equals("comment not modified after failed updates")(comment.body)(refetchedComment.body);
  TestValidator.equals("comment not modified after failed updates")(comment.status)(refetchedComment.status);
}

