}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";
import type { IGuestAuthGuestValidateRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestValidateRequest";
import type { IGuestAuthGuestValidateResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestValidateResponse";

/**
 * Validate the proper response for an expired or invalid guest JWT token.
 *
 * This test ensures that the `/auth/guest/validate` endpoint correctly detects when a guest JWT token is expired or otherwise invalid. It covers a complete guest session from obtaining a token to simulating token invalidation and validation.
 *
 * Step-by-step process:
 * 1. Perform guest login via `/auth/guest/login` to obtain a guest JWT token using realistic user agent and IP address info.
 * 2. Simulate an invalid/expired token by programmatically altering the JWT value (this is used to cause a validation failure, as we cannot practically wait for TTL expiry in a test).
 * 3. Call `/auth/guest/validate` with the manipulated token, user agent, and IP address to trigger a rejection.
 * 4. Assert that the API response `.valid` is false and `.reason` indicates the invalid/expired/revoked state.
 *
 * This validates both backend token revocation/expiry logic and correctness of error reporting for guest JWT validation flows.
 */
export async function test_api_guest_jwt_validation_expired_token(connection: api.IConnection) {
  // 1. Perform guest login to obtain a valid JWT token
  const userAgent = `e2e-test-agent-${RandomGenerator.alphaNumeric(6)}`;
  const ipAddress = `192.168.1.${typia.random<number & tags.Type<"uint8"> & tags.Minimum<2> & tags.Maximum<254>>()}`;
  const signInResponse = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: userAgent,
      ip_address: ipAddress,
    },
  });
  typia.assert(signInResponse);
  const { token } = signInResponse;

  // 2. Simulate token expiry/invalidity by intentionally altering a char
  // (No way to truly fast-forward expiration for real, so this mimics an invalid/expired/revoked token)
  const invalidToken = token.slice(0, -1) + (token.slice(-1) === 'x' ? 'y' : 'x');

  // 3. Attempt validation with the invalid/expired token
  const validationResponse = await api.functional.auth.guest.validate.validateToken(connection, {
    body: {
      token: invalidToken,
      user_agent: userAgent,
      ip_address: ipAddress,
    },
  });
  typia.assert(validationResponse);

  // 4. Validate that the response correctly reports the token as not valid
  TestValidator.equals("token validity should be false for expired/invalid")(validationResponse.valid)(false);
  TestValidator.predicate("reason should explain invalid/expired state")(
    !!validationResponse.reason && ["expired", "invalid", "revoked", "not found"].includes(validationResponse.reason),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";
import type { IGuestAuthGuestValidateRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestValidateRequest";
import type { IGuestAuthGuestValidateResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestValidateResponse";

/**
 * Validate that the system detects a tampered guest JWT and correctly rejects it.
 *
 * Businesses often must defend against token forgery or manipulation by validating JWT signatures. This test ensures that after a guest session successfully retrieves a token, if the token is modified even slightly (thus invalidating the cryptographic signature), the /auth/guest/validate endpoint returns a validation failure, not a false positive.
 *
 * Step-by-step process:
 * 1. Perform guest login to obtain a valid JWT token (via /auth/guest/login).
 * 2. Modify the acquired JWT by changing a single character in its signature part.
 * 3. Submit the tampered JWT to /auth/guest/validate along with user agent and IP used in step 1.
 * 4. Check the response: 'valid' must be false, and 'reason' should indicate invalidity (e.g., 'invalid', 'tampered', or similar).
 */
export async function test_api_guest_jwt_validation_invalid_signature(connection: api.IConnection) {
  // 1. Guest login: request a valid guest JWT
  const request: IGuestAuthGuestSignInRequest = {
    user_agent: RandomGenerator.alphabets(10),
    ip_address: [
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<1> & tags.Maximum<255>>(),
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<0> & tags.Maximum<255>>(),
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<0> & tags.Maximum<255>>(),
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<1> & tags.Maximum<254>>()
    ].join("."),
  };
  const loginOutput: IGuestAuthGuestSignInResponse = await api.functional.auth.guest.login.signIn(connection, {
    body: request,
  });
  typia.assert(loginOutput);

  // 2. Tamper the JWT string: change a character (in signature part)
  let tamperedToken = loginOutput.token;
  const parts = tamperedToken.split('.');
  if (parts.length !== 3) throw new Error("JWT does not have 3 parts");
  let sig = parts[2];
  // Flip first character as a safe, minimal mutation
  const origChar = sig[0];
  let mutatedChar;
  if (origChar === 'A') mutatedChar = 'B';
  else if (origChar === 'B') mutatedChar = 'A';
  else mutatedChar = 'A';
  sig = mutatedChar + sig.slice(1);
  parts[2] = sig;
  tamperedToken = parts.join('.');

  // 3. Call /auth/guest/validate with tampered JWT
  const validationOutput: IGuestAuthGuestValidateResponse =
    await api.functional.auth.guest.validate.validateToken(connection, {
      body: {
        token: tamperedToken,
        user_agent: request.user_agent,
        ip_address: request.ip_address,
      },
    });
  typia.assert(validationOutput);

  // 4. Assert invalid token is detected
  TestValidator.equals("token should be invalid")(validationOutput.valid)(false);
  TestValidator.predicate("reason is present")(typeof validationOutput.reason === 'string' && validationOutput.reason.length > 0);
}

