}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostReport";
import type { IPageIDiscussionBoardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * E2E - Search post reports as a moderator, validating filtering and pagination.
 *
 * This test verifies that a moderator can successfully search, filter, and paginate abuse reports on posts in various ways.
 *
 * Workflow:
 * 1. Register multiple members for diversity in reporting scenarios
 * 2. Have each member create a post (some posts will receive multiple reports)
 * 3. Have members file abuse reports on each other's posts, with deliberate differences in reason_type and post combinations.
 * 4. As moderator, perform post report search with different filters:
 *    - By report reason_type
 *    - By reporting member (discussion_board_member_id)
 *    - By post id (discussion_board_post_id)
 *    - By limit/page (pagination)
 * 5. For each search, validate correctness of filtered content and pagination metadata
 *
 * Limitations:
 * - Cannot influence workflow status or handler_admin_id of reports (report status is backend-determined on report creation)
 * - Thus, filter/validate only on controllable properties: reason_type, reporting member, post id, and pagination
 */
export async function test_api_post_report_search_moderator_with_filters(connection: api.IConnection) {
  // 1. Register three test members
  const members = await Promise.all([
    api.functional.auth.member.register.signUp(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "password!1",
        nickname: RandomGenerator.name(),
      },
    }),
    api.functional.auth.member.register.signUp(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "password!1",
        nickname: RandomGenerator.name(),
      },
    }),
    api.functional.auth.member.register.signUp(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "password!1",
        nickname: RandomGenerator.name(),
      },
    }),
  ]);
  for (const session of members) typia.assert(session);

  // Map of memberId for role switching
  const memberIds = members.map((m) => m.member.id);

  // 2. Each member creates a post
  const posts = await Promise.all(
    members.map((session, idx) =>
      api.functional.discussionBoard.member.posts.create(
        { ...connection, headers: { ...connection.headers, Authorization: session.setHeaders.Authorization } },
        {
          body: {
            title: `Test Post #${idx + 1} by ${session.member.nickname}`,
            body: `Content for post ${idx + 1}.`,
          },
        },
      ),
    ),
  );
  for (const post of posts) typia.assert(post);
  const postIds = posts.map((p) => p.id);

  // 3. Members file abuse reports on various posts
  // We'll ensure all permutations for filter richness:
  // M1 reports P2 (reason: spam), M2 reports P3 (reason: hate), M3 reports P1 (reason: hate), plus one duplicate for status check
  const reportSpecs = [
    { reporter: members[0], targetPost: posts[1], reason_type: "spam" },
    { reporter: members[1], targetPost: posts[2], reason_type: "hate" },
    { reporter: members[2], targetPost: posts[0], reason_type: "hate" },
    // Add one more for multi-report test
    { reporter: members[0], targetPost: posts[2], reason_type: "spam" },
  ];

  const reports: (import("../../api/structures/IDiscussionBoardPostReport").IDiscussionBoardPostReport)[] = [];
  for (const spec of reportSpecs) {
    const report = await api.functional.discussionBoard.member.postReports.create(
      { ...connection, headers: { ...connection.headers, Authorization: spec.reporter.setHeaders.Authorization } },
      {
        body: {
          discussion_board_post_id: spec.targetPost.id,
          reason_type: spec.reason_type,
          reason_text: `Reporting ${spec.reason_type}`,
        },
      },
    );
    typia.assert(report);
    reports.push(report);
  }
  // Map reports for quick filter checks
  // 4. As moderator, perform search queries with various filters

  // By reason_type 'spam'
  {
    const output = await api.functional.discussionBoard.moderator.postReports.search(connection, {
      body: {
        reason_type: "spam",
        page: 1,
        limit: 10,
      },
    });
    typia.assert(output);
    // Must contain only reports with reason_type "spam"
    for (const report of output.data) {
      TestValidator.equals("reason_type is 'spam'")(report.reason_type)("spam");
    }
    // Should match 2 reports because we made two 'spam' type reports
    TestValidator.equals("spam report count")(output.data.length)(2);
  }

  // By reason_type 'hate'
  {
    const output = await api.functional.discussionBoard.moderator.postReports.search(connection, {
      body: {
        reason_type: "hate",
        page: 1,
        limit: 10,
      },
    });
    typia.assert(output);
    for (const report of output.data) {
      TestValidator.equals("reason_type is 'hate'")(report.reason_type)("hate");
    }
    TestValidator.equals("hate report count")(output.data.length)(2);
  }

  // By reporting member
  {
    const reportingMemberId = members[0].member.id;
    const output = await api.functional.discussionBoard.moderator.postReports.search(connection, {
      body: {
        discussion_board_member_id: reportingMemberId,
        page: 1,
        limit: 10,
      },
    });
    typia.assert(output);
    for (const report of output.data) {
      TestValidator.equals("reporter is member 0")(report.discussion_board_member_id)(reportingMemberId);
    }
    // Should be 2 because M1 made two reports
    TestValidator.equals("M1 report count")(output.data.length)(2);
  }

  // By post id
  {
    const postId = posts[2].id;
    const output = await api.functional.discussionBoard.moderator.postReports.search(connection, {
      body: {
        discussion_board_post_id: postId,
        page: 1,
        limit: 10,
      },
    });
    typia.assert(output);
    for (const report of output.data) {
      TestValidator.equals("report is for P3")(report.discussion_board_post_id)(postId);
    }
    // Should match 2: M2 reported P3 (hate), M1 reported P3 (spam)
    TestValidator.equals("P3 report count")(output.data.length)(2);
  }

  // Pagination tests: limit = 2, page = 1
  {
    const output = await api.functional.discussionBoard.moderator.postReports.search(connection, {
      body: {
        page: 1,
        limit: 2,
      },
    });
    typia.assert(output);
    // Should have at most 2 per page
    TestValidator.predicate("<=2 results')(output.data.length <= 2);
    TestValidator.equals("current page is 1")(output.pagination.current)(1);
    TestValidator.equals("limit")(output.pagination.limit)(2);
    // Total records = 4, so total pages = 2
    TestValidator.equals("total records")(output.pagination.records)(4);
    TestValidator.equals("total pages")(output.pagination.pages)(2);
  }

  // Pagination tests: limit = 2, page = 2
  {
    const output = await api.functional.discussionBoard.moderator.postReports.search(connection, {
      body: {
        page: 2,
        limit: 2,
      },
    });
    typia.assert(output);
    TestValidator.predicate("<=2 results")(output.data.length <= 2);
    TestValidator.equals("current page is 2")(output.pagination.current)(2);
    TestValidator.equals("limit")(output.pagination.limit)(2);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
