import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate that unauthorized roles cannot access the discussion board admin list API.
 *
 * Business context:
 * The /discussionBoard/admin/admins (PATCH) endpoint returns the paginated list of admin accounts, intended for administrative audit, management, or compliance workflows. Only authenticated system administrators should be able to access this resource; regular members, moderators, and unauthenticated sessions must be strictly forbidden (receive an authorization error). All access attempts should be logged for audit purposes. This ensures robust role-based access control.
 *
 * Test steps:
 * 1. Register an admin account for positive control (to obtain a valid admin email to assign as the moderator creator).
 * 2. Register a member account (role: member).
 * 3. Register a moderator account (role: moderator, requires admin email for assignment).
 * 4. Attempt to access the admin list endpoint as a regular member (should be denied access).
 * 5. Attempt to access the admin list endpoint as a moderator (should be denied access).
 * 6. Attempt to access the admin list endpoint as a fully unauthenticated session (should be denied access).
 * 7. (Optional: Control test) Attempt to access the endpoint as admin (should succeed, for completeness).
 *
 * The test confirms robust enforcement of RBAC on a privileged API endpoint for admin enumeration, and helps ensure unauthorized access is never allowed, even for authenticated non-admin roles.
 */
export async function test_api_admin_search_unauthorized_access_forbidden(connection: api.IConnection) {
  // 1. Register an admin (for positive case and to assign moderators)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "A_strong_1234";
  const adminResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminResponse);

  // 2. Register a member user (member role)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Member_pass_4321";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 3. Register a moderator (moderator role)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Mod_pass_2024!";
  const moderatorResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorResponse);

  // 4. As member: try accessing admin list (should be forbidden)
  Object.assign(connection.headers, memberSession.setHeaders);
  await TestValidator.error("member forbidden from admin list")(
    async () => {
      await api.functional.discussionBoard.admin.admins.search(connection, {
        body: {},
      });
    },
  );

  // 5. As moderator: try accessing admin list (should be forbidden)
  Object.assign(connection.headers, moderatorResponse.setHeaders);
  await TestValidator.error("moderator forbidden from admin list")(
    async () => {
      await api.functional.discussionBoard.admin.admins.search(connection, {
        body: {},
      });
    },
  );

  // 6. As unauthenticated: clear auth headers and try (should be forbidden)
  for (const k of Object.keys(connection.headers || {})) delete connection.headers[k];
  await TestValidator.error("unauthenticated forbidden from admin list")(
    async () => {
      await api.functional.discussionBoard.admin.admins.search(connection, {
        body: {},
      });
    },
  );

  // 7. As admin: should succeed
  Object.assign(connection.headers, adminResponse.setHeaders);
  const result = await api.functional.discussionBoard.admin.admins.search(connection, {
    body: {},
  });
  typia.assert(result);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IPageIDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * E2E test for moderator comment vote search/filter/pagination in the discussion board.
 *
 * Validates that moderators can search and paginate comment votes using advanced filters:
 * - Filter by member ID (voter)
 * - Filter by target comment ID
 * - Filter by vote type (upvote/downvote)
 * - Filter by creation date range
 * - Combination of above filters
 * - Paginate through large result sets, verify total counts and navigation logic
 *
 * The test includes setup of multiple comment votes with different members, comments, and vote types. The test authenticates as a moderator, executes various search requests with different filter combinations, and validates:
 *   - Only the matching votes are returned
 *   - Pagination is correct and consistent with total record count
 *   - All returned votes respect the applied filters
 *   - Security prevents non-moderators from accessing the API
 *   - Error cases for invalid parameters (e.g. negative page, excessive limit)
 *   - Access control errors (unauthorized roles)
 *   - Each found record can be loaded in detail via the detail API
 */
export async function test_api_comment_vote_search_various_filters_pagination(
  connection: api.IConnection,
) {
  // ----------- Step 1: Authenticate as moderator -----------
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = "P@ssw0rd!";
  // Moderator account should already exist in test system.
  const moderatorSignIn = await api.functional.auth.moderator.login.signIn(
    connection,
    {
      body: {
        email: moderatorEmail,
        password: moderatorPassword,
      } satisfies IModerator.SignIn,
    },
  );
  typia.assert(moderatorSignIn);
  // SDK will update Authorization header in connection automatically.

  // ----------- Step 2: Data setup - Create comments, members and votes -----------
  // Simulate several unique comment/member IDs for votes. Assume all referenced comments/members exist in test DB.
  const commentIds = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const memberIds = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  // Prepare a matrix: for each (member, comment), create one upvote and one downvote
  const voteRecords: IDiscussionBoardCommentVote[] = [];
  for (const memberId of memberIds) {
    for (const commentId of commentIds) {
      for (const is_upvote of [true, false]) {
        const vote = await api.functional.discussionBoard.member.commentVotes.create(
          connection,
          {
            body: {
              discussion_board_comment_id: commentId,
              is_upvote,
            } satisfies IDiscussionBoardCommentVote.ICreate,
          },
        );
        typia.assert(vote);
        voteRecords.push(vote);
      }
    }
  }

  // ----------- Step 3: Filtering & pagination tests -----------
  // 3a. Search by member ID
  for (const memberId of memberIds) {
    const result = await api.functional.discussionBoard.moderator.commentVotes.search(
      connection,
      {
        body: {
          discussion_board_member_id: memberId,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      },
    );
    typia.assert(result);
    for (const v of result.data) TestValidator.equals("member id matches")(v.discussion_board_member_id)(memberId);
  }
  // 3b. Search by comment ID
  for (const commentId of commentIds) {
    const result = await api.functional.discussionBoard.moderator.commentVotes.search(
      connection,
      {
        body: {
          discussion_board_comment_id: commentId,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      },
    );
    typia.assert(result);
    for (const v of result.data) TestValidator.equals("comment id matches")(v.discussion_board_comment_id)(commentId);
  }
  // 3c. Search by vote type (upvote/downvote)
  for (const is_upvote of [true, false]) {
    const result = await api.functional.discussionBoard.moderator.commentVotes.search(
      connection,
      {
        body: {
          is_upvote,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      },
    );
    typia.assert(result);
    for (const v of result.data) TestValidator.equals("is_upvote matches")(v.is_upvote)(is_upvote);
  }
  // 3d. Search by date range (using a window covering all votes, then narrow)
  const minDate = voteRecords.reduce((min, v) => min < v.created_at ? min : v.created_at, voteRecords[0].created_at);
  const maxDate = voteRecords.reduce((max, v) => max > v.created_at ? max : v.created_at, voteRecords[0].created_at);
  // (i) All votes in the full range
  const allVotes = await api.functional.discussionBoard.moderator.commentVotes.search(
    connection,
    {
      body: {
        created_after: minDate,
        created_before: maxDate,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    },
  );
  typia.assert(allVotes);
  for (const v of allVotes.data) {
    TestValidator.predicate("Within range")(
      v.created_at >= minDate && v.created_at <= maxDate,
    );
  }

  // (ii) Expect zero for future-only range
  const futureDate = new Date(Date.now() + 10 * 365 * 24 * 60 * 60 * 1000).toISOString();
  const futureSearch = await api.functional.discussionBoard.moderator.commentVotes.search(
    connection,
    {
      body: {
        created_after: futureDate,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    },
  );
  typia.assert(futureSearch);
  TestValidator.equals("future search empty")(futureSearch.data.length)(0);

  // 3e. Pagination: limit/page
  const pageTest = await api.functional.discussionBoard.moderator.commentVotes.search(
    connection,
    {
      body: {
        limit: 2,
        page: 1,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    },
  );
  typia.assert(pageTest);
  TestValidator.equals("page one limited")(pageTest.data.length <= 2)(true);
  const total = pageTest.pagination.records;

  if (total > 2) {
    const page2 = await api.functional.discussionBoard.moderator.commentVotes.search(
      connection,
      {
        body: {
          limit: 2,
          page: 2,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      },
    );
    typia.assert(page2);
    TestValidator.equals("page two limited")(page2.data.length <= 2)(true);
    // No overlapping records between first and second page
    const page1Ids = pageTest.data.map((v) => v.id);
    const page2Ids = page2.data.map((v) => v.id);
    for (const id of page1Ids) TestValidator.notEquals("not in second page")(page2Ids.includes(id))(true);
  }

  // 3f. Combined filter (member + comment + is_upvote)
  const combined = await api.functional.discussionBoard.moderator.commentVotes.search(
    connection,
    {
      body: {
        discussion_board_member_id: memberIds[0],
        discussion_board_comment_id: commentIds[0],
        is_upvote: true,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    },
  );
  typia.assert(combined);
  for (const v of combined.data) {
    TestValidator.equals("combined member")(v.discussion_board_member_id)(memberIds[0]);
    TestValidator.equals("combined comment")(v.discussion_board_comment_id)(commentIds[0]);
    TestValidator.equals("combined is_upvote")(v.is_upvote)(true);
  }

  // ----------- Step 4: Result detail lookups -----------
  for (const v of voteRecords) {
    const detail = await api.functional.discussionBoard.moderator.commentVotes.at(
      connection,
      {
        commentVoteId: v.id,
      },
    );
    typia.assert(detail);
    TestValidator.equals("detail matches")(detail)(v);
  }

  // ----------- Step 5: Error scenarios -----------
  // 5a. Invalid page (zero, negative)
  for (const badPage of [0, -1]) {
    await TestValidator.error("page must be >=1")(() =>
      api.functional.discussionBoard.moderator.commentVotes.search(connection, {
        body: {
          page: badPage,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      }),
    );
  }
  // 5b. Excessive limit (>100)
  await TestValidator.error("limit must be <= 100")(() =>
    api.functional.discussionBoard.moderator.commentVotes.search(connection, {
      body: {
        limit: 101,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    }),
  );

  // 5c. Unauthorized use (simulate non-moderator)
  // Simulate by removing the auth token (connection.headers.Authorization = undefined)
  const nonAuthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized for non-moderator")(() =>
    api.functional.discussionBoard.moderator.commentVotes.search(nonAuthConnection, {
      body: {},
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";
import type { IGuestAuthGuestSignOutResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignOutResponse";

/**
 * Validates successful logout of a guest session, ensuring JWT session termination and subsequent token invalidation.
 *
 * This test covers the full logout lifecycle for a guest:
 * 1. Issue a guest JWT token by authenticating as a guest using device metadata (user agent, IP).
 * 2. Perform logout for the guest using the active session token.
 * 3. Confirm a positive response is returned, indicating session invalidation.
 * 4. Attempt to use the (now invalid) guest JWT token for another guest API, and expect failure (error thrown).
 *
 * This ensures guests cannot access resources after logout and verifies compliance with session invalidation policy.
 */
export async function test_api_guest_logout_success_session_end(connection: api.IConnection) {
  // 1. Issue a guest JWT token by logging in as a guest (with metadata).
  const signInBody: IGuestAuthGuestSignInRequest = {
    user_agent: RandomGenerator.alphabets(12),
    ip_address: `192.168.${typia.random<number & tags.Type<"uint8">>()}.${typia.random<number & tags.Type<"uint8">>()}`,
  };
  const loginResponse = await api.functional.auth.guest.login.signIn(connection, { body: signInBody });
  typia.assert(loginResponse);
  TestValidator.predicate("JWT token issued and present")(typeof loginResponse.token === "string" && loginResponse.token.length > 0);
  TestValidator.equals("Authorization header matches JWT token")(
    loginResponse.setHeaders.Authorization.replace(/^Bearer\s+/i, "")
  )(loginResponse.token);

  // 2. Set the guest JWT Token in connection header for logout and subsequent access
  connection.headers = { ...connection.headers, Authorization: `Bearer ${loginResponse.token}` };

  // 3. Perform logout (signOut) – this should invalidate session
  const logoutResponse = await api.functional.auth.guest.logout.signOut(connection);
  typia.assert(logoutResponse);

  // 4. Attempt to use the logged-out token for another guest API, expecting failure (401/invalid token)
  await TestValidator.error("Using guest API after logout should fail")(
    async () => {
      // Attempt to call signOut *again* using the logged-out JWT
      await api.functional.auth.guest.logout.signOut(connection);
    },
  );
}

