import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate error handling when deleting a non-existent or already-soft-deleted notification.
 *
 * This test ensures that the API returns a 'not found' error when admin attempts to soft-delete
 * a notification ID that does not exist or has been previously deleted. The test also confirms
 * correct role authentication and highlights that audit logging is expected as part of the backend's
 * operational responsibility (though not directly asserted here due to API limitations).
 *
 * Step-by-step process:
 * 1. Register a new admin account for authentication/authorization.
 * 2. Authenticate as the new admin (using the setHeaders/Authorization returned by the API).
 * 3. Attempt to soft-delete a notification using a random UUID extremely unlikely to exist.
 * 4. Expect an error to be thrown, validating proper error handling for invalid/soft-deleted notification IDs.
 *    The business rules mandate this be audit-logged, but direct verification of logs is not part of this E2E test.
 */
export async function test_api_notification_soft_delete_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new admin account (authentication prerequisite)
  const adminCreateInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
  } satisfies IDiscussionBoardAdmin.ICreate;
  const adminResponse = await api.functional.auth.admin.register.signUp(connection, { body: adminCreateInput });
  typia.assert(adminResponse);

  // 2. Authenticate as the admin by setting Authorization header
  if (adminResponse.setHeaders && adminResponse.setHeaders.Authorization) {
    connection.headers.Authorization = adminResponse.setHeaders.Authorization;
  }

  // 3. Attempt to soft-delete a non-existent notification ID
  const nonExistentNotificationId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("deleting non-existent or already-soft-deleted notification should fail")(
    async () => {
      await api.functional.discussionBoard.admin.notifications.erase(
        connection,
        { notificationId: nonExistentNotificationId }
      );
    },
  );
  // Note: Audit logging is the system's responsibility and is not directly verified in this test.
}

