import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate successful member login with correct credentials.
 *
 * This test ensures that a member who has just registered can authenticate using their email and password, and that the login endpoint returns a proper session containing a JWT token and session profile. The test follows a realistic user journey:
 *
 * 1. Register a new member (required so valid credentials exist for login).
 * 2. Log in using the same email and password used at registration.
 * 3. Validate the login response contains a JWT token, proper Authorization header, and a profile matching the recently registered user.
 *
 * This test confirms both the registration and authentication flows work in sequence, and checks that all major fields (token, setHeaders.Authorization, session profile) return valid types and expected values.
 */
export async function test_api_member_login_success(connection: api.IConnection) {
  // 1. Register new member
  const registrationInput: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPassword1!",
    nickname: RandomGenerator.name(),
    avatar_uri: null,
  };
  const registration: IDiscussionBoardMember.ISession = await api.functional.auth.member.register.post.signUp(connection, {
    body: registrationInput,
  });
  typia.assert(registration);

  // 2. Login with the same email and password
  const login: IDiscussionBoardMember.ISession = await api.functional.auth.member.login.post.signIn(connection, {
    body: {
      email: registrationInput.email,
      password: registrationInput.password,
    },
  });
  typia.assert(login);

  // 3. Validate session token, headers, and session profile
  TestValidator.predicate("session token is non-empty string")(typeof login.token === "string" && login.token.length > 0);
  TestValidator.predicate("setHeaders.Authorization is non-empty string")(typeof login.setHeaders?.Authorization === "string" && login.setHeaders.Authorization.length > 0);

  // The profile fields should match the registered user (except for fields not set at creation like id, joined_at)
  TestValidator.equals("email matches")(login.member.email)(registrationInput.email);
  TestValidator.equals("nickname matches")(login.member.nickname)(registrationInput.nickname);

  // avatar_uri may be omitted/null
  if (typeof registrationInput.avatar_uri === "string")
    TestValidator.equals("avatar_uri matches")(login.member.avatar_uri)(registrationInput.avatar_uri);
}

