import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that unauthorized users and members with insufficient privileges cannot erase post reports via the moderator endpoint.
 *
 * Business context:
 * Only users with moderator or admin roles are permitted to invoke DELETE on /discussionBoard/moderator/postReports/{postReportId}. Regular members, guests (unauthenticated users), or non-moderators must be forbidden from performing this operation. This protects audit integrity and prevents unauthorized tampering with abuse/violation reports.
 *
 * Test steps:
 * 1. Register a regular member (for use in the member test case).
 * 2. Choose a (likely random) postReportId for negative testing (since we have no creation API or knowledge of actual reports; our goal is forbidden, not notfound).
 * 3. As a logged-in member (using the acquired token), attempt to DELETE this post report by id. Verify that a forbidden error is thrown and the operation is not allowed.
 * 4. Log out (anonymous/guest session; remove authorization from connection headers).
 * 5. As an unauthenticated user, attempt the DELETE operation again. Confirm forbidden/unauthorized error occurs.
 * 6. (Edge) Optionally attempt the call with completely empty headers to mimic a guest/no-session scenario. Confirm forbidden/unauthorized is enforced.
 *
 * We expect all attempts from unauthorized or regular-member sessions to be rejected with forbidden errors. Implementation does not check effect on audit data, as no creation/examination APIs are exposed, but verifies that the endpoint enforces strict authorization on access.
 */
export async function test_api_post_report_moderator_erase_unauthorized(connection: api.IConnection) {
  // 1. Register a regular member for the unauthorized test role
  const memberInput: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "test1234!",
    nickname: RandomGenerator.name(),
  };
  const memberSession = await api.functional.auth.member.register.signUp(connection, { body: memberInput });
  typia.assert(memberSession);

  // Helper for repeated negative test attempts
  async function tryEraseWithConn(conn: api.IConnection, tag: string) {
    const randomReportId = typia.random<string & tags.Format<"uuid">>();
    await TestValidator.error(`${tag} cannot erase post report`)(async () => {
      await api.functional.discussionBoard.moderator.postReports.erase(conn, { postReportId: randomReportId });
    });
  }

  // 2. As member: try erase (should be forbidden)
  const memberConn: api.IConnection = { ...connection, headers: { ...connection.headers, ...memberSession.setHeaders } };
  await tryEraseWithConn(memberConn, "Member");

  // 3. As guest/unauthenticated: remove Authorization
  const guestConn: api.IConnection = { ...connection, headers: { ...connection.headers } };
  delete guestConn.headers["Authorization"];
  await tryEraseWithConn(guestConn, "Guest");

  // 4. As minimal/anonymous session: clear all custom headers
  await tryEraseWithConn({ ...connection, headers: {} }, "Anonymous");
}

