import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReport";
import type { IPageIDiscussionBoardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validates that non-admin users (members and guests) are forbidden from accessing the comment report admin search endpoint.
 *
 * Scenario:
 * - Register a discussion board member to act as a normal user.
 * - Attempt to use the admin comment report search as this member (should be forbidden).
 * - Attempt the same admin search as a guest (i.e., with no authentication).
 * - Assert that both attempts result in an error, and no sensitive data is leaked (forbidden access enforced).
 *
 * Steps:
 * 1. Register a discussion board member
 * 2. Attempt admin comment report search as member (expect forbidden error)
 * 3. Attempt admin comment report search as guest (expect forbidden error)
 */
export async function test_api_comment_report_admin_search_no_permission(
  connection: api.IConnection,
) {
  // 1. Register a normal member for negative case
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "AutoBE!Test1234";
  const nickname = RandomGenerator.name();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname,
    },
  });
  typia.assert(session);

  // 2. Attempt admin comment report search as registered member
  let memberError: unknown = null;
  try {
    await api.functional.discussionBoard.admin.commentReports.search(connection, {
      body: {
        page: 1,
        limit: 10,
      },
    });
  } catch (err) {
    memberError = err;
  }
  TestValidator.predicate("forbidden error for member user")(!!memberError);

  // 3. Attempt admin comment report search as guest (no authentication)
  // Remove the Authorization header to simulate a guest/no-login request
  const guestConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete guestConnection.headers.Authorization;
  let guestError: unknown = null;
  try {
    await api.functional.discussionBoard.admin.commentReports.search(guestConnection, {
      body: {
        page: 1,
        limit: 10,
      },
    });
  } catch (err) {
    guestError = err;
  }
  TestValidator.predicate("forbidden error for guest user")(!!guestError);
}

