import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that normal members and guests are forbidden from accessing admin-only category detail endpoint.
 *
 * This test ensures the API enforces proper access restrictions by denying detail access requests to /discussionBoard/admin/categories/{categoryId}
 * for both ordinary members (non-admin/moderator) and unauthenticated guests. Proper forbidden errors should be returned, and no sensitive data exposed.
 *
 * Steps:
 * 1. As an admin (by default, assumed API connection is privileged), create a category to have a testable categoryId.
 * 2. Register and authenticate as a normal member (non-admin), and switch the connection context accordingly.
 * 3. Attempt to access the category detail endpoint as this normal member. Expect a forbidden error.
 * 4. Logout or remove member authentication from connection to simulate guest access.
 * 5. Attempt again to access category detail endpoint as guest (unauthenticated). Expect a forbidden error.
 *
 * Validation:
 * - API should reject access for non-admin/non-moderator users
 * - API should reject access for guests (no authentication)
 * - Forbidden error (HTTP 403) should be thrown for both cases
 */
export async function test_api_category_detail_view_permission_denied_member_or_guest(
  connection: api.IConnection,
) {
  // 1. Create a category as admin
  const createdCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      display_order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
      version: 1,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(createdCategory);

  // 2. Register (and login as) a normal member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: "Test1234!",
      nickname: RandomGenerator.alphabets(8),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);
  // Set Authorization token for connection
  connection.headers.Authorization = memberSession.setHeaders.Authorization;

  // 3. Attempt unauthorized access to category detail as non-admin member
  await TestValidator.error("non-admin member forbidden to access category detail")(async () => {
    await api.functional.discussionBoard.admin.categories.at(connection, {
      categoryId: createdCategory.id,
    });
  });

  // 4. Remove token to simulate guest
  delete connection.headers.Authorization;

  // 5. Attempt unauthorized access to category detail as guest
  await TestValidator.error("guest forbidden to access category detail")(async () => {
    await api.functional.discussionBoard.admin.categories.at(connection, {
      categoryId: createdCategory.id,
    });
  });
}

