import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdIntegrationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdIntegrationLog";
import type { IPageIDiscussionBoardAdIntegrationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdIntegrationLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test error handling for advanced search on ad integration logs with invalid or malformed filter criteria.
 *
 * Business context:
 * The admin ad integration log analytics endpoint allows sophisticated filtering over ad integration logs. Validation should reject unsupported fields or incorrect data types, returning a clear and safe error without backend disruption. This ensures the analytics system is robust and does not allow unvalidated queries to propagate to the database or internal business logic.
 *
 * Steps:
 * 1. Construct a deliberately invalid filter request with unsupported fields and wrong types for allowed fields.
 * 2. Send this request via the PATCH /discussionBoard/admin/adIntegrationLogs API.
 * 3. Validate that the system rejects the request with an error, confirming that validation is enforced at the API boundary.
 *
 * The test succeeds if the invalid request triggers a validation error (not a backend exception).
 */
export async function test_api_ad_integration_log_search_invalid_filter(
  connection: api.IConnection,
): Promise<void> {
  // 1. Compose an invalid filter request (extra key, wrong types)
  const invalidRequest = {
    ad_channel: 12345, // should be string | null
    event_type: false, // should be string | null
    unsupported_field: "not allowed", // not defined in schema
    page: "not-a-number", // should be number | null
  };

  // 2. Make the PATCH request expecting validation error
  await TestValidator.error("invalid filter request is rejected")(
    async () => {
      await api.functional.discussionBoard.admin.adIntegrationLogs.search(
        connection,
        { body: invalidRequest },
      );
    },
  );
}

