import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validate updating the metadata of a discussion board guest session record as an admin.
 *
 * This test performs the following steps:
 * 1. Create a guest session via login to obtain a valid guestId for update.
 * 2. As an admin, update the guest record's metadata (such as ip_address and user_agent).
 * 3. Verify that only allowed fields are updated and audit fields (like updated_at) reflect the update.
 * 4. Confirm that the returned record accurately reflects the new values and has an updated timestamp.
 *
 * Steps:
 * 1. Issue a guest login via POST /auth/guest/login with random user_agent and ip_address; obtain a guestId representing the guest session created.
 * 2. As ADMIN (assuming connection is already admin-authed), update the guest record via PUT /discussionBoard/admin/guests/{guestId}, changing ip_address and user_agent fields; verify response.
 * 3. Assert output reflects the new ip_address/user_agent, audit field (updated_at) is later than created_at, and other fields remain immutable.
 */
export async function test_api_guest_update_metadata_success(connection: api.IConnection) {
  // 1. Create a guest session
  const signInInput = {
    user_agent: RandomGenerator.alphaNumeric(16),
    ip_address: [0, 0, 0, 0].map(() =>
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<1> & tags.Maximum<255>>()
    ).join("."),
  } satisfies IGuestAuthGuestSignInRequest;
  const signInResp = await api.functional.auth.guest.login.signIn(connection, { body: signInInput });
  typia.assert(signInResp);

  // In a real system, we'd map session_token or returned header info to the persisted guestId.
  // For this E2E test, we assume we can obtain guestId in a real integrated environment (stub here).
  const guestId = signInResp.token; // Stub: Mapping from issued token/session to guestId record.

  // 2. Prepare update input (change metadata fields)
  const updateInput = {
    ip_address: [0, 0, 0, 0].map(() =>
      typia.random<number & tags.Type<"uint8"> & tags.Minimum<1> & tags.Maximum<255>>()
    ).join("."),
    user_agent: RandomGenerator.alphaNumeric(20),
  } satisfies IDiscussionBoardGuest.IUpdate;

  // 3. Update the guest record as an admin
  const updated = await api.functional.discussionBoard.admin.guests.update(connection, {
    guestId,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. Validate metadata fields updated and audit timestamp advanced
  TestValidator.equals("ip_address updated")(updated.ip_address)(updateInput.ip_address);
  TestValidator.equals("user_agent updated")(updated.user_agent)(updateInput.user_agent);
  TestValidator.predicate("updated_at advanced")(new Date(updated.updated_at).getTime() >= new Date(updated.created_at).getTime());
}

