import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Test anonymous search and filtering of discussion board posts.
 *
 * This E2E test validates that an anonymous (not logged-in) user can search for discussion board posts
 * with various filtering parameters and pagination. The test ensures that status filtering, category
 * filtering, and keyword searching operate as expected and that only posts with "active" status or otherwise
 * visible to the public are included. No hidden or deleted posts should be returned to anonymous searches.
 *
 * 1. Create at least one visible post (status: 'active') using the member-post creation API.
 * 2. Search as an anonymous user (i.e., not passing any auth context) by title substring and category filter.
 * 3. Assert all returned summaries have status "active", match keyword and category, and that pagination matches.
 * 4. Verify that posts not visible to guests (hidden/deleted) are not in the returned dataset (implicit, by only checking for 'active').
 */
export async function test_api_post_search_anonymous_success(connection: api.IConnection) {
  // 1. Create a post as a member with a predictable title keyword and custom category
  const titleKeyword = RandomGenerator.alphabets(10);
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: `TestPost_${titleKeyword}`,
      body: RandomGenerator.content()()(),
      category_id: categoryId,
      attachments: null,
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 2. Search (anonymous - no auth context) using title keyword and category filter; restrict to 'active'
  const searchResult = await api.functional.discussionBoard.posts.search(connection, {
    body: {
      title: titleKeyword,
      category_id: categoryId,
      status: "active",
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardPost.IRequest
  });
  typia.assert(searchResult);

  // 3. For each hit, check only "active" status, title includes keyword, and category matches
  for (const summary of searchResult.data) {
    TestValidator.equals("Status should be 'active'")(summary.status)("active");
    TestValidator.predicate("Title contains keyword")(
      summary.title.includes(titleKeyword)
    );
    TestValidator.equals("Category matches")(summary.category.id)(categoryId);
  }

  // 4. Pagination info check
  TestValidator.equals("Returned page1")(searchResult.pagination.current)(1);
  TestValidator.equals("Limit is 10")(searchResult.pagination.limit)(10);
}

