import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReport";

/**
 * Test successful retrieval of a specific comment report's full details by an admin.
 *
 * This test verifies that when an admin retrieves a comment report by its unique ID using the GET endpoint, all relevant fields are present and correct, report state statuses are as expected, and audit/comment/message fields are consistent with what was created. The process simulates the full business workflow: creating a post, adding a comment, reporting the comment, then admin-getting the report. This ensures the admin endpoint works with realistic preceding business activity/data, not just random UUIDs.
 *
 * Step-by-step process:
 * 1. Create a discussion board post as a member (simulate user context).
 * 2. Add a comment to this post (again as a member).
 * 3. Report the comment for abuse using a valid reason_type and optional text.
 * 4. As (implicitly) an admin, retrieve the comment report by its id.
 * 5. Verify that retrieved report's fields are correct, status is 'pending', that comment id matches the one reported, and reason data/audit fields are as expected. Confirm no unauthorized fields or unexpected workflow states are present.
 */
export async function test_api_comment_report_admin_at_success(connection: api.IConnection) {
  // 1. Create a new discussion board post as a member
  const postInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph(1)(),
    body: RandomGenerator.content(1)(),
  };
  const post = await api.functional.discussionBoard.member.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 2. Add a comment to the post
  const commentInput: IDiscussionBoardComment.ICreate = {
    body: RandomGenerator.content(1)(),
  };
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, { postId: post.id, body: commentInput });
  typia.assert(comment);
  TestValidator.equals("comment post id matches")(comment.post_id)(post.id);

  // 3. Report the comment for abuse
  const commentReportInput: IDiscussionBoardCommentReport.ICreate = {
    discussion_board_comment_id: comment.id,
    reason_type: "spam",
    reason_text: RandomGenerator.paragraph(1)(),
  };
  const commentReport = await api.functional.discussionBoard.member.commentReports.create(connection, { body: commentReportInput });
  typia.assert(commentReport);
  TestValidator.equals("reported comment id matches")(commentReport.discussion_board_comment_id)(comment.id);
  TestValidator.equals("report initial status is pending")(commentReport.status)("pending");

  // 4. Retrieve the report as an admin by its ID
  const fetchedReport = await api.functional.discussionBoard.admin.commentReports.at(connection, { commentReportId: commentReport.id });
  typia.assert(fetchedReport);

  // 5. Validate fetched report fields and status
  TestValidator.equals("fetch matches id")(fetchedReport.id)(commentReport.id);
  TestValidator.equals("fetch matches comment id")(fetchedReport.discussion_board_comment_id)(comment.id);
  TestValidator.equals("fetch matches reason type")(fetchedReport.reason_type)(commentReport.reason_type);
  TestValidator.equals("fetch matches status")(fetchedReport.status)(commentReport.status);
  TestValidator.predicate("created_at present")(
    typeof fetchedReport.created_at === "string" && fetchedReport.created_at.length > 0
  );
  TestValidator.predicate("updated_at present")(
    typeof fetchedReport.updated_at === "string" && fetchedReport.updated_at.length > 0
  );
}

