import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * Ensure that only members can search member-only discussion board posts, and access is denied to non-authenticated or improperly authenticated users.
 *
 * Business context:
 * This test confirms strict enforcement of role-based access control for member-specific content on the discussion board. Preventing anonymous or unauthorized users from viewing or searching member-only posts protects privacy and enforces community policy.
 *
 * Step-by-step process:
 * 1. Provision a sample post using the member post creation endpoint (authenticated context, dependency satisfied).
 * 2. Attempt to search posts with a missing authentication token (simulate non-authenticated user).
 * 3. Verify that the API responds with an unauthorized/forbidden error.
 * 4. Attempt to search posts with an explicitly invalid (malformed or expired) token.
 * 5. Verify that a forbidden/unauthorized error is returned.
 */
export async function test_api_member_post_search_permission_enforcement(connection: api.IConnection) {
  // 1. Provision a sample post as a dependency
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1).substring(0, 100),
      body: RandomGenerator.content()(1)().substring(0, 4000),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 2. Attempt to search posts with no authentication (simulate a non-authenticated user)
  const unauthenticatedConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("search forbidden for unauthenticated user")(async () => {
    await api.functional.discussionBoard.member.posts.search(unauthenticatedConnection, {
      body: {},
    });
  });

  // 3. Attempt to search posts with an invalid/expired token
  const invalidAuthConnection = { ...connection, headers: { ...connection.headers, Authorization: "Bearer INVALID.TOKEN" } };
  await TestValidator.error("search forbidden for invalid token")(async () => {
    await api.functional.discussionBoard.member.posts.search(invalidAuthConnection, {
      body: {},
    });
  });
}

