import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test successful deletion of a comment vote by its owner (member).
 *
 * This E2E test validates the ability of a discussion board member to remove their own upvote/downvote from a comment. The workflow ensures all prerequisites and dependencies are handled using only real API functions:
 *
 * 1. Register as a new member, storing authentication context.
 * 2. As the member, create a discussion post (basic required fields only).
 * 3. As the member, comment on the post.
 * 4. As the member, add an upvote to the comment.
 * 5. As the member, delete their own vote using the vote's ID.
 * 6. Attempting to delete again throws an error, confirming proper vote deletion mechanics.
 */
export async function test_api_comment_vote_delete_by_owner_success(connection: api.IConnection) {
  // 1. Register a new discussion board member
  const email = typia.random<string & tags.Format<"email">>();
  const password = "Password123!";
  const nickname = RandomGenerator.name();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname,
      avatar_uri: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(session);

  // 2. Create a discussion post (as the member)
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1).slice(0, 100),
      body: RandomGenerator.content()(1, 3).slice(0, 4000),
      category_id: null,
      platform_config_id: null,
      attachments: null,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Add a comment to the post
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(1).slice(0, 1000),
      thread_parent_comment_id: null,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Add a vote (upvote) to the comment
  const vote = await api.functional.discussionBoard.member.commentVotes.create(connection, {
    body: {
      discussion_board_comment_id: comment.id,
      is_upvote: true,
    } satisfies IDiscussionBoardCommentVote.ICreate,
  });
  typia.assert(vote);

  // 5. Delete the vote as the owner
  await api.functional.discussionBoard.member.commentVotes.erase(connection, {
    commentVoteId: vote.id,
  });

  // 6. Attempting to delete again confirms vote is gone (must throw error)
  await TestValidator.error("Deleting already deleted vote throws error")(
    async () => {
      await api.functional.discussionBoard.member.commentVotes.erase(connection, {
        commentVoteId: vote.id,
      });
    },
  );
}

