import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPlatformConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPlatformConfig";
import type { IPageIDiscussionBoardPlatformConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPlatformConfig";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate that a non-admin (regular member) and unauthenticated session are forbidden from searching admin platform configs.
 *
 * Business context:
 * Only admin or moderator users may access the platform configuration search API for the discussion board. Regular members and guest users must be denied, enforcing system security and robust auditing of permission boundaries.
 *
 * 1. Register a regular member account with unique credentials to create a non-admin session.
 * 2. Attempt to invoke the admin-only discussion board platformConfigs.search API with the new member session.
 * 3. Confirm the call is denied (HTTP 401/403 error), validating enforcement of access control.
 * 4. Attempt the config search again using a guest (no Authorization) session, and confirm similar denial.
 * 5. (Optional) Note: Audit trail for denied attempts cannot be asserted directly without a log retrieval API.
 */
export async function test_api_platform_config_search_admin_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register a regular member for non-admin session
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: "test-api-password-123!",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 2. Attempt admin config search as regular member (should be forbidden)
  await TestValidator.error("non-admin access forbidden")(
    async () => {
      await api.functional.discussionBoard.admin.platformConfigs.search(connection, {
        body: {} satisfies IDiscussionBoardPlatformConfig.IRequest,
      });
    }
  );

  // 3. Attempt admin config search as guest/unauthenticated
  const guestConnection: api.IConnection = {
