import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";
import type { IVoidSuccess } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidSuccess";

/**
 * Validate that administrator password change is not allowed without authentication.
 *
 * This test checks that the admin password update endpoint enforces authentication—preventing unauthenticated calls regardless of request body validity. It ensures that a missing, expired, or invalid JWT prevents password change for discussion board administrators. This is important to confirm security and access controls are correctly applied.
 *
 * 1. Register a new admin account to define valid credentials (no token will be used during password change).
 * 2. Attempt to call the password change API WITHOUT any Authorization header (simulating a missing/unauthenticated context).
 * 3. Verify that the system rejects the request with an unauthorized error and does not process the change.
 */
export async function test_api_admin_password_change_unauthenticated_access(
  connection: api.IConnection,
) {
  // 1. Register a new admin account to have a valid admin in the system (do not use result for authentication)
  const adminInfo = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestAuth123!"
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(adminInfo);

  // 2. Clear any Authorization from headers to simulate unauthenticated state
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
    },
  };

  // 3. Attempt to change password WITHOUT authentication, expect an error
  await TestValidator.error("Password change without authentication should fail")(
    async () => {
      await api.functional.auth.admin.password.changePassword(unauthConnection, {
        body: {
          oldPassword: "TestAuth123!",
          newPassword: "NewUnAuthPass12$"
        } satisfies IDiscussionBoardAdmin.IChangePassword
      });
    }
  );
}

