import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate that an admin can update any comment, overriding normal author/edit window restrictions.
 *
 * This test ensures that using the admin comment update endpoint works as intended, regardless of who originally authored the comment or edit policy windows. Since only admin SDK endpoints are currently available, all create/update steps are performed in admin context. Fields and structure strictly follow the available DTO definitions and business descriptions.
 *
 * Steps:
 * 1. Register and authenticate as an admin user.
 * 2. Create a discussion post as admin.
 * 3. Add a comment to the post as admin.
 * 4. Update the comment as admin, modifying body and status fields.
 * 5. Validate that comment content, status, and audit trail fields are updated as expected (including updated_at predicated on update operation).
 */
export async function test_api_comment_update_by_admin_success(connection: api.IConnection) {
  // 1. Register and authenticate as an admin user.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // 2. Create a discussion post as admin.
  const post = await api.functional.discussionBoard.admin.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1).slice(0, 100),
      body: RandomGenerator.content()(3).slice(0, 4000),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Add a comment to the post as admin.
  const originalCommentBody = RandomGenerator.paragraph()(1).slice(0, 1000);
  const comment = await api.functional.discussionBoard.admin.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: originalCommentBody,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Update the comment as admin, changing body and status.
  const updatedCommentBody = RandomGenerator.paragraph()(1).slice(0, 1000);
  const newStatus = "hidden";
  const updatedComment = await api.functional.discussionBoard.admin.posts.comments.update(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      body: updatedCommentBody,
      status: newStatus,
    } satisfies IDiscussionBoardComment.IUpdate,
  });
  typia.assert(updatedComment);

  // 5. Validate that content, status, and audit trail are updated correctly.
  TestValidator.equals("id unchanged")(updatedComment.id)(comment.id);
  TestValidator.equals("post_id unchanged")(updatedComment.post_id)(post.id);
  TestValidator.equals("body updated")(updatedComment.body)(updatedCommentBody);
  TestValidator.equals("status updated")(updatedComment.status)(newStatus);
  TestValidator.predicate("updated_at increases")(new Date(updatedComment.updated_at) > new Date(comment.updated_at));
  TestValidator.equals("author_admin_id unchanged")(updatedComment.author_admin_id)(comment.author_admin_id);
}

