import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardExternalAuthLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardExternalAuthLog";

/**
 * Validate creation and error handling for external authentication log entries as admin.
 *
 * This test covers the creation of an external authentication log for the discussion board platform through the admin endpoint. The workflow includes:
 *
 * 1. Successful creation: Submits all required and optional fields to create a new authentication event log. Checks event completeness, mapping to a user, referential integrity, presence/absence of audit and error fields, and expected audit output.
 * 2. Field coverage: Ensures all core, optional, nullable fields are exercised with valid data.
 * 3. Missing fields error: Attempts creation with mandatory fields omitted, checks API returns error.
 * 4. Invalid format error: Attempts creation with invalid-formatted values (e.g., malformed email or date-time).
 * 5. Permission error: Attempts creation from a (simulated) non-admin context, expects rejection.
 */
export async function test_api_external_auth_log_creation_unique_and_validation(
  connection: api.IConnection,
) {
  // 1. Successful creation with all fields set
  const inputComplete: IDiscussionBoardExternalAuthLog.ICreate = {
    discussion_board_member_id: typia.random<string & tags.Format<"uuid">>(),
    auth_channel: "google",
    external_user_id: typia.random<string & tags.Format<"uuid">>(),
    subject_email: typia.random<string & tags.Format<"email">>(),
    issued_at: new Date().toISOString(),
    completed_at: new Date(Date.now() + 10_000).toISOString(),
    success: true,
    error_code: null,
    error_message: null,
  };
  const created = await api.functional.discussionBoard.admin.externalAuthLogs.create(connection, { body: inputComplete });
  typia.assert(created);
  // Check result structure
  TestValidator.equals("subject_email matches")(created.subject_email)(inputComplete.subject_email);
  TestValidator.equals("success flag matches")(created.success)(inputComplete.success);
  TestValidator.equals("channel matches")(created.auth_channel)(inputComplete.auth_channel);

  // 2. Creation with minimal required fields only (omit optionals/nullables)
  const inputMinimal: IDiscussionBoardExternalAuthLog.ICreate = {
    auth_channel: "kakao",
    subject_email: typia.random<string & tags.Format<"email">>(),
    issued_at: new Date().toISOString(),
    success: false,
  };
  const createdMinimal = await api.functional.discussionBoard.admin.externalAuthLogs.create(connection, { body: inputMinimal });
  typia.assert(createdMinimal);
  TestValidator.equals("required email")(createdMinimal.subject_email)(inputMinimal.subject_email);
  TestValidator.equals("required channel")(createdMinimal.auth_channel)(inputMinimal.auth_channel);
  TestValidator.equals("success flag minimal")(createdMinimal.success)(inputMinimal.success);

  // 3. Error: Missing required field (e.g. omit subject_email)
  const missingField = {
    auth_channel: "naver",
    issued_at: new Date().toISOString(),
    success: true,
  } as any; // purposely broken type (TypeScript will error but runtime test is business logic)
  await TestValidator.error("should fail missing subject_email")(() =>
    api.functional.discussionBoard.admin.externalAuthLogs.create(connection, { body: missingField })
  );

  // 4. Error: Invalid format (malformed email)
  const invalidFormat: IDiscussionBoardExternalAuthLog.ICreate = {
    auth_channel: "email",
    subject_email: "not-an-email-format",
    issued_at: new Date().toISOString(),
    success: true,
  };
  await TestValidator.error("should fail invalid email format")(() =>
    api.functional.discussionBoard.admin.externalAuthLogs.create(connection, { body: invalidFormat })
  );

  // 5. Error: Non-admin context simulation (simulate context removal if possible)
  const noAdminConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("should reject non-admin access")(() =>
    api.functional.discussionBoard.admin.externalAuthLogs.create(noAdminConnection, { body: inputMinimal })
  );
}

