import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate system handling of duplicate post titles by the same admin in rapid succession.
 *
 * This test checks if the platform allows an admin to create two posts with the same title, or whether it enforces uniqueness and rejects the duplicate. The correct result depends on platform business rules: either (a) both posts are allowed and get unique IDs, or (b) the second creation throws an error (e.g., unique constraint violation or business logic rejection).
 *
 * Steps:
 * 1. Register a new admin and authenticate, enabling post creation.
 * 2. Compose a post creation payload with a random title and a consistent body.
 * 3. Create the first post; validate proper persistence and data.
 * 4. Attempt to create a second post immediately with the same title and body; check for:
 *    - Success (with different post IDs, title/body match): duplicates allowed.
 *    - Or error thrown: uniqueness enforced by platform policy (test passes).
 * 5. The test succeeds if one (and only one) of these platform-compliant behaviors occurs.
 */
export async function test_api_post_creation_admin_duplicate_title_handling(connection: api.IConnection) {
  // 1. Register a new admin via the proper workflow
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegisterResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    }
  });
  typia.assert(adminRegisterResp);
  // At this point, the admin's JWT is present in the connection headers

  // 2. Prepare a valid post creation payload
  const postTitle = RandomGenerator.alphabets(16);
  const postBody = RandomGenerator.paragraph()(RandomGenerator.number(2, 4));
  const postPayload = {
    title: postTitle,
    body: postBody,
  } satisfies IDiscussionBoardPost.ICreate;

  // 3. Create the first post
  const firstPost = await api.functional.discussionBoard.admin.posts.create(connection, {
    body: postPayload,
  });
  typia.assert(firstPost);
  TestValidator.equals("title matches")(firstPost.title)(postTitle);
  TestValidator.equals("body matches")(firstPost.body)(postBody);

  // 4. Attempt to create a duplicate post
  let duplicatePolicyValidated = false;
  // Try error assertion – if error, policy forbids duplicates
  await TestValidator.error("duplicate title policy: forbidden")(
    async () => {
      await api.functional.discussionBoard.admin.posts.create(connection, {
        body: postPayload,
      });
      duplicatePolicyValidated = true; // Will not be set unless no error
    }
  );
  // Only if above did not succeed (no error thrown, duplicates allowed), try positive assertion
  if (!duplicatePolicyValidated) {
    const secondPost = await api.functional.discussionBoard.admin.posts.create(connection, {
      body: postPayload,
    });
    typia.assert(secondPost);
    TestValidator.notEquals("IDs must differ for two posts")(secondPost.id)(firstPost.id);
    TestValidator.equals("title matches")(secondPost.title)(postTitle);
    TestValidator.equals("body matches")(secondPost.body)(postBody);
  }
}

