import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardEmailLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardEmailLog";
import type { IPageIDiscussionBoardEmailLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardEmailLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching and paginating outgoing email logs as an admin.
 *
 * This test confirms that an admin can use multiple filters (recipient, type, status, date range) to query outgoing email logs, with correct pagination, and verifies that soft-deleted records are excluded. It also covers handling of malformed input producing errors. Only actual API/DtOs/fields are used, following type safety and E2E conventions.
 *
 * Steps:
 * 1. Setup test data: Use dependency endpoint to create several email logs with varied recipient, type, status, and send time values.
 * 2. Perform search queries:
 *    - Filter by recipient_email (expect only that recipient)
 *    - Filter by email_type and delivery_status (expect logs matching both)
 *    - Filter by sent_at date range (expect logs in range)
 *    - Paginate results (validate limit/page and correct entries returned)
 * 3. Confirm soft-deleted records are never included
 * 4. Test error case: malformed filter input (invalid page number)
 */
export async function test_api_email_logs_search_pagination_and_filtering(connection: api.IConnection) {
  // 1. Setup test data: create sample email logs
  const recipientEmails = [
    typia.random<string & tags.Format<"email">>(),
    typia.random<string & tags.Format<"email">>()
  ];
  const types = ["verification", "notification", "password_reset"];
  const statuses = ["SENT", "DELIVERED", "FAILED"];
  const now = new Date();

  // Create several diverse logs
  const createdLogs = await Promise.all(
    ArrayUtil.repeat(10)(async (_, i) => {
      const email_type = RandomGenerator.pick(types);
      const delivery_status = RandomGenerator.pick(statuses);
      const sent_at = new Date(now.getTime() - i * 3600 * 1000).toISOString();
      const recipient_email = RandomGenerator.pick(recipientEmails);
      const subject = RandomGenerator.alphaNumeric(12);
      const log = await api.functional.discussionBoard.admin.emailLogs.create(connection, {
        body: {
          recipient_email,
          email_type,
          subject,
          sent_at,
          delivery_status,
        } satisfies IDiscussionBoardEmailLog.ICreate,
      });
      typia.assert(log);
      return log;
    })
  );

  // 2a. Search by recipient_email
  const testRecipient = recipientEmails[0];
  const resultByRecipient = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      recipient_email: testRecipient,
      page: 1,
      limit: 5,
    },
  });
  typia.assert(resultByRecipient);
  TestValidator.predicate("results match recipient")(
    resultByRecipient.data.every((item) => item.recipient_email === testRecipient)
  );

  // 2b. Search by both email_type and delivery_status
  const testType = types[0];
  const testStatus = statuses[0];
  const typeStatusResult = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      email_type: testType,
      delivery_status: testStatus,
    },
  });
  typia.assert(typeStatusResult);
  TestValidator.predicate("results match type and status")(
    typeStatusResult.data.every((item) => item.email_type === testType && item.delivery_status === testStatus)
  );

  // 2c. Search by sent_at date range (last 6 hours)
  const fromDate = new Date(now.getTime() - 6 * 3600 * 1000).toISOString();
  const toDate = now.toISOString();
  const dateRangeResult = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      from_date: fromDate,
      to_date: toDate,
    },
  });
  typia.assert(dateRangeResult);
  TestValidator.predicate("results within date range")(
    dateRangeResult.data.every((item) => item.sent_at >= fromDate && item.sent_at <= toDate)
  );

  // 2d. Pagination: page=1, limit=2, should return 0, 1, or 2 entries
  const paged = await api.functional.discussionBoard.admin.emailLogs.search(connection, {
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(paged);
  TestValidator.predicate("pagination respected")(paged.data.length <= 2);

  // 3. Confirm soft-deleted records excluded (deleted_at must be null/absent)
  TestValidator.predicate("no soft-deleted logs")(
    paged.data.every((item) => !('deleted_at' in item) || item.deleted_at === null)
  );

  // 4. Error case: malformed filter input (e.g. negative page)
  await TestValidator.error("invalid page rejects")(
    async () => {
      await api.functional.discussionBoard.admin.emailLogs.search(connection, {
        body: {
          page: -1,
        },
      });
    }
  );
}

