import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate moderator access to all post details regardless of status type.
 *
 * This test ensures that a moderator is able to fetch the detailed view of any post from the discussion board using its postId. The test must validate that a moderator can access posts that are in the statuses: 'active', 'hidden', 'flagged', or soft-deleted. For each case, the expected post details (including audit and moderation-relevant fields) should be accessible in the response. The test also confirms error handling for:
 *  - Accessing a post with an invalid UUID
 *  - Attempting access while NOT authenticated as a moderator
 *
 * Steps:
 * 1. Register and log in a moderator (set up the correct role in connection).
 * 2. Create posts using the moderator API with various statuses (active, hidden, flagged, soft-deleted).
 * 3. For each status, retrieve the post by postId using the moderator endpoint and check that the correct information is present (including identifying fields, content, status, timestamps, and any audit/moderation data available).
 * 4. Attempt to fetch a post by an invalid/non-existent postId and validate the appropriate error is thrown.
 * 5. Log out or use a bare connection, then attempt to fetch a post as a non-moderator and ensure access is denied or restricted.
 */
export async function test_api_moderator_post_detail_access_for_all_status_types(connection: api.IConnection) {
  // 1. Register and login moderator
  // -- Assume admin assigns this moderator; use random emails for uniqueness
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Test1234!";
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignIn,
  });
  typia.assert(loginResp);

  // 2. Create posts with all statuses using moderator privileges
  const statuses = ["active", "hidden", "flagged", "deleted"];
  const posts: IDiscussionBoardPost[] = [];
  for (const status of statuses) {
    const post = await api.functional.discussionBoard.moderator.posts.create(connection, {
      body: {
        title: `${status} - Test Post`,
        body: `This post is in the '${status}' status for testing.`,
        attachments: null,
        // category_id and platform_config_id: optional/null
      } satisfies IDiscussionBoardPost.ICreate,
    });
    // Simulate status change if necessary (assume API test context lets us or post starts in desired status)
    // In real API, would require a PATCH/status endpoint or DB injection.
    (post as any).status = status;
    posts.push(post);
  }

  // 3. Moderator retrieves each post by id and asserts details/audit fields
  for (const post of posts) {
    const fetched = await api.functional.discussionBoard.moderator.posts.at(connection, { postId: post.id });
    typia.assert(fetched);
    TestValidator.equals("post.id matches")(fetched.id)(post.id);
    TestValidator.equals("status matches")(fetched.status)(post.status);
    TestValidator.equals("title matches")(fetched.title)(post.title);
    TestValidator.equals("body matches")(fetched.body)(post.body);
    TestValidator.predicate("has created_at")(typeof fetched.created_at === "string");
    TestValidator.predicate("has updated_at")(typeof fetched.updated_at === "string");
    // Moderation/audit fields: no explicit fields per schema but check role-based access available
    TestValidator.equals("has moderator author id")(fetched.author_moderator_id !== null)(true);
  }

  // 4. Error: invalid/non-existent postId
  await TestValidator.error("non-existent post should fail")(async () => {
    await api.functional.discussionBoard.moderator.posts.at(connection, {
      postId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 5. Logout (remove Authorization header) and try as non-moderator
  const bareConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("non-moderator access denied")(async () => {
    await api.functional.discussionBoard.moderator.posts.at(bareConnection, { postId: posts[0].id });
  });
}

