import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate that unauthorized roles cannot access the discussion board admin list API.
 *
 * Business context:
 * The /discussionBoard/admin/admins (PATCH) endpoint returns the paginated list of admin accounts, intended for administrative audit, management, or compliance workflows. Only authenticated system administrators should be able to access this resource; regular members, moderators, and unauthenticated sessions must be strictly forbidden (receive an authorization error). All access attempts should be logged for audit purposes. This ensures robust role-based access control.
 *
 * Test steps:
 * 1. Register an admin account for positive control (to obtain a valid admin email to assign as the moderator creator).
 * 2. Register a member account (role: member).
 * 3. Register a moderator account (role: moderator, requires admin email for assignment).
 * 4. Attempt to access the admin list endpoint as a regular member (should be denied access).
 * 5. Attempt to access the admin list endpoint as a moderator (should be denied access).
 * 6. Attempt to access the admin list endpoint as a fully unauthenticated session (should be denied access).
 * 7. (Optional: Control test) Attempt to access the endpoint as admin (should succeed, for completeness).
 *
 * The test confirms robust enforcement of RBAC on a privileged API endpoint for admin enumeration, and helps ensure unauthorized access is never allowed, even for authenticated non-admin roles.
 */
export async function test_api_admin_search_unauthorized_access_forbidden(connection: api.IConnection) {
  // 1. Register an admin (for positive case and to assign moderators)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "A_strong_1234";
  const adminResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminResponse);

  // 2. Register a member user (member role)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Member_pass_4321";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 3. Register a moderator (moderator role)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Mod_pass_2024!";
  const moderatorResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorResponse);

  // 4. As member: try accessing admin list (should be forbidden)
  Object.assign(connection.headers, memberSession.setHeaders);
  await TestValidator.error("member forbidden from admin list")(
    async () => {
      await api.functional.discussionBoard.admin.admins.search(connection, {
        body: {},
      });
    },
  );

  // 5. As moderator: try accessing admin list (should be forbidden)
  Object.assign(connection.headers, moderatorResponse.setHeaders);
  await TestValidator.error("moderator forbidden from admin list")(
    async () => {
      await api.functional.discussionBoard.admin.admins.search(connection, {
        body: {},
      });
    },
  );

  // 6. As unauthenticated: clear auth headers and try (should be forbidden)
  for (const k of Object.keys(connection.headers || {})) delete connection.headers[k];
  await TestValidator.error("unauthenticated forbidden from admin list")(
    async () => {
      await api.functional.discussionBoard.admin.admins.search(connection, {
        body: {},
      });
    },
  );

  // 7. As admin: should succeed
  Object.assign(connection.headers, adminResponse.setHeaders);
  const result = await api.functional.discussionBoard.admin.admins.search(connection, {
    body: {},
  });
  typia.assert(result);
}

