import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate that unauthorized roles cannot access the discussion board admin list API.
 *
 * Business context:
 * The /discussionBoard/admin/admins (PATCH) endpoint returns the paginated list of admin accounts, intended for administrative audit, management, or compliance workflows. Only authenticated system administrators should be able to access this resource; regular members, moderators, and unauthenticated sessions must be strictly forbidden (receive an authorization error). All access attempts should be logged for audit purposes. This ensures robust role-based access control.
 *
 * Test steps:
 * 1. Register an admin account for positive control (to obtain a valid admin email to assign as the moderator creator).
 * 2. Register a member account (role: member).
 * 3. Register a moderator account (role: moderator, requires admin email for assignment).
 * 4. Attempt to access the admin list endpoint as a regular member (should be denied access).
 * 5. Attempt to access the admin list endpoint as a moderator (should be denied access).
 * 6. Attempt to access the admin list endpoint as a fully unauthenticated session (should be denied access).
 * 7. (Optional: Control test) Attempt to access the endpoint as admin (should succeed, for completeness).
 *
 * The test confirms robust enforcement of RBAC on a privileged API endpoint for admin enumeration, and helps ensure unauthorized access is never allowed, even for authenticated non-admin roles.
 */
export async function test_api_admin_search_unauthorized_access_forbidden(connection: api.IConnection) {
  // 1. Register an admin (for positive case and to assign moderators)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "A_strong_1234";
  const adminResponse = await api.functional.auth.admin.register.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminResponse);

  // 2. Register a member user (member role)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Member_pass_4321";
  const memberSession = await api.functional.auth.member.register.post(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 3. Register a moderator (moderator role)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Mod_pass_2024!";
  const moderatorResponse = await api.functional.auth.moderator.register.post(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorResponse);

  // 4. As member: try accessing admin list (should be forbidden)
  connection.headers = { ...(connection.headers ?? {}), ...memberSession.setHeaders };
  await TestValidator.error("member forbidden from admin list")(
    async () => {
      await api.functional.discussionBoard.admin.admins.patch(connection, {
        body: {},
      });
    },
  );

  // 5. As moderator: try accessing admin list (should be forbidden)
  connection.headers = { ...(connection.headers ?? {}), ...moderatorResponse.setHeaders };
  await TestValidator.error("moderator forbidden from admin list")(
    async () => {
      await api.functional.discussionBoard.admin.admins.patch(connection, {
        body: {},
      });
    },
  );

  // 6. As unauthenticated: clear auth headers and try (should be forbidden)
  connection.headers = {};
  await TestValidator.error("unauthenticated forbidden from admin list")(
    async () => {
      await api.functional.discussionBoard.admin.admins.patch(connection, {
        body: {},
      });
    },
  );

  // 7. As admin: should succeed
  connection.headers = { ...(connection.headers ?? {}), ...adminResponse.setHeaders };
  const result = await api.functional.discussionBoard.admin.admins.patch(connection, {
    body: {},
  });
  typia.assert(result);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Test that a moderator user can successfully update a category's editable fields.
 *
 * Business context: Moderators have permission to update certain fields of discussion board categories. This test verifies that those permissions are respected, the edit is recorded correctly, and audit/version fields are updated appropriately.
 *
 * Test steps:
 * 1. Register a moderator to obtain a JWT and moderator privileges.
 * 2. As an admin, create a new category that will later be updated by the moderator.
 * 3. Switch connection context/authentication to the moderator (set Authorization header).
 * 4. Update the category using the moderator endpoint; change editable fields such as name, display_order, description, icon_uri, enabled, and version.
 * 5. Verify the returned category has the desired changes, and that audit fields (updated_at, version override, etc.) have been appropriately set/updated.
 * 6. (Edge case) Ensure that only permitted fields are modified, and moderator role is required for the operation.
 */
export async function test_api_category_update_success_moderator(
  connection: api.IConnection,
) {
  // 1. Register moderator and obtain JWT
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const signUpRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: "Test1234$",
      assigned_by_admin_email: adminEmail,
    } satisfies IModerator.SignUp,
  });
  typia.assert(signUpRes);
  TestValidator.equals("moderator email matches")(signUpRes.email)(moderatorEmail);
  // Set Authorization header on connection so API calls use moderator identity
  connection.headers = connection.headers || {};
  connection.headers["Authorization"] = signUpRes.setHeaders.Authorization;

  // 2. Create a category as admin (simulate by switching context or before setting moderator header)
  // Temporarily remove Authorization header to act as admin
  const prevHeaders = { ...connection.headers };
  connection.headers["Authorization"] = undefined;
  const initialCategoryInput: IDiscussionBoardCategory.ICreate = {
    name: "Initial Category",
    display_order: 100,
    enabled: true,
    version: 1,
    description: "Initial category for moderator update test",
    icon_uri: "https://example.com/icon.png",
  };
  const createdCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: initialCategoryInput,
  });
  typia.assert(createdCategory);
  // Restore moderator authentication on connection
  connection.headers["Authorization"] = signUpRes.setHeaders.Authorization;

  // 3. Prepare a set of updates for the category as moderator
  const updateInput: IDiscussionBoardCategory.IUpdate = {
    name: "Updated Category",
    display_order: 200,
    description: "Category updated by moderator.",
    icon_uri: "https://example.com/updated-icon.png",
    enabled: false,
    version: 2,
    // parent_id omitted (would require an existing different category for re-parenting)
  };

  // 4. Call the moderator update endpoint
  const updatedCategory = await api.functional.discussionBoard.moderator.categories.update(connection, {
    categoryId: createdCategory.id,
    body: updateInput,
  });
  typia.assert(updatedCategory);

  // 5. Verify that the changes have taken effect and audit fields have been updated.
  TestValidator.equals("category id matches")(updatedCategory.id)(createdCategory.id);
  TestValidator.equals("name updated")(updatedCategory.name)(updateInput.name!);
  TestValidator.equals("display_order updated")(updatedCategory.display_order)(updateInput.display_order!);
  TestValidator.equals("icon_uri updated")(updatedCategory.icon_uri)(updateInput.icon_uri!);
  TestValidator.equals("description updated")(updatedCategory.description)(updateInput.description!);
  TestValidator.equals("enabled updated")(updatedCategory.enabled)(updateInput.enabled!);
  TestValidator.equals("version updated")(updatedCategory.version)(updateInput.version!);
  TestValidator.predicate("updated_at is after created_at")(
    new Date(updatedCategory.updated_at).getTime() > new Date(updatedCategory.created_at).getTime(),
  );
}

