import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate the advanced search and pagination of external authentication logs as an admin.
 *
 * This test ensures that an administrator can:
 * 1. Register and log in (acquire admin privileges)
 * 2. Create multiple external auth log entries with diverse auth channels, success statuses, error messages, and different timestamps
 * 3. Search with a variety of filters (by auth channel, by success/failure, by email, and by issued_at date range)
 * 4. Use pagination controls (page, limit) to confirm paging behaviors
 * 5. Confirm that results match query filters and are paged according to the provided pagination metadata
 * 6. Ensure sensitive authentication data is visible only to admins
 */
export async function test_api_external_auth_log_search_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register and log in as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecurePassword1!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // 2. Create several external auth log entries with a variety of data
  // We'll simulate records for multiple channels, users, and both success/failure events
  const baseIssuedAt = new Date();
  const logEntries: IDiscussionBoardExternalAuthLog[] = [];
  for (const [i, [auth_channel, success, extra]] of [
    ["kakao", true, {}],
    ["google", false, { error_code: "ERR_OAUTH", error_message: "OAuth failed" }],
    ["naver", true, {}],
    ["email", false, { error_code: "INVALID_TOKEN", error_message: "Token expired" }],
  ].entries()) {
    const log = await api.functional.discussionBoard.admin.externalAuthLogs.create(connection, {
      body: {
        auth_channel,
        subject_email: `user${i + 1}@example.com`,
        issued_at: new Date(baseIssuedAt.getTime() - i * 24 * 60 * 60 * 1000).toISOString(),
        completed_at: success ? new Date(baseIssuedAt.getTime() - i * 24 * 60 * 60 * 1000 + 60000).toISOString() : null,
        success,
        ...extra,
      } satisfies IDiscussionBoardExternalAuthLog.ICreate,
    });
    typia.assert(log);
    logEntries.push(log);
  }

  // 3. Test search with filter: by auth_channel (e.g., 'kakao')
  const filterByChannel = await api.functional.discussionBoard.admin.externalAuthLogs.search(connection, {
    body: {
      auth_channel: "kakao",
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardExternalAuthLog.IRequest,
  });
  typia.assert(filterByChannel);
  for (const log of filterByChannel.data) {
    TestValidator.equals("filtered by channel")(log.auth_channel)("kakao");
  }

  // 4. Test search with filter: by success status (e.g., only failures)
  const filterByFailure = await api.functional.discussionBoard.admin.externalAuthLogs.search(connection, {
    body: {
      success: false,
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardExternalAuthLog.IRequest,
  });
  typia.assert(filterByFailure);
  for (const log of filterByFailure.data) {
    TestValidator.equals("filtered by failed status")(log.success)(false);
  }

  // 5. Test search with filter: issued_at range covering only subset
  const fromDate = new Date(baseIssuedAt.getTime() - 24 * 60 * 60 * 1000).toISOString();
  const toDate = baseIssuedAt.toISOString();
  const filterByDate = await api.functional.discussionBoard.admin.externalAuthLogs.search(connection, {
    body: {
      issued_at_gte: fromDate,
      issued_at_lte: toDate,
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardExternalAuthLog.IRequest,
  });
  typia.assert(filterByDate);
  for (const log of filterByDate.data) {
    TestValidator.predicate("issued_at within range")(
      log.issued_at >= fromDate && log.issued_at <= toDate,
    );
  }

  // 6. Test pagination - using a page size of 2
  const paginationTest = await api.functional.discussionBoard.admin.externalAuthLogs.search(connection, {
    body: {
      page: 1,
      limit: 2,
    } satisfies IDiscussionBoardExternalAuthLog.IRequest,
  });
  typia.assert(paginationTest);
  TestValidator.equals("pagination.limit")(paginationTest.pagination.limit)(2);
  TestValidator.predicate("pagination size <= limit")(paginationTest.data.length <= 2);

  // 7. Ensure sensitive data is present for admin in search results
  for (const log of paginationTest.data) {
    TestValidator.predicate("admin can see subject_email")(typeof log.subject_email === "string" && log.subject_email.length > 0);
  }
}

