import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Verify that unauthorized users cannot access the admin-only endpoint for fetching comment report details.
 *
 * Business context:
 * - The comment report detail endpoint (/discussionBoard/admin/commentReports/:commentReportId) is restricted to admins and moderators for abuse/violation review.
 * - Regular community members and guests must not be able to fetch these resources.
 * - Unauthorized or forbidden error responses are expected for such access attempts.
 *
 * Steps:
 * 1. Register a regular member (not admin/moderator) in the discussion board.
 * 2. Attempt to fetch comment report details as this member via the admin endpoint.
 * 3. Confirm an authorization error is returned (no data exposed).
 * 4. Attempt the same request as an unauthenticated guest and confirm the error is also returned.
 */
export async function test_api_comment_report_admin_at_unauthorized(connection: api.IConnection) {
  // 1. Register a regular discussion board member
  const registration = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234!AdminForbidden",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(registration);

  // 2. Attempt admin endpoint as this member
  await TestValidator.error("Access denied for regular member")(() =>
    api.functional.discussionBoard.admin.commentReports.at(connection, {
      commentReportId: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // 3. Remove auth for guest access (simulate guest/unauthed user)
  const guestConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined
    }
  };
  await TestValidator.error("Access denied for guest")(() =>
    api.functional.discussionBoard.admin.commentReports.at(guestConnection, {
      commentReportId: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

