  TestValidator.predicate("complex filter")(
    result.data.every(
      (x) => x.status === "active" && x.category.id === categoryA.id && x.title.includes("Active"),
    ),
  );

  // 12. Edge: Impossible filter (empty)
  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { status: "active", category_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(result);
  TestValidator.equals("no match empty array")(result.data.length)(0);

