  result = await api.functional.discussionBoard.admin.posts.search(connection, {
    body: { category_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(result);
  TestValidator.equals("invalid category no match")(result.data.length)(0);

  // 14. Edge: Negative page index (expect graceful error)
  await TestValidator.error("negative page index error")(
    async () => {
      await api.functional.discussionBoard.admin.posts.search(connection, {
        body: { page: -1 },
      });
    },
  );

  // 15. Verify audit info (where distinguishable by type/structure only)
}

