import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserSanction";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test successful hard deletion of an active user sanction record by an admin.
 *
 * Ensures correct admin-only policy enforcement and that sanction records are
 * completely destroyed (hard delete) and cannot be deleted twice. This verifies
 * proper compliance and clean-up after sanctions expire or are resolved successfully.
 *
 * Steps:
 * 1. Register a new admin (simulate elevated privileges). Receives JWT token.
 * 2. Register a new member account (future sanction target).
 * 3. Admin creates a sanction for the member.
 * 4. Confirm the sanction was created and is active.
 * 5. Admin deletes the sanction using DELETE /discussionBoard/admin/userSanctions/{userSanctionId}
 * 6. Negative test: Ensure a second DELETE attempt fails (resource is gone)
 * 7. (GET/search to confirm complete removal are not possible; not implemented due to missing API)
 */
export async function test_api_user_sanction_admin_delete_active_sanction(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPwd = 'TestAdmin#' + typia.random<string & tags.Alphanumeric & tags.Minimum<8> & tags.Maximum<16>>();
  const adminResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPwd,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminResp);

  // 2. Register target member
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const memberResp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: 'UserPwd#' + typia.random<string & tags.Alphanumeric & tags.Minimum<8> & tags.Maximum<16>>(),
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberResp);

  // 3. Admin creates a sanction for the member
  const sanctionInput = {
    sanctioned_member_id: memberResp.member.id,
    sanctioning_admin_id: adminResp.admin_id,
    sanction_type: 'temporary_ban',
    sanction_level: 'moderate',
    reason_type: 'spam',
    reason_text: 'Bulk posting advertisements',
    timeline_start: new Date().toISOString(),
    timeline_end: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
  } satisfies IDiscussionBoardUserSanction.ICreate;
  const sanction = await api.functional.discussionBoard.admin.userSanctions.create(connection, {
    body: sanctionInput,
  });
  typia.assert(sanction);
  TestValidator.equals('sanctioned member')(sanction.sanctioned_member_id)(memberResp.member.id);
  TestValidator.predicate('sanction active')(sanction.active === true);

  // 4. Delete the sanction (hard delete)
  await api.functional.discussionBoard.admin.userSanctions.erase(connection, {
    userSanctionId: sanction.id,
  });

  // 5. Negative test: double deletion should fail
  await TestValidator.error('Sanction already deleted')(async () => {
    await api.functional.discussionBoard.admin.userSanctions.erase(connection, {
      userSanctionId: sanction.id,
    });
  });
  // (Dashboard/search check not possible here; GET endpoint unavailable)
}

