import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReport";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate that an admin can create a report for a comment written by a different user (member).
 *
 * This test covers the admin privilege for auditing or moderation workflows where the admin may submit comment reports on behalf of the system (not self-authored content).
 *
 * Steps:
 * 1. Register an admin and log in to obtain a privileged JWT token.
 * 2. Register a member and log in as the member.
 * 3. As the member, create a discussion post (providing title and body).
 * 4. As the member, comment on the created post.
 * 5. Switch back to admin account by logging in.
 * 6. As admin, submit a comment report for the member's comment.
 * 7. Validate that:
 *    - The report is successfully created and all required fields are present.
 *    - The report status is set to 'pending', and other workflow/audit fields are correct.
 *    - The report associates to the correct comment and member.
 */
export async function test_api_admin_comment_report_creation_for_other_user(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegister = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRegister);

  // 2. Login as admin (to obtain tokens for later use)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ILogin,
  });
  typia.assert(adminLogin);
  // Save admin JWT for switching back after member actions;
  const adminToken = adminLogin.setHeaders.Authorization;

  // 3. Register member
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberNickname = RandomGenerator.name();
  const memberRegister = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberRegister);
  const memberId = memberRegister.member.id;

  // 4. Login as member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IDiscussionBoardMember.ILogin,
  });

  // 5. Create a post as the member
  const postTitle = RandomGenerator.paragraph()(1, 5);
  const postBody = RandomGenerator.content()()();
  const createdPost = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: postTitle,
      body: postBody,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(createdPost);
  const postId = createdPost.id;

  // 6. Add a comment as the member
  const commentBody = RandomGenerator.content()(2, 3);
  const createdComment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId,
    body: {
      body: commentBody,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(createdComment);
  const commentId = createdComment.id;

  // 7. Switch back to admin (set admin token in connection headers)
  connection.headers = {
    ...connection.headers,
    Authorization: adminToken,
  };

  // 8. Submit a comment report as admin
  const reportReasonType = "spam"; // Use a realistic value (could be customized if enum values are documented)
  const reportReasonText = RandomGenerator.paragraph()(1, 2);
  const createdReport = await api.functional.discussionBoard.admin.commentReports.create(connection, {
    body: {
      discussion_board_comment_id: commentId,
      reason_type: reportReasonType,
      reason_text: reportReasonText,
    } satisfies IDiscussionBoardCommentReport.ICreate,
  });
  typia.assert(createdReport);

  // 9. Validate the report record
  TestValidator.equals("report comment id")(createdReport.discussion_board_comment_id)(commentId);
  TestValidator.equals("report status")(createdReport.status)("pending");
  TestValidator.equals("report reason type")(createdReport.reason_type)(reportReasonType);
  TestValidator.equals("handler admin id is null")(createdReport.handler_admin_id)(null);
  TestValidator.predicate("report created_at exists")(!!createdReport.created_at);
  TestValidator.equals("deleted_at is null")(createdReport.deleted_at)(null);
}

