 *
 * Validates that a successfully authenticated moderator can log out and that, after logging out, the session/JWT token is invalidated. Ensures subsequent privileged requests using the same token are rejected. Also verifies the success status in the logout response. This test follows full RBAC and audit compliance.
 *
 * 1. Register a new moderator (simulate admin privilege for test setup)
 * 2. Log in with the moderator to obtain a valid JWT/token
 * 3. Use the JWT to perform a privileged API call to verify access works with a valid session (repeat login as positive test)
 * 4. Log out using the JWT/session
 * 5. Confirm the logout response reports success = true
 * 6. Attempt to use the previously-valid JWT on a privileged endpoint (login) and expect authentication rejection
 * 7. Optionally, check audit logs or session status if such endpoints are available (if not, omit)
 * 8. Ensure stateless session/JWT revocation or server-blacklist if implemented
 */
export async function test_api_moderator_logout_session_invalidation(connection: api.IConnection) {
  // Step 1: Admin registers a new moderator
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = "SecureP@ssw0rd!";
  const signUpRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: password,
    } satisfies IModerator.SignUp,
  });
  typia.assert(signUpRes);
  TestValidator.equals("status should be active")(signUpRes.status)("active");
  TestValidator.equals("email matches")(signUpRes.email)(moderatorEmail);

  // Step 2: Moderator logs in to authenticate
  const signInRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: password,
    } satisfies IModerator.SignIn,
  });
  typia.assert(signInRes);
  TestValidator.equals("email matches")(signInRes.email)(moderatorEmail);

  // Step 3: Use JWT to perform a privileged operation (re-attempt login to verify token works)
  // This confirms that moderator is actually authenticated prior to logout
  const privilegedRes = await api.functional.auth.moderator.login.signIn({
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: signInRes.setHeaders.Authorization,
    },
  }, {
    body: {
      email: moderatorEmail,
      password: password,
    } satisfies IModerator.SignIn,
  });
  typia.assert(privilegedRes);
  TestValidator.equals("second login works")(privilegedRes.email)(moderatorEmail);

  // Step 4: Log out
  const signOutRes = await api.functional.auth.moderator.logout.signOut({
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: signInRes.setHeaders.Authorization,
    },
  });
  typia.assert(signOutRes);
  TestValidator.equals("logout success")(signOutRes.success)(true);

  // Step 5: Attempt to perform privileged action (login) with the old token -- should be rejected
  await TestValidator.error("post-logout: old token should not work")(
    () => api.functional.auth.moderator.login.signIn({
      ...connection,
      headers: {
        ...connection.headers,
        Authorization: signInRes.setHeaders.Authorization,
      },
    }, {
      body: {
        email: moderatorEmail,
        password: password,
      } satisfies IModerator.SignIn,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * End-to-end JWT token validation workflow for moderator accounts.
 *
 * This test ensures proper authentication, status lifecycle, and error handling for moderator tokens:
 *
 * 1. Register a new moderator as an admin (receive JWT and verify status is 'active').
 * 2. Log in as the moderator (assert correct account linkage and token issuance).
 * 3. Validate the legitimate JWT: should return valid and correct moderator info.
 * 4. Validate with a tampered JWT: must report invalid token.
 * 5. Use admin to set moderator status to 'revoked': then JWT validation must fail.
 * 6. Reactivate moderator, then suspend: after suspension, JWT validation must fail (reactivation confirmed by a success between steps).
 * 7. Throughout, validate all transitions and stateful assertions; all error attempts are expected to be logged for audit/security, though this cannot be explicitly checked in the test.
 */
export async function test_api_moderator_validate_token_validity_and_account_status(
  connection: api.IConnection,
) {
  // -- 1. Register moderator (admin action) --
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(16);
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();

  const signUpResponse = await api.functional.auth.moderator.register.signUp(
    connection,
    {
      body: {
        email: moderatorEmail,
        assigned_by_admin_email: adminEmail,
        password,
      } satisfies IModerator.SignUp,
    },
  );
  typia.assert(signUpResponse);
  TestValidator.equals("Moderator status after sign up")(signUpResponse.status)("active");

  // -- 2. Login as moderator --
  const signInResponse = await api.functional.auth.moderator.login.signIn(
    connection,
    {
      body: {
        email: moderatorEmail,
        password,
      } satisfies IModerator.SignIn,
    },
  );
  typia.assert(signInResponse);
  TestValidator.equals("Moderator id matches after login")(signInResponse.moderator_id)(signUpResponse.moderator_id);
  TestValidator.equals("Moderator email matches after login")(signInResponse.email)(signUpResponse.email);

  // -- 3. Validate legitimate JWT --
  const validateResponse = await api.functional.auth.moderator.validate.validateToken(
    connection,
    {
      body: { token: signInResponse.token } satisfies IModerator.ValidateTokenRequest,
    },
  );
  typia.assert(validateResponse);
  TestValidator.equals("Token valid")(validateResponse.valid)(true);
  TestValidator.equals("Moderator id valid")(validateResponse.moderator_id)(signInResponse.moderator_id);
  TestValidator.equals("Email valid")(validateResponse.email)(signInResponse.email);
  TestValidator.equals("Moderator status valid")(validateResponse.status)("active");

  // -- 4. Tampered JWT should fail --
  await TestValidator.error("Tampered token is invalid")(async () => {
    await api.functional.auth.moderator.validate.validateToken(connection, {
      body: { token: signInResponse.token.slice(0, -1) + "X" } satisfies IModerator.ValidateTokenRequest,
    });
  });

  // -- 5. Revoke moderator: validation must now fail --
  const updatedRevoked = await api.functional.discussionBoard.admin.moderators.update(
    connection,
    {
      moderatorId: signUpResponse.moderator_id,
      body: {
        status: "revoked",
        revoked_at: new Date().toISOString(),
      } satisfies IDiscussionBoardModerator.IUpdate,
    },
  );
  typia.assert(updatedRevoked);
  TestValidator.equals("Moderator status after revoke")(updatedRevoked.status)("revoked");

  await TestValidator.error("JWT invalid after revoke")(async () => {
    await api.functional.auth.moderator.validate.validateToken(connection, {
      body: { token: signInResponse.token } satisfies IModerator.ValidateTokenRequest,
    });
  });

  // -- 6. Reactivate, then suspend --
  const updatedActive = await api.functional.discussionBoard.admin.moderators.update(
    connection,
    {
      moderatorId: signUpResponse.moderator_id,
      body: { status: "active", revoked_at: null } satisfies IDiscussionBoardModerator.IUpdate,
    },
  );
  typia.assert(updatedActive);
  TestValidator.equals("Moderator status after reactivation")(updatedActive.status)("active");

  // Re-validation should again succeed
  const validateResponseAfterReactivate = await api.functional.auth.moderator.validate.validateToken(
    connection,
    {
      body: { token: signInResponse.token } satisfies IModerator.ValidateTokenRequest,
    },
  );
  typia.assert(validateResponseAfterReactivate);
  TestValidator.equals("Token valid after reactivation")(validateResponseAfterReactivate.valid)(true);
  TestValidator.equals("Moderator status after reactivation")(validateResponseAfterReactivate.status)("active");

  // Now suspend account
  const updatedSuspended = await api.functional.discussionBoard.admin.moderators.update(
    connection,
    {
      moderatorId: signUpResponse.moderator_id,
      body: { status: "suspended", revoked_at: null } satisfies IDiscussionBoardModerator.IUpdate,
    },
  );
  typia.assert(updatedSuspended);
  TestValidator.equals("Moderator status after suspension")(updatedSuspended.status)("suspended");

  await TestValidator.error("JWT invalid after suspension")(async () => {
    await api.functional.auth.moderator.validate.validateToken(connection, {
      body: { token: signInResponse.token } satisfies IModerator.ValidateTokenRequest,
    });
  });
}

