import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPolicyChangeLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPolicyChangeLog";

/**
 * Test creation of a policy change log entry as an admin.
 *
 * This test validates that an administrator can successfully create a policy change log entry with all required and optional audit fields provided, and that the response matches the submitted data. The purpose of this log is to provide audit trailing, compliance history, and tracking of configuration/policy evolution in the discussion board system.
 *
 * Steps:
 * 1. Prepare all log fields: actor_admin_id (UUID), policy_namespace (domain of change), target_table (which policy/config is impacted), target_field (changed element), previous_value (before state), new_value (after state), and an explanatory change_reason. previous_policy_change_id can be omitted if this is an initial change.
 * 2. Submit a POST request to /discussionBoard/admin/policyChangeLogs as an admin with these fields.
 * 3. Assert that the returned object is a valid policy change log and that major fields echo the submission.
 */
export async function test_api_policy_change_log_creation_success(connection: api.IConnection) {
  // 1. Prepare required and optional fields for the policy change log
  const createInput: IDiscussionBoardPolicyChangeLog.ICreate = {
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
    policy_namespace: "moderation", // example domain
    target_table: "discussion_policy",
    target_field: "max_post_length",
    previous_value: "5000",
    new_value: "10000",
    change_reason: "Increase max post length due to user feedback.",
    // previous_policy_change_id omitted for an initial log entry
  };

  // 2. Create the policy change log entry (POST)
  const log: IDiscussionBoardPolicyChangeLog = await api.functional.discussionBoard.admin.policyChangeLogs.create(connection, {
    body: createInput
  });
  typia.assert(log);

  // 3. Validate key audit fields are persisted as submitted
  TestValidator.equals("actor_admin_id")(log.actor_admin_id)(createInput.actor_admin_id);
  TestValidator.equals("policy_namespace")(log.policy_namespace)(createInput.policy_namespace);
  TestValidator.equals("target_table")(log.target_table)(createInput.target_table);
  TestValidator.equals("target_field")(log.target_field)(createInput.target_field);
  TestValidator.equals("previous_value")(log.previous_value)(createInput.previous_value);
  TestValidator.equals("new_value")(log.new_value)(createInput.new_value);
  TestValidator.equals("change_reason")(log.change_reason)(createInput.change_reason);
  // Note: id and created_at are system-generated and not directly asserted here.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
