/**
 * Test creation with a duplicate or conflicting policy change log scenario.
 *
 * This test verifies the system's ability to detect and reject duplicate or conflicting policy change log entries for the same field and value within the same domain (namespace/table/field) at the same time, enforcing integrity and uniqueness constraints as required for audit compliance.
 *
 * Steps:
 * 1. Prepare a valid policy change log creation input as would be performed by an admin.
 * 2. Successfully create the first policy change log entry using the API.
 * 3. Attempt to create a second policy change log entry with the exact same data (same admin, namespace, table, field, new_value) immediately after.
 * 4. Validate that the first creation is successful and returns a valid policy change log object.
 * 5. Assert that the second creation attempt is rejected by the system, e.g., with an error or conflict indication (system must not allow exact duplicate entries if uniqueness is enforced).
 *
 * This test ensures duplicate/conflicting policy changes cannot be created in violation of business rules, preserving log integrity for auditing purposes.
 */
export async function test_api_policy_change_log_creation_duplicate_handling(connection: api.IConnection) {
  // 1. Prepare valid policy change log input
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const input: IDiscussionBoardPolicyChangeLog.ICreate = {
    actor_admin_id: adminId,
    policy_namespace: "moderation",
    target_table: "board_settings",
    target_field: "max_post_length",
    previous_value: "1000",
    new_value: "2000",
    change_reason: "Increase post limit for users due to business requirements",
  };

  // 2. Successfully create the first policy change log entry
  const first = await api.functional.discussionBoard.admin.policyChangeLogs.create(connection, {
    body: input,
  });
  typia.assert(first);
  TestValidator.equals("input vs output actor_admin_id")(first.actor_admin_id)(adminId);
  TestValidator.equals("input vs output target_field")(first.target_field)(input.target_field);
  TestValidator.equals("input vs output new_value")(first.new_value)(input.new_value);

  // 3. Attempt to create a duplicate policy change log entry (same input)
  await TestValidator.error("duplicate policy change log should fail")(async () => {
    await api.functional.discussionBoard.admin.policyChangeLogs.create(connection, {
      body: input,
    });
  });
}

