 *
 * Steps:
 * 1. Create an initial user sanction record (as moderator context prerequisite).
 * 2. Update the record's allowed fields (e.g., change sanction_level, add reason_text, toggle "active") and validate changes.
 * 3. Assert updated_at is changed after update.
 * 4. Attempt to update immutable fields (should be rejected).
 * 5. Attempt update on a non-existent record (should error).
 */
export async function test_api_moderator_user_sanction_update_success(connection: api.IConnection) {
  // 1. Create a sanction as prerequisite
  const createInput: IDiscussionBoardUserSanction.ICreate = {
    sanctioned_member_id: typia.random<string & tags.Format<"uuid">>(),
    sanctioning_admin_id: typia.random<string & tags.Format<"uuid">>(),
