 *
 * Test process:
 * 1. Register an admin account and obtain an authentication token. This is necessary for all privileged admin endpoints.
 * 2. Create an initial daily statistics record for a specific date. All required metrics for that day will be provided.
 * 3. Update several metrics (such as posts_count, comments_count, votes_up_count, votes_down_count, etc.) for the same record via its unique dailyStatsId, simulating a post-audit fix or admin correction. Some fields (such as date_utc) are not meant to be updated unless business rationale exists, so they will remain unchanged in this test.
 * 4. Validate that the response matches the updated record — all modified fields must reflect the supplied update, while all other values stay the same. The id, date_utc, and audit fields (created_at, updated_at) should have correct relationships.
 * 5. Type safety and business logic validations are performed throughout (e.g., positive integers for counts, correct formats).
 */
export async function test_api_daily_stats_update_successful_admin(connection: api.IConnection) {
