  // 2. Create a new daily statistics record for a chosen UTC date
  const initialStatsInput: IDiscussionBoardDailyStats.ICreate = {
    date_utc: new Date("2025-08-12T00:00:00Z").toISOString(),
    posts_count: typia.random<number & tags.Type<"int32">>(),
