    comments_count: dailyStats.comments_count + 2,
    votes_up_count: dailyStats.votes_up_count + 11,
    votes_down_count: dailyStats.votes_down_count + 2,
    reports_count: dailyStats.reports_count,
    new_user_signups_count: dailyStats.new_user_signups_count,
    active_users_count: dailyStats.active_users_count + 1,
