import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate the admin's ability to search and paginate discussion board members by basic filtering fields (email and nickname).
 *
 * This e2e test ensures that:
 *  - Only an authenticated admin can access the member search list endpoint
 *  - Members with specific email or nickname substrings are returned when using those filters
 *  - Pagination metadata (current, limit, records, pages) matches the expected result given the number of search matches
 *
 * Test steps:
 * 1. Register an admin account (authenticate and call the admin member search endpoint)
 * 2. Register multiple member accounts with known email and nickname patterns for searchability
 * 3. As the admin, perform a search using a substring of one of the member emails
 *     - Confirm only members whose email matches the substring are returned
 *     - Confirm pagination metadata is correct for number of results
 * 4. As the admin, perform a search using a substring of one of the member nicknames
 *     - Confirm only members whose nickname matches the substring are returned
 *     - Confirm pagination metadata is correct for number of results
 * 5. As the admin, perform an unfiltered search (no filters), with limit/pagination params
 *     - Confirm all members are returned (according to limit) and pagination metadata is set correctly
 * 6. (Negative) Attempt the search without admin authentication, and confirm access is denied
 */
export async function test_api_member_search_basic_filtering(connection: api.IConnection) {
  // 1. Register admin for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Adm1n!234";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);
  // Set admin authentication header
  connection.headers = { ...connection.headers, Authorization: adminAuth.setHeaders.Authorization };

  // 2. Register several members with specific email/nickname patterns
  const memberRegistrations = await Promise.all([
    api.functional.auth.member.register.signUp(connection, {
      body: {
        email: `john.doe+unittest1@domain.com`,
        password: "Password1!",
        nickname: "johnnyTestA",
        avatar_uri: null
      } satisfies IDiscussionBoardMember.ICreate,
    }),
    api.functional.auth.member.register.signUp(connection, {
      body: {
        email: `janet.smith+unittest2@domain.com`,
        password: "Password2!",
        nickname: "janet_QA",
        avatar_uri: null
      } satisfies IDiscussionBoardMember.ICreate,
    }),
    api.functional.auth.member.register.signUp(connection, {
      body: {
        email: `alice.moderator+unittest3@domain.com`,
        password: "Password3!",
        nickname: "aliceNick",
        avatar_uri: null
      } satisfies IDiscussionBoardMember.ICreate,
    }),
  ]);
  memberRegistrations.forEach(session => typia.assert(session));

  // 3. Search using part of a member's email
  const emailFilter = "unittest1@domain.com";
  const emailSearchRes = await api.functional.discussionBoard.admin.members.search(connection, {
    body: { email: emailFilter, limit: 10, page: 1 } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(emailSearchRes);
  TestValidator.predicate("only members with filtered email are returned")(
    emailSearchRes.data.every(member => member.email.includes(emailFilter))
  );
  TestValidator.equals("pagination records for filtered email")(emailSearchRes.pagination.records)(emailSearchRes.data.length);

  // 4. Search using part of a member's nickname
  const nicknameFilter = "janet_";
  const nicknameSearchRes = await api.functional.discussionBoard.admin.members.search(connection, {
    body: { nickname: nicknameFilter, limit: 10, page: 1 } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(nicknameSearchRes);
  TestValidator.predicate("only members with filtered nickname are returned")(
    nicknameSearchRes.data.every(member => member.nickname.includes(nicknameFilter))
  );
  TestValidator.equals("pagination records for filtered nickname")(nicknameSearchRes.pagination.records)(nicknameSearchRes.data.length);

  // 5. Search with no filters, pagination check
  const unfilteredRes = await api.functional.discussionBoard.admin.members.search(connection, {
    body: { limit: 2, page: 1 } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(unfilteredRes);
  TestValidator.equals("unfiltered search - limit size")(unfilteredRes.data.length)(2);
  TestValidator.equals("unfiltered search - pagination current page")(unfilteredRes.pagination.current)(1);
  TestValidator.equals("unfiltered search - pagination limit")(unfilteredRes.pagination.limit)(2);
  TestValidator.predicate("unfiltered search - total records >= registered members")(
    unfilteredRes.pagination.records >= memberRegistrations.length
  );

  // 6. Negative: Search as unauthenticated user; should be denied (simulate by removing Authorization)
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthorized search should fail")(async () => {
    await api.functional.discussionBoard.admin.members.search(unauthConn, { body: { limit: 1, page: 1 } });
  });
}

