import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate moderator-powered member search with filter and pagination controls.
 *
 * This test verifies that a properly authenticated moderator can retrieve and filter the member list via PATCH /discussionBoard/moderator/members, using parameters such as email, nickname, status, and date fields for flexible search, and that results respect those filters and the pagination meta. It also checks that no sensitive fields—especially passwords or confidential/account fields—are present in the results, and that only the moderator role has this access.
 *
 * Step-by-step:
 * 1. Register a new moderator for authentication (with unique moderator email, known admin assignment).
 * 2. Register several members with distinct emails, nicknames, status, and joined_at patterns (ensure variety for filter testing).
 * 3. Issue a PATCH request as the moderator, filtering by a specific member's email—expect only the matching member in results.
 * 4. Repeat search using nickname filter for another member—expect results with matching nickname only.
 * 5. Use status as filter to return users with a shared status—expect all with that status, no others.
 * 6. Use registration date (joined_at_from, joined_at_to) to get members within a certain date range—expect only members in-period.
 * 7. Use pagination and check result's page, limit, and data count alignment.
 * 8. Confirm that response objects only include safe fields: id, email, nickname, avatar_uri, joined_at, last_login_at, status. Assert no passwords, tokens, or internal fields present.
 */
export async function test_api_member_search_by_moderator_success(connection: api.IConnection) {
  // 1. Register a moderator
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "StrongP@ssw0rd";
  const moderatorResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorResp);
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorResp.setHeaders.Authorization,
  };

  // 2. Register multiple members
  const memberList = await ArrayUtil.asyncRepeat(3)(async (idx: number) => {
    // For diverse joined_at, rely on system-generated date fields (cannot directly set via API, but registration time will slightly differ)
    const email = typia.random<string & tags.Format<"email">>();
    const memberSession = await api.functional.auth.member.register.signUp(connection, {
      body: {
        email,
        password: "TestPwd123!",
        nickname: `TestUser${idx}_${RandomGenerator.alphaNumeric(3)}`,
        avatar_uri: `https://cdn.example.com/avatars/avatar${idx}.png`,
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(memberSession);
    // Collect only safe properties relevant to filters
    return {
      id: memberSession.member.id,
      email,
      nickname: memberSession.member.nickname,
      status: memberSession.member.status,
      joined_at: memberSession.member.joined_at,
      avatar_uri: memberSession.member.avatar_uri ?? null,
      last_login_at: memberSession.member.last_login_at ?? null,
    };
  });

  // 3. Search by email (exact match for member 0)
  const searchByEmail = await api.functional.discussionBoard.moderator.members.search(connection, {
    body: { email: memberList[0].email } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(searchByEmail);
  TestValidator.predicate("email search single result")(searchByEmail.data.length === 1);
  TestValidator.equals("email matches")(searchByEmail.data[0].email)(memberList[0].email);

  // 4. Search by nickname (exact match for member 1)
  const searchByNickname = await api.functional.discussionBoard.moderator.members.search(connection, {
    body: { nickname: memberList[1].nickname } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(searchByNickname);
  TestValidator.predicate("nickname search single result")(searchByNickname.data.length === 1);
  TestValidator.equals("nickname matches")(searchByNickname.data[0].nickname)(memberList[1].nickname);

  // 5. Search by status (collect status of last member, get all with that status)
  const testStatus = memberList[2].status;
  const searchByStatus = await api.functional.discussionBoard.moderator.members.search(connection, {
    body: { status: testStatus } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(searchByStatus);
  TestValidator.predicate("all have status")(
    searchByStatus.data.every((m) => m.status === testStatus),
  );

  // 6. Date range: joined_at_from to joined_at_to includes only member[0], member[1]
  // Use their joined_at fields (ISO8601) for tight window
  const from = new Date(memberList[1].joined_at);
  from.setSeconds(from.getSeconds() - 1);
  const to = new Date(memberList[0].joined_at);
  to.setSeconds(to.getSeconds() + 1);
  const searchByDate = await api.functional.discussionBoard.moderator.members.search(connection, {
    body: {
      joined_at_from: from.toISOString(),
      joined_at_to: to.toISOString(),
    } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(searchByDate);
  const foundIDs = searchByDate.data.map((m) => m.id);
  TestValidator.predicate("date window includes target members")(
    foundIDs.includes(memberList[0].id) && foundIDs.includes(memberList[1].id),
  );

  // 7. Pagination: limit results to 2 per page
  const paged = await api.functional.discussionBoard.moderator.members.search(connection, {
    body: {
      limit: 2,
      page: 1,
      order_by: "joined_at",
      order: "asc",
    } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("pagination limit")(paged.pagination.limit)(2);

  // 8. Only safe fields are exposed in ISummary
  paged.data.forEach((member) => {
    const safeKeys: (keyof IDiscussionBoardMember.ISummary)[] = ["id", "email", "nickname", "avatar_uri", "joined_at", "last_login_at", "status"];
    (Object.keys(member) as (keyof typeof member)[]).forEach((key) => {
      TestValidator.predicate(`no unsafe field: ${String(key)}`)(safeKeys.includes(key as keyof IDiscussionBoardMember.ISummary));
    });
  });
}

