 *
 * **Test Steps:**
 * 1. Register an admin account and acquire a valid JWT (Authorization header).
 * 2. Register a new member account and record the generated memberId.
 * 3. Switch session to admin by setting the Authorization header.
 * 4. Use GET /discussionBoard/admin/members/{memberId} to retrieve the profile details for the member as admin.
 * 5. Assert that all expected fields are present and that sensitive fields are absent (enforced by type), plus validate profile lifecycle/status and audit timestamps as appropriate.
 */
export async function test_api_member_retrieve_detail_success(connection: api.IConnection) {
  // 1. Register a new admin and obtain their JWT credentials
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "A_strong_password!123";
  const adminRegResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRegResponse);

  // 2. Register a new member to test with
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberNickname: string = RandomGenerator.name();
  const memberPassword: string = "Valid_member_pass_!1";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
      avatar_uri: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);
  const memberId = memberSession.member.id;

  // 3. Switch session context to the admin (by JWT)
  connection.headers = {
    ...connection.headers,
    Authorization: adminRegResponse.setHeaders.Authorization,
  };

  // 4. Retrieve the member profile as the admin
  const profile = await api.functional.discussionBoard.admin.members.at(connection, {
    memberId,
  });
  typia.assert(profile);

  // 5. Validate returned data: all non-sensitive fields and correct audit/status
  TestValidator.equals("member id")(profile.id)(memberSession.member.id);
  TestValidator.equals("email")(profile.email)(memberEmail);
  TestValidator.equals("nickname")(profile.nickname)(memberNickname);
  TestValidator.equals("avatar uri null")(profile.avatar_uri)(null);
  TestValidator.predicate("joined_at is date-time")(typeof profile.joined_at === "string" && !isNaN(Date.parse(profile.joined_at)));
  TestValidator.predicate("last_login_at is date-time")(typeof profile.last_login_at === "string" && !isNaN(Date.parse(profile.last_login_at)));
  TestValidator.equals("status is pending_verification or active")(["pending_verification", "active"].includes(profile.status))(true);
  TestValidator.predicate("created_at is date-time")(typeof profile.created_at === "string" && !isNaN(Date.parse(profile.created_at)));
  TestValidator.predicate("updated_at is date-time")(typeof profile.updated_at === "string" && !isNaN(Date.parse(profile.updated_at)));
  // For a new member, deleted_at should be null or undefined
  TestValidator.equals("deleted_at is null or undefined")(profile.deleted_at == null)(true);
  // By type, sensitive fields (e.g., password) cannot exist -- type safety ensures this
}

