/**
 * Validates successful creation of a new policy document as an admin.
 *
 * This test simulates an admin registering, authenticating (JWT issued), and then using that session
 * to create a new platform policy or legal document entry via the admin-protected endpoint. It verifies
 * all required business/case fields as well as key optional and audit fields, ensuring policy document versioning
 * auditability, status, and admin attribution are properly handled.
 *
 * Steps:
 * 1. Register an admin user using unique credentials and receive JWT/access token.
 * 2. Prepare a unique policy document title, body content (e.g., Markdown text), monotonic version number, mark as active,
 *    and use the created admin’s UUID for author attribution.
 * 3. Use the admin-authenticated session (with Authorization header) to create the policy document.
 * 4. Validate the response: correct title, body, version, is_active status, created_by_admin_id, created_at, updated_at fields are returned with correct formats/values; deleted_at is null or omitted.
 *
 * Note: The test focuses on the success scenario. Edge-cases (like duplicate title/version) or downstream compliance workflow
 * integration are out-of-scope per business instructions and available SDK.
 */
export async function test_api_policy_document_creation_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const adminRegisterResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminRegisterResponse);
  const adminId = adminRegisterResponse.admin_id;

  // Set Authorization header using token from registration response
  connection.headers = {
    ...connection.headers,
    Authorization: adminRegisterResponse.setHeaders.Authorization
  };

  // 2. Prepare unique policy document creation data
  const policyTitle = `Policy - ${RandomGenerator.alphabets(12)}`;
  const policyBody = "# Terms of Service\n\nWelcome to our community. Please read carefully.";
  const policyVersion = typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<10000>>();
  const isActive = true;
  const policyCreateBody = {
    title: policyTitle,
    body: policyBody,
    version: policyVersion,
    is_active: isActive,
    created_by_admin_id: adminId
  } satisfies IDiscussionBoardPolicyDocument.ICreate;

  // 3. Create the policy document as admin
  const createdPolicy = await api.functional.discussionBoard.admin.policyDocuments.create(connection, {
    body: policyCreateBody
  });
  typia.assert(createdPolicy);

  // 4. Validate the response (all business & audit fields)
  TestValidator.equals("title matches")(createdPolicy.title)(policyCreateBody.title);
  TestValidator.equals("body matches")(createdPolicy.body)(policyCreateBody.body);
  TestValidator.equals("version matches")(createdPolicy.version)(policyCreateBody.version);
  TestValidator.equals("is_active is correct")(createdPolicy.is_active)(policyCreateBody.is_active);
  TestValidator.equals("created_by_admin_id matches")(createdPolicy.created_by_admin_id)(policyCreateBody.created_by_admin_id);
  TestValidator.predicate("created_at must be valid ISO-8601 date")(
    !isNaN(Date.parse(createdPolicy.created_at))
  );
  TestValidator.predicate("updated_at must be valid ISO-8601 date")(
    !isNaN(Date.parse(createdPolicy.updated_at))
  );
  TestValidator.equals("deleted_at must be null or omitted")(
    createdPolicy.deleted_at === undefined || createdPolicy.deleted_at === null
  )(true);
}

