import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPolicyDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPolicyDocument";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate successful update of a policy document (admin flow).
 *
 * This test simulates the complete administrator workflow for updating an existing policy/legal document in the platform (such as Terms of Service or Community Guidelines). It covers setup, execution, and verification.
 *
 * 1. Register a new admin for authorization and obtain credentials.
 * 2. Create an initial policy document using the admin, simulating a typical policy draft.
 * 3. Update the policy document by changing its title, body, version number, and activation status.
 * 4. Assert that the updated fields in the response match the submitted values.
 * 5. Confirm that audit fields (like updated_at) are refreshed and that the version is incremented.
 * 6. Optionally, validate version history or audit trail as business logic supports.
 */
export async function test_api_policy_document_update_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin for authorization
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "test12345$";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // 2. Create an initial policy document
  const initialTitle = "Initial Platform Policy";
  const initialBody = "This is the original version of the policy document.";
  const createdPolicy = await api.functional.discussionBoard.admin.policyDocuments.create(connection, {
    body: {
      title: initialTitle,
      body: initialBody,
      version: 1,
      is_active: true,
      created_by_admin_id: adminAuth.admin_id,
    } satisfies IDiscussionBoardPolicyDocument.ICreate,
  });
  typia.assert(createdPolicy);

  // 3. Prepare updated data and submit PUT update
  const updatedTitle = "Updated Platform Policy";
  const updatedBody = "This is the updated version of the policy document with revised terms.";
  const updatedVersion = createdPolicy.version + 1;

  const updateResult = await api.functional.discussionBoard.admin.policyDocuments.update(connection, {
    policyDocumentId: createdPolicy.id,
    body: {
      title: updatedTitle,
      body: updatedBody,
      version: updatedVersion,
      is_active: false,
    } satisfies IDiscussionBoardPolicyDocument.IUpdate,
  });
  typia.assert(updateResult);

  // 4. Assert that the update is reflected
  TestValidator.equals("title updated")(updateResult.title)(updatedTitle);
  TestValidator.equals("body updated")(updateResult.body)(updatedBody);
  TestValidator.equals("version incremented")(updateResult.version)(updatedVersion);
  TestValidator.equals("status update")(updateResult.is_active)(false);

