 * 1. Creation of multiple guest sessions to obtain a known, real guestId
 * 2. Registration and authentication of an admin account
 * 3. Retrieving the session detail as an admin and verifying all expected fields are present and correctly formatted
 * 4. Ensuring security: verifying that access is not allowed for non-admin tokens (guests)
 *
 * Steps:
 * 1. Register a new admin (store access token and credentials)
 * 2. Issue several guest session logins, collect guestIds from the backend
 * 3. As admin, retrieve a specific guest record by guestId and validate fields: session_token, ip_address, user_agent, last_seen_at, created_at, updated_at, and optional deleted_at
 * 4. Attempt to retrieve the same record as guest (without admin credentials) and expect authorization error
 */
export async function test_api_guest_tracking_detail_retrieve_success(connection: api.IConnection) {
  // 1. Register an admin (store tokens for later re-authentication)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecurePW123!";
