  // NOTE: The actual guestId produced by guest login is not directly revealed by the login response.
  // In a true E2E system, test infra would extract the correct guestId (e.g., from a test DB helper or system echo) after login.
  // For demonstration purposes, we use a random UUID. In production E2E, always use the actual guestId if retrievable.
  const guestId = typia.random<string & tags.Format<"uuid">>();

  // 3. Re-authenticate as admin for privileged guest detail lookup
  connection.headers = {
    ...connection.headers,
