  TestValidator.predicate("access token issued")(!!login1.access_token);
  TestValidator.predicate("refresh token issued")(!!login1.refresh_token);
  TestValidator.predicate("admin_id is present")(!!login1.admin_id);
  TestValidator.equals("admin_id matches registration")(login1.admin_id)(registration.admin_id);

