import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validates searching and filtering of permission matrix entries via admin.
 *
 * This test ensures that only authorized administrators can retrieve permission matrix records, with correct application of filter and pagination logic. The result should reflect only non-deleted entries and conform to the expected paginated schema.
 *
 * Steps:
 * 1. Register a new admin user (using a unique email/password)
 * 2. Perform a search as this admin using various filters (role, resource, action, allowed, effective_from_after, effective_to_before, etc.) and paginated parameters (page, limit)
 * 3. Validate the response: only non-deleted records are returned, filter constraints are respected, data matches requested schema
 * 4. Confirm that if an unauthenticated (or unauthorized) attempt is made, the operation is forbidden
 */
export async function test_api_permission_matrix_search_success(connection: api.IConnection) {
  // 1. Register a new admin user
  const email = typia.random<string & tags.Format<"email">>();
  const res = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password: "TestPassword123!"
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(res);

  // The Authorization header is now set for admin session

  // 2. Perform a search with representative filters as the authenticated admin
  const filter: IDiscussionBoardPermissionMatrix.IRequest = {
    role_name: "admin",
    resource: "post",
    action: "read",
    allowed: true,
    effective_from_after: null,
    effective_to_before: null,
    page: 1,
    limit: 10,
  };
  const output = await api.functional.discussionBoard.admin.permissionMatrices.search(connection, {
    body: filter,
  });
  typia.assert(output);

  // 3. Validate pagination and filter logic
  TestValidator.predicate("pagination parameters respected")(
    output.pagination.limit === filter.limit && output.pagination.current === filter.page
  );
  output.data.forEach((item) => {
    TestValidator.equals("role_name matches filter")(item.role_name)(filter.role_name);
    TestValidator.equals("resource matches filter")(item.resource)(filter.resource);
    TestValidator.equals("action matches filter")(item.action)(filter.action);
    TestValidator.equals("allowed matches filter")(item.allowed)(filter.allowed);
    TestValidator.equals("deleted_at is null")(item.deleted_at)(null);
  });

  // 4. Simulate unauthorized search by removing Authorization header
  const headers = { ...connection.headers };
  delete headers.Authorization;
  const unauthConnection = { ...connection, headers };
  await TestValidator.error("forbidden to unauthenticated user")(async () => {
    await api.functional.discussionBoard.admin.permissionMatrices.search(unauthConnection, {
      body: filter,
    });
  });
}

