 *
 * This test covers the workflow where an admin creates a category and then performs an update on editable fields including name, enabled status, display order, description, and icon URI.
 *
 * Validation steps:
 * 1. Create a category using the admin "create" API (used as the update target).
 * 2. Update one or more editable fields using the update API (e.g., change name, display_order, enabled, description, icon_uri).
 * 3. Assert the response has all updated fields, version increment/update, and appropriate updated_at timestamp.
 * 4. Confirm all non-updated fields remain unchanged.
 *
 * This verifies proper admin update rights, accurate update field handling, and audit/version field updates.
 */
export async function test_api_category_update_success_admin(connection: api.IConnection) {
  // 1. Create a new category as admin
  const initialCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(12),
      display_order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
      version: 1,
      description: RandomGenerator.paragraph()(),
      icon_uri: null,
      parent_id: null,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(initialCategory);

  // 2. Update editable fields of this category
  const newName = RandomGenerator.alphabets(10);
  const newDescription = RandomGenerator.paragraph()();
