  // 3. Validate that the update is reflected
  TestValidator.equals("category id")(updatedCategory.id)(initialCategory.id);
  TestValidator.equals("name updated")(updatedCategory.name)(newName);
  TestValidator.equals("description updated")(updatedCategory.description)(newDescription);
  TestValidator.equals("display order updated")(updatedCategory.display_order)(newDisplayOrder);
