  if (connection.headers)
    delete connection.headers["Authorization"];
  const initialCategoryInput: IDiscussionBoardCategory.ICreate = {
    name: "Initial Category",
    display_order: 100,
    enabled: true,
    version: 1,
    description: "Initial category for moderator update test",
    icon_uri: "https://example.com/icon.png",
  };
  const createdCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: initialCategoryInput,
  });
  typia.assert(createdCategory);
  // Restore moderator authentication on connection
  if (!connection.headers) connection.headers = {};
  if (prevAuthorization)
    connection.headers["Authorization"] = prevAuthorization;
  else
    connection.headers["Authorization"] = signUpRes.setHeaders.Authorization;

  // 3. Prepare a set of updates for the category as moderator
  const updateInput: IDiscussionBoardCategory.IUpdate = {
    name: "Updated Category",
    display_order: 200,
    description: "Category updated by moderator.",
    icon_uri: "https://example.com/updated-icon.png",
