  const updatedCategory = await api.functional.discussionBoard.moderator.categories.update(connection, {
    categoryId: createdCategory.id,
    body: updateInput,
  });
  typia.assert(updatedCategory);

  // 5. Verify that the changes have taken effect and audit fields have been updated.
  TestValidator.equals("category id matches")(updatedCategory.id)(createdCategory.id);
  TestValidator.equals("name updated")(updatedCategory.name)(updateInput.name!);
  TestValidator.equals("display_order updated")(updatedCategory.display_order)(updateInput.display_order!);
  TestValidator.equals("icon_uri updated")(updatedCategory.icon_uri)(updateInput.icon_uri!);
  TestValidator.equals("description updated")(updatedCategory.description)(updateInput.description!);
  TestValidator.equals("enabled updated")(updatedCategory.enabled)(updateInput.enabled!);
  TestValidator.equals("version updated")(updatedCategory.version)(updateInput.version!);
  TestValidator.predicate("updated_at is after created_at")(
    new Date(updatedCategory.updated_at).getTime() > new Date(updatedCategory.created_at).getTime(),
  );
}

