    TestValidator.equals("Status should be 'active'")(summary.status)("active");
    TestValidator.predicate("Title contains keyword")(
      summary.title.includes(titleKeyword)
    );
    // Cannot validate category, as ISummary.category is an empty object
  }

  // 4. Pagination info check
  TestValidator.equals("Returned page1")(searchResult.pagination.current)(1);
  TestValidator.equals("Limit is 10")(searchResult.pagination.limit)(10);
}

