import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validate guest notification pagination and filtering.
 *
 * This test verifies that a guest user can retrieve a paginated and filtered list of notifications relevant to their own session, including filters for unread status and event type. This ensures proper implementation of recipient-based filtering and correct behavior of pagination.
 *
 * Business flow:
 * 1. Authenticate as guest to obtain a JWT and unique guest context.
 * 2. As admin, create several notifications targeting the guest (with varying event types, unread status, etc).
 * 3. As the guest (with JWT), request notifications using pagination and filter inputs (unread only, by event_type, limit/page, etc).
 * 4. Assert that only relevant notifications are retrieved, meta information matches, and filters/paging are respected.
 */
export async function test_api_guest_notification_pagination_and_filtering_success(connection: api.IConnection) {
  // 1. Guest authentication (get JWT token for the test guest session)
  const guestAuth = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: RandomGenerator.alphaNumeric(12),
      ip_address: "127.0.0.1",
    },
  });
  typia.assert(guestAuth);
  const guestToken = guestAuth.token;
  const guestAuthorization = guestAuth.setHeaders.Authorization;

  // Extract a synthetic guest identifier for targeting: typically the guest JWT, but strictly guest_id for notification
  // For this test, we'll use the JWT token (issued identity), as guest_id must match for notification delivery
  const guestId = guestToken;

  // 2. Admin creates notifications for this guest (3 with various event_types)
  const eventTypes = ["post_comment", "sanction", "announcement"];
  const notifications = await Promise.all(eventTypes.map(async (eventType) => {
    const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
      body: {
        member_id: null,
        moderator_id: null,
        admin_id: null,
        guest_id: guestId,
        title: RandomGenerator.paragraph()(3),
        body: RandomGenerator.content()()(),
        event_type: eventType,
        related_entity_id: null,
        related_entity_type: null,
      },
    });
    typia.assert(notification);
    return notification;
  }));

  // 3. Act as the guest: set the Authorization header for API requests
  const guestConnection = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: guestAuthorization } };

  // 4. Notification retrieval: test filtering and pagination

  //   a. Retrieve all notifications for guest
  const allRes = await api.functional.discussionBoard.guest.notifications.search(guestConnection, {
    body: {
      recipient_role: "guest",
      recipient_id: guestId,
    },
  });
  typia.assert(allRes);
  TestValidator.predicate("all notifications belong to eventTypes")(
    allRes.data.every(row => eventTypes.includes(row.event_type))
  );
  TestValidator.predicate("all notifications unread")(
    allRes.data.every(row => row.unread === true)
  );

  //   b. Event type filter: check each eventType returns only matching rows
  for (const eventType of eventTypes) {
    const r = await api.functional.discussionBoard.guest.notifications.search(guestConnection, {
      body: {
        recipient_role: "guest",
        recipient_id: guestId,
        event_type: eventType,
      },
    });
    typia.assert(r);
    TestValidator.predicate(`event_type: ${eventType}`)(
      r.data.every(row => row.event_type === eventType)
    );
  }

  //   c. Pagination test: limit and page
  const paged = await api.functional.discussionBoard.guest.notifications.search(guestConnection, {
    body: {
      recipient_role: "guest",
      recipient_id: guestId,
      page: 1,
      limit: 2,
    },
  });
  typia.assert(paged);
  TestValidator.equals("paged result size == 2")(paged.data.length)(2);
  TestValidator.equals("paged/limit meta")(paged.pagination.limit)(2);
  TestValidator.equals("paged/current meta")(paged.pagination.current)(1);

  //   d. Unread filter: all true
  const unreadRes = await api.functional.discussionBoard.guest.notifications.search(guestConnection, {
    body: {
      recipient_role: "guest",
      recipient_id: guestId,
      unread: true,
    },
  });
  typia.assert(unreadRes);
  TestValidator.predicate("all notifications are unread")(
    unreadRes.data.every(row => row.unread === true)
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
