import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Test successful and secure fetch of a moderator notification detail by the recipient moderator.
 *
 * This test ensures that after registering a moderator account, an admin can send a notification specifically targeting that moderator, and the moderator is able to fetch that notification via the notification detail endpoint. All aspects of the returned entity are checked for correctness, including role targeting and recipient linkage. The test also validates that the session role/authorization is enforced: the moderator can only fetch notifications addressed to themselves. 
 *
 * Steps:
 * 1. Register a new moderator (using /auth/moderator/register) to generate a fresh moderator account with assigned_by_admin_email.
 * 2. As admin, create a new notification using /discussionBoard/admin/notifications, designating the new moderator as the recipient (moderator_id field) and filling all other required fields. Capture notificationId from the response.
 * 3. As the moderator (using the JWT token/session from registration), call /discussionBoard/moderator/notifications/{notificationId} to fetch notification details.
 * 4. Assert all response fields: id, moderator_id, title, body, event_type, unread, timestamps, etc., ensuring the entity is correct and recipient linkage matches the moderator.
 * 5. (Negative case) As the moderator, attempt to fetch a notificationId not addressed to them, and assert 403/404 is returned (role filtering).
 */
export async function test_api_moderator_notification_detail_access_self_success(connection: api.IConnection) {
  // 1. Register a new moderator. This yields moderator_id, email, JWT/setHeaders.Authorization.
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const password = "secureTestPass123!";

  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password,
    },
  });
  typia.assert(moderatorReg);

  // 2. Admin creates notification addressed to the newly registered moderator.
  const notificationTitle = "Moderator Test Notification";
  const notificationBody = "This is a message for E2E test.";
  const eventType = "test_event";
  const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      moderator_id: moderatorReg.moderator_id,
      title: notificationTitle,
      body: notificationBody,
      event_type: eventType,
    },
  });
  typia.assert(notification);

  // 3. Simulate moderator session using JWT from registration
  connection.headers = connection.headers ?? {};
  connection.headers.Authorization = moderatorReg.setHeaders.Authorization;

  // 4. Moderator fetches their own notification by id
  const fetched = await api.functional.discussionBoard.moderator.notifications.at(connection, {
    notificationId: notification.id,
  });
  typia.assert(fetched);

  // Validate fields and correct recipient linkage
  TestValidator.equals("notification id matches")(fetched.id)(notification.id);
  TestValidator.equals("moderator_id matches")(fetched.moderator_id)(moderatorReg.moderator_id);
  TestValidator.equals("title matches")(fetched.title)(notificationTitle);
  TestValidator.equals("body matches")(fetched.body)(notificationBody);
  TestValidator.equals("event_type matches")(fetched.event_type)(eventType);
  TestValidator.equals("recipient is current moderator")(fetched.moderator_id)(moderatorReg.moderator_id);
  TestValidator.equals("unread true initially")(fetched.unread)(true);

  // Ensure other recipient fields are null/undefined
  TestValidator.equals("non-moderator recipient fields null")(fetched.member_id)(null);
  TestValidator.equals("non-moderator recipient fields null")(fetched.admin_id)(null);
  TestValidator.equals("non-moderator recipient fields null")(fetched.guest_id)(null);

  // Timestamps should exist
  TestValidator.predicate("created_at valid")(!!fetched.created_at);
  TestValidator.predicate("updated_at valid")(!!fetched.updated_at);

  // 5. Negative case: try to fetch a notification ID not belonging to the moderator (expect error)
  const fakeNotificationId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("Cannot access another's notification")(
    async () => {
      await api.functional.discussionBoard.moderator.notifications.at(connection, {
        notificationId: fakeNotificationId,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Test error handling for retrieving a moderator notification that is either not found, soft-deleted, or not permitted (forbidden).
 *
 * This test ensures that when a moderator tries to fetch notification details by notificationId from /discussionBoard/moderator/notifications/{notificationId}, the system returns the correct error (403 forbidden or 404 not found) when:
 *   - The notification does not exist
 *   - The notification is deleted (soft-deleted)
 *   - The notification exists but is addressed to someone else (e.g., another moderator, member, admin, or guest)
 * The test checks:
 *   - The error type is correct (HttpError 404 or 403)
 *   - No sensitive/private data is leaked in error response
 *   - Authenticated moderator can only see notifications addressed to them
 *
 * Steps:
 * 1. Register a moderator that will perform the test (modA)
 * 2. Register a second moderator (modB) with a different email
 * 3. As an admin, create a notification addressed to modB
 * 4. With modA's session, attempt to fetch modB's notification → expect forbidden or not found
 * 5. Attempt to fetch a random (nonexistent) notificationId → expect not found
 *
 * Only test successful and relevant error scenarios that are permitted by provided API materials.
 */
export async function test_api_moderator_notification_detail_access_forbidden_or_not_found(connection: api.IConnection) {
  // 1. Register moderator A
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const modAEmail: string = typia.random<string & tags.Format<"email">>();
  const modAPassword: string = "Test1234!";
  const modA = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modAEmail,
      assigned_by_admin_email: adminEmail,
      password: modAPassword,
    },
  });
  typia.assert(modA);

  // 2. Register moderator B
  const modBEmail: string = typia.random<string & tags.Format<"email">>();
  const modBPassword: string = "Test1234!";
  const modB = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modBEmail,
      assigned_by_admin_email: adminEmail,
      password: modBPassword,
    },
  });
  typia.assert(modB);

  // 3. As admin, create a notification for modB only
  const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      moderator_id: modB.moderator_id,
      title: "Notification for modB",
      body: "This is a secure notification for modB.",
      event_type: "test_event",
      member_id: null,
      admin_id: null,
      guest_id: null,
      related_entity_id: null,
      related_entity_type: null,
    },
  });
  typia.assert(notification);

  // 4. Authenticate connection as modA before testing access
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modAEmail,
      assigned_by_admin_email: adminEmail,
      password: modAPassword,
    },
  });

  // modA should not be able to access modB's notification
  TestValidator.error("modA forbidden/notfound for modB's notification")(() =>
    api.functional.discussionBoard.moderator.notifications.at(connection, {
      notificationId: notification.id,
    }),
  );

  // 5. Random notificationId should also result in not found
  const randomNotificationId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found for random notification ID")(() =>
    api.functional.discussionBoard.moderator.notifications.at(connection, {
      notificationId: randomNotificationId,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Verify that an admin account can fetch details of any notification regardless of recipient role.
 *
 * This test covers the following workflow:
 * 1. Admin registers and receives authentication (JWT/session) for subsequent API use.
 * 2. As admin, creates four notifications: one each assigned to a member, moderator, admin, and guest recipient (using proper mutually exclusive ID fields).
 * 3. For each created notification, fetches its details by id via the admin detail endpoint. Confirms:
 *    - All notification content (title, body, event_type, entity linkage fields) exactly matches creation,
 *    - The correct recipient _id key is set as intended and all others are null
 *    - unread flag is true
 *    - Creation and update timestamps are present
 * 4. Attempts to fetch a notification using a random/nonexistent id and verifies an error is thrown (basic negative-path check)
 */
export async function test_api_admin_notification_detail_access_success(connection: api.IConnection) {
  // 1. Register new admin and get authentication for API session
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signupResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signupResp);
  connection.headers = { ...(connection.headers ?? {}), ...signupResp.setHeaders };
  const adminId = signupResp.admin_id;

  // 2. Prepare four notifications with different recipient keys
  const recipientRoles = [
    { key: 'member_id',  label: 'member',    fakeId: typia.random<string & tags.Format<'uuid'>>() },
    { key: 'moderator_id', label: 'moderator', fakeId: typia.random<string & tags.Format<'uuid'>>() },
    { key: 'admin_id',   label: 'admin',     fakeId: adminId },
    { key: 'guest_id',   label: 'guest',     fakeId: typia.random<string & tags.Format<'uuid'>>() },
  ];
  const createdNotifications: { id: string; roleKey: string; expectedBody: any }[] = [];

  for (const role of recipientRoles) {
    // distinctly mark each notification content for validation
    const createBody = {
      [role.key]: role.fakeId,
      title: `AutoTest - ${role.label} - ${RandomGenerator.paragraph()(4)}`,
      body: RandomGenerator.content()(2)(30),
      event_type: 'autotest-event',
      related_entity_id: typia.random<string & tags.Format<'uuid'>>(),
      related_entity_type: 'autotest-entity-type',
    };
    const notification = await api.functional.discussionBoard.admin.notifications.create(connection, {
      body: createBody,
    });
    typia.assert(notification);
    createdNotifications.push({ id: notification.id, roleKey: role.key, expectedBody: createBody });
  }

  // 3. Fetch and validate each notification in detail by id
  for (const note of createdNotifications) {
    const fetched = await api.functional.discussionBoard.admin.notifications.at(connection, {
      notificationId: note.id,
    });
    typia.assert(fetched);
    TestValidator.equals(`event_type matches`)(fetched.event_type)(note.expectedBody.event_type);
    TestValidator.equals(`title matches`)(fetched.title)(note.expectedBody.title);
    TestValidator.equals(`body matches`)(fetched.body)(note.expectedBody.body);
    TestValidator.equals(`unread flag true`)(fetched.unread)(true);
    TestValidator.equals('related_entity_id matches')(fetched.related_entity_id)(note.expectedBody.related_entity_id);
    TestValidator.equals('related_entity_type matches')(fetched.related_entity_type)(note.expectedBody.related_entity_type);
    // Only the intended recipient key should be non-null; others null/undefined
    for (const key of ['member_id', 'moderator_id', 'admin_id', 'guest_id']) {
      if (key === note.roleKey)
        TestValidator.equals(`recipient: ${key} set`)((fetched as any)[key])(note.expectedBody[key]);
      else
        TestValidator.equals(`recipient: ${key} null/undefined`)((fetched as any)[key])(null);
    }
    TestValidator.predicate('created_at present')(!!fetched.created_at);
    TestValidator.predicate('updated_at present')(!!fetched.updated_at);
  }

  // 4. Negative: Attempt to fetch nonexistent notification, expect error
  await TestValidator.error('not found error thrown for bad id')(
    async () => {
      await api.functional.discussionBoard.admin.notifications.at(connection, {
        notificationId: typia.random<string & tags.Format<'uuid'>>(),
      });
    },
  );
}

