import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validate guest access to their own notification detail by ID in discussion board system.
 *
 * This test checks that a guest user, after obtaining a session and token, can only retrieve notifications that were explicitly created for their own session (by guest_id), and that the notification returned matches schema and linkage rules. It also ensures that this notification is not accessible by others and must return full content accurately.
 *
 * Test steps:
 * 1. Authenticate as a guest user: obtain a valid session/JWT token. This establishes the guest session/identity and gives us a guest_id (typically encoded in the JWT or mapped server-side).
 * 2. Simulate the admin creating a notification for this guest (using guest_id in the notification recipient field). Capture newly created notification's ID for lookup and ensure that the notification's guest_id matches that of the logged-in guest.
 * 3. As the same guest session, call GET /discussionBoard/guest/notifications/:notificationId using the notificationId. Validate that the returned entity is of type IDiscussionBoardNotification, that its guest_id matches, and that all core fields (title, body, event_type, unread, timestamps etc.) match what was set by the admin.
 * 4. Optionally: Attempt access with a different session (e.g., a new guest token or without authentication) to ensure 403/404 error. (This negative test is described in scenario, but skipped if cannot simulate alternate sessions in current harness.)
 */
export async function test_api_guest_notification_detail_access_success(connection: api.IConnection) {
  // 1. Authenticate guest session
  const guestSignInReq: IGuestAuthGuestSignInRequest = {
    user_agent: RandomGenerator.alphaNumeric(16),
    ip_address: `192.168.${typia.random<number & tags.Type<"uint32"> & tags.Maximum<255>>()}.${typia.random<number & tags.Type<"uint32"> & tags.Maximum<255>>()}`,
  };
  const guestAuthResp: IGuestAuthGuestSignInResponse = await api.functional.auth.guest.login.signIn(connection, { body: guestSignInReq });
  typia.assert(guestAuthResp);

  // Update connection with guest token for authenticated actions
  connection.headers = {
    ...(connection.headers ?? {}),
    ...(guestAuthResp.setHeaders ?? {}),
  };

  // 2. Admin creates notification for this guest_id
  // Extract guest_id from JWT to set for notification recipient
  const guestId = extractGuestIdFromToken(guestAuthResp.setHeaders.Authorization);
  if (!guestId)
    throw new Error("Could not extract guest_id from guest JWT token.");

  const notificationBody: IDiscussionBoardNotification.ICreate = {
    guest_id: guestId,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.paragraph()(),
    event_type: "system.alert"
  };
  const notifResp: IDiscussionBoardNotification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: notificationBody,
  });
  typia.assert(notifResp);

  // 3. Guest calls GET notification detail endpoint
  const notifDetail = await api.functional.discussionBoard.guest.notifications.at(connection, {
    notificationId: notifResp.id
  });
  typia.assert(notifDetail);

  // 4. Validate that the returned entity matches schema and linkage logic
  TestValidator.equals("returned notification id matches")(notifDetail.id)(notifResp.id);
  TestValidator.equals("notification guest_id matches")(notifDetail.guest_id)(notifResp.guest_id);
  TestValidator.equals("title matches")(notifDetail.title)(notificationBody.title);
  TestValidator.equals("body matches")(notifDetail.body)(notificationBody.body);
  TestValidator.equals("event_type matches")(notifDetail.event_type)(notificationBody.event_type);
  TestValidator.predicate("must be unread")(notifDetail.unread === true);
  TestValidator.predicate("created_at exists")(!!notifDetail.created_at);
  TestValidator.predicate("updated_at exists")(!!notifDetail.updated_at);
  // 5. Optional: Verify forbidden access with wrong guest or unauthenticated (not implemented here)
}

// Helper: decode guest_id from JWT token (simplified placeholder, not for prod use)
function extractGuestIdFromToken(token: string): string | undefined {
  // JWT: header.payload.signature base64
  const payload = token.split(".")[1];
  if (!payload) return undefined;
  try {
    const json = JSON.parse(Buffer.from(payload, "base64").toString("utf8"));
    return json.guest_id || json.sub || undefined;
  } catch {
    return undefined;
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";

/**
 * Validates access control for guest notifications in the discussion board.
 *
 * This test ensures that a guest user cannot read notification details unless the notification is
 * specifically addressed to their session. It covers two negative cases:
 *
 * 1. Attempting to access a notification addressed to a different guest session:
 *    - Should result in forbidden (403) or not found (404).
 *    - The API must not leak notification data between sessions.
 * 2. Attempting to access a notification using a random, non-existent UUID:
 *    - Should result in not found (404) without leaking any data.
 *
 * Steps:
 * 1. Authenticate as a guest user, acquiring a guest session and JWT via user_agent and IP.
 * 2. As admin, create a notification addressed to a completely different (random) guest_id.
 * 3. As the test guest user, attempt to retrieve that notification -> expect forbidden or not found.
 * 4. As the test guest user, attempt to retrieve a notification by a random UUID -> expect not found.
 *
 * These checks validate that notification privacy and error reporting are strictly enforced for guest sessions.
 */
export async function test_api_guest_notification_detail_access_forbidden_or_not_found(
  connection: api.IConnection,
) {
  // 1. Guest signs in to receive a JWT (unique session)
  const guestSignIn = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: RandomGenerator.alphabets(12),
      ip_address: "127.0.0.1",
    },
  });
  typia.assert(guestSignIn);
  // At this point, the e2e infra should have placed the token on connection.headers for further API calls

  // 2. As admin, create a notification for a different guest (not the test guest session)
  const otherGuestId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const foreignNotification = await api.functional.discussionBoard.admin.notifications.create(connection, {
    body: {
      guest_id: otherGuestId,
      title: "Other guest notification",
      body: "Should not be visible to test guest.",
      event_type: RandomGenerator.alphabets(6),
    } satisfies IDiscussionBoardNotification.ICreate,
  });
  typia.assert(foreignNotification);

  // 3. As test guest user, try to fetch the notification addressed to a different guest
  await TestValidator.error("guest forbidden/not found for another guest's notification")(
    async () => {
      await api.functional.discussionBoard.guest.notifications.at(connection, {
        notificationId: foreignNotification.id,
      });
    },
  );

  // 4. As test guest user, try to fetch a notification by a random (non-existent) UUID
  await TestValidator.error("guest gets not found for non-existent notification")(
    async () => {
      await api.functional.discussionBoard.guest.notifications.at(connection, {
        notificationId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPlatformConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPlatformConfig";
import type { IPageIDiscussionBoardPlatformConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPlatformConfig";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validates admin search, filter, and pagination for platform configuration records.
 *
 * This test simulates an admin managing platform configuration and verifying advanced query capabilities via `/discussionBoard/admin/platformConfigs`:
 *   - Can search/filter by config_name (exact/partial), enabled status, description keywords, and date windows.
 *   - Validates that only matching records are returned for each filter scenario.
 *   - Confirms pagination works correctly (checks page, limit, total, page count, etc).
 *   - Asserts that audit trail and sensitive metadata fields are present on all results (id, config_name, config_value, enabled, version, description, created_at, updated_at, deleted_at).
 *   - Guarantees all API responses conform to schema, exposing all documented fields.
 *
 * Steps performed:
 * 1. Register a new admin account and authenticate (JWT automatically in connection context).
 * 2. As admin, create several distinct platform configuration records with varied config_name, enabled flag, descriptions, and timestamps.
 * 3. Exercise search endpoint using config_name, enabled (true/false), description keyword, and created_at window as filters.
 * 4. Assert each filter only returns matching configs.
 * 5. Validate pagination: correct page/limit mapping, result boundaries, page count, and total record estimation.
 * 6. For all result records, check inclusion/type of all required and audit/sensitive fields (including nullables).
 */
export async function test_api_platform_config_search_admin_access_with_various_filters(connection: api.IConnection) {
  // 1. Register new admin and authenticate
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(16);
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminAuth);

  // 2. Create diverse platform configuration records
  const configs: IDiscussionBoardPlatformConfig[] = [];
  for (let i = 0; i < 5; ++i) {
    const rec = await api.functional.discussionBoard.admin.platformConfigs.create(connection, {
      body: {
        config_name: `feature_toggle_${i}`,
        config_value: RandomGenerator.alphaNumeric(10),
        enabled: i % 2 === 0,
        version: 1,
        description: i % 2 ? `Auxiliary Description ${i}` : `Important keyword ${i}`,
      },
    });
    typia.assert(rec);
    configs.push(rec);
  }

  // 3. Search: config_name filter (exact)
  const resultByName = await api.functional.discussionBoard.admin.platformConfigs.search(connection, {
    body: { config_name: "feature_toggle_1" },
  });
  typia.assert(resultByName);
  TestValidator.predicate("config_name filter")(
