  TestValidator.equals("attachments")(fullPost.attachments)(fullPostInput.attachments);
  TestValidator.predicate("status is 'active'")(fullPost.status === "active");
  TestValidator.predicate("id is uuid")(/^[0-9a-fA-F\-]{36}$/.test(fullPost.id));
  TestValidator.predicate("created_at is date-time")(/\d{4}-\d{2}-\d{2}T\d{2}:.+/.test(fullPost.created_at));

  // 4. Post with attachments explicitly set to null
