      email,
      password,
      nickname
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(regSession);
  TestValidator.predicate("registration returns JWT token")(!!regSession.token);

  // 2. Create a new post
  const createPostBody: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1).substring(0, 100),
    body: RandomGenerator.content()(1)().substring(0, 4000),
    attachments: JSON.stringify([
      RandomGenerator.alphaNumeric(8) + ".jpg"
    ])
