  TestValidator.equals("created title matches")(createdPost.title)(createPostBody.title);
  TestValidator.equals("created body matches")(createdPost.body)(createPostBody.body);

  // 3. Update the post within the allowed edit window
  const updateInput: IDiscussionBoardPost.IUpdate = {
    title: RandomGenerator.paragraph()(1).substring(0, 100),
    body: RandomGenerator.content()(1)().substring(0, 4000),
    attachments: JSON.stringify([
      RandomGenerator.alphaNumeric(10) + ".pdf",
      RandomGenerator.alphaNumeric(8) + ".png"
    ])
