 *
 * Business context:
 * Moderators should be able to alter any editable field of a member's post (e.g., content, status, category, attachments) for purposes such as policy enforcement, correction, or hiding. Authorship should be preserved, and audit fields (updated_at) should reflect the update. Enforcement of moderator privileges and auditability is crucial.
 *
 * Test workflow:
 * 1. Register a random member (obtain access token)
 * 2. That member creates a post with required fields (title, body)
 * 3. Register a moderator (obtain access token by registration)
 * 4. As moderator, update the member's post changing title, body, attachments, category_id, and set status to 'hidden'.
 * 5. Verify the returned post has the expected updates, updated_at has changed, and authorship (author_member_id) remains unchanged.
 */
export async function test_api_moderator_update_another_users_post(connection: api.IConnection) {
  // 1. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "1234Strong!";
