import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test that an admin can update any discussion board post, including system (audit) fields such as status for moderation purposes.
 *
 * Business context:
 * Ensures system administrators have full override and compliance powers for editing, moderating, or changing any post regardless of original author. This test covers editing all editable fields and system/moderation fields such as 'status'.
 *
 * Steps:
 * 1. Register a new admin (simulate platform bootstrap, obtain access token).
 * 2. As admin, create three posts with default status (simulate normal creation).
 * 3. Update each post as admin for various moderation cases:
 *    a. Edit content of an 'active' post (title/body fields)
 *    b. Toggle 'status' of posts between 'active'/'hidden'/'flagged' to verify admin audit control
 *    c. For each update, assert that the update applied and 'updated_at' is changed
 */
export async function test_api_admin_update_any_post_fields_and_audit(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Test1234!";
  const adminAuth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);

  // 2. Create three posts as admin with default status
  const statuses = ["active", "hidden", "flagged"];
  const createdPosts = await ArrayUtil.asyncMap(statuses)(async (initialStatus) => {
    // New post with random title/body, attachments null
    const created = await api.functional.discussionBoard.admin.posts.create(connection, {
      body: {
        title: RandomGenerator.paragraph()(1).substring(0, 100),
        body: RandomGenerator.content()()(1).substring(0, 4000),
        attachments: null,
      } satisfies IDiscussionBoardPost.ICreate,
    });
    typia.assert(created);

    // If starting status is NOT active, immediately update it to test admin system override
    let updated = created;
    if (initialStatus !== "active") {
      updated = await api.functional.discussionBoard.admin.posts.update(connection, {
        postId: created.id,
        body: {
          status: initialStatus,
        } satisfies IDiscussionBoardPost.IUpdate,
      });
      typia.assert(updated);
      TestValidator.equals("admin can set post status")(updated.status)(initialStatus);
      TestValidator.predicate("updated_at is updated")(updated.updated_at !== created.updated_at);
    }
    return updated;
  });

  // 3. For each post, perform admin updates on content and system field (status), then validate
  for (const post of createdPosts) {
    // (a) Edit title/body for 'active' scenario
    if (post.status === "active") {
      const newTitle = RandomGenerator.paragraph()(1).substring(0, 100);
      const newBody = RandomGenerator.content()()(1).substring(0, 4000);
      const updated = await api.functional.discussionBoard.admin.posts.update(connection, {
        postId: post.id,
        body: {
          title: newTitle,
          body: newBody,
        } satisfies IDiscussionBoardPost.IUpdate,
      });
      typia.assert(updated);
      TestValidator.equals("admin updated title")(updated.title)(newTitle);
      TestValidator.equals("admin updated body")(updated.body)(newBody);
      TestValidator.predicate("updated_at reflects change")(updated.updated_at !== post.updated_at);
    }
    // (b) Toggle moderation/status fields
    else {
      const toggleTo = post.status === "hidden" ? "active" : "hidden";
      const updated = await api.functional.discussionBoard.admin.posts.update(connection, {
        postId: post.id,
        body: {
          status: toggleTo,
        } satisfies IDiscussionBoardPost.IUpdate,
      });
      typia.assert(updated);
      TestValidator.equals("admin toggled status")(updated.status)(toggleTo);
      TestValidator.predicate("updated_at reflects status change")(updated.updated_at !== post.updated_at);
    }
  }
}

