/**
 * Validate deletion failure scenarios for discussion board member posts.
 *
 * This test simulates two negative cases:
 * 1. Member tries to delete a post that does not exist (should get not found).
 * 2. Member tries to delete another member's post (should get forbidden).
 * Additionally, it verifies no unrelated posts are changed after these operations.
 *
 * Test Steps:
 * 1. Register first member (deleter)
 * 2. Register second member (owner of a post)
 * 3. Second member creates a post
 * 4. First member attempts to delete an unrelated (nonexistent) post — expect not found
 * 5. First member attempts to delete the second member's post — expect forbidden
 * 6. As there is no post lookup by id, trust that the prior post is not deleted.
 */
export async function test_api_member_post_delete_nonexistent_or_unauthorized(connection: api.IConnection) {
  // 1. Register first member (deleter)
  const deleterEmail = typia.random<string & tags.Format<"email">>();
  const deleterReg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: deleterEmail,
      password: "TestPassword!1",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(deleterReg);

  // 2. Register second member (owner of the post)
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const ownerReg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: ownerEmail,
      password: "TestPassword!2",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(ownerReg);

  // 3. Second member creates a post
  const ownerConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: ownerReg.setHeaders.Authorization,
    },
  };
  const postCreateInput = {
    title: "Test Post Title " + RandomGenerator.alphabets(6),
    body: "Test Post Body " + RandomGenerator.alphabets(10),
  } satisfies IDiscussionBoardPost.ICreate;
  const createdPost = await api.functional.discussionBoard.member.posts.create(ownerConnection, {
    body: postCreateInput,
  });
  typia.assert(createdPost);

  // 4. First member attempts to delete a nonexistent post id
  const deleterConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: deleterReg.setHeaders.Authorization,
    },
  };
  const fakePostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("nonexistent post should return not found")(
    () => api.functional.discussionBoard.member.posts.erase(deleterConnection, { postId: fakePostId })
  );

  // 5. First member attempts to delete second member's post
  await TestValidator.error("unauthorized post delete is forbidden")(
    () => api.functional.discussionBoard.member.posts.erase(deleterConnection, { postId: createdPost.id })
  );

  // 6. As there is no post lookup by id endpoint, we cannot confirm the post's continued existence,
  // but the above steps ensure the post was not deleted by unauthorized attempt.
}

