 *
 * This scenario verifies that an administrator can update mutable fields (such as success, diagnostics, analytic context) of a specific ad integration log entry using its adIntegrationLogId. The test first creates a log entry, then sends an update containing new data for several mutable fields, and finally verifies that these changes are persisted and reflected correctly in the update response.
 *
 * Steps:
 * 1. Create an ad integration log entry, capturing its returned id.
 * 2. Prepare an update payload modifying several mutable fields: success, diagnostics (error message, error code), and analytic context (local_event_context, response_payload).
 * 3. Call the admin update API with adIntegrationLogId and the update payload.
 * 4. Assert that the response from the update reflects the changed values for the updated fields and that unchanged fields remain as originally created.
 */
export async function test_api_ad_integration_log_update_success(connection: api.IConnection) {
  // 1. Create an ad integration log entry to obtain a valid id
  const createdLog = await api.functional.discussionBoard.admin.adIntegrationLogs.create(connection, {
    body: {
      ad_channel: "google-ads",
      event_type: "impression",
      event_at: new Date().toISOString(),
      success: true,
    } satisfies IDiscussionBoardAdIntegrationLog.ICreate,
  });
  typia.assert(createdLog);

  // 2. Prepare an update payload that changes success, diagnostics, and analytic context fields
  const updatePayload: IDiscussionBoardAdIntegrationLog.IUpdate = {
    success: false,
    error_message: "Network failure during callback.",
    error_code: "NET-500",
    local_event_context: "attempted-refresh",
    response_payload: "{\"status\":\"timeout\"}",
  };

  // 3. Admin updates the log entry
  const updatedLog = await api.functional.discussionBoard.admin.adIntegrationLogs.update(connection, {
    adIntegrationLogId: createdLog.id,
    body: updatePayload,
  });
  typia.assert(updatedLog);

  // 4. Assert update: changed fields reflect new values, others remain from creation
  TestValidator.equals("success updated")(updatedLog.success)(updatePayload.success);
  TestValidator.equals("error_message updated")(updatedLog.error_message)(updatePayload.error_message);
  TestValidator.equals("error_code updated")(updatedLog.error_code)(updatePayload.error_code);
  TestValidator.equals("local_event_context updated")(updatedLog.local_event_context)(updatePayload.local_event_context);
  TestValidator.equals("response_payload updated")(updatedLog.response_payload)(updatePayload.response_payload);
  TestValidator.equals("ad_channel unchanged")(updatedLog.ad_channel)(createdLog.ad_channel);
  TestValidator.equals("event_type unchanged")(updatedLog.event_type)(createdLog.event_type);
}

