/**
 * Validate privileged operation log search by admin.
 *
 * Business context: Admins must be able to search, filter, and paginate operation logs for audit and dashboard compliance.
 * The test ensures that with at least one operation log present, complex filters return correct results and pagination behaves as expected.
 *
 * Steps:
 * 1. Create an operation log entry as precondition (using POST)
 * 2. Run search (PATCH) for logs, applying exact-match filter to return the entry
 * 3. Run search with a partial filter variant (e.g., only action_type filter) and check it still returns the entry
 * 4. Run search with pagination and verify at least one entry (the created one) appears
 * 5. Run search with a date range filter covering the created_at field and confirm the entry is returned
 * 6. Optionally, test search with a filter for unrelated actor/resource and confirm empty results
 */
export async function test_api_operation_logs_search_success(connection: api.IConnection) {
  // 1. Create an operation log as precondition
  const logInput: IDiscussionBoardOperationLog.ICreate = {
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "user_sanction",
    resource_table: "discussion_board_posts",
    resource_id: typia.random<string & tags.Format<"uuid">>(),
    ip_address: "192.168.1.1",
    ua_string: "Mozilla/5.0 (E2E-Test)",
    action_details: JSON.stringify({ reason: "test entry" })
  };
  const logCreated = await api.functional.discussionBoard.admin.operationLogs.create(connection, { body: logInput });
  typia.assert(logCreated);

  // 2. Search: full exact match filter
  const created_from = new Date(new Date(logCreated.created_at).getTime() - 1000).toISOString();
  const created_to = new Date(new Date(logCreated.created_at).getTime() + 1000).toISOString();
  const resultFull = await api.functional.discussionBoard.admin.operationLogs.search(connection, {
    body: {
      actor_admin_id: logCreated.actor_admin_id,
      action_type: logCreated.action_type,
      resource_table: logCreated.resource_table,
      resource_id: logCreated.resource_id,
      ip_address: logCreated.ip_address,
      ua_string: logCreated.ua_string,
      created_from,
      created_to,
      page: 1,
      limit: 10,
      sort_by: "created_at",
      sort_dir: "desc"
    }
  });
  typia.assert(resultFull);
  TestValidator.predicate("Full filter should return at least one record")(resultFull.data.length > 0);
  TestValidator.equals("Top result matches")(resultFull.data[0].id)(logCreated.id);

  // 3. Search: partial filter (by action_type)
  const resultByActionType = await api.functional.discussionBoard.admin.operationLogs.search(connection, {
    body: {
      action_type: logCreated.action_type,
      page: 1,
      limit: 10
    }
  });
  typia.assert(resultByActionType);
  TestValidator.predicate("Partial filter (action_type) returns created log")(resultByActionType.data.some(d => d.id === logCreated.id));

  // 4. Search: pagination test
  const paginationResult = await api.functional.discussionBoard.admin.operationLogs.search(connection, {
    body: {
      page: 1,
      limit: 1,
      sort_by: "created_at",
      sort_dir: "desc"
    }
  });
  typia.assert(paginationResult);
  TestValidator.predicate("Pagination at least one result")(paginationResult.data.length > 0);

  // 5. Search: created_at date range
  const dateRangeResult = await api.functional.discussionBoard.admin.operationLogs.search(connection, {
    body: {
      created_from,
      created_to,
      page: 1,
      limit: 10
    }
  });
  typia.assert(dateRangeResult);
  TestValidator.predicate("Date range search returns log")(dateRangeResult.data.some(d => d.id === logCreated.id));

  // 6. Search with unrelated actor_admin_id (should yield empty result)
  const unrelatedActorId = typia.random<string & tags.Format<"uuid">>();
  const emptyResult = await api.functional.discussionBoard.admin.operationLogs.search(connection, {
    body: {
      actor_admin_id: unrelatedActorId,
      page: 1,
      limit: 5
    }
  });
  typia.assert(emptyResult);
  TestValidator.equals("Unrelated actor filter yields no results")(emptyResult.data.length)(0);
}

