import type { IPageIDiscussionBoardExternalAuthLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardExternalAuthLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Test error handling for invalid filter parameters on external auth logs search.
 *
 * Ensures that when an admin supplies syntactically invalid or unsupported filter parameters to the external authentication logs search endpoint, the API returns validation errors, does not leak log data, and the failed search attempt could be audit-logged (if testable).
 *
 * **Steps:**
 * 1. Register a new admin to obtain credentials.
 * 2. (Implicit) Use provided JWTs for authentication—handled automatically.
 * 3. Attempt various invalid external auth log search requests, including:
 *    - Improper UUID string for member
 *    - Negative and extreme values for pagination/limit
 *    - Malformed or impossible date-time values
 *    - Empty channel string or other semantically invalid values
 * 4. For each case, verify that an error is thrown. Never receive log data object for these invalid requests.
 */
export async function test_api_external_auth_log_search_invalid_filter_error_handling(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'TestPassword123!';
  const adminRegisterResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminRegisterResp);

  // 2. Compose a set of invalid filter parameters
  const invalidRequests: IDiscussionBoardExternalAuthLog.IRequest[] = [
    // Invalid UUID format for discussion_board_member_id
    { discussion_board_member_id: 'not-a-uuid' },
    // Negative page index (should be >= 1)
    { page: -1 },
    // Malformed ISO date for issued_at_gte
    { issued_at_gte: 'definitelynotadate' },
    // Impossible date ('99' month and day)
    { issued_at_lte: '9999-99-99T99:99:99Z' },
    // Zero/invalid limit (should be > 0)
    { limit: 0 },
    // Overly large limit
    { limit: 1000000 },
    // Empty authentication channel
    { auth_channel: '' },
  ];

  // 3. For each, submit the search and expect an error
  for (const invalidBody of invalidRequests) {
    await TestValidator.error('invalid filter should cause error')(async () => {
      await api.functional.discussionBoard.admin.externalAuthLogs.search(connection, { body: invalidBody });
    });
  }
}

