  // 1. Create a parent category as admin
  const parentInput: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(8),
    display_order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
    version: 1,
    description: RandomGenerator.paragraph()(),
    icon_uri: `https://cdn.icons.com/${RandomGenerator.alphaNumeric(6)}.png`,
