    name: RandomGenerator.alphabets(8),
    display_order: parent.display_order + 1,
    enabled: false,
    version: 1,
    parent_id: parent.id,
    description: RandomGenerator.paragraph()(),
    icon_uri: `https://cdn.icons.com/${RandomGenerator.alphaNumeric(6)}.png`,
  };
  const sub: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
