import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPolicyDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPolicyDocument";
import type { IPageIDiscussionBoardPolicyDocument } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPolicyDocument";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the search, filtering, and pagination of policy documents as an admin.
 *
 * This test ensures the search API correctly filters and paginates policy documents based on fields such as title, is_active, version, and content. It also confirms that the pagination respects the requested page/limit, and that the response schema matches expectations.
 *
 * Steps:
 * 1. Create a collection of policy documents with diverse titles, versions, is_active status, and body content, some having overlapping values.
 * 2. Run search queries with:
 *    - Exact and partial title matches (e.g., 'Terms', 'Guide')
 *    - Filtering by is_active true/false
 *    - Full text searches (search in title/body)
 *    - Filter by specific version
 *    - Pagination: set limits and request different pages (page 1, page 2 with a small limit)
 *    - Sorting fields (order_by and order)
 * 3. For each query, confirm:
 *    - Response structure matches IPageIDiscussionBoardPolicyDocument
 *    - Data array contains only items matching the filter (by fields available)
 *    - Pagination info matches actual data (i.e., correct page/limit/records/pages)
 *    - Sorting order is respected if specified
 *    - Soft deleted records are not included
 */
export async function test_api_policy_document_search_success(connection: api.IConnection) {
  // Step 1: Create diverse policy documents to establish a robust test dataset
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const titles = [
    "Terms of Service",
    "Privacy Policy",
    "Community Guidelines",
    "Content Moderation Guide",
    "Acceptable Use Policy",
  ];
  // Prepare a pool of distinct documents
  const docs = await Promise.all(
    [
      // active version, v1
      { title: titles[0], version: 1, is_active: true, body: "Full legal terms of service." },
      // inactive version, v2 of same title
      { title: titles[0], version: 2, is_active: false, body: "Legacy terms." },
      // different title, active
      { title: titles[1], version: 1, is_active: true, body: "How we handle your data." },
      // different title, active
      { title: titles[2], version: 1, is_active: true, body: "Expected community behavior including community standards." },
      // guide, inactive with the keyword to test search
      { title: titles[3], version: 1, is_active: false, body: "Content rules, community best practices and formats." },
      // use policy, active
      { title: titles[4], version: 1, is_active: true, body: "Usage restrictions for community platform." },
    ].map(async info => {
      const doc = await api.functional.discussionBoard.admin.policyDocuments.create(connection, {
        body: {
          title: info.title,
          version: info.version,
          is_active: info.is_active,
          body: info.body,
          created_by_admin_id: adminId,
        } satisfies IDiscussionBoardPolicyDocument.ICreate,
      });
      typia.assert(doc);
      return doc;
    })
  );

  // Step 2: Partial title match search (expect only docs with 'Policy')
  let res = await api.functional.discussionBoard.admin.policyDocuments.search(connection, {
    body: { title: "Policy" } satisfies IDiscussionBoardPolicyDocument.IRequest,
  });
  typia.assert(res);
  TestValidator.predicate("title contains 'Policy'")(
    res.data.every(x => x.title.includes("Policy"))
  );

  // Step 3: is_active true filter (should exclude all inactive docs)
  res = await api.functional.discussionBoard.admin.policyDocuments.search(connection, {
    body: { is_active: true } satisfies IDiscussionBoardPolicyDocument.IRequest,
  });
  typia.assert(res);
  TestValidator.predicate("only active docs listed")(
    res.data.every(x => x.is_active === true)
  );

  // Step 4: Full text search (can only check fields present in ISummary, so title)
  res = await api.functional.discussionBoard.admin.policyDocuments.search(connection, {
    body: { search: "community" } satisfies IDiscussionBoardPolicyDocument.IRequest,
  });
  typia.assert(res);
  // Only check if title includes the keyword
  TestValidator.predicate("title includes 'community'")(
    res.data.some(x => x.title.toLowerCase().includes("community"))
  );

  // Step 5: Version filter (specific version of a title)
  res = await api.functional.discussionBoard.admin.policyDocuments.search(connection, {
    body: { title: titles[0], version: 2 } satisfies IDiscussionBoardPolicyDocument.IRequest,
  });
  typia.assert(res);
  TestValidator.equals("all version==2 for given title")(
    res.data.every(x => x.version === 2 && x.title === titles[0])
  )(true);

  // Step 6: Pagination - first page
  res = await api.functional.discussionBoard.admin.policyDocuments.search(connection, {
    body: { limit: 2, page: 1, order_by: "title", order: "asc" } satisfies IDiscussionBoardPolicyDocument.IRequest,
  });
  typia.assert(res);
  TestValidator.equals("page size==2")(res.data.length)(2);
  TestValidator.equals("current==1")(res.pagination.current)(1);
  TestValidator.equals("limit==2")(res.pagination.limit)(2);

  // Step 7: Pagination - next page (should not overlap with page 1)
  const next = await api.functional.discussionBoard.admin.policyDocuments.search(connection, {
    body: { limit: 2, page: 2, order_by: "title", order: "asc" } satisfies IDiscussionBoardPolicyDocument.IRequest,
  });
  typia.assert(next);
  TestValidator.equals("current==2")(next.pagination.current)(2);
  TestValidator.predicate("no overlap between page 1&2")(
    res.data.every(d1 => !next.data.some(d2 => d2.id === d1.id))
  );

  // Step 8: Descending title sort (should match manual sort)
  res = await api.functional.discussionBoard.admin.policyDocuments.search(connection, {
    body: { order_by: "title", order: "desc"} satisfies IDiscussionBoardPolicyDocument.IRequest,
  });
  typia.assert(res);
  const titlesSorted = res.data.map(x => x.title);
  const manuallySorted = [...titlesSorted].sort().reverse();
  TestValidator.equals("title desc order matches")(
    titlesSorted.join("|")
  )(
    manuallySorted.join("|")
  );
}

