/**
 * Validate system admin can perform a hard delete (irreversible removal) of a user metrics analytic record.
 *
 * This scenario ensures the complete, irreversible deletion of a discussion board member's user metrics analytic record by an admin. It checks correct behavior, error handling, and absence of undeletable traces or re-creation anomalies.
 *
 * **Steps:**
 * 1. Create a user metrics analytic record for a fake member (admin-only).
 * 2. Perform a hard delete using the record's ID.
 * 3. Attempt to perform a second delete on the same ID, expect a not-found error.
 * 4. Attempt to delete a freshly generated, random (nonexistent) user metrics ID, expect a not-found error.
 * 5. Attempt to re-create the metrics record for the same member: expect creation to succeed, as hard delete should allow clean recreation. (Audit-log checks omitted as API is not present.)
 */
export async function test_api_user_metrics_erase_hard_delete_success(connection: api.IConnection) {
  // 1. Create a user metrics analytic record
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const metricsBody: IDiscussionBoardUserMetric.ICreate = {
    discussion_board_member_id: memberId,
    posts_count: 0,
    comments_count: 0,
    votes_up_given_count: 0,
    votes_down_given_count: 0,
    reports_made_count: 0,
    reputation_score: 0,
    last_activity_at: null,
  };
  const created = await api.functional.discussionBoard.admin.userMetrics.create(connection, { body: metricsBody });
  typia.assert(created);
  TestValidator.equals("member ID matches")(created.discussion_board_member_id)(memberId);

  // 2. Hard delete the user metrics record
  await api.functional.discussionBoard.admin.userMetrics.erase(connection, {
    userMetricsId: created.id,
  });

  // 3. Try deleting again - expect not found error
  await TestValidator.error("delete already deleted metrics should fail")(async () => {
    await api.functional.discussionBoard.admin.userMetrics.erase(connection, {
      userMetricsId: created.id,
    });
  });

  // 4. Try deleting a random non-existent user metrics ID
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("delete non-existent metrics should fail")(async () => {
    await api.functional.discussionBoard.admin.userMetrics.erase(connection, {
      userMetricsId: randomId,
    });
  });

  // 5. Try creating a new metrics for the same member again (should succeed)
  const newMetrics = await api.functional.discussionBoard.admin.userMetrics.create(connection, { body: metricsBody });
  typia.assert(newMetrics);
  TestValidator.equals("new member ID matches")(newMetrics.discussion_board_member_id)(memberId);
