import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate the member post search functionality for discussion board posts using various filters and pagination.
 *
 * This test verifies that an authenticated member can search discussion board posts using different combinations of filters (title, body, category, created_at_from/to, etc.) and pagination parameters.
 *
 * The test covers:
 * 1. Member registration and login for secure authenticated session
 * 2. Creation of several discussion board posts with varying categories (using random UUIDs)
 * 3. Filtering by title substring and category ID, confirming all hits match the filter
 * 4. Pagination: confirms result size matches requested limit and checks for out-of-bounds returns
 * 5. Edge cases: no-filter returns visible/active posts only, and non-matching filter returns empty result set
 * 6. Asserts that only posts with status 'active' (or 'visible', if that status exists) are present in search results as per business rules
 * 7. Only valid filter fields from schema are used—invalid field tests are omitted per schema contract
 */
export async function test_api_member_post_search_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberNickname = RandomGenerator.name();
  const signUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(signUp);

  // 2. Log in as the member to establish session
  const signIn = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IDiscussionBoardMember.ILogin,
  });
  typia.assert(signIn);

  // 3. Create several posts as the member in two categories
  const category1 = typia.random<string & tags.Format<'uuid'>>();
  const category2 = typia.random<string & tags.Format<'uuid'>>();
  const posts: IDiscussionBoardPost[] = [];
  for (let i = 0; i < 4; ++i) {
    const cat = i < 2 ? category1 : category2;
    const post = await api.functional.discussionBoard.member.posts.create(connection, {
      body: {
        category_id: cat,
        title: `Post #${i} - ${RandomGenerator.paragraph()(4)}`.slice(0, 100),
        body: `Body ${i}: ${RandomGenerator.content()()().slice(0, 100)}`,
        attachments: null,
      } satisfies IDiscussionBoardPost.ICreate,
    });
    typia.assert(post);
    posts.push(post);
  }

  // 4. Search with empty filter: should only return posts with status 'active' or 'visible'
  const basicSearch = await api.functional.discussionBoard.member.posts.search(connection, {
    body: {},
  });
  typia.assert(basicSearch);
  TestValidator.predicate('only active/visible')(basicSearch.data.every(
    (p) => p.status === 'active' || p.status === 'visible',
  ));

  // 5. Filter by title substring
  const filterTitle = posts[0].title.substring(0, 8);
  const byTitle = await api.functional.discussionBoard.member.posts.search(connection, {
    body: { title: filterTitle },
  });
  typia.assert(byTitle);
  TestValidator.predicate('match title substring')(byTitle.data.every(
    (p) => p.title.toLowerCase().includes(filterTitle.toLowerCase()),
  ));

  // 6. Filter by category_id (cannot check p.category.id by type, so check result post IDs)
  const expectedIds = posts.filter(post => post.category_id === category2).map(post => post.id);
  const byCategory = await api.functional.discussionBoard.member.posts.search(connection, {
    body: { category_id: category2 },
  });
  typia.assert(byCategory);
  // Confirm every result's ID is in the set created for that category
  TestValidator.predicate('all in filtered category')(
    byCategory.data.every((p) => expectedIds.includes(p.id))
  );

  // 7. Pagination returns correct length
  const limit = 2;
  const paged = await api.functional.discussionBoard.member.posts.search(connection, {
    body: { page: 1, limit },
  });
  typia.assert(paged);
  TestValidator.equals('page size respected')(paged.data.length)(Math.min(limit, posts.length));

  // 8. Pagination out-of-bounds returns empty
  const maxPage = Math.ceil(posts.length / limit) + 1;
  const pagedOut = await api.functional.discussionBoard.member.posts.search(connection, {
    body: { page: maxPage, limit },
  });
  typia.assert(pagedOut);
  TestValidator.equals('empty on overflow')(pagedOut.data.length)(0);

  // 9. Non-matching filter yields empty result
  const filterNone = await api.functional.discussionBoard.member.posts.search(connection, {
    body: { title: 'NO_MATCH_TITLE_!@#' },
  });
  typia.assert(filterNone);
  TestValidator.equals('no result for unmatched')(filterNone.data.length)(0);

  // 10. Time window filtering (created_at_from within recent seconds)
  const now = new Date();
  const timeWindow = await api.functional.discussionBoard.member.posts.search(connection, {
    body: {
      created_at_from: new Date(now.getTime() - 1000 * 10).toISOString() as string & tags.Format<'date-time'>,
    },
  });
  typia.assert(timeWindow);
  TestValidator.predicate('created_at_from bounds')(
    timeWindow.data.every((x) => new Date(x.created_at).getTime() >= now.getTime() - 1000 * 10),
  );
}

