    });
    typia.assert(post);
    // NOTE: The test assumes each created post starts as 'active'. There's no status parameter in .ICreate or a status update API, so distinction for other statuses cannot be set via public API.
    // For demonstration, store posts and the intended status
    (post as any)._testStatus = status;
    createdPosts.push(post);
  }

  // 4. Search all posts, no filter (moderator sees all their created posts)
  let out = await api.functional.discussionBoard.moderator.posts.search(connection, { body: {}});
  typia.assert(out);
  // All created post IDs should be in results
  for(const p of createdPosts) {
    TestValidator.predicate(`should find post id ${p.id}`)(out.data.some(r => r.id === p.id));
  }
  // Pagination/records count isn't guaranteed for a multi-user environment, but at least our posts must be present

  // 5. Search by moderator author id
  const moderatorId = signUpRes.moderator_id;
  const filterByAuthor = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { author_moderator_id: moderatorId } });
  typia.assert(filterByAuthor);
  for(const p of createdPosts) {
    TestValidator.predicate(`found by author_moderator_id ${p.id}`)(filterByAuthor.data.some(r => r.id === p.id));
  }

  // 6. Search by title fragment, and by body fragment
  for(const post of createdPosts) {
    const fragTitle = post.title.slice(0, 8);
    const fragBody = post.body.slice(0, 10);
    const byTitle = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { title: fragTitle } });
    typia.assert(byTitle);
    TestValidator.predicate(`should match partial title ${fragTitle}`)(byTitle.data.some(r => r.id === post.id));
    const byBody = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { body: fragBody } });
    typia.assert(byBody);
    TestValidator.predicate(`should match partial body ${fragBody}`)(byBody.data.some(r => r.id === post.id));
  }

  // 7. Search by category_id for each post
  for(let i=0; i<createdPosts.length; ++i) {
    const post = createdPosts[i];
    const categoryId = categoryIds[i];
    const byCat = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { category_id: categoryId } });
    typia.assert(byCat);
    TestValidator.predicate(`should match by category_id ${categoryId}`)(byCat.data.some(r => r.id === post.id));
  }

  // 8. Test pagination with page/limit - get first page, then second if needed
  const pageSize = 2;
  const firstPage = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { page: 1, limit: pageSize } });
  typia.assert(firstPage);
  TestValidator.equals("first page length")(firstPage.data.length)(Math.min(pageSize, createdPosts.length));
  if(createdPosts.length > pageSize) {
    const secondPage = await api.functional.discussionBoard.moderator.posts.search(connection, { body: { page: 2, limit: pageSize } });
    typia.assert(secondPage);
    // Just check our test posts are present, not absolute length, as there might be posts from other users
    for(const p of createdPosts.slice(pageSize)) {
      TestValidator.predicate(`post present on page 2`)(secondPage.data.some(r => r.id === p.id));
    }
  }
}

