  TestValidator.equals("effective_from unchanged")(
    updatedMatrix.effective_from,
  )(createdMatrix.effective_from);
  TestValidator.equals("effective_to unchanged")(
    updatedMatrix.effective_to,
  )(createdMatrix.effective_to ?? null);
}

