/**
 * Validates paginated and filtered search over discussion board rule log entries using the admin API.
 *
 * This test ensures:
 *   - Admin registration, login and JWT session are working (prerequisite for endpoint access)
 *   - At least one rule log entry exists by creating a new permission matrix
 *   - Rule log search returns proper paginated results with accurate data fields and mappings
 *   - Filters by operator_admin_id, rule_type, and effectivity time range are applied correctly
 *   - Pagination metadata (current, limit, records, pages) is consistent
 *
 * Test Steps:
 * 1. Register a new admin account
 * 2. Login as the admin to obtain valid authentication
 * 3. Create a permission matrix, causing a rule log event (operator is the admin)
 * 4. Search rule logs paginated/filtered by
 *    - operator_admin_id (should return the log generated above)
 *    - rule_type = 'permission_matrix' (should match log above)
 *    - effective_from range (should match log above)
 *    - basic pagination
 * 5. Validate data contents, mapping, pagination info, and filtering logic
 */
export async function test_api_rule_log_search_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate
  });
  typia.assert(adminReg);

  // 2. Log in as the admin
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword as string & tags.Format<"password">,
    } satisfies IDiscussionBoardAdmin.ILogin
  });
  typia.assert(adminAuth);
  const adminId = adminAuth.admin_id;

  // 3. Create new permission matrix to generate a rule log
  const now = new Date().toISOString();
  const permMatrix = await api.functional.discussionBoard.admin.permissionMatrices.create(connection, {
    body: {
      role_name: "admin",
      resource: "post",
      action: "approve",
      allowed: true,
      effective_from: now,
      effective_to: null
    } satisfies IDiscussionBoardPermissionMatrix.ICreate
  });
  typia.assert(permMatrix);

  // 4a. Filter by operator_admin_id
  const resByAdmin = await api.functional.discussionBoard.admin.ruleLogs.search(connection, {
    body: {
      operator_admin_id: adminId
    } satisfies IDiscussionBoardRuleLog.IRequest
  });
  typia.assert(resByAdmin);
  TestValidator.predicate("Should include at least one rule log entry by adminId")(
    resByAdmin.data.some(x => x.operator_admin_id === adminId)
  );

  // 4b. Filter by rule_type
  const resByType = await api.functional.discussionBoard.admin.ruleLogs.search(connection, {
    body: {
      rule_type: "permission_matrix"
    } satisfies IDiscussionBoardRuleLog.IRequest
  });
  typia.assert(resByType);
  TestValidator.predicate("Should include at least one rule log of type permission_matrix")(
    resByType.data.some(x => x.rule_type === "permission_matrix")
  );

  // 4c. Filter by effective_from (gte/lte)
  const resByTime = await api.functional.discussionBoard.admin.ruleLogs.search(connection, {
    body: {
      effective_from_gte: now,
      effective_from_lte: now
    } satisfies IDiscussionBoardRuleLog.IRequest
  });
  typia.assert(resByTime);
  TestValidator.predicate("Should find rule log with expected effective_from")(
    resByTime.data.some(x => x.effective_from === now)
  );

  // 4d. Pagination: limit 1, page 1
  const paged = await api.functional.discussionBoard.admin.ruleLogs.search(connection, {
    body: {
      limit: 1,
      page: 1
    } satisfies IDiscussionBoardRuleLog.IRequest
  });
  typia.assert(paged);
  TestValidator.equals("pagination limit")(paged.pagination.limit)(1);
  TestValidator.equals("pagination current page")(paged.pagination.current)(1);

  // 5. Validate log fields mapping with known values
  const matchingLog = resByAdmin.data.find(x => x.rule_type === "permission_matrix" && x.operator_admin_id === adminId);
  if (!matchingLog) throw new Error("Expected rule log not found");
  TestValidator.equals("rule log action matches")(matchingLog.change_type)("created");
  TestValidator.equals("rule type matches")(matchingLog.rule_type)("permission_matrix");
}

