/**
 * Validate admin search, filter, and pagination of user sanctions (disciplinary actions).
 *
 * This test ensures an admin can create sanctions for discussion board users, then retrieve, filter,
 * and paginate those records accurately for compliance or moderation reviews. The API must return only non-deleted,
 * active sanctions, and summary info in search must be well-formed for dashboard/analytics workflows.
 *
 * Steps:
 * 1. Create at least two user sanction records with distinct users/types.
 * 2. Search without filters and confirm both sanctions appear, pagination meta correct.
 * 3. Filter by sanction_type (should only return matching records).
 * 4. Filter by user (sanctioned_member_id) and verify correct record.
 * 5. Filter by active=true (no deleted records).
 * 6. Confirm pagination for all (limit high); check metadata fields
 * 7. Paginate with limit=1 and check both sanctions are returned across pages.
 * 8. Verify summary field structure for each returned row.
 */
export async function test_api_user_sanctions_admin_search_basic_pagination(connection: api.IConnection) {
  // 1. Create two user sanction records as admin
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const user1: string = typia.random<string & tags.Format<"uuid">>();
  const user2: string = typia.random<string & tags.Format<"uuid">>();
  const type1 = "warning";
  const type2 = "temporary_ban";
  const level1 = "minor";
  const level2 = "severe";
  const reason1 = "spam";
  const reason2 = "hate";
  const now = new Date();
  const start1 = now.toISOString();
  const start2 = new Date(now.getTime() + 10000).toISOString();

  const sanctionA = await api.functional.discussionBoard.admin.userSanctions.create(connection, {
    body: {
      sanctioned_member_id: user1,
      sanctioning_admin_id: adminId,
      sanction_type: type1,
      sanction_level: level1,
      reason_type: reason1,
      reason_text: "Unsolicited spam messages",
      timeline_start: start1,
      timeline_end: null,
    },
  });
  typia.assert(sanctionA);

  const sanctionB = await api.functional.discussionBoard.admin.userSanctions.create(connection, {
    body: {
      sanctioned_member_id: user2,
      sanctioning_admin_id: adminId,
      sanction_type: type2,
      sanction_level: level2,
      reason_type: reason2,
      reason_text: "Hate speech content",
      timeline_start: start2,
      timeline_end: null,
    },
  });
  typia.assert(sanctionB);

  // 2. Search for all sanctions (no filters)
  const resultAll = await api.functional.discussionBoard.admin.userSanctions.search(connection, {
    body: {},
  });
  typia.assert(resultAll);
  TestValidator.predicate("contains both created sanctions")(
    resultAll.data.some(row => row.id === sanctionA.id) &&
      resultAll.data.some(row => row.id === sanctionB.id)
  );

  // 3. Filter by sanction_type (type1)
  const resultType1 = await api.functional.discussionBoard.admin.userSanctions.search(connection, {
    body: { sanction_type: type1 },
  });
  typia.assert(resultType1);
  TestValidator.predicate("only first sanction present")(
    resultType1.data.some(row => row.id === sanctionA.id) &&
      resultType1.data.every(row => row.sanction_type === type1)
  );

  // 4. Filter by sanctioned_member_id (user2)
  const resultUser2 = await api.functional.discussionBoard.admin.userSanctions.search(connection, {
    body: { sanctioned_member_id: user2 },
  });
  typia.assert(resultUser2);
  TestValidator.predicate("only second sanction present")(
    resultUser2.data.length === 1 && resultUser2.data[0].id === sanctionB.id
  );

  // 5. Filter by active only
  const resultActive = await api.functional.discussionBoard.admin.userSanctions.search(connection, {
    body: { active: true },
  });
  typia.assert(resultActive);
  TestValidator.predicate("both sanctions are active")(
    resultActive.data.every(row => row.active === true)
  );

  // 6. Confirm pagination for 1-page (limit high)
  const resultPaged = await api.functional.discussionBoard.admin.userSanctions.search(connection, {
    body: { limit: 100 },
  });
  typia.assert(resultPaged);
  TestValidator.equals("pagination meta 2 records")(
    resultPaged.pagination.records
  )(2);
  TestValidator.equals("single page")(
    resultPaged.pagination.pages
  )(1);

  // 7. Use limit=1 for multi-page, should see both entries in different pages
  const page1 = await api.functional.discussionBoard.admin.userSanctions.search(connection, {
    body: { limit: 1, page: 1, orderBy: "created_at", direction: "asc" },
  });
  typia.assert(page1);
  TestValidator.equals("page size 1")(
    page1.data.length
  )(1);
  TestValidator.equals("total records 2")(
    page1.pagination.records
  )(2);
  TestValidator.equals("total pages 2")(
    page1.pagination.pages
  )(2);

  const page2 = await api.functional.discussionBoard.admin.userSanctions.search(connection, {
    body: { limit: 1, page: 2, orderBy: "created_at", direction: "asc" },
  });
  typia.assert(page2);
  TestValidator.equals("page size 1 on page 2")(
    page2.data.length
  )(1);

  // 8. Verify important summary fields
  for (const row of resultAll.data) {
    TestValidator.predicate("id is uuid")(
      typeof row.id === "string" && row.id.length > 0
    );
    TestValidator.predicate("sanctioned_member_id is uuid")(
      typeof row.sanctioned_member_id === "string" && row.sanctioned_member_id.length > 0
    );
    TestValidator.predicate("sanction_type present")(
      typeof row.sanction_type === "string" && row.sanction_type.length > 0
    );
    TestValidator.predicate("reason_type present")(
      typeof row.reason_type === "string" && row.reason_type.length > 0
    );
    TestValidator.predicate("timeline_start valid")(
      typeof row.timeline_start === "string" && row.timeline_start.length > 0
    );
    TestValidator.predicate("created_at valid")(
      typeof row.created_at === "string" && row.created_at.length > 0
    );
    TestValidator.predicate("updated_at valid")(
      typeof row.updated_at === "string" && row.updated_at.length > 0
    );
  }
}

