/**
 * Validate that a registered discussion board member can update their own comment within the allowed edit period.
 *
 * This test verifies the full workflow:
 * 1. Register a new member (sign up and authenticate JWT).
 * 2. As this member, create a new discussion post (required for commenting).
 * 3. On the created post, submit an initial comment.
 * 4. Immediately update that comment's body field with new content (within edit window).
 * 5. Validate the API correctly returns the updated comment object:
 *    - The body is updated.
 *    - The updated_at timestamp is newer than the original.
 *    - The id, post_id, and author_member_id remain unchanged.
 *    - Comment audit and relation fields are properly preserved.
 *    - No fields for moderator/admin authorship are present (null).
 *
 * This ensures the comment editing API enforces author, edit-policy, and audit integrity.
 */
export async function test_api_comment_update_by_member_success(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberInput: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    nickname: RandomGenerator.name(),
    avatar_uri: null,
  };
  const memberSession = await api.functional.auth.member.register.signUp(connection, { body: memberInput });
  typia.assert(memberSession);
  const memberId = memberSession.member.id;

  // 2. Create a new post as this member
  const postInput: IDiscussionBoardPost.ICreate = {
    title: RandomGenerator.paragraph()(1, 10),
    body: RandomGenerator.paragraph()(5, 50),
    attachments: null,
    category_id: null,
    platform_config_id: null,
  };
  const post = await api.functional.discussionBoard.member.posts.create(connection, { body: postInput });
  typia.assert(post);
  TestValidator.equals("post author_member_id correct")(post.author_member_id)(memberId);

  // 3. Create a comment on the post
  const commentInput: IDiscussionBoardComment.ICreate = {
    body: RandomGenerator.paragraph()(2, 20),
    thread_parent_comment_id: null,
  };
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: commentInput,
  });
  typia.assert(comment);
  TestValidator.equals("comment author_member_id correct")(comment.author_member_id)(memberId);
  TestValidator.equals("comment post id")(comment.post_id)(post.id);
  const originalUpdatedAt = comment.updated_at;

  // 4. Update the comment body within the edit window
  const updatedContent = RandomGenerator.paragraph()(3, 25);
  const updateInput: IDiscussionBoardComment.IUpdate = {
    body: updatedContent,
    status: null,
  };
  const updatedComment = await api.functional.discussionBoard.member.posts.comments.update(connection, {
    postId: post.id,
    commentId: comment.id,
    body: updateInput,
  });
