  TestValidator.equals("comment id unchanged")(updatedComment.id)(comment.id);
  TestValidator.equals("comment author unchanged")(updatedComment.author_member_id)(memberId);
  TestValidator.equals("post id unchanged")(updatedComment.post_id)(post.id);
  TestValidator.equals("body updated")(updatedComment.body)(updatedContent);
  TestValidator.predicate("updated_at advanced")(new Date(updatedComment.updated_at) > new Date(originalUpdatedAt));
  TestValidator.equals("moderator id null")(updatedComment.author_moderator_id)(null);
  TestValidator.equals("admin id null")(updatedComment.author_admin_id)(null);
  if (comment.thread_parent_comment_id)
    TestValidator.equals("parent comment (reply) unchanged")(updatedComment.thread_parent_comment_id)(comment.thread_parent_comment_id);
  else
