import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate that only admin users can delete a user sanction record (RBAC enforcement on DELETE /discussionBoard/admin/userSanctions/{userSanctionId})
 *
 * This test verifies that member and moderator users cannot delete a user sanction, and that appropriate forbidden errors (RBAC enforcement) are returned, leaving audit trace and the record intact. Only admins may successfully delete sanction records.
 *
 * The test covers:
 * 1. Admin registers (establishes privileged session)
 * 2. Member registers (target for sanction, also attempts unauthorized delete)
 * 3. Moderator registers (with admin assignment, attempts unauthorized delete)
 * 4. Admin creates a user sanction for the member (target for later negative test)
 * 5. Member (using their JWT) attempts to delete the sanction — must receive forbidden error
 * 6. Moderator (using their JWT) attempts to delete the sanction — must receive forbidden error
 * 7. Guest (no auth) tries DELETE — must receive forbidden/unauthorized error
 * 8. Admin deletes sanction (for completeness)
 * 9. After each step, verify that unauthorized attempts do not remove the record, and that only the admin is able to delete it
 */
export async function test_api_user_sanction_admin_delete_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Admin registers (privileged session)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "A-strong_password1!"; // fixed for login consistency if needed
  const adminRegister = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRegister);
  // attach admin token for subsequent admin API calls
  connection.headers = {
    ...connection.headers,
    Authorization: adminRegister.setHeaders.Authorization,
  };

  // 2. Member registers
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "M-strong_pw1!"; // fixed for repeatable login
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);
  // store member token for later
  const memberToken = memberSession.setHeaders.Authorization;
  const memberId = memberSession.member.id;

  // 3. Moderator registers (must be assigned by admin)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Mod_pw1!";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      assigned_by_admin_email: adminEmail,
    } satisfies IModerator.SignUp,
  });
  typia.assert(moderatorSignUp);
  const moderatorToken = moderatorSignUp.setHeaders.Authorization;
  const moderatorId = moderatorSignUp.moderator_id;

  // 4. Admin creates a user sanction for the member
  const createSanction = await api.functional.discussionBoard.admin.userSanctions.create(connection, {
    body: {
      sanctioned_member_id: memberId,
      sanctioning_admin_id: adminRegister.admin_id,
      sanction_type: "temporary_ban", // example type
      sanction_level: "moderate", // example level
      reason_type: "spam",
      reason_text: "Test sanction for RBAC check.",
      timeline_start: new Date().toISOString(),
      timeline_end: null,
    } satisfies IDiscussionBoardUserSanction.ICreate,
  });
  typia.assert(createSanction);
  const sanctionId = createSanction.id;

  // 5. Member tries to delete the sanction (should be forbidden)
  connection.headers = {
    ...connection.headers,
    Authorization: memberToken,
  };
  await TestValidator.error("Member forbidden delete sanction")(
    async () => {
      await api.functional.discussionBoard.admin.userSanctions.erase(connection, {
        userSanctionId: sanctionId,
      });
    },
  );

  // 6. Moderator tries to delete the sanction (should be forbidden)
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorToken,
  };
  await TestValidator.error("Moderator forbidden delete sanction")(
    async () => {
      await api.functional.discussionBoard.admin.userSanctions.erase(connection, {
        userSanctionId: sanctionId,
      });
    },
  );

  // 7. Guest (no auth) tries delete (should be unauthorized/forbidden)
  delete connection.headers.Authorization;
  await TestValidator.error("Guest forbidden delete sanction")(
    async () => {
      await api.functional.discussionBoard.admin.userSanctions.erase(connection, {
        userSanctionId: sanctionId,
      });
    },
  );

  // Sanction record should still be present
  // (Assume no read endpoint; in practice, create endpoint would error if it was deleted; here, we can attempt re-delete as admin to verify it still exists)

  // 8. Admin successfully deletes the sanction
  connection.headers = {
    ...connection.headers,
    Authorization: adminRegister.setHeaders.Authorization,
  };
  await api.functional.discussionBoard.admin.userSanctions.erase(connection, {
    userSanctionId: sanctionId,
  });

  // Optionally, try to re-delete to check it's really deleted (should error)
  await TestValidator.error("Sanction already deleted")(
    async () => {
      await api.functional.discussionBoard.admin.userSanctions.erase(connection, {
        userSanctionId: sanctionId,
      });
    },
  );
}

