/**
 * Test notification search, filter, and pagination for Discussion Board admin dashboard.
 *
 * 1. Register and authenticate an admin.
 * 2. As admin, create several notifications with different target roles (member, moderator, admin, guest) and event_types and unread statuses.
 * 3. Call PATCH /discussionBoard/admin/notifications with a body filtering for recipient_role (e.g., 'member'), event_type, unread, pagination (limit=2), and check results:
 *    a. Returned notifications match specified filters.
 *    b. Pagination metadata (current page, limit, total records, pages) is correct.
 *    c. All notification summary fields are present and correctly formatted.
 *    d. The dashboard and admin center expected data is present for workflow.
 * 4. Edge cases: Try filtering for a non-existent event_type and expect zero results. Filter by unread=true and unread=false as well.
 * 5. Confirm correct structure and types for all responses via typia.assert.
 */
export async function test_api_notification_admin_search_pagination_and_filtering(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = 'StrongPassword123!';
  const auth = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(auth);
  // Admin authentication is automatic since returned JWT/access_token + setHeaders
  const adminId = auth.admin_id;

  // 2. Create diverse notifications for each target role/event_type
  // Prepare recipient UUIDs (simulate as random UUIDs; only admin_id is known to be real, others random)
  const roles = ['member', 'moderator', 'admin', 'guest'] as const;
  const eventTypes = ['post_comment', 'sanction', 'announcement', 'update'] as const;

  const createdNotifications: IDiscussionBoardNotification.ICreate[] = [];

  for (const role of roles) {
    for (const event_type of eventTypes) {
      // Explicit recipient field selection
      let createBody: IDiscussionBoardNotification.ICreate;
      if (role === 'admin') {
        createBody = {
          admin_id: adminId,
          title: `Test ${role} ${event_type}`,
          body: `Message for ${role} about ${event_type}`,
          event_type,
        };
      } else if (role === 'member') {
        createBody = {
          member_id: typia.random<string & tags.Format<"uuid">>(),
          title: `Test ${role} ${event_type}`,
          body: `Message for ${role} about ${event_type}`,
          event_type,
        };
      } else if (role === 'moderator') {
        createBody = {
          moderator_id: typia.random<string & tags.Format<"uuid">>(),
          title: `Test ${role} ${event_type}`,
          body: `Message for ${role} about ${event_type}`,
          event_type,
        };
      } else {
        createBody = {
          guest_id: typia.random<string & tags.Format<"uuid">>(),
          title: `Test ${role} ${event_type}`,
          body: `Message for ${role} about ${event_type}`,
          event_type,
        };
      }
      await api.functional.discussionBoard.admin.notifications.create(connection, { body: createBody });
      createdNotifications.push(createBody);
    }
  }

  // 3. Test search with various filters and pagination
  // a. Filter by recipient_role='member', event_type='post_comment', unread=true, limit=2 (test pagination)
  let searchResult = await api.functional.discussionBoard.admin.notifications.search(connection, {
    body: {
      recipient_role: 'member',
      event_type: 'post_comment',
      unread: true,
      limit: 2,
      page: 1
    }
  });
  typia.assert(searchResult);
  // b. Validate that results match filters and pagination is honored
  for (const notif of searchResult.data) {
    TestValidator.equals('event_type matches')(notif.event_type)('post_comment');
    TestValidator.equals('unread matches')(notif.unread)(true);
    // All summary fields must be present
    TestValidator.predicate('All summary fields present')(
      Boolean(notif.id) &&
      typeof notif.title === 'string' &&
      typeof notif.body === 'string' &&
      typeof notif.event_type === 'string' &&
      typeof notif.unread === 'boolean' &&
      Boolean(notif.created_at)
    );
  }
  TestValidator.predicate('pagination present')(!!searchResult.pagination);
  TestValidator.equals('pagination.limit')(searchResult.pagination.limit)(2);
  TestValidator.equals('pagination.current')(searchResult.pagination.current)(1);
  TestValidator.equals('pagination.records')(searchResult.pagination.records)(searchResult.data.length);

  // c. Next page (page 2)
  let searchResult2 = await api.functional.discussionBoard.admin.notifications.search(connection, {
    body: {
      recipient_role: 'member',
      event_type: 'post_comment',
      unread: true,
      limit: 2,
      page: 2
    }
  });
  typia.assert(searchResult2);
  TestValidator.equals('pagination.current')(searchResult2.pagination.current)(2);

  // 4. Edge: filter for a non-existent event_type, expect zero results
  const noneResult = await api.functional.discussionBoard.admin.notifications.search(connection, {
    body: {
      event_type: 'NON_EXISTENT_TYPE',
      limit: 2
    }
  });
  typia.assert(noneResult);
  TestValidator.equals('no data')(noneResult.data.length)(0);
  TestValidator.predicate('pagination present on empty')(!!noneResult.pagination);

  // 5. Filter by unread explicitly true and false
  const unreadTrue = await api.functional.discussionBoard.admin.notifications.search(connection, {
    body: { unread: true, limit: 10 }
  });
  typia.assert(unreadTrue);
  for (const notif of unreadTrue.data) {
    TestValidator.equals('all unread true')(notif.unread)(true);
  }
  const unreadFalse = await api.functional.discussionBoard.admin.notifications.search(connection, {
    body: { unread: false, limit: 10 }
  });
  typia.assert(unreadFalse);
  for (const notif of unreadFalse.data) {
    TestValidator.equals('all unread false')(notif.unread)(false);
  }
}

