    body: {
      email,
      password,
      nickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(signUpRes);
  const memberId = signUpRes.member.id;

  // 2. Login as member
  const signInRes = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IDiscussionBoardMember.ILogin,
  });
  typia.assert(signInRes);

  // 3. Create discussion post
  const postRes = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(100),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(postRes);
  const postId = postRes.id;

  // 4. Comment as member
  const commentRes = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId,
    body: {
      body: RandomGenerator.paragraph()(6),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(commentRes);
  const commentId = commentRes.id;

  // 5. Submit initial report (should succeed)
  const reportReq = {
    discussion_board_comment_id: commentId,
    reason_type: "spam",
    reason_text: RandomGenerator.content()()(30),
