  TestValidator.equals("reason type matches")(reportRes.reason_type)("spam");

  // 6. Try to report again with same member and comment (should fail)
  TestValidator.error("duplicate comment report must be rejected")(async () => {
    await api.functional.discussionBoard.member.commentReports.create(connection, {
      body: reportReq,
    });
  });
}

