  const memberPassword = "Member1234!";
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name()
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberSignUp);
  const memberId = memberSignUp.member.id;

