 * 3. Assert that all details match and integrity is preserved
 * 4. Assert correct workflow/status fields (active, not deleted, status present)
 * 5. Validate fields with date-time/string formats as required by the DTO
 */
export async function test_api_post_report_detail_view_success_moderator(
  connection: api.IConnection
) {
