/**
 * Validate the ability of an admin to update a post report's status, resolution, and handler notes.
 *
 * This e2e test covers the real moderation workflow:
 *
 * 1. A member files an abuse report on a discussion board post
 * 2. Admin resolves the post report by updating the status, resolution message, and handler_admin_id
 * 3. Validates allowed status transition, audit fields, and field updates
 * 4. Verifies that pre-existing report fields are preserved
 * 5. Negative test: illegal status transition triggers error
 */
export async function test_api_admin_update_post_report_status_resolution(connection: api.IConnection) {
  // 1. Simulate a member reporting a post
  const postReport = await api.functional.discussionBoard.member.postReports.create(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      reason_type: "spam",
      reason_text: "This post is spam content."
    } satisfies IDiscussionBoardPostReport.ICreate
  });
  typia.assert(postReport);

  // 2. Admin updates report to 'action_taken' with resolution message and handler
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const updatedReport = await api.functional.discussionBoard.admin.postReports.update(connection, {
    postReportId: postReport.id,
    body: {
      status: "action_taken",
      resolution_message: "The post was reviewed and action was taken.",
      handler_admin_id: adminId
    } satisfies IDiscussionBoardPostReport.IUpdate
  });
  typia.assert(updatedReport);

  // 3. Confirm business logic: updated fields and preserved original info
  TestValidator.equals("status updated")(updatedReport.status)("action_taken");
  TestValidator.equals("resolution message")(updatedReport.resolution_message)("The post was reviewed and action was taken.");
  TestValidator.equals("handler_admin_id")(updatedReport.handler_admin_id)(adminId);
  TestValidator.equals("discussion_board_post_id")(updatedReport.discussion_board_post_id)(postReport.discussion_board_post_id);
  TestValidator.equals("discussion_board_member_id")(updatedReport.discussion_board_member_id)(postReport.discussion_board_member_id);
  TestValidator.equals("reason_type")(updatedReport.reason_type)(postReport.reason_type);
  TestValidator.equals("reason_text")(updatedReport.reason_text)(postReport.reason_text);

  // 4. Check audit: updated_at should be newer than pre-update
  TestValidator.predicate("updated_at is refreshed")(new Date(updatedReport.updated_at) > new Date(postReport.updated_at));

  // 5. Negative: illegal status transition triggers error
  await TestValidator.error("illegal status transition")(() =>
    api.functional.discussionBoard.admin.postReports.update(connection, {
      postReportId: postReport.id,
      body: {
        status: "pending"
      } satisfies IDiscussionBoardPostReport.IUpdate
    })
  );
}

