/**
 * Validate the enforcement of report status workflow constraints on post report updates by admin.
 *
 * Business context:
 * Community platforms often require admin/moderator workflow for handling abuse reports, where transitions between statuses (e.g. 'pending' → 'in_review' → 'closed') are strictly regulated. This test ensures business logic prevents skipping required workflow steps (such as going directly from 'pending' to 'closed').
 *
 * Test process:
 * 1. Set up a post report as a normal member (which will initially have a 'pending' status).
 * 2. As admin, attempt to update the report to 'closed' directly, skipping any required intermediate status ('in_review').
 * 3. Confirm that the API responds with an error (rejection) rather than allowing the forbidden transition.
 * 4. Additionally, confirm that other data is not modified and the report remains in the original status (not implemented since no read API is available).
 */
export async function test_api_admin_update_post_report_invalid_status_transition(
  connection: api.IConnection,
) {
  // 1. Member creates a report — acts as dependency setup
  const report: IDiscussionBoardPostReport = await api.functional.discussionBoard.member.postReports.create(
    connection,
    {
      body: {
        discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
        reason_type: "spam",
        reason_text: "Obvious spam content",
      } satisfies IDiscussionBoardPostReport.ICreate,
    },
  );
  typia.assert(report);
  TestValidator.equals("initial status is pending")(report.status)("pending");

  // 2. As admin, try invalid transition directly to 'closed'
  await TestValidator.error("invalid direct workflow transition is blocked")(
    async () => {
      await api.functional.discussionBoard.admin.postReports.update(
        connection,
        {
          postReportId: report.id,
          body: {
            status: "closed",
            resolution_message: "Closed without review.",
          } satisfies IDiscussionBoardPostReport.IUpdate,
        },
      );
    },
  );

  // 3. If a 'read' API existed, re-fetch the report and confirm status is still 'pending'.
  // Not implemented: reloading the report to check persistent status as no relevant SDK is supplied.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
