/**
 * Validates that updating a soft-deleted (deleted) post report fails with an appropriate error.
 *
 * Business context:
 * - Post abuse reports, once deleted by an admin (soft-deleted), must remain immutable for audit/compliance purposes.
 * - The system should reject any attempt to update a deleted (soft-deleted) report, returning a not-found or invalid-operation error.
 *
 * Test Procedure:
 * 1. Create a new post report as a member (simulating a report from a user).
 * 2. As admin, soft-delete the report using the erase endpoint.
 * 3. Attempt to update the now-deleted report as admin.
 * 4. Confirm the update operation fails (throws an error), proving deleted reports cannot be modified further.
 */
export async function test_api_admin_update_post_report_on_deleted_report(
  connection: api.IConnection,
) {
  // 1. Create a post report as a member
  const report = await api.functional.discussionBoard.member.postReports.create(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      reason_type: "spam", // assuming 'spam' is a valid reason type for reporting
      reason_text: "Attempted for soft-delete update error validation",
    } satisfies IDiscussionBoardPostReport.ICreate,
  });
  typia.assert(report);

  // 2. Soft-delete the report as admin
  await api.functional.discussionBoard.admin.postReports.erase(connection, {
    postReportId: report.id,
  });

  // 3. Attempt to update the deleted report; expect an error (cannot update deleted)
  await TestValidator.error("Cannot update a post report that was deleted (soft-deleted)")(
    async () => {
      await api.functional.discussionBoard.admin.postReports.update(connection, {
        postReportId: report.id,
        body: {
          status: "resolved", // plausible workflow status change
          resolution_message: "Should fail: report already deleted",
          handler_admin_id: typia.random<string & tags.Format<"uuid">>(),
        } satisfies IDiscussionBoardPostReport.IUpdate,
      });
    },
  );
