import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostReport";

/**
 * Validate that a moderator can review and update a post abuse report in the discussion board system.
 *
 * Business context:
 * - Community users can report posts for abuse. A report is created with status 'pending'.
 * - Moderators must be able to update the status (e.g., from 'pending' to 'in_review' or 'resolved'), optionally write a resolution message, and be shown as the handler admin for audit trails.
 * - Proper moderation workflows and traceability must be enforced.
 *
 * Steps:
 * 1. Create an abuse report for a post as a member (dependency setup).
 * 2. Moderator updates the report, changing status and setting resolution message and handler_admin_id.
 * 3. Validate the fields are updated as expected and audit properties (handler, resolution, timestamps) reflect the workflow.
 * 4. Edge case test: attempt an invalid state transition or redundant update for business rule coverage if possible.
 */
export async function test_api_moderator_update_post_report_status_resolution(
  connection: api.IConnection,
) {
  // 1. Create an abuse report as a member
  const postReport: IDiscussionBoardPostReport = await api.functional.discussionBoard.member.postReports.create(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      reason_type: "spam", // sample valid code
      reason_text: "Suspected spam content in the post."
    } satisfies IDiscussionBoardPostReport.ICreate
  });
  typia.assert(postReport);

  // 2. Moderator updates the report: change status, add resolution, set handler
  const moderatorId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const updateInput: IDiscussionBoardPostReport.IUpdate = {
    status: "resolved",
    resolution_message: "Confirmed spam, action taken.",
    handler_admin_id: moderatorId
  };
  const updatedReport: IDiscussionBoardPostReport = await api.functional.discussionBoard.moderator.postReports.update(connection, {
    postReportId: postReport.id,
    body: updateInput
  });
  typia.assert(updatedReport);
  TestValidator.equals("status updated")(updatedReport.status)("resolved");
  TestValidator.equals("resolution message")(updatedReport.resolution_message)("Confirmed spam, action taken.");
  TestValidator.equals("handler_admin_id")(updatedReport.handler_admin_id)(moderatorId);
  TestValidator.equals("post id")(updatedReport.discussion_board_post_id)(postReport.discussion_board_post_id);

  // 3. Edge case: Try a redundant update (submit the same 'resolved' status again)
  const redundantUpdateInput: IDiscussionBoardPostReport.IUpdate = {
    status: "resolved",
    resolution_message: "Redundant update test.",
    handler_admin_id: moderatorId
  };
  const redundantReport: IDiscussionBoardPostReport = await api.functional.discussionBoard.moderator.postReports.update(connection, {
    postReportId: postReport.id,
    body: redundantUpdateInput
  });
  typia.assert(redundantReport);
  TestValidator.equals("status remains resolved")(redundantReport.status)("resolved");
  TestValidator.equals("resolution message changed")(redundantReport.resolution_message)("Redundant update test.");
}

