import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserMetric";
import type { IPageIDiscussionBoardUserMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardUserMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * E2E test: Admin search for user-level discussion board metrics (analytics)
 *
 * This test validates the user metrics analytics search API, focusing on:
 *   - Filtering based on analytics fields (reputation, upvotes, etc.)
 *   - Paginated and sorted results
 *   - Full admin access (including records restricted from normal members)
 *   - Pagination metadata (current/total pages, record count, etc.)
 *   - Effectiveness of filters (that result set matches requested filter/window)
 *
 * Workflow:
 * 1. Register an admin account and authenticate the connection with admin rights.
 * 2. Register a sufficient number of member accounts (at least 4) and save their member ids.
 * 3. For each member, create analytic metric records with diverse field values (posts_count, votes, reports, etc.)
 * 4. As admin, perform a paginated search with default (no filters) and verify the full metric dataset is returned, with correct paging metadata.
 * 5. Perform filter-based searches (e.g., reputation above threshold, engagement window) and validate only expected records are returned.
 * 6. For records intended to be "admin-only" (simulate by having negative reputation), verify they are visible to admin in search results.
 * 7. Check that pagination metadata (current, limit, total, pages) matches the actual data returned and is consistent across requests.
 * 8. Edge case: filter producing no results returns an empty data set and correct pagination.
 */
export async function test_api_user_metrics_search_by_admin_success(connection: api.IConnection) {
  // 1. Register admin and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "A_secureP@ss12345";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminSignUp);
  connection.headers = {
    ...connection.headers,
    ...adminSignUp.setHeaders,
  };

  // 2. Register several members
  const memberCount = 4;
  const members: Array<IDiscussionBoardMember.ISessionProfile> = [];
  for (let i = 0; i < memberCount; ++i) {
    const email = typia.random<string & tags.Format<"email">>();
    const resp = await api.functional.auth.member.register.signUp(connection, {
      body: {
        email,
        password: "userPassw0rd!",
        nickname: RandomGenerator.name(),
        avatar_uri: null,
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(resp);
    members.push(resp.member);
  }

  // 3. For each member, create a diverse analytic user metric profile
  const metricInputs: IDiscussionBoardUserMetric.ICreate[] = [
    // High reputation, high upvotes
    {
      discussion_board_member_id: members[0].id,
      posts_count: 12,
      comments_count: 40,
      votes_up_given_count: 39,
      votes_down_given_count: 2,
      reports_made_count: 0,
      reputation_score: 250,
      last_activity_at: new Date().toISOString(),
    },
    // Negative reputation (simulate flagged)
    {
      discussion_board_member_id: members[1].id,
      posts_count: 2,
      comments_count: 9,
      votes_up_given_count: 0,
      votes_down_given_count: 15,
      reports_made_count: 10,
      reputation_score: -25,
      last_activity_at: new Date(Date.now() - 5 * 86400000).toISOString(),
    },
    // Moderate engagement
    {
      discussion_board_member_id: members[2].id,
      posts_count: 5,
      comments_count: 7,
      votes_up_given_count: 2,
      votes_down_given_count: 0,
      reports_made_count: 1,
      reputation_score: 20,
      last_activity_at: new Date(Date.now() - 2 * 86400000).toISOString(),
    },
    // Edge: no activity yet
    {
      discussion_board_member_id: members[3].id,
      posts_count: 0,
      comments_count: 0,
      votes_up_given_count: 0,
      votes_down_given_count: 0,
      reports_made_count: 0,
      reputation_score: 0,
      last_activity_at: null,
    },
  ];

  const metrics = [];
  for (const metricInput of metricInputs) {
    const metric = await api.functional.discussionBoard.admin.userMetrics.create(connection, {
      body: metricInput,
    });
    typia.assert(metric);
    metrics.push(metric);
  }

  // 4. Search: no filter, default paging
  const allResult = await api.functional.discussionBoard.admin.userMetrics.search(connection, {
    body: {},
  });
  typia.assert(allResult);
  TestValidator.predicate("should at least return all created analytic metric records")(
    allResult.data.length >= metrics.length,
  );
  TestValidator.equals("pagination total should be >= test data count")(
    allResult.pagination.records >= metrics.length,
  );

  // 5. Filter: reputation_score >= 20
  const goodRepResult = await api.functional.discussionBoard.admin.userMetrics.search(connection, {
    body: { reputation_score_min: 20 },
  });
  typia.assert(goodRepResult);
  TestValidator.predicate("every result has rep >= 20")(goodRepResult.data.every(x => x.reputation_score >= 20));
  TestValidator.predicate("filtered: only correct members")(
    goodRepResult.data.every(x =>
      [members[0].id, members[2].id].includes(x.discussion_board_member_id),
    ),
  );

  // 6. Filter: negative reputation (simulate admin-only or flagged)
  const flaggedResult = await api.functional.discussionBoard.admin.userMetrics.search(connection, {
    body: { reputation_score_max: -1 },
  });
  typia.assert(flaggedResult);
  TestValidator.predicate("flagged/low rep member visible to admin")(
    flaggedResult.data.some(x => x.discussion_board_member_id === members[1].id),
  );

  // 7. Pagination metadata validation
  TestValidator.equals("pagination current is 1 by default")(allResult.pagination.current)(1);
  TestValidator.equals("pagination limit has a value")(!!allResult.pagination.limit)(true);
  TestValidator.predicate("records >= metrics.length")(allResult.pagination.records >= metrics.length);
  TestValidator.predicate("pages >= 1")(allResult.pagination.pages >= 1);

  // 8. Search: filter for last_activity_after future date, expect no results
  const emptyResult = await api.functional.discussionBoard.admin.userMetrics.search(connection, {
    body: {
      last_activity_after: new Date(Date.now() + 7 * 86400000).toISOString(),
    },
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty result on future activity filter")(emptyResult.data.length)(0);
}

