 *
 * This test ensures that when an admin creates a privileged operation log entry, it can be immediately fetched by its unique ID using the appropriate endpoint. This validates that all audit trail and operation fields are included and consistent for security auditing, compliance, and dashboard scenarios.
 *
 * Step-by-step process:
 * 1. Create an operation log entry as admin to obtain a known operationLogId.
 * 2. Retrieve the full details of the created log by its id.
 * 3. Confirm that all critical audit and operation fields in the response match those from creation, and that types/formats are correct for auditing/compliance.
 */
export async function test_api_operation_log_fetch_detail_success_authorized(
  connection: api.IConnection,
) {
  // 1. Create a privileged operation log entry as admin
  const createInput: IDiscussionBoardOperationLog.ICreate = {
    action_type: "user_sanction",
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
    resource_table: "users",
    resource_id: typia.random<string & tags.Format<"uuid">>(),
    ip_address: "127.0.0.1",
    ua_string: "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
    action_details: JSON.stringify({ reason: "policy_violation", ban_length_days: 7 }),
  };
  const createdLog: IDiscussionBoardOperationLog = await api.functional.discussionBoard.admin.operationLogs.create(connection, {
    body: createInput,
  });
  typia.assert(createdLog);

  // 2. Retrieve the operation log by its id
  const fetchedLog: IDiscussionBoardOperationLog = await api.functional.discussionBoard.admin.operationLogs.at(connection, {
    operationLogId: createdLog.id,
  });
  typia.assert(fetchedLog);

  // 3. Confirm all key audit/operation fields match and types/formats are correct
  TestValidator.equals("id matches")(fetchedLog.id)(createdLog.id);
  TestValidator.equals("admin id matches")(fetchedLog.actor_admin_id)(createdLog.actor_admin_id);
