  TestValidator.predicate("created_at is ISO string")(!!Date.parse(fetchedLog.created_at));

  // Optional fields for moderator/member: should be undefined (not present) as created
  TestValidator.equals("moderator id undefined")(fetchedLog.actor_moderator_id)(undefined);
  TestValidator.equals("member id undefined")(fetchedLog.actor_member_id)(undefined);
