 * 4. Ensure the result matches the system's uniqueness policy. If UUID is auto-generated and duplicates are allowed, test should succeed. Otherwise, error assertion is expected.
 *
 * The test simulates both scenarios: successful duplicate creation (if system allows) and error (if not allowed).
 */
export async function test_api_operation_log_creation_duplicate_check(
  connection: api.IConnection,
) {
  // 1. Prepare operation log data (excluding readonly/generated fields like id/created_at)
  const logInput: IDiscussionBoardOperationLog.ICreate = {
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
