 *
 * This test validates the business-critical workflow for compliance audits: verifying that an admin can perform advanced filter and pagination searches over policy change logs. The filters tested include combinations of admin, namespace, table, field, date ranges, sorting, and pagination. The function ensures that search results respect applied filters, pagination returns the right number of results per page, and sorting operates correctly. Full auditability and regulatory review requirements are validated by this process.
 *
 * Steps:
 * 1. Create multiple policy change log records with different actor_admin_id, policy_namespace, target_table, target_field, and created_at values
 * 2. Perform advanced search requests using PATCH /discussionBoard/admin/policyChangeLogs with various filter combinations:
 *     a. By actor_admin_id
 *     b. By policy_namespace
 *     c. By target_table/target_field
 *     d. By date range (created_from, created_to)
 *     e. By sorting (asc, desc on created_at)
 *     f. By pagination (page/limit), confirming correct slicing and total record counts
 * 3. For each search, assert that results match filter constraints
 * 4. Test that pagination mechanics work as expected—correct records per page and navigation through pages
 *
 * This test ensures robust and compliant recordkeeping for audit and incident response scenarios.
 */
export async function test_api_policy_change_log_search_filters_success(
  connection: api.IConnection,
) {
  // 1. Create policy change log entries for different admins, namespaces, and fields
  const adminIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const namespaces = ["moderation", "user_signup"];
  const tables = ["discussion_policies", "user_settings"];
  const fields = ["max_comment_length", "signup_email_required"];
  const now = new Date();
  const createdLogIds: string[] = [];
  for (let i = 0; i < 8; ++i) {
    // Stagger creation times to enable date range filtering
    const createdAt = new Date(now.getTime() - i * 3600 * 1000).toISOString();
    const log = await api.functional.discussionBoard.admin.policyChangeLogs.create(
      connection,
      {
        body: {
          actor_admin_id: adminIds[i % 2],
          policy_namespace: namespaces[i % 2],
          target_table: tables[i % 2],
          target_field: fields[i % 2],
          previous_value: i % 2 === 0 ? "10" : "false",
          new_value: i % 2 === 0 ? (10 + i).toString() : (i % 3 === 0 ? "true" : "false"),
          change_reason: `Change reason ${i}`,
          previous_policy_change_id: i > 0 ? createdLogIds[i-1] : undefined,
        } satisfies IDiscussionBoardPolicyChangeLog.ICreate,
      }
    );
    typia.assert(log);
    // Patch created_at to match the simulated test timeline
    // (In a real test harness, you might patch the DB; here just track for searching)
    createdLogIds.push(log.id);
  }

  // 2. Test filtering by actor_admin_id
  const searchByAdmin = await api.functional.discussionBoard.admin.policyChangeLogs.search(
    connection,
    {
      body: {
        actor_admin_id: adminIds[0],
      } satisfies IDiscussionBoardPolicyChangeLog.IRequest,
    },
  );
  typia.assert(searchByAdmin);
  for (const x of searchByAdmin.data)
    TestValidator.equals("actor_admin_id matches filter")(x.actor_admin_id)(adminIds[0]);

  // 3. Test filtering by policy_namespace
  const searchByNamespace = await api.functional.discussionBoard.admin.policyChangeLogs.search(
    connection,
    {
      body: {
        policy_namespace: namespaces[1],
      } satisfies IDiscussionBoardPolicyChangeLog.IRequest,
    },
  );
  typia.assert(searchByNamespace);
  for (const x of searchByNamespace.data)
    TestValidator.equals("policy_namespace filter matches")(x.policy_namespace)(namespaces[1]);

  // 4. Test filtering by target_table/target_field
  const searchByTableField = await api.functional.discussionBoard.admin.policyChangeLogs.search(
    connection,
    {
      body: {
        target_table: tables[0],
        target_field: fields[0],
      } satisfies IDiscussionBoardPolicyChangeLog.IRequest,
    },
  );
  typia.assert(searchByTableField);
  for (const x of searchByTableField.data) {
    TestValidator.equals("target_table")(x.target_table)(tables[0]);
    TestValidator.equals("target_field")(x.target_field)(fields[0]);
  }

  // 5. Test date range filter (get logs created within last 3 hours)
  const created_from = new Date(now.getTime() - 3 * 3600 * 1000).toISOString();
  const searchByDate = await api.functional.discussionBoard.admin.policyChangeLogs.search(
    connection,
    {
      body: {
        created_from,
      } satisfies IDiscussionBoardPolicyChangeLog.IRequest,
    },
  );
  typia.assert(searchByDate);
  for (const x of searchByDate.data) {
    TestValidator.predicate("created_at within range")(new Date(x.created_at).getTime() >= new Date(created_from).getTime());
  }

  // 6. Test sorting (ascending by created_at)
  const searchAsc = await api.functional.discussionBoard.admin.policyChangeLogs.search(
    connection,
    {
      body: {
        sort_by: "created_at",
        sort_dir: "asc",
        limit: 3,
      } satisfies IDiscussionBoardPolicyChangeLog.IRequest,
    },
  );
  typia.assert(searchAsc);
  for (let i = 1; i < searchAsc.data.length; ++i) {
    TestValidator.predicate("ascending order")(
      new Date(searchAsc.data[i].created_at).getTime() >= new Date(searchAsc.data[i-1].created_at).getTime(),
    );
  }

  // 7. Test pagination: (limit 2, pages 1 and 2)
  const page1 = await api.functional.discussionBoard.admin.policyChangeLogs.search(
    connection,
    {
      body: {
        page: 1,
        limit: 2,
      } satisfies IDiscussionBoardPolicyChangeLog.IRequest,
    },
  );
  typia.assert(page1);
  TestValidator.equals("pagination page1 length")(page1.data.length)(2);
  TestValidator.equals("pagination page number")(page1.pagination.current)(1);

  const page2 = await api.functional.discussionBoard.admin.policyChangeLogs.search(
    connection,
    {
      body: {
        page: 2,
        limit: 2,
      } satisfies IDiscussionBoardPolicyChangeLog.IRequest,
    },
  );
  typia.assert(page2);
  TestValidator.equals("pagination page2 length")(page2.data.length)(2);
  TestValidator.equals("pagination page number")(page2.pagination.current)(2);
