  const impossible_admin_id: string = typia.random<string & tags.Format<"uuid">>();
  const future_from: string = new Date(Date.now() + 3 * 365 * 24 * 60 * 60 * 1000).toISOString(); // 3 years in the future
  const future_to: string = new Date(Date.now() + 4 * 365 * 24 * 60 * 60 * 1000).toISOString(); // 4 years in the future

  const result = await api.functional.discussionBoard.admin.policyChangeLogs.search(connection, {
