import type { IGuestAuthGuestValidateResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestValidateResponse";

/**
 * Validate a guest JWT token (freshly issued) using the session validation endpoint.
 *
 * Business context:
 * Ensures that a guest user – who does not create a full user account – can still obtain a JWT for API access as an anonymous visitor. This test confirms that the validation endpoint properly recognizes a freshly issued token as valid, simulating the actual guest workflow for anonymous access, rate limiting, and security checks.
 *
 * Steps:
 * 1. Simulate a guest login via the appropriate endpoint, providing realistic device and session metadata (user agent, IP address).
 * 2. Confirm the successful issuance of a guest JWT token in the login response.
 * 3. Submit the received token to the guest token validation endpoint, optionally echoing the metadata.
 * 4. Validate the API’s response: the token should be considered valid (valid === true), no error reason should be returned, and the session_token field (if present) should match expectations.
 */
export async function test_api_guest_jwt_validation_valid_token(connection: api.IConnection) {
  // 1. Perform guest login to obtain JWT token with realistic metadata
  const signInRequest: IGuestAuthGuestSignInRequest = {
    user_agent: RandomGenerator.alphabets(10),
    ip_address: `192.168.1.${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<254>>()}`,
  };
  const authResponse: IGuestAuthGuestSignInResponse = await api.functional.auth.guest.login.signIn(connection, {
    body: signInRequest,
  });
  typia.assert(authResponse);
  TestValidator.predicate("guest JWT token must be present and non-empty")(typeof authResponse.token === "string" && authResponse.token.length > 0);
  TestValidator.equals("Authorization header matches token")(authResponse.setHeaders.Authorization)(authResponse.token);

  // 2. Validate freshly issued JWT token
  const validateRequest: IGuestAuthGuestValidateRequest = {
    token: authResponse.token,
    user_agent: signInRequest.user_agent,
    ip_address: signInRequest.ip_address,
  };
  const validateResponse: IGuestAuthGuestValidateResponse = await api.functional.auth.guest.validate.validateToken(connection, {
    body: validateRequest,
  });
  typia.assert(validateResponse);
  TestValidator.equals("token is valid")(validateResponse.valid)(true);
  TestValidator.equals("no error reason")(validateResponse.reason)(undefined);
  TestValidator.equals("session_token, if present, is non-empty string or undefined")(typeof validateResponse.session_token === "string" || typeof validateResponse.session_token === "undefined")(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IGuestAuthGuestSignInRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInRequest";
import type { IGuestAuthGuestSignInResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestSignInResponse";
import type { IGuestAuthGuestValidateRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestValidateRequest";
import type { IGuestAuthGuestValidateResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IGuestAuthGuestValidateResponse";

/**
 * Validate that the system detects a tampered guest JWT and correctly rejects it.
 *
 * Businesses often must defend against token forgery or manipulation by validating JWT signatures. This test ensures that after a guest session successfully retrieves a token, if the token is modified even slightly (thus invalidating the cryptographic signature), the /auth/guest/validate endpoint returns a validation failure, not a false positive.
 *
 * Step-by-step process:
 * 1. Perform guest login to obtain a valid JWT token (via /auth/guest/login).
 * 2. Modify the acquired JWT by changing a single character in its signature part.
 * 3. Submit the tampered JWT to /auth/guest/validate along with user agent and IP used in step 1.
 * 4. Check the response: 'valid' must be false, and 'reason' should indicate invalidity (e.g., 'invalid', 'tampered', or similar).
 */
export async function test_api_guest_jwt_validation_invalid_signature(connection: api.IConnection) {
  // 1. Guest login: request a valid guest JWT
  const request: IGuestAuthGuestSignInRequest = {
    user_agent: RandomGenerator.alphabets(10),
    ip_address: [
      typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<255>>(),
      typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>(),
      typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>(),
      typia.random<number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<254>>()
    ].join("."),
  };
  const loginOutput: IGuestAuthGuestSignInResponse = await api.functional.auth.guest.login.signIn(connection, {
    body: request,
  });
  typia.assert(loginOutput);

  // 2. Tamper the JWT string: change a character (in signature part)
  let tamperedToken = loginOutput.token;
  const parts = tamperedToken.split('.');
  if (parts.length !== 3) throw new Error("JWT does not have 3 parts");
  let sig = parts[2];
  // Flip first character as a safe, minimal mutation
  const origChar = sig[0];
  let mutatedChar;
  if (origChar === 'A') mutatedChar = 'B';
  else if (origChar === 'B') mutatedChar = 'A';
  else mutatedChar = 'A';
  sig = mutatedChar + sig.slice(1);
  parts[2] = sig;
  tamperedToken = parts.join('.');

  // 3. Call /auth/guest/validate with tampered JWT
  const validationOutput: IGuestAuthGuestValidateResponse =
    await api.functional.auth.guest.validate.validateToken(connection, {
      body: {
        token: tamperedToken,
        user_agent: request.user_agent,
        ip_address: request.ip_address,
      },
    });
  typia.assert(validationOutput);

  // 4. Assert invalid token is detected
  TestValidator.equals("token should be invalid")(validationOutput.valid)(false);
  TestValidator.predicate("reason is present")(typeof validationOutput.reason === 'string' && validationOutput.reason.length > 0);
}

