/**
 * Validate successful discussion board member registration.
 *
 * This test simulates the process by which a new user signs up as a discussion board member using unique and valid registration data.
 * It checks the returned session for the expected JWT token, validates profile fields, and ensures email verification is set to pending (i.e., not completed at registration).
 * It does not test duplicate registration, which is covered by a separate scenario.
 *
 * Steps:
 * 1. Generate unique and valid registration data (email, strong password, unique nickname, optional avatar URI).
 * 2. Call the registration API endpoint to submit this data.
 * 3. Validate that the response includes a valid JWT token and well-formed session profile.
 * 4. Assert that email verification is pending (email_verified === false, status === 'pending_verification').
 * 5. Confirm that the returned profile and setHeaders data is structurally correct and matches input values where appropriate.
 */
export async function test_api_member_registration_success(connection: api.IConnection) {
  // Step 1: Generate unique and valid registration data
  const registration: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12), // Simulate a strong password
    nickname: RandomGenerator.alphabets(8), // Ensure uniqueness and length
    avatar_uri: Math.random() < 0.5 ? typia.random<string & tags.Format<"uri">>() : null,
  };

  // Step 2: Register the member
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: registration,
  });
  typia.assert(session);

  // Step 3: Validate that the response includes a JWT token and well-formed session profile
  TestValidator.predicate("JWT token present")(typeof session.token === "string" && session.token.length > 0);
  TestValidator.predicate("Authorization set in setHeaders")(
    session.setHeaders && typeof session.setHeaders.Authorization === "string" && session.setHeaders.Authorization.length > 0
  );

