 * This test ensures that after registering a new member (with email_verified: false and status: 'pending_verification'),
 * attempting to log in before email verification either fails (rejected login) or returns a session that reflects the limited status—according to business policy.
 * This covers the rule that members must verify their email before having full access.
 *
 * Steps:
 * 1. Register a new member account with a unique email, omitting any email verification flow.
 * 2. Attempt to log in immediately with the same credentials while the email is still unverified.
 * 3. Validate business rule:
 *    - Either login is rejected (error thrown),
 *    - Or, if permitted, login returns a session whose member.email_verified === false and status === 'pending_verification'.
 *
 * Notes:
 * - Edge case: ensures testing with a never-verified, freshly created member.
 * - This test does NOT trigger out-of-band verification flows or manual confirmation.
 * - Acceptable system behavior: strict login blocking, or restricted session with limited access and explicit email_verified === false.
 */
export async function test_api_member_login_unverified_email(connection: api.IConnection) {
  // 1. Register a new member (email_verified: false, status: 'pending_verification' by default)
  const registerInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "ValidPassw0rd!",
    nickname: RandomGenerator.name(),
    avatar_uri: undefined, // optional
  } satisfies IDiscussionBoardMember.ICreate;

  const registration = await api.functional.auth.member.register.signUp(connection, {
    body: registerInput,
  });
  typia.assert(registration);
  TestValidator.equals("registered member is initially unverified")(registration.member.email_verified)(false);
  TestValidator.equals("member status is pending_verification")(registration.member.status)("pending_verification");

