/**
 * Test that a member (the author of a comment) can successfully soft delete their own comment on a post.
 *
 * This test covers the following workflow:
 * 1. Register and authenticate a member user
 * 2. Create a new post as the member
 * 3. Add a comment to the post as the member (author)
 * 4. Soft-delete (logical delete) the comment using the appropriate API endpoint
 * 5. (Verification) Confirm that the comment's status is changed to 'deleted', and that the comment is no longer retrievable by normal comment queries.
 *
 * The test will assert that all creation flows work, and that the comment's status and deletion field are set by the erase call. Due to the absence of a direct comment read/query endpoint in the API, direct post-deletion verification of comment status is not possible and is noted accordingly below. All steps are performed in sequence and use only actual APIs and types provided.
 */
export async function test_api_member_comment_soft_delete_happy_path(connection: api.IConnection) {
  // 1. Register and authenticate a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: "password123!",
      nickname: memberNickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 2. Create a new post as that member
  const postTitle = RandomGenerator.paragraph()(1, 10);
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: postTitle,
      body: postBody,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Add a comment as the member
  const commentBody = RandomGenerator.paragraph()(3, 30);
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: commentBody,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("comment active")(comment.status)("active");
  TestValidator.equals("not deleted")(comment.deleted_at)(null);

  // 4. Soft-delete the comment
  await api.functional.discussionBoard.member.posts.comments.erase(connection, {
    postId: post.id,
    commentId: comment.id,
  });

  // 5. Verification: direct status check after delete is not possible (API does not expose comment fetch or list)
  // In a complete system, we would fetch the comment or comments for the post and verify the deleted status or missing from list
  // As this API does not expose those, the test ends here as per implementable scope
}

