/**
 * Validates that a moderator can soft-delete any comment on a post.
 *
 * Business context:
 * Moderators are expected to be able to perform moderation actions such as removing (soft deleting) comments regardless of authorship, for moderation and compliance reasons. Deletion should be a soft delete: comment remains in system but is marked as deleted (with deleted_at set, status changed).
 *
 * Steps:
 * 1. Register a new discussion board member, capturing their UUID and credentials.
 * 2. Register a new moderator (requires assigned_by_admin_email, so use random admin email), capturing moderator credentials/UUID.
 * 3. Member creates a discussion post (title and body per schema, category may be omitted or set null).
 * 4. Member, on their post, creates a comment (top-level, not a reply).
 * 5. Moderator logs in (no explicit login/SDK in the API, but registration provides token/setHeaders – after moderator registration, just perform following actions as moderator using session with correct Authorization).
 * 6. Using moderator Authorization, call eraseByPostidAndCommentid to soft delete member’s comment (pass correct postId and commentId).
 * 7. Fetch the comment again (cannot: API for fetch by ID of comment not exposed; omit this – only internal confirmation possible is via following steps if API existed).
 * 8. Final validation: since there is no comment fetch-by-ID, we cannot check status or deleted_at – but we can validate that erase completes without error, and all prior data was created and typia.assert-validated.
 * NOTE: If additional fetch or audit-log endpoints existed, add logic for status check and audit-log validation, but per current API, only creation/erase can be through E2E test.
 */
export async function test_api_moderator_comment_soft_delete_happy_path(connection: api.IConnection) {
  // 1. Register member (comment author)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Test123!";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name(),
    },
  });
  typia.assert(memberSession);

  // 2. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "ModTest!123";
  const adminEmail = typia.random<string & tags.Format<"email">>(); // Any random admin email for assignment
  const moderatorSession = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      assigned_by_admin_email: adminEmail,
    },
  });
  typia.assert(moderatorSession);

  // 3. Member creates a discussion board post
  connection.headers = { ...connection.headers, Authorization: memberSession.setHeaders.Authorization };
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(30),
      body: RandomGenerator.paragraph()(200),
    },
  });
  typia.assert(post);

  // 4. Member creates a comment on the post
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(50),
    },
  });
  typia.assert(comment);

  // 5. Switch to moderator session
  connection.headers = { ...connection.headers, Authorization: moderatorSession.setHeaders.Authorization };

  // 6. Moderator soft deletes the member's comment
  await api.functional.discussionBoard.moderator.posts.comments.erase(connection, {
    postId: post.id,
    commentId: comment.id,
  });
}

