/**
 * Test that deleting an already-soft-deleted comment returns an error.
 *
 * This test verifies that when a moderator attempts to delete a comment that has already been soft-deleted (i.e., logical deletion), the API returns a proper error indicating redundant deletion is not allowed. Ensures the backend business logic is robust, prevents repeated deletion actions, and provides appropriate error feedback.
 *
 * Workflow steps:
 * 1. Register a new discussion board member (member registration)
 * 2. Register a moderator (moderator registration)
 * 3. Using the member session, create a new post
 * 4. Using the member session, create a new comment on the post
 * 5. Switch to moderator session, delete the comment (soft-delete)
 * 6. Attempt to delete the same comment again (should fail)
 * 7. Confirm API responds with an error for redundant deletion
 */
export async function test_api_moderator_comment_soft_delete_already_deleted(connection: api.IConnection) {
  // 1. Register a member for posting and commenting
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "P@ssw0rd123!";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: RandomGenerator.name()
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberSession);

  // 2. Register a moderator for deletion actions
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "M0d3r@t0rPW!";
  const assignedByAdminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorSession = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: assignedByAdminEmail,
      password: moderatorPassword
    } satisfies IModerator.SignUp
  });
  typia.assert(moderatorSession);

  // 3. Member creates a post
  connection.headers = { ...connection.headers, Authorization: memberSession.setHeaders.Authorization };
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()(30)()
      // attachments/category omitted as they are optional for this test
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Member creates a comment for the post
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()(8)()
      // thread_parent_comment_id omitted for top-level
    } satisfies IDiscussionBoardComment.ICreate
  });
  typia.assert(comment);

  // 5. Switch to moderator session for soft deletion
  connection.headers = { ...connection.headers, Authorization: moderatorSession.setHeaders.Authorization };

  // Soft-delete the comment (first deletion)
  await api.functional.discussionBoard.moderator.posts.comments.erase(connection, {
    postId: post.id,
    commentId: comment.id
  });

  // 6. Attempt to delete already-deleted comment, expect error
  await TestValidator.error("cannot delete already-deleted comment")(
    async () => {
      await api.functional.discussionBoard.moderator.posts.comments.erase(connection, {
        postId: post.id,
        commentId: comment.id
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Verify that only admin users can soft delete comments via the admin endpoint, enforcing RBAC constraints.
 *
 * This test exercises attempted access to /discussionBoard/admin/posts/:postId/comments/:commentId DELETE endpoint with unauthorized user roles (member and moderator) and expects a forbidden (403) error, confirming that only admins are authorized to perform soft deletion of comments.
 *
 * Step-by-step process:
 * 1. Register a regular member user (unauthorized for admin endpoint).
 * 2. Register a moderator user (also unauthorized for admin endpoint).
 * 3. Register a separate member that will author the post and the comment.
 * 4. The comment-authoring member creates a new post.
 * 5. The same member creates a comment on that post.
 * 6. As the member user (not comment author), attempt to soft-delete the comment using the admin endpoint: expect 403 forbidden.
 * 7. As the moderator user, attempt to soft-delete the comment using the admin endpoint: expect 403 forbidden.
 *
 * This verifies RBAC for admin-only comment deletion functionality.
 */
export async function test_api_admin_comment_soft_delete_unauthorized_role(connection: api.IConnection) {
  // 1. Register a regular member (unauthorized)
  const memberUserEmail = typia.random<string & tags.Format<"email">>();
  const memberUser: IDiscussionBoardMember.ISession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberUserEmail,
      password: "MemberPass!123",
      nickname: RandomGenerator.name(),
    },
  });
  typia.assert(memberUser);

  // 2. Register a moderator
  const assigningAdminEmail = `admin+${RandomGenerator.alphaNumeric(6)}@test.com`;
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: assigningAdminEmail,
      password: "Moderat0rPass!",
    },
  });
  typia.assert(moderatorSignUp);

  // 3. Register a separate member as author
  const authorEmail = typia.random<string & tags.Format<"email">>();
  const authorUser: IDiscussionBoardMember.ISession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: authorEmail,
      password: "AuthorPass!123",
      nickname: RandomGenerator.name(),
    },
  });
  typia.assert(authorUser);

  // Switch to author session for post/comment creation
  connection.headers = { ...connection.headers, ...authorUser.setHeaders };

  // 4. Create a post as author
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1, 3),
      body: RandomGenerator.content()()(1, 5),
      // category_id, platform_config_id, attachments: optional, omitted
    },
  });
  typia.assert(post);

  // 5. Add a comment as author
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(1, 2),
      // thread_parent_comment_id: optional, omitted to make it top-level
    },
  });
  typia.assert(comment);

  // 6. Switch to member user and attempt forbidden deletion
  connection.headers = { ...connection.headers, ...memberUser.setHeaders };
  await TestValidator.error("Member cannot soft-delete comment using admin endpoint")(
    () => api.functional.discussionBoard.admin.posts.comments.erase(connection, {
      postId: post.id,
      commentId: comment.id,
    })
  );

  // 7. Switch to moderator session and attempt forbidden deletion
  connection.headers = { ...connection.headers, ...moderatorSignUp.setHeaders };
  await TestValidator.error("Moderator cannot soft-delete comment using admin endpoint")(
    () => api.functional.discussionBoard.admin.posts.comments.erase(connection, {
      postId: post.id,
      commentId: comment.id,
    })
  );
}

