import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate admin search for post votes supports pagination and handles invalid filters robustly.
 *
 * This test ensures that the admin post vote search endpoint correctly processes pagination requests and deals robustly with invalid filter parameters (non-existent memberId or postId). It validates that the API does not crash, break pagination, or behave unexpectedly, and that it returns either an empty result or an appropriate error (not a transport or server error) when filters do not match existing records.
 *
 * 1. Register a new admin user to obtain authorization.
 * 2. Attempt to search for post votes with a non-existent discussion_board_member_id filter.
 * 3. Confirm the API returns an empty result set and valid pagination metadata, without errors or instabilities.
 * 4. Attempt to search for post votes with a non-existent discussion_board_post_id filter.
 * 5. Confirm the API again returns an empty result, correct pagination metadata, and no errors.
 * 6. Optionally, try invalid pagination parameters (e.g., page=1000000) and confirm robust empty handling or appropriate validation.
 *
 * All responses must pass type assertion and API must remain stable for all scenarios.
 */
export async function test_api_admin_post_vote_search_pagination_and_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const adminAuth: IDiscussionBoardAdminAuthResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAuth);
  // Set admin JWT header for authorization
  connection.headers = { ...connection.headers, ...adminAuth.setHeaders };

  // 2. Search with a non-existent member ID filter
  const outputByMember: IPageIDiscussionBoardPostVote = await api.functional.discussionBoard.admin.postVotes.search(connection, {
    body: {
      discussion_board_member_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(outputByMember);
  TestValidator.equals("empty results - memberId")(outputByMember.data.length)(0);
  TestValidator.predicate("valid pagination - memberId")(outputByMember.pagination !== undefined && outputByMember.pagination.current === 1);

  // 3. Search with a non-existent post ID filter
  const outputByPost: IPageIDiscussionBoardPostVote = await api.functional.discussionBoard.admin.postVotes.search(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(outputByPost);
  TestValidator.equals("empty results - postId")(outputByPost.data.length)(0);
  TestValidator.predicate("valid pagination - postId")(outputByPost.pagination !== undefined && outputByPost.pagination.current === 1);

  // 4. Search with an absurdly high page number to confirm stable pagination/empty results
  const outputHighPage: IPageIDiscussionBoardPostVote = await api.functional.discussionBoard.admin.postVotes.search(connection, {
    body: {
      page: 1000000,
      limit: 10,
    } satisfies IDiscussionBoardPostVote.IRequest,
  });
  typia.assert(outputHighPage);
  TestValidator.predicate("no crash on high page")(outputHighPage.data.length === 0 || outputHighPage.pagination.current === 1000000);
}

