import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test successful retrieval of all comments for a given postId.
 *
 * This test validates end-to-end commenting and retrieval on the discussion board:
 * 1. Register a member (to gain privileges for posting and commenting)
 * 2. Create a post as this member and obtain its postId
 * 3. Add several top-level comments to the post
 * 4. For at least one top-level comment, add replies (nested/threaded comments)
 * 5. Use the comment search endpoint (PATCH /discussionBoard/posts/{postId}/comments) to retrieve paginated comments
 * 6. Validate that all added comments, both top-level and replies, are present in the result set with correct relationships
 * 7. Test comment pagination by limiting result size and using page parameter
 * 8. Test comment sorting with ascending/descending created_at
 * 9. Ensure only 'active' status comments are visible per typical role-based rules
 */
export async function test_api_comment_search_by_post_id_success(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "StrongPass!42",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);
  const memberId = memberSession.member.id;

  // 2. Create a post as this member
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()()(30),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);
  const postId = post.id;

  // 3. Add several top-level comments
  const topLevelComments: IDiscussionBoardComment[] = [];
  for (let i = 0; i < 3; ++i) {
    const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
      postId,
      body: {
        body: `Top-level comment #${i + 1}: ` + RandomGenerator.paragraph()(4),
      } satisfies IDiscussionBoardComment.ICreate,
    });
    typia.assert(comment);
    topLevelComments.push(comment);
  }

  // 4. Add replies to the first top-level comment
  const replies: IDiscussionBoardComment[] = [];
  for (let j = 0; j < 2; ++j) {
    const reply = await api.functional.discussionBoard.member.posts.comments.create(connection, {
      postId,
      body: {
        body: `Reply #${j + 1} to top-level #1: ` + RandomGenerator.paragraph()(3),
        thread_parent_comment_id: topLevelComments[0].id,
      } satisfies IDiscussionBoardComment.ICreate,
    });
    typia.assert(reply);
    replies.push(reply);
  }

  // 5. Retrieve all comments (default page/sort)
  const searchResult = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId,
    body: {
      post_id: postId,
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(searchResult);

  // 6. Validate that each comment is present by ID
  const returnedIds = searchResult.data.map((c) => c.id);
  for (const comment of topLevelComments) {
    TestValidator.predicate("Top-level comment is present")(returnedIds.includes(comment.id));
  }
  for (const reply of replies) {
    const found = searchResult.data.find(
      (c) => c.id === reply.id && c.thread_parent_comment_id === topLevelComments[0].id,
    );
    TestValidator.predicate("Reply comment present and correctly threaded")(!!found);
  }

  // 7. Search with pagination (limit=2, page=1)
  const paged = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId,
    body: {
      post_id: postId,
      limit: 2,
      page: 1,
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(paged);
  TestValidator.predicate("Paged result limited to 2 items and correct page")(
    paged.data.length <= 2 && paged.pagination.current === 1,
  );

  // 8. Test sorting (ascending vs descending on created_at)
  const ascResult = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId,
    body: {
      post_id: postId,
      sort_by: "created_at",
      sort_direction: "asc",
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(ascResult);
  const descResult = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId,
    body: {
      post_id: postId,
      sort_by: "created_at",
      sort_direction: "desc",
    } satisfies IDiscussionBoardComment.IRequest,
  });
  typia.assert(descResult);
  if (ascResult.data.length >= 2 && descResult.data.length >= 2) {
    TestValidator.notEquals("Order of asc and desc differs")(
      ascResult.data[0].id
    )(descResult.data[0].id);
  }

  // 9. Ensure 'active' status for all returned comments
  for (const comment of searchResult.data) {
    TestValidator.equals("Returned comment is active")(comment.status)("active");
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validate advanced comment list filtering, sorting, and pagination for a forum post.
 *
 * Business context: Listing comments under a given post is used for threaded discussion UX. Forums must support large volumes of comments with rich UI search and paging, including filtering by status/author/thread, ordering, and controlling page size for performance.
 *
 * This test covers UI/UX and backend business rules for comment list API including:
 *   - Setup: Register a member, create a post, add sufficient comments (and some replies) for paging (20+)
 *   - Filtering: by author; by parent (show only top/comments/replies)
 *   - Sorting: by creation date ascending and descending
 *   - Pagination: check page 1, next/last page, enforced min=1 and max=100 page sizes, empty result handling
 *   - Edge Cases: Exactly one page, request beyond last page, invalid limits, filtering w/ no matches
 *   - Security: Ensure deleted/hidden comments status are only visible to creator (via status filter), not by unrelated members
 *
 * Test Flow:
 * 1. Register and authenticate a new member.
 * 2. Create a new post as this member.
 * 3. Add top-level and threaded comments (e.g., 15 top-level, 5 replies).
 * 4. List comments with default params: verify correct data, proper page size, ordering by created_at (default sort).
 * 5. Fetch with explicit sort descending and page 1, confirm ordering is reversed.
 * 6. Fetch replies-only (filter by parent_comment_id).
 * 7. Filter by author_member_id: expect only their comments.
 * 8. Try limit=150 (over max): should clamp/fail to 100 per policy.
 * 9. Page beyond last page: expect empty results with accurate pagination meta.
 * 10. Filter by status='deleted'/'hidden': should not see unless creator; verify as other member (register), no results on those statuses.
 * 11. Attempt invalid (zero/negative/too high) page/limit values, expect validation error or fallback to policy.
 */
export async function test_api_comment_search_pagination_and_filtering(
  connection: api.IConnection,
) {
  // Step 1: Register primary member
  const email: string = typia.random<string & tags.Format<"email">>();
  const nickname: string = RandomGenerator.name();
  const password: string = RandomGenerator.alphaNumeric(10);
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname,
      avatar_uri: null,
    },
  });
  const member = session.member;
  typia.assert(member);

  // Step 2: Create a new post as this member
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(10).slice(0, 100),
      body: RandomGenerator.content()(3)(3).slice(0, 4000),
      category_id: null,
      platform_config_id: null,
      attachments: null,
    },
  });
  typia.assert(post);

  // Step 3: Add top-level and threaded comments (threaded "replies").
  const topComments: IDiscussionBoardComment[] = await ArrayUtil.asyncRepeat(15)(async () => {
    const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body: RandomGenerator.paragraph()(5).slice(0, 1000),
      },
    });
    typia.assert(comment);
    return comment;
  });
  // Add replies (threaded comments) to some of the top-level comments
  const replies: IDiscussionBoardComment[] = await ArrayUtil.asyncRepeat(5)(async () => {
    const parent = RandomGenerator.pick(topComments);
    const reply = await api.functional.discussionBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body: RandomGenerator.paragraph()(3).slice(0, 1000),
        thread_parent_comment_id: parent.id,
      },
    });
    typia.assert(reply);
    return reply;
  });
  const allComments: IDiscussionBoardComment[] = [...topComments, ...replies];

  // Step 4: List comments with default params (page 1)
  const page1 = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
    },
  });
  typia.assert(page1);
  TestValidator.predicate("page1 has comments")(page1.data.length > 0);
  TestValidator.equals("pagination page 1 is 1")(page1.pagination.current)(1);

  // Step 5: Fetch with sort desc and page 1, check ordering
  const desc = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      sort_by: "created_at",
      sort_direction: "desc",
    },
  });
  typia.assert(desc);
  if (desc.data.length > 1) {
    TestValidator.predicate("descending order")(desc.data[0].created_at >= desc.data[1].created_at);
  }

  // Step 6: Fetch replies-only for a random parent (parent_comment_id)
  if (replies.length > 0) {
    const parentId = replies[0].thread_parent_comment_id!;
    const childList = await api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        post_id: post.id,
        parent_comment_id: parentId,
      },
    });
    typia.assert(childList);
    TestValidator.predicate("replies have correct parent")(
      childList.data.every(d => d.thread_parent_comment_id === parentId),
    );
  }

  // Step 7: Filter by author_member_id
  const byAuthor = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      author_member_id: member.id,
    },
  });
  typia.assert(byAuthor);
  TestValidator.predicate("all comments belong to member")(
    byAuthor.data.every(d => d.author_role === "member" && d.author_display_name === nickname),
  );

  // Step 8: limit>100 (should clamp/cap to 100)
  const bigLimit = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      limit: 150,
    },
  });
  typia.assert(bigLimit);
  TestValidator.predicate("limit clamped to 100")(bigLimit.pagination.limit === 100);

  // Step 9: Page beyond last page (expect empty)
  const beyond = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      page: 9999,
    },
  });
  typia.assert(beyond);
  TestValidator.equals("beyond page is empty")(beyond.data.length)(0);

  // Step 10: Filter by status=deleted (should be empty; no deleted comments present)
  const deleted = await api.functional.discussionBoard.posts.comments.search(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      status: "deleted",
    },
  });
  typia.assert(deleted);
  TestValidator.equals("deleted filtered is empty")(deleted.data.length)(0);

  // Step 11: Invalid limits/pages (should error)
  await TestValidator.error("limit=0 should error")(
    () => api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        post_id: post.id,
        limit: 0,
      },
    }),
  );
  await TestValidator.error("limit=-3 should error")(
    () => api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        post_id: post.id,
        limit: -3,
      },
    }),
  );
  await TestValidator.error("page=0 should error")(
    () => api.functional.discussionBoard.posts.comments.search(connection, {
      postId: post.id,
      body: {
        post_id: post.id,
        page: 0,
      },
    }),
  );
}

