    body: RandomGenerator.paragraph()(30),
  } satisfies IDiscussionBoardComment.ICreate;
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: commentBody
  });
  typia.assert(comment);

  // 4. Create a reply (child) comment
  const replyBody = {
    body: RandomGenerator.content()()(20),
    thread_parent_comment_id: comment.id
  } satisfies IDiscussionBoardComment.ICreate;
  const reply = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: replyBody
  });
  typia.assert(reply);

  // 5. Retrieve the top-level comment by postId and commentId
  const retrieved = await api.functional.discussionBoard.posts.comments.at(connection, {
    postId: post.id,
    commentId: comment.id
  });
  typia.assert(retrieved);

  // 6. Assert that returned fields match what was created
  TestValidator.equals("post id")(retrieved.post_id)(post.id);
  TestValidator.equals("comment id")(retrieved.id)(comment.id);
  TestValidator.equals("body")(retrieved.body)(comment.body);
  TestValidator.equals("status")(retrieved.status)("active");
  TestValidator.equals("thread_parent_comment_id")(retrieved.thread_parent_comment_id)(null);
  TestValidator.equals("author_member_id")(retrieved.author_member_id)(signUp.member.id);

  // 7. Retrieve and check the reply (child) comment
  const replyRetrieved = await api.functional.discussionBoard.posts.comments.at(connection, {
    postId: post.id,
    commentId: reply.id
  });
  typia.assert(replyRetrieved);
  TestValidator.equals("parent linkage")(replyRetrieved.thread_parent_comment_id)(comment.id);
  TestValidator.equals("body")(replyRetrieved.body)(reply.body);
  TestValidator.equals("author_member_id")(replyRetrieved.author_member_id)(signUp.member.id);
}

