import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: Admin successful search of subcategories under a parent category.
 *
 * Purpose: Ensure admin can retrieve all immediate subcategories under a category,
 * with proper filtering and pagination as per UI and API contract.
 *
 * Business context: Category management UI (taxonomy/tree editor) for discussion board/forum.
 *
 * Steps:
 * 1. Create a parent category as admin.
 * 2. Create several subcategories under that parent with varying parameters.
 * 3. Retrieve and verify all subs (no filter).
 * 4. Retrieve with partial name filter.
 * 5. Retrieve only enabled subs (true).
 * 6. Retrieve only disabled subs (false).
 * 7. Paginate + order by display_order descending.
 * 8. Validate that audit and hierarchy fields are present and correct on results.
 */
export async function test_api_admin_subcategory_search_success(
  connection: api.IConnection,
) {
  // 1. Create parent category
  const parent = await api.functional.discussionBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphabets(10),
        display_order: 1,
        enabled: true,
        version: 1,
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(parent);

  // 2. Create multiple subcategories with controlled test fields
  const subDefs = [
    { name: "AlphaSub", enabled: true, display_order: 1 },
    { name: "BetaSub", enabled: false, display_order: 2 },
    { name: "GammaSub", enabled: true, display_order: 3 },
    { name: "SubDelta", enabled: true, display_order: 4 },
  ];
  const subs = [];
  for (const def of subDefs) {
    const sub = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(
      connection,
      {
        categoryId: parent.id,
        body: {
          name: def.name,
          display_order: def.display_order,
          enabled: def.enabled,
          version: 1,
          parent_id: parent.id,
        } satisfies IDiscussionBoardCategory.ICreate,
      },
    );
    typia.assert(sub);
    subs.push(sub);
  }

  // 3. Retrieve all subs (no filter)
  const all = await api.functional.discussionBoard.admin.categories.subs.searchSub(
    connection,
    {
      categoryId: parent.id,
      body: {} satisfies IDiscussionBoardCategory.IRequest,
    },
  );
  typia.assert(all);
  TestValidator.equals("all immediate subcount")(all.data.length)(subs.length);

  // 4. Filter by partial name ('Sub')
  const filterName = await api.functional.discussionBoard.admin.categories.subs.searchSub(
    connection,
    {
      categoryId: parent.id,
      body: { name: "Sub" } satisfies IDiscussionBoardCategory.IRequest,
    },
  );
  typia.assert(filterName);
  TestValidator.predicate("filtered only name contains 'Sub'")(
    filterName.data.every((cat) => cat.name.includes("Sub")),
  );

  // 5. Filter by enabled true
  const filterEnabled = await api.functional.discussionBoard.admin.categories.subs.searchSub(
    connection,
    {
      categoryId: parent.id,
      body: { enabled: true } satisfies IDiscussionBoardCategory.IRequest,
    },
  );
  typia.assert(filterEnabled);
