/**
 * Test access control for the subcategory search endpoint.
 *
 * This test verifies that only admins and moderators are allowed to access the subcategory search endpoint (`/discussionBoard/admin/categories/{categoryId}/subs`).
 * Specifically, it creates a registered member and issues a guest session, then tries to invoke the endpoint as both member and guest, expecting each attempt to be denied with an authorization error (i.e., forbidden).
 *
 * This ensures proper API access control for taxonomy management endpoints and helps prevent privilege escalation or unauthorized discovery of category structure.
 *
 * Steps:
 * 1. Register a member and acquire their JWT session
 * 2. Issue a guest session token for anonymous/guest user
 * 3. Attempt to search subcategories as the registered member (should be denied)
 * 4. Attempt to search subcategories as the guest (should be denied)
 *
 * The test expects errors and does not require category setup or admin session, as only rejection is validated.
 */
export async function test_api_admin_subcategory_search_access_control(connection: api.IConnection) {
  // 1. Register a member and get JWT session
  const memberEmail = typia.random<string & tags.Format<"email">>();
