    body: {
      email: memberEmail,
      password: "Test1234!",
      nickname: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberSession);

  // 2. Issue guest session
  const guestSession = await api.functional.auth.guest.login.signIn(connection, {
    body: {
      user_agent: RandomGenerator.alphaNumeric(16),
      ip_address: "127.0.0.1"
    }
  });
  typia.assert(guestSession);

  // Test data for endpoint
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const body: IDiscussionBoardCategory.IRequest = {};

