  const memberConn = { ...connection, headers: { ...connection.headers, Authorization: memberSession.setHeaders.Authorization } };
  await TestValidator.error("Member should not access subcategory admin API")(() =>
    api.functional.discussionBoard.admin.categories.subs.searchSub(memberConn, { categoryId, body })
  );

  // 4. Attempt as guest (should fail)
  const guestConn = { ...connection, headers: { ...connection.headers, Authorization: guestSession.setHeaders.Authorization } };
  await TestValidator.error("Guest should not access subcategory admin API")(() =>
    api.functional.discussionBoard.admin.categories.subs.searchSub(guestConn, { categoryId, body })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
