import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate that a moderator can search and retrieve subcategories immediately under a parent category.
 *
 * Business context:
 * Moderators need to manage forum taxonomy trees for content assignment. This test ensures a moderator can view the subcategories for a parent category created by an admin, confirming that taxonomy visibility and permissions boundaries are correctly enforced.
 *
 * Steps:
 * 1. Register a moderator account, noting the Authorization token for future API calls.
 * 2. As admin, create a new parent (root) discussion board category.
 * 3. As admin, create at least two subcategories beneath this parent using its id.
 * 4. Switch the API session to use the moderator’s token (simulate login/session switch for testing authorization).
 * 5. Invoke the moderator's subcategory search API, filtering by the newly created parent.
 * 6. Assert that all created subcategories are returned and reference the correct parent.
 * 7. Assert that audit and display fields (created_at, updated_at, enabled, etc) are present and that the response does not expose admin-only or sensitive data fields.
 */
export async function test_api_moderator_subcategory_search_success(connection: api.IConnection) {
  // 1. Register a moderator account (as an admin by providing assigned_by_admin_email)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = "Moderator#123";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: moderatorPassword
    }
  });
  typia.assert(moderatorSignUp);

  // 2. As admin, create a root/parent category
  const parentCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      display_order: 1,
      enabled: true,
      version: 1
    }
  });
  typia.assert(parentCategory);

  // 3. As admin, create at least two subcategories under parent
  const subcategories = await ArrayUtil.asyncRepeat(2)(async (i) => {
    const subcat = await api.functional.discussionBoard.admin.categories.subs.createSubCategory(connection, {
      categoryId: parentCategory.id,
      body: {
        name: RandomGenerator.alphabets(8),
        display_order: i + 1,
        enabled: true,
        version: 1
      }
    });
    typia.assert(subcat);
    return subcat;
  });

  // 4. Switch session to moderator by updating Authorization (simulate login)
  connection.headers = { ...connection.headers, Authorization: moderatorSignUp.setHeaders.Authorization };

  // 5. As moderator, search for subcategories under parent category
  const result = await api.functional.discussionBoard.moderator.categories.subs.searchSub(connection, {
    categoryId: parentCategory.id,
    body: { parent_id: parentCategory.id }
  });
  typia.assert(result);

  // 6. Validate each created subcategory is present in the response and parent_id matches
  const resultIds = result.data.map(c => c.id);
  for (const subcat of subcategories) {
    TestValidator.predicate("subcategory is present")(resultIds.includes(subcat.id));
    TestValidator.equals("parent id matches")(subcat.parent_id)(parentCategory.id);
  }

  // 7. Ensure response includes expected audit + display fields and does not leak admin-only data
  for (const subcat of result.data) {
    TestValidator.predicate("subcat has created_at")(typeof subcat.created_at === "string");
    TestValidator.predicate("subcat has updated_at")(typeof subcat.updated_at === "string");
    TestValidator.predicate("subcat has version")(typeof subcat.version === "number");
    TestValidator.predicate("subcat has name")(typeof subcat.name === "string");
    TestValidator.predicate("subcat has display_order")(typeof subcat.display_order === "number");
    TestValidator.predicate("subcat has enabled")(typeof subcat.enabled === "boolean");
    TestValidator.predicate("no admin-leak fields")(Object.keys(subcat).every(k => [
      "id", "parent_id", "name", "description", "display_order", "icon_uri", "enabled", "version", "created_at", "updated_at", "deleted_at"
    ].includes(k)));
  }
}

