 *
 * ## Steps
 * 1. Register a new discussion board member, capturing initial profile and authentication context
 * 2. Build valid profile updates (nickname and avatar_uri)
 * 3. Submit the update using the authenticated session
 * 4. Assert that the updated fields are returned and audit (updated_at) is newer
 * 5. Confirm email/id remain unchanged and other business audit fields (joined_at, status) are consistent
 */
export async function test_api_member_profile_self_update_success(
  connection: api.IConnection,
) {
  // 1. Register a new member for the test
  const registrationInput: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    nickname: RandomGenerator.alphaNumeric(8),
