 *
 * This test ensures the endpoint:
 * - Returns empty data (pagination and result array) for non-matching filters (such as random UUIDs, non-existent status, unregistered reasons, and out-of-range dates).
 * - Properly throws errors for requests with invalid input such as page below 1, limit below 1, badly formatted dates, or non-UUID strings where UUID is required.
 *
 * Steps:
 * 1. Register a member (to ensure data context exists).
 * 2. Create a discussion board post as that member.
 * 3. Admin searches for post reports with random/mismatched filters and expects empty array and zero records.
 * 4. Admin searches using obviously invalid filter values for error scenarios: page below minimum, limit below minimum, malformed dates, and malformed UUIDs.
 */
export async function test_api_post_report_search_admin_empty_results_and_error_handling(connection: api.IConnection) {
  // 1. Register a member
  const email = typia.random<string & tags.Format<"email">>();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password: "Test1234!@#",
      nickname: RandomGenerator.name(),
      avatar_uri: null
    }
  });
