  // 2. Create a post as the registered member
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      category_id: null,
      platform_config_id: null,
      title: RandomGenerator.alphaNumeric(16),
      body: RandomGenerator.paragraph()(),
      attachments: null
    }
  });
  typia.assert(post);

  // 3. Admin searches for post reports with non-matching filters (random UUIDs, fake status/reason values, out-of-range dates)
  const emptyResult = await api.functional.discussionBoard.admin.postReports.search(connection, {
    body: {
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussion_board_member_id: typia.random<string & tags.Format<"uuid">>(),
      handler_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason_type: "nonexistent-reason",
      status: "resolved-not-a-status",
      created_from: "2000-01-01T00:00:00.000Z",
      created_to: "2000-01-02T00:00:00.000Z",
      order_by: "created_at",
      direction: "asc",
      page: 1,
      limit: 10
    }
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty result data")(emptyResult.data)([]);
  TestValidator.equals("empty result size")(emptyResult.pagination.records)(0);

  // 4. Admin searches for post reports with intentionally invalid input (should throw errors)
  await TestValidator.error("page too small")(() =>
    api.functional.discussionBoard.admin.postReports.search(connection, {
      body: {
        page: 0, // invalid (minimum is 1)
        limit: 10
      }
    })
  );

  await TestValidator.error("limit too small")(() =>
    api.functional.discussionBoard.admin.postReports.search(connection, {
      body: {
        page: 1,
        limit: 0 // invalid (minimum is 1)
      }
    })
  );

  await TestValidator.error("bad date format")(() =>
    api.functional.discussionBoard.admin.postReports.search(connection, {
      body: {
        page: 1,
        limit: 10,
        created_from: "notadate"
      }
    })
  );

  await TestValidator.error("bad uuid")(() =>
    api.functional.discussionBoard.admin.postReports.search(connection, {
      body: {
        page: 1,
        limit: 10,
        discussion_board_post_id: "this-is-not-a-uuid"
      }
    })
  );
}

