import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate no-results search functionality for discussion board category search (admin endpoint).
 *
 * This test verifies that searching the discussion board categories with a filter that matches no existing data (for example, a non-existent name pattern or an enabled status value not present in the dataset) does not produce an error and returns a proper paginated empty result set.
 *
 * Steps:
 * 1. Perform a category search with a 'name' filter using a random, non-existent string pattern.
 * 2. Assert that the returned data array is empty.
 * 3. Assert that pagination metadata is supplied and records/pages are zero.
 * 4. Perform a category search with a strict status filter (such as enabled=false, assuming all current categories are enabled).
 * 5. Assert the result is also an empty data set with correct zero-count pagination.
 */
export async function test_api_category_search_admin_no_results(
  connection: api.IConnection,
) {
  // 1. Search with a random, non-existent category name
  const randomName = `no-category-${typia.random<number & tags.Type<"int32">>()}-${Date.now()}`;
  const nameSearch = await api.functional.discussionBoard.admin.categories.search(connection, {
    body: {
      name: randomName,
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardCategory.IRequest,
  });
  typia.assert(nameSearch);
  // 2. Assert that no records are returned
  TestValidator.equals("no results for non-existent name")(nameSearch.data.length)(0);
  TestValidator.equals("zero records")(nameSearch.pagination.records)(0);
  TestValidator.equals("zero pages")(nameSearch.pagination.pages)(0);

  // 3. Search for disabled categories, assuming all are enabled initially
  const disabledSearch = await api.functional.discussionBoard.admin.categories.search(connection, {
    body: {
      enabled: false,
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardCategory.IRequest,
  });
  typia.assert(disabledSearch);
  TestValidator.equals("no disabled categories")(disabledSearch.data.length)(0);
  TestValidator.equals("zero records")(disabledSearch.pagination.records)(0);
  TestValidator.equals("zero pages")(disabledSearch.pagination.pages)(0);
}

