/**
 * Validate search for discussion board categories as a moderator where no results should be found.
 *
 * This test ensures that when a moderator performs a category search using filters that do not match any existing categories (such as a random substring for the name or an impossible parent_id), the API correctly returns an empty page with valid pagination metadata, and does not throw an error. This is essential to verify that empty searches are correctly handled and do not cause failures for moderator users.
 *
 * Steps:
 * 1. Register a new moderator (obtain authentication for a fresh moderator account).
 * 2. As the moderator, perform a category search with a filter known to match no categories (e.g., name=random large/rare string, or parent_id=random UUID guaranteed not to exist).
 * 3. Assert that the returned page contains zero data items, and all pagination metadata (current, limit, records, pages) are coherent.
 * 4. Assert no error is thrown and API responds successfully.
 */
export async function test_api_category_search_moderator_no_results(connection: api.IConnection) {
  // 1. Register a new moderator (for authentication)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const signUpResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      assigned_by_admin_email: adminEmail,
      password: "test1234!"
    }
  });
  typia.assert(signUpResp);
  // Moderator is now authenticated (token set via SDK auto-injection)

  // 2. Search categories with a filter known to return no results
  // Option A: use a random string in 'name' unlikely to match
  const impossibleName = "zzzzzzzzzz_no_such_category_zzzzzzzzzz";
  const page = await api.functional.discussionBoard.moderator.categories.search(connection, {
    body: {
      name: impossibleName,
      limit: 10,
      page: 1
    }
  });
  typia.assert(page);

  // 3. Assert returned data array is empty
  TestValidator.equals("empty results")(page.data.length)(0);

  // 4. Assert pagination metadata is consistent
  TestValidator.equals("zero records")(page.pagination.records)(0);
  TestValidator.equals("zero pages")(page.pagination.pages)(0);
  TestValidator.equals("current page 1")(page.pagination.current)(1);
  TestValidator.equals("limit 10")(page.pagination.limit)(10);
}

