  TestValidator.equals("moderator email matches")(modReg.email)(moderatorEmail);
  TestValidator.equals("status should be active")(modReg.status)("active");

  // 3. Admin soft-deletes the moderator
  await api.functional.discussionBoard.admin.moderators.erase(connection, {
    moderatorId: modReg.moderator_id,
  });

  // 4. (If a GET/status check existed, verify that status is now 'revoked' and deleted_at is set.)
