 * 2. As a logged-in admin, request PATCH /discussionBoard/admin/admins using filters for status and assigned_at.
 * 3. Verify that only admins matching filters are returned.
 * 4. Assert that pagination works as expected (batch size, page count, totals, correctness). 
 * 5. Verify all returned admin records only contain id, email, status, assigned_at, revoked_at fields (no extra/sensitive info).
 * 6. Optionally, test that a request without admin authentication fails (if supported).
 */
export async function test_api_admin_search_successful_pagination_and_filters(connection: api.IConnection) {
  // 1. Register multiple admin accounts
  const createdAdmins = await Promise.all([
    // Admin A: active, assigned now
    api.functional.auth.admin.register.signUp(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "Password1!"
      } satisfies IDiscussionBoardAdmin.ICreate
