/**
 * Validate that posts with status 'hidden' or 'deleted' cannot be accessed by unauthorized users (guest or regular members).
 *
 * This test covers discussion board content visibility and API access control workflows as follows:
 *
 * 1. Register a normal discussion board member (acquire authentication token in connection).
 * 2. As the member, create a new post ('active' status by default).
 * 3. Simulate admin context (by clearing connection headers) and update the post's status to 'hidden'.
 * 4. Attempt to fetch the hidden post as a guest (no Authorization header) — should raise not found or forbidden error.
 * 5. Attempt to fetch as a regular member (with token) — should also raise error.
 * 6. As admin, update status to 'deleted'.
 * 7. Test access as guest (again) and member (again) — both must fail.
 *
 * Notes:
 * - The admin session is simulated by clearing the connection.headers so no member token is present, matching API auth patterns.
 * - If the admin endpoint supports pure fetch (i.e., GET as admin), positive control could be checked, but here, all core negative controls are validated.
 */
export async function test_api_post_detail_hidden_post_access_denied(connection: api.IConnection) {
  // 1. Register a discussion board member (simulate member registration/login)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const password = "_Test1234!";
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password,
      nickname: RandomGenerator.name(),
    },
  });
  typia.assert(memberSession);

  // 2. As the member, create a new post ('active' status)
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1, 1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 3. Simulate admin context (no Authorization header) to update post status to 'hidden'
  const adminConnection = { ...connection, headers: {} };
  const hiddenPost = await api.functional.discussionBoard.admin.posts.update(adminConnection, {
    postId: post.id,
    body: { status: "hidden" },
  });
  typia.assert(hiddenPost);

  // 4. Attempt to fetch hidden post as guest (no Authorization header)
  await TestValidator.error("hidden post cannot be fetched as guest")(
    async () => {
      await api.functional.discussionBoard.posts.at(adminConnection, { postId: post.id });
    },
  );

  // 5. Attempt to fetch as regular member
  await TestValidator.error("hidden post cannot be fetched as member")(
    async () => {
      await api.functional.discussionBoard.posts.at(connection, { postId: post.id });
    },
  );

  // 6. As admin, update post status to 'deleted'
  const deletedPost = await api.functional.discussionBoard.admin.posts.update(adminConnection, {
    postId: post.id,
    body: { status: "deleted" },
  });
  typia.assert(deletedPost);

  // 7. Fetch as guest again (should fail)
  await TestValidator.error("deleted post cannot be fetched as guest")(
    async () => {
      await api.functional.discussionBoard.posts.at(adminConnection, { postId: post.id });
    },
  );

  // Fetch as member again (should fail)
  await TestValidator.error("deleted post cannot be fetched as member")(
    async () => {
      await api.functional.discussionBoard.posts.at(connection, { postId: post.id });
    },
  );
}

