/**
 * Validate that an admin can retrieve a filtered and paginated list of comment votes,
 * ensuring only records matching provided filters are returned, and that sorting, pagination,
 * and audit fields function according to requirements. Test both a matching vote result and
 * an empty set by adjusting search filters appropriately.
 *
 * 1. Register a new admin; authenticate for admin rights and search access.
 * 2. Create a new post as a member to serve as the context for a comment.
 * 3. Add a comment to the member-created post.
 * 4. Cast a vote on the comment as a member, so there is at least one comment vote record.
 * 5. As the admin, search for comment votes using filters that should yield the new vote (filter by comment ID, member ID, upvote flag, paginated, with sorting direction).
 *    - Assert the result contains the correct vote, that audit fields are present, and sorting matches expectations.
 * 6. As the admin, search with filters that produce an empty result set (e.g., a non-existent member/comment ID or opposite upvote flag).
 *    - Assert that the data array is empty and pagination meta is still correct.
 */
export async function test_api_comment_vote_search_admin_basic_filters(connection: api.IConnection) {
  // 1. Register a new admin and store credentials for later login if needed.
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "Admin!234";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminReg);

  // The admin's token is now in the connection headers for future admin calls.

  // 2. Create a forum post as a member (simulate member session).
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()().slice(0, 100),
      body: RandomGenerator.content()()().slice(0, 4000),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Add a comment to the post.
  const comment = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()().slice(0, 1000),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Cast a vote on the comment.
  const vote = await api.functional.discussionBoard.member.commentVotes.create(connection, {
    body: {
      discussion_board_comment_id: comment.id,
      is_upvote: true,
    } satisfies IDiscussionBoardCommentVote.ICreate,
  });
  typia.assert(vote);

  // 5. As admin, search for comment votes matching the just-created vote (by comment ID, is_upvote true, paginated).
  const pageResult = await api.functional.discussionBoard.admin.commentVotes.search(connection, {
    body: {
      discussion_board_comment_id: comment.id,
      is_upvote: true,
      sort_by: "created_at",
      sort_direction: "desc",
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardCommentVote.IRequest,
  });
  typia.assert(pageResult);
  TestValidator.predicate("vote result contains the just-created vote")(
    pageResult.data.some((v) => v.id === vote.id)
  );
  for (const v of pageResult.data) {
    TestValidator.equals("comment id matches")(v.discussion_board_comment_id)(comment.id);
    TestValidator.equals("is_upvote matches")(v.is_upvote)(true);
    TestValidator.predicate("created_at is a date")(!!v.created_at && !isNaN(Date.parse(v.created_at)));
    TestValidator.predicate("updated_at is a date")(!!v.updated_at && !isNaN(Date.parse(v.updated_at)));
  }

  TestValidator.equals("pagination page number")(pageResult.pagination.current)(1);
  TestValidator.equals("pagination limit")(pageResult.pagination.limit)(10);
  TestValidator.predicate("pagination record count")(pageResult.pagination.records >= 1);

  // 6. Search with a filter that will yield an empty data set (wrong comment ID).
  const emptyPage = await api.functional.discussionBoard.admin.commentVotes.search(connection, {
    body: {
      discussion_board_comment_id: typia.random<string & tags.Format<"uuid">>(), // unlikely to collide
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardCommentVote.IRequest,
  });
  typia.assert(emptyPage);
  TestValidator.equals("data array should be empty")(emptyPage.data.length)(0);
  TestValidator.equals("pagination current")(emptyPage.pagination.current)(1);
  TestValidator.equals("pagination limit")(emptyPage.pagination.limit)(10);
}

