import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * E2E test for moderator comment vote search/filter/pagination in the discussion board.
 *
 * Validates that moderators can search and paginate comment votes using advanced filters:
 * - Filter by member ID (voter)
 * - Filter by target comment ID
 * - Filter by vote type (upvote/downvote)
 * - Filter by creation date range
 * - Combination of above filters
 * - Paginate through large result sets, verify total counts and navigation logic
 *
 * The test includes setup of multiple comment votes with different members, comments, and vote types. The test authenticates as a moderator, executes various search requests with different filter combinations, and validates:
 *   - Only the matching votes are returned
 *   - Pagination is correct and consistent with total record count
 *   - All returned votes respect the applied filters
 *   - Security prevents non-moderators from accessing the API
 *   - Error cases for invalid parameters (e.g. negative page, excessive limit)
 *   - Access control errors (unauthorized roles)
 *   - Each found record can be loaded in detail via the detail API
 */
export async function test_api_comment_vote_search_various_filters_pagination(
  connection: api.IConnection,
) {
  // ----------- Step 1: Authenticate as moderator -----------
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = "P@ssw0rd!";
  // Moderator account should already exist in test system.
  const moderatorSignIn = await api.functional.auth.moderator.login.signIn(
    connection,
    {
      body: {
        email: moderatorEmail,
        password: moderatorPassword,
      } satisfies IModerator.SignIn,
    },
  );
  typia.assert(moderatorSignIn);
  // SDK will update Authorization header in connection automatically.

  // ----------- Step 2: Data setup - Create comments, members and votes -----------
  // Simulate several unique comment/member IDs for votes. Assume all referenced comments/members exist in test DB.
  const commentIds = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const memberIds = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  // Prepare a matrix: for each (member, comment), create one upvote and one downvote
  const voteRecords: IDiscussionBoardCommentVote[] = [];
  for (const memberId of memberIds) {
    for (const commentId of commentIds) {
      for (const is_upvote of [true, false]) {
        const vote = await api.functional.discussionBoard.member.commentVotes.create(
          connection,
          {
            body: {
              discussion_board_comment_id: commentId,
              is_upvote,
            } satisfies IDiscussionBoardCommentVote.ICreate,
          },
        );
        typia.assert(vote);
        voteRecords.push(vote);
      }
    }
  }

  // ----------- Step 3: Filtering & pagination tests -----------
  // 3a. Search by member ID
  for (const memberId of memberIds) {
    const result = await api.functional.discussionBoard.moderator.commentVotes.search(
      connection,
      {
        body: {
          discussion_board_member_id: memberId,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      },
    );
    typia.assert(result);
    for (const v of result.data) TestValidator.equals("member id matches")(v.discussion_board_member_id)(memberId);
  }
  // 3b. Search by comment ID
  for (const commentId of commentIds) {
    const result = await api.functional.discussionBoard.moderator.commentVotes.search(
      connection,
      {
        body: {
          discussion_board_comment_id: commentId,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      },
    );
    typia.assert(result);
    for (const v of result.data) TestValidator.equals("comment id matches")(v.discussion_board_comment_id)(commentId);
  }
  // 3c. Search by vote type (upvote/downvote)
  for (const is_upvote of [true, false]) {
    const result = await api.functional.discussionBoard.moderator.commentVotes.search(
      connection,
      {
        body: {
          is_upvote,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      },
    );
    typia.assert(result);
    for (const v of result.data) TestValidator.equals("is_upvote matches")(v.is_upvote)(is_upvote);
  }
  // 3d. Search by date range (using a window covering all votes, then narrow)
  const minDate = voteRecords.reduce((min, v) => min < v.created_at ? min : v.created_at, voteRecords[0].created_at);
  const maxDate = voteRecords.reduce((max, v) => max > v.created_at ? max : v.created_at, voteRecords[0].created_at);
  // (i) All votes in the full range
  const allVotes = await api.functional.discussionBoard.moderator.commentVotes.search(
    connection,
    {
      body: {
        created_after: minDate,
        created_before: maxDate,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    },
  );
  typia.assert(allVotes);
  for (const v of allVotes.data) {
    TestValidator.predicate("Within range")(
      v.created_at >= minDate && v.created_at <= maxDate,
    );
  }

  // (ii) Expect zero for future-only range
  const futureDate = new Date(Date.now() + 10 * 365 * 24 * 60 * 60 * 1000).toISOString();
  const futureSearch = await api.functional.discussionBoard.moderator.commentVotes.search(
    connection,
    {
      body: {
        created_after: futureDate,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    },
  );
  typia.assert(futureSearch);
  TestValidator.equals("future search empty")(futureSearch.data.length)(0);

  // 3e. Pagination: limit/page
  const pageTest = await api.functional.discussionBoard.moderator.commentVotes.search(
    connection,
    {
      body: {
        limit: 2,
        page: 1,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    },
  );
  typia.assert(pageTest);
  TestValidator.equals("page one limited")(pageTest.data.length <= 2)(true);
  const total = pageTest.pagination.records;

  if (total > 2) {
    const page2 = await api.functional.discussionBoard.moderator.commentVotes.search(
      connection,
      {
        body: {
          limit: 2,
          page: 2,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      },
    );
    typia.assert(page2);
    TestValidator.equals("page two limited")(page2.data.length <= 2)(true);
    // No overlapping records between first and second page
    const page1Ids = pageTest.data.map((v) => v.id);
    const page2Ids = page2.data.map((v) => v.id);
    for (const id of page1Ids) TestValidator.notEquals("not in second page")(page2Ids.includes(id))(true);
  }

  // 3f. Combined filter (member + comment + is_upvote)
  const combined = await api.functional.discussionBoard.moderator.commentVotes.search(
    connection,
    {
      body: {
        discussion_board_member_id: memberIds[0],
        discussion_board_comment_id: commentIds[0],
        is_upvote: true,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    },
  );
  typia.assert(combined);
  for (const v of combined.data) {
    TestValidator.equals("combined member")(v.discussion_board_member_id)(memberIds[0]);
    TestValidator.equals("combined comment")(v.discussion_board_comment_id)(commentIds[0]);
    TestValidator.equals("combined is_upvote")(v.is_upvote)(true);
  }

  // ----------- Step 4: Result detail lookups -----------
  for (const v of voteRecords) {
    const detail = await api.functional.discussionBoard.moderator.commentVotes.at(
      connection,
      {
        commentVoteId: v.id,
      },
    );
    typia.assert(detail);
    TestValidator.equals("detail matches")(detail)(v);
  }

  // ----------- Step 5: Error scenarios -----------
  // 5a. Invalid page (zero, negative)
  for (const badPage of [0, -1]) {
    await TestValidator.error("page must be >=1")(() =>
      api.functional.discussionBoard.moderator.commentVotes.search(connection, {
        body: {
          page: badPage,
        } satisfies IDiscussionBoardCommentVote.IRequest,
      }),
    );
  }
  // 5b. Excessive limit (>100)
  await TestValidator.error("limit must be <= 100")(() =>
    api.functional.discussionBoard.moderator.commentVotes.search(connection, {
      body: {
        limit: 101,
      } satisfies IDiscussionBoardCommentVote.IRequest,
    }),
  );

  // 5c. Unauthorized use (simulate non-moderator)
  // Simulate an unauthenticated connection by removing the Authorization header
  const headers = connection.headers ? { ...connection.headers } : {};
  if ("Authorization" in headers) {
    delete headers["Authorization"];
  }
  const nonAuthConnection = { ...connection, headers };
  await TestValidator.error("unauthorized for non-moderator")(() =>
    api.functional.discussionBoard.moderator.commentVotes.search(nonAuthConnection, {
      body: {},
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IPageIDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Test that non-moderator roles (members and guests) cannot access moderator comment vote search.
 *
 * This test verifies strict access controls for the PATCH /discussionBoard/moderator/commentVotes endpoint.
 * It ensures that only users with appropriate moderator/admin privileges can search all comment votes.
 * Regular members and guests must be denied access.
 *
 * **Steps:**
 * 1. Register a regular (non-moderator) discussion board member.
 * 2. Using the member account, cast a vote on a random comment.
 * 3. Attempt to search comment votes using the moderator endpoint:
 *    a. As the member (with a valid JWT): must be forbidden.
 *    b. As a guest (no token): must be forbidden.
 *    c. With an invalid/expired token: must be forbidden.
 * 4. All these attempts are expected to be denied (403 error), fulfilling audit compliance.
 */
export async function test_api_comment_vote_search_access_denied_for_non_moderator_roles(
  connection: api.IConnection,
) {
  // 1. Register a regular member (not moderator or admin)
  const memberInput: IDiscussionBoardMember.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "testPassword1!",
    nickname: RandomGenerator.name(),
  };
  const session: IDiscussionBoardMember.ISession = await api.functional.auth.member.register.signUp(connection, {
    body: memberInput,
  });
  typia.assert(session);

  // 2. As member, cast a vote on a random comment
  const commentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const vote: IDiscussionBoardCommentVote = await api.functional.discussionBoard.member.commentVotes.create(
    {
      ...connection,
      headers: {
        ...connection.headers,
        Authorization: session.setHeaders.Authorization,
      },
    },
    {
      body: {
        discussion_board_comment_id: commentId,
        is_upvote: true,
      },
    },
  );
  typia.assert(vote);

  // 3a. Attempt moderator vote search as member (should be forbidden)
  await TestValidator.error("non-moderator member forbidden")(
    () =>
      api.functional.discussionBoard.moderator.commentVotes.search(
        {
          ...connection,
          headers: {
            ...connection.headers,
            Authorization: session.setHeaders.Authorization,
          },
        },
        {
          body: {
            discussion_board_comment_id: commentId,
            discussion_board_member_id: vote.discussion_board_member_id,
            limit: 10,
            page: 1,
          },
        },
      ),
  );

  // 3b. Attempt moderator vote search as guest (no authorization header)
  await TestValidator.error("guest forbidden")(
    () =>
      api.functional.discussionBoard.moderator.commentVotes.search(connection, {
        body: {
          discussion_board_comment_id: commentId,
          limit: 10,
          page: 1,
        },
      }),
  );

  // 3c. Attempt moderator vote search with an invalid/expired token
  await TestValidator.error("invalid/expired token forbidden")(
    () =>
      api.functional.discussionBoard.moderator.commentVotes.search(
        {
          ...connection,
          headers: {
            ...connection.headers,
            Authorization: "Bearer invalid.invalid.invalid",
          },
        },
        {
          body: {
            discussion_board_comment_id: commentId,
            limit: 10,
            page: 1,
          },
        },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardAdminAuthResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdminAuthResponse";

/**
 * Validate retrieval of comment vote details as an admin, for both valid and non-existent IDs.
 *
 * Business context:
 * An administrator is authorized to view details of any comment vote for purposes of moderation and audit in the discussion board. Attempting to retrieve a vote by a missing or deleted ID must result in a proper not-found error. Every field returned by the detail endpoint should match the source record.
 *
 * Process:
 * 1. Log in as an administrator, saving the token for subsequent requests.
 * 2. Create a comment vote (as a member context is assumed available for test infrastructure).
 * 3. Retrieve the vote detail via the admin endpoint and validate all fields against the created record.
 * 4. Attempt retrieval with a non-existent commentVoteId and verify a not-found error occurs.
 */
export async function test_api_comment_vote_detail_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Log in as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.Format<"password">>();
  const adminAuth = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IDiscussionBoardAdmin.ILogin,
  });
  typia.assert(adminAuth);

  // Update connection headers with admin JWT token
  connection.headers = {
    ...connection.headers,
    Authorization: adminAuth.setHeaders.Authorization,
  };

  // 2. Create a comment vote as member (test assumes member session context is in place)
  const commentId = typia.random<string & tags.Format<"uuid">>();
  const voteCreated = await api.functional.discussionBoard.member.commentVotes.create(connection, {
    body: {
      discussion_board_comment_id: commentId,
      is_upvote: true,
    } satisfies IDiscussionBoardCommentVote.ICreate,
  });
  typia.assert(voteCreated);

  // 3. Retrieve and validate details as admin
  const voteDetail = await api.functional.discussionBoard.admin.commentVotes.at(connection, {
    commentVoteId: voteCreated.id,
  });
  typia.assert(voteDetail);
  TestValidator.equals("id matches")(voteDetail.id)(voteCreated.id);
  TestValidator.equals("comment id matches")(voteDetail.discussion_board_comment_id)(voteCreated.discussion_board_comment_id);
  TestValidator.equals("member id matches")(voteDetail.discussion_board_member_id)(voteCreated.discussion_board_member_id);
  TestValidator.equals("vote type matches")(voteDetail.is_upvote)(voteCreated.is_upvote);
  TestValidator.equals("created_at matches")(voteDetail.created_at)(voteCreated.created_at);
  TestValidator.equals("updated_at matches")(voteDetail.updated_at)(voteCreated.updated_at);
  TestValidator.equals("deleted_at matches")(voteDetail.deleted_at ?? null)(voteCreated.deleted_at ?? null);

  // 4. Attempt to fetch a non-existent commentVote ID and expect a not found error
  await TestValidator.error("not found for missing commentVote ID")(() =>
    api.functional.discussionBoard.admin.commentVotes.at(connection, {
      commentVoteId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerator";

/**
 * Validate moderator access to comment vote detail and enforce access denial for non-moderators.
 *
 * This test ensures:
 * 1. Moderators can successfully retrieve all details of a specific comment vote by its UUID.
 * 2. Access by members or unauthenticated guests to moderator-only comment vote detail endpoint is denied.
 * 3. Accessing with an invalid or nonexistent commentVoteId returns a not-found error.
 *
 * Workflow:
 * 1. Create a comment vote as a member (simulated context as no member login API exists).
 * 2. Obtain the commentVoteId from the result.
 * 3. Authenticate as moderator using known email/password, storing token from response.
 * 4. Access /discussionBoard/moderator/commentVotes/{commentVoteId} as a moderator and verify details match the created vote.
 * 5. Remove Authorization (simulate guest/member context) and verify access to same endpoint is denied.
 * 6. Switch back to moderator Authorization and attempt access to a random (invalid) UUID, expecting not found.
 */
export async function test_api_comment_vote_detail_access_by_moderator_and_denied_for_others(
  connection: api.IConnection
) {
  // 1. Create a comment vote as a member
  const commentVote: IDiscussionBoardCommentVote = await api.functional.discussionBoard.member.commentVotes.create(
    connection,
    {
      body: {
        discussion_board_comment_id: typia.random<string & tags.Format<"uuid">>(),
        is_upvote: true,
      } satisfies IDiscussionBoardCommentVote.ICreate,
    }
  );
  typia.assert(commentVote);

  // 2. Authenticate as moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Password123!";
  // It is assumed that a moderator account exists with this credential.
  const moderatorSession = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IModerator.SignIn,
  });
  typia.assert(moderatorSession);

  // 3. Set Authorization header for moderator context
  connection.headers = {
    ...connection.headers,
    ...(moderatorSession.setHeaders ?? {}),
  };

  // 4. Access comment vote details as moderator (should succeed)
  const moderatorView: IDiscussionBoardCommentVote = await api.functional.discussionBoard.moderator.commentVotes.at(
    connection,
    {
      commentVoteId: commentVote.id,
    }
  );
  typia.assert(moderatorView);
  TestValidator.equals("vote details match")(moderatorView)(commentVote);

  // 5. Remove Authorization header to simulate guest/member access and verify denial
  delete connection.headers.Authorization;
  await TestValidator.error("member/guest forbidden")(
    async () =>
      await api.functional.discussionBoard.moderator.commentVotes.at(connection, {
        commentVoteId: commentVote.id,
      })
  );

  // 6. Restore moderator Authorization and access invalid/nonexistent UUID
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorSession.setHeaders.Authorization,
  };
  await TestValidator.error("not found")(
    async () =>
      await api.functional.discussionBoard.moderator.commentVotes.at(connection, {
        commentVoteId: typia.random<string & tags.Format<"uuid">>(),
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validates member comment voting on the discussion board, covering upvote/downvote creation and duplicate prevention.
 *
 * This test covers the end-to-end flow required to create legitimate upvote and downvote actions from a registered member on distinct comments and ensures that duplicate votes on the same comment are properly blocked. All actions are asserted for business logic and type safety per API contracts.
 *
 * Step-by-step process:
 * 1. Register a new member to serve as the voter and obtain session context.
 * 2. Create two distinct posts as the discussion context for comments.
 * 3. Author a comment on each post, each yielding unique comment IDs for independent voting.
 * 4. Member creates an upvote for the first comment and a downvote for the second comment.
 * 5. Assert the vote objects for correct type, association to comment/member, and vote type.
 * 6. Attempt to create a duplicate upvote for the first comment (same member, same comment); expect a business logic error. Repeat for the downvote on the second comment.
 * 7. Ensure all creation and duplicate prevention rules are strictly enforced per business contract.
 */
export async function test_api_comment_vote_creation_success_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Register a new member who will act as the voter
  const email = typia.random<string & tags.Format<"email">>();
  const password = "password1234";
  const nickname = RandomGenerator.name();
  const session = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
      nickname,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(session);
  const memberId = session.member.id;

  // 2. Create two posts as the context for voting
  const post1 = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.paragraph()(80),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post1);
  const post2 = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(16),
      body: RandomGenerator.paragraph()(45),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post2);

  // 3. Author one comment per post (producing separate comment IDs)
  const comment1 = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post1.id,
    body: {
      body: RandomGenerator.paragraph()(10),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment1);
  const comment2 = await api.functional.discussionBoard.member.posts.comments.create(connection, {
    postId: post2.id,
    body: {
      body: RandomGenerator.paragraph()(20),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment2);

  // 4. Create an upvote for the first comment
  const upvote = await api.functional.discussionBoard.member.commentVotes.create(connection, {
    body: {
      discussion_board_comment_id: comment1.id,
      is_upvote: true,
    } satisfies IDiscussionBoardCommentVote.ICreate,
  });
  typia.assert(upvote);
  TestValidator.equals("Upvote member context")(upvote.discussion_board_member_id)(memberId);
  TestValidator.equals("Upvote comment reference")(upvote.discussion_board_comment_id)(comment1.id);
  TestValidator.equals("Is upvote true")(upvote.is_upvote)(true);

  // 5. Create a downvote for the second comment
  const downvote = await api.functional.discussionBoard.member.commentVotes.create(connection, {
    body: {
      discussion_board_comment_id: comment2.id,
      is_upvote: false,
    } satisfies IDiscussionBoardCommentVote.ICreate,
  });
  typia.assert(downvote);
  TestValidator.equals("Downvote member context")(downvote.discussion_board_member_id)(memberId);
  TestValidator.equals("Downvote comment reference")(downvote.discussion_board_comment_id)(comment2.id);
  TestValidator.equals("Is upvote false")(downvote.is_upvote)(false);

  // 6. Attempt to create a duplicate upvote (should fail)
  await TestValidator.error("Duplicate upvote by same member forbidden")(() =>
    api.functional.discussionBoard.member.commentVotes.create(connection, {
      body: {
        discussion_board_comment_id: comment1.id,
        is_upvote: true,
      } satisfies IDiscussionBoardCommentVote.ICreate,
    })
  );

  // 7. Attempt to create a duplicate downvote (should fail)
  await TestValidator.error("Duplicate downvote by same member forbidden")(() =>
    api.functional.discussionBoard.member.commentVotes.create(connection, {
      body: {
        discussion_board_comment_id: comment2.id,
        is_upvote: false,
      } satisfies IDiscussionBoardCommentVote.ICreate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVote";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * Validates error handling on comment vote creation for the discussion board API.
 *
 * This test ensures APIs return explicit validation or business errors when creating a comment vote with invalid data, specifically:
 *
 * 1. Malformed UUID for comment ID (invalid format).
 * 2. Reference to a non-existent comment (random, but syntactically valid UUID).
 * 3. Invalid type for `is_upvote` (passing a string instead of boolean, within compile-time type constraints).
 *
 * Scenarios involving omission of required fields or compile-time type errors are not tested, as per E2E guidelines: only runtime-input errors are validated.
 *
 * Steps:
 * 1. Register a new member to obtain a valid JWT session for requests.
 * 2. Create a post by the member (context setup; cannot create comments due to API limitations, so vote targets are synthetic).
 * 3. Attempt to create a vote with a malformed comment ID (fail: validation error).
 * 4. Attempt to create a vote with a non-existent comment ID (fail: business logic error).
 * 5. Attempt to create a vote with `is_upvote` as a string (fail: validation error).
 */
export async function test_api_comment_vote_creation_validation_errors(
  connection: api.IConnection,
) {
  // 1. Register a new member and obtain authentication
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "test1234!";
  const memberNickname = RandomGenerator.name();
  const memberSession = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
      nickname: memberNickname,
    },
  });
  typia.assert(memberSession);
  const memberId = memberSession.member.id;

  // 2. Create a post as the member (no comment creation API, so cannot produce valid comment ID)
  const post = await api.functional.discussionBoard.member.posts.create(connection, {
    body: {
      title: "Vote error test post - " + RandomGenerator.paragraph()(10),
      body: "Testing comment vote creation errors.",
    },
  });
  typia.assert(post);

  // 3. Test with malformed comment UUID
  await TestValidator.error("vote creation fails with malformed comment ID")(
    async () => {
      await api.functional.discussionBoard.member.commentVotes.create(connection, {
        body: {
          discussion_board_comment_id: "not-a-uuid" as string,
          is_upvote: true,
        },
      });
    },
  );

  // 4. Test with syntactically valid but non-existent comment UUID
  await TestValidator.error("vote creation fails for non-existent comment ID")(
    async () => {
      await api.functional.discussionBoard.member.commentVotes.create(connection, {
        body: {
          discussion_board_comment_id: typia.random<string & tags.Format<"uuid">>(),
          is_upvote: true,
        },
      });
    },
  );

  // 5. Test with invalid is_upvote type (string instead of boolean)
  await TestValidator.error("vote creation fails when is_upvote is a string")(
    async () => {
      await api.functional.discussionBoard.member.commentVotes.create(connection, {
        body: {
          discussion_board_comment_id: typia.random<string & tags.Format<"uuid">>(),
          is_upvote: "yes" as unknown as boolean,
        },
      });
    },
  );
}
